window.__D("text/zohar-hebrew-translation/c010",{"p":[[9522011434,"<p>וַאֲנִי בְּבֹאִי מִפַּדַּן מֵתָה עָלַי רָחֵל בַּדֶּרֶךְ וְגוֹ'. רַבִּי אַבָּא פָּתַח, (ירמיה לא) כֹּה אָמַר ה' קוֹל בְּרָמָה נִשְׁמָע וְגוֹ'. מַה כָּתוּב אַחֲרָיו? כֹּה אָמַר ה' מִנְעִי קוֹלֵךְ מִבֶּכִי וְעֵינַיִךְ מִדִּמְעָה כִּי יֵשׁ שָׂכָר לִפְעֻלָּתֵךְ וְגוֹ' וְשָׁבוּ בָנִים לִגְבוּלָם. לֹא אָמַר וְיָשׁוּבוּ, אֶלָּא וְשָׁבוּ, כְּבָר שָׁבוּ.</p>\n<p>בֹּא רְאֵה, אָמַר רַבִּי אֶלְעָזָר, בְּשָׁעָה שֶׁיִּהְיֶה דִין עַל הָהָר, תִּתְעַטֵּר הַגְּבִירָה עַל הָהָר, וְהִיא סְבוּרָה שֶׁבְּנֵיהֶם אוֹבְדִים בַּדִּין, וְסוֹד - (ישעיה נד) רָנִּי עֲקָרָה לֹא יָלָדָה פִּצְחִי רִנָּה וְצַהֲלִי וְגוֹ'. לָמַדְנוּ, רַבִּים יִהְיוּ בְּנֵי הַכִּסֵּא מִשֶּׁלָּהּ, זֶהוּ שֶׁכָּתוּב כִּי רַבִּים בְּנֵי שׁוֹמֵמָה מִבְּנֵי בְעוּלָה. תָּשׁוּב הַגְּבִירָה לְבַעְלָהּ, (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>מִקֹּדֶם לָכֵן תֹּאמַר הַגְּבִירָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא, אֵיפֹה הַבָּנִים שֶׁלִּי? הוּא יֹאמַר לָהּ, הֵם בְּדִין. הִיא תַחְשּב שֶׁהֵם אוֹבְדִים בַּדִּין, וּבוֹכָה עַל הַדִּין שֶׁל בָּנֶיהָ, כִּי הֲרֵי הַרְבֵּה יֵשׁ לְךְ לָקַחַת מִמֶּנִּי בְּשֶׁלָּהֶם, שֶׁהָיְתָה עִמָּם, וַהֲרֵי שָׁבוּ מֵאֶרֶץ אוֹיֵב.</p>\n<p>וְכִי לֹא הָיָה יוֹדֵעַ שֶׁאִמּוֹ מֵתָה? שָׁם הָיָה עִמָּה כְּשֶׁמֵּתָה. אֶלָּא יֹאמַר יִשְׂרָאֵל הָעֶלְיוֹן, כְּשֶׁתָּבֹא גְּאֻלַּת יִשְׂרָאֵל, תִּתְעוֹרֵר הַגְּבִירָה, וְתִתְעוֹרֵר כְּנֶסֶת יִשְׂרָאֵל וְתַעֲרֹךְ קְרָב עִם הָעַמִּים, וְיָמוּתוֹ מֵהֶם, וְיִתְקָרְבוּ כִּמְעַט לָבֹא אַרְצָה. יֹאמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּשֶׁהִיא בּוֹכָה: אַל תְּפַחֲדִי, יֵשׁ שָׂכָר לַבָּנִים שֶׁמֵּתוּ עַל שְׁמִי, הָאֲחֵרִים הֲרֵי שָׁבוּ, אֵלּוּ יָשׁוּבוּ לִתְחִיַּת הַמֵּתִים.</p>\n<p>מֵתָה עָלַי רָחֵל. מֵתָה עַל יִחוּד שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְלָכֵן נֶאֱמַר בְּעוֹד כִּבְרַת אֶרֶץ לָבא, שֶׁמֵּתוּ עַל יִחוּד שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִחוּץ לָאָרֶץ, בְּאֶרֶץ זוֹ לֹא יָמוּת אֶחָד מֵהֶם.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי אַבָּא, עֲתִידִים יִשְׂרָאֵל לַעֲרֹב קְרָב בַּדֶּרֶךְ אֶפְרָת וְיָמוּתוּ מֵהֶם עַם רַב, וְאַחַר כָּךְ יָקוּמוּ בִּתְחִיַּת הַמֵּתִים. יוֹתֵר שִׁלְטוֹן יִהְיֶה לָהֶם שֶׁמֵּתוּ בְּדֶרֶךְ זוֹ מִכָּל שֶׁהָיָה לִפְנֵיהֶם בִּירוּשָׁלַיִם.</p>\n<p>וְלָמָּה נִקְרָא שֵׁם הַמָּקוֹם הַקָּדוֹשׁ שֶׁל מָקוֹם זֶה לֶחֶם? מִשּׁוּם שֶׁהוּא מִשֵּׁם הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁבּוֹ, שֶׁיָּמוּתוּ שָׁם עַל שְׁמוֹ י\"ד, שֶׁיָּמוּתוּ שָׁם עַל שְׁמוֹ י\"ה, לֶחֶם בַּגָּלוּת, בִּשְׁבִיל שֶׁהוּא מִשְּׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9522011435,"<p>וַיַּרְא יִשְׂרָאֵל אֶת בְּנֵי יוֹסֵף וַיֹּאמֶר מִי אֵלֶּה. רַבִּי אַבָּא פָּתַח, (ישעיה מט) וְאָמַרְתְּ בִּלְבָבֵךְ מִי יָלַד לִי אֶת אֵלֶּה. מָה רָצָה בָּזֶה? יִשְׂרָאֵל שֶׁלְּמַטָּה רָאָה שֶׁיָּבֹאוּ בְּנֵי יִשְׂרָאֵל לְפָנָיו, כְּשֶׁיָּבֹאוּ (שם יא) מֵעֵילָם וּמִשִּׁנְעָר וּמֵחֲמָת וּמֵאִיֵּי הַיָּם, וְיִתְכַּנְּסוּ כֻלָּם וְיִהְיוּ רַבִּים, תֹּאמַר הַשְּׁכִינָה: מֵאֵיפֹה כָּל אֵלֶּה, וְאֵין בָּהֶם פְּסוּל מִבְּנֵי נָכְרִים? יֹאמְרוּ לוֹ, אֲנַחְנוּ כֻּלָּנוּ מִבָּנֶיךְ וְאֵין בָּנוּ נָכְרִי עִמָּנוּ, שֶׁיִּפָּרְדוּ זֶה מִזֶּה וְיִכְרוֹת אוֹתָם כְּאֶחָד, וְיִתְגַּיְּרוּ, וְיָשׁוּבוּ גֵרִים עִם יִשְׂרָאֵל וְיִהְיוּ כְּאֶחָד.</p>\n<p>שָׁנִינוּ, קָשִׁים גֵּרִים לְיִשְׂרָאֵל כְּסַפַּחַת בְּעוֹר הַחַי, לְאַרְצָם. כָּתוּב (שם יד) כִּי יְרַחֵם ה' אֶת יַעֲקֹב וּבָחַר עוֹד בְּיִשְׂרָאֵל (וגו') וְנִלְוָה הַגֵּר עֲלֵיהֶם וְנִסְפְּחוּ עַל בֵּית יַעֲקֹב. כְּשֶׁיָּשׁוּבוּ לְאַרְצָם הַבָּנִים וְתִהְיֶה בֵינֵיהֶם אַהֲבָה, יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד, יִתְלַוּוּ גֵרִים עִם יִשְׂרָאֵל וְיִהְיוּ לָהֶם כְּסַפַּחַת בִּבְשָׂרָם.</p>\n<p>וְכָל כָּךְ לָמָּה? בֹּא שְׁמַע, אָמַר רַבִּי שִׁמְעוֹן, עַל תְּחוּמֵי הָאָרֶץ שֶׁלְּכָל אֶחָד יִהְיֶה רָצוֹן לָדוּר בְּאֶרֶץ יִשְׂרָאֵל וְיִתְרָאוּ הַדַּיָּרִים כָּתוּב (שם נד) וִיתֵדתַיִךְ חַזֵּקִי. רוֹצֶה לוֹמַר, הַיְתֵדוֹת שֶׁהָיוּ עִמָּךְ מֵהַהַתְחָלָה, חַזְּקִי אוֹתָם, וַעֲזֹר לָהֶם יוֹתֵר מִשְּׁאָר הָעַמִּים כִּבְיָכוֹל, שֶׁאַתָּה הִסְתַּכַּלְתָּ לְחַזֵּק אוֹתָם בְּכָל הָעַמִּים הָאֲחֵרִים, וְיִהְיוּ רַבִּים.</p>"],[9522011436,"<p>וַיֹּאמֶר יוֹסֵף אֶל אָבִיו בָּנַי הֵם אֲשֶׁר נָתַן לִי אֱלֹהִים בָּזֶה. רַבִּי שִׁמְעוֹן שָׁנָה, מִכָּאן (דברים ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. יֹאמַר יִשְׂרָאֵל לְמַטָּה, כְּשֶׁיִּשְׂרָאֵל עֲלֵיהֶם מִלְמַעְלָה, בָּנַי הֵם, שֶׁנָּתַן לִי הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹרָה, כַּמָּה שֶׁדָּתָם וּמִנְהֲגֵיהֶם אֲמִתִּיִּים בְּהַנְהָגוֹת הַתּוֹרָה (שנתתי להם, בא ראה, כשיהיו ישראל תחת כנפי השכינה, התורה) שֶׁלָּהֶם נִקְרֵאת זֶה, זֶהוּ שֶׁכָּתוּב (שמות טו) זֶה אֵלִי וְאַנְוֵהוּ. וּבְכָל זְמַן שֶׁלֹּא הָיָה דָוִד מְדַבֵּר תַּחַת כַּנְפֵי הַשְּׁכִינָה דָּבָר זֶה, אֶלָּא מִתְנַבֵּא מַה שֶּׁיִּהְיֶה, נִקְרֵאת זאת.</p>\n<p>רַב נַחְמָן אָמַר מִכָּאן, (תהלים כז) אִם תַּחֲנֶה עָלַי מַחֲנֶה לֹא יִירָא לִבִּי וְגוֹ' בְּזֹאת אֲנִי בּוֹטֵחַ, זֹאת - זוֹ תּוֹרָה תִּהְיֶה לִכְשֶׁיָּבֹא הַמָּשִׁיחַ, וְלָכֵן (שיר ב) וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ. לָמָּה נִמְשְׁלָה הַתּוֹרָה לְגוֹזָל? מַה גּוֹזָל קוֹלוֹ עָרֵב - אַף דִּבְרֵי הַתּוֹרָה קוֹלָם עָרֵב, וְהַקּוֹל הַזֶּה יִהְיֶה כְּשֶׁיָּבֹא הַמָּשִׁיחַ לְיוֹם הַדִּין.</p>\n<p>לָמַדְנוּ, הַנִּצָּנִים נִרְאוּ בָאָרֶץ עֵת הַזָּמִיר הִגִּיעַ וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ. הַנִּצָּנִים - אֵלּוּ הָאָבוֹת שֶׁל הַמֶּרְכָּבָה שֶׁמִּן הָעוֹלָם הֵם יָקוּמוּ וְיִתְרָאוּ.</p>\n<p>עֵת הַזָּמִיר הִגִּיעַ - הַתִּשְׁבָּחוֹת שֶׁיְּשַׁבְּחוּ הַלְוִיִּם כְּשֶׁיָּשׁוּבוּ לַעֲבוֹדָתָם כְּבַתְּחִלָּה. וְקוֹל הַתּוֹר - אֲשֶׁר נָתַן לִי אֱלֹהִים בָּזֶה, דִּבְרֵי תוֹרָה שֶׁהֵם עֲרֵבִים כְּקוֹל הַתּוֹר הַזֶּה, זֶ\"ה וְזֹא\"ת תּוֹר שָׁוִים.</p>\n<p>מָה רוֹצֶה לוֹמַר? וְסוֹד הַדָּבָר - בִּזְמַן שֶׁלֹּא תִהְיוּ תַּחַת כַּנְפֵי הַשְּׁכִינָה, א' שֶׁל זֹאת יוֹרֵד, וְהוּא מִתַּחַת לַכֹּל, וְעוֹלָה ה' שֶׁל זֶה אֶל וְאַנְוֵהוּ מִשֶּׁחָרַב הַבַּיִת, שֶׁהֵ\"א לֹא יָכְלָה לָדוּר וְלִהְיוֹת בֵּין עַמִּים נָכְרִים, שֶׁהֵ\"א קְדוֹשָׁה חֲתוּכָה מִן הַשֵּׁם. הֵ\"א אָלֶף: הֵ\"א עֲדִיפָה בַּקְּדֻשָּׁה, א' עֲדִיפָה לָאוֹתִיּוֹת. כְּשֶׁיָּשׁוּבוּ יִשְׂרָאֵל לְאַרְצָם, הֵ\"א קְדוֹשָׁה שֶׁהִיא חֲתוּכָה מִן הַשֵּׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, תָּשׁוּב בָּזֶה וְיֵצֵא מִנְיָן מְתֻקָּן.</p>\n<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (ישעיה מ) מִי מָדַד בְּשָׁעֳלוֹ מַיִם וְשָׁמַיִם בַּזֶּרֶת תִּכֵּן. זֶה תּוֹר, שָׁוִין כִּבְיָכוֹל ז' לְר', ר' לְת', ו' לְה', זֶרֶת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּשֵׁשׁ מֵאוֹת שִׁבְעִים שָׁנִים. מִכָּאן מִן הַשָּׁמַיִם וְעַד הָאָרֶץ, כֵּיצַד? תּוֹ\"ר, זֶרֶ\"ת ו\"ה ה\"ו תר\"ז. הֻקְדְּמָה ה' לְו' וְהֻקְדְּמָה ו' לְת', ת' לְר', ר' לְז', (שמות כח) רָבוּעַ יִהְיֶה כָּפוּל זֶרֶת אָרְכּוֹ וְזֶרֶת רָחְבּוֹ כָּפוּל.</p>\n<p>וַיֹּאמַר קָחֶם נָא אֵלַי וַאֲבָרֲכֵם. יֹאמַר, מִשֶּׁהָיוּ מִתְעַסְּקִים בְּדִבְרֵי תוֹרָה וְהָיְתָה מִדָּה זוֹ בֵּין חַכְמֵיהֶם, אֲבָרֵךְ אוֹתָם, וְהַסּוֹד - (בראשית לב) וַיֹּאמֶר אֵלָיו מַה שְּׁמֶךְ וַיֹּאמֶר יַעֲקֹב. וַיֹּאמֶר לָמָּה זֶּה תִּשְׁאַל לִשְׁמִי. וַיֹּאמֶר יַעֲקֹב, מִנְיָן זֶה לַמִּנְיָן הָרִאשׁוֹן שֶׁלְּפָנָיו, כְּמוֹ שֶׁפֵּרַשְׁנוּ בִּמְקוֹמוֹ.</p>\n<p>וְסוֹד אַחֵר - וַיִּשְׁאַל יַעֲקֹב וְגוֹ', וַיֹּאמֶר לָמָּה זֶּה תִּשְׁאַל לִשְׁמִי וַיְבָרֶךְ אֹתוֹ שָׁם. זֶה לֹא עָתִיד, אֶלָּא בִּזְכוּתוֹ שֶׁל זֶה לְבָרֵךְ אוֹתָם.</p>\n<p>וְסוֹד גָּדוֹל שֵׁנִי בַּמָּקוֹם שֶׁל הַפָּסוּק הַזֶּה, אֲבָל לֹא בָאתִי לְפָנֶיךְ אֶלָּא לְהַשְׁמִיעַ פָּסוּק זֶה שֶׁאָמַרְתִּי מִלִּפְנֵי שֶׁאָמַרְתִּי לְךְ שֶׁהַתּוֹרָה נִקְרֵאת זֶה. כָּתוּב (שופטים ה) זֶה סִינַי מִפְּנֵי ה' אֱלֹהֵי יִשְׂרָאֵל, כְּשֶׁנִּתְּנָה תּוֹרָה עַל יְדֵי מֹשֶׁה, (שמות לב) כִּי זֶה מֹשֶׁה הָאִישׁ, (שמות טו) זֶה אֵלִי וְאַנְוֵהוּ. הַתּוֹרָה הָיְתָה יוֹרֶדֶת מִלִּפְנֵי אֱלֹהֵי יִשְׂרָאֵל.</p>"],[9522011437,"<p>וְעֵינֵי יִשְׂרָאֵל כָּבְדוּ מִזֹּקֶן וְגוֹ'. וְלָכֵן אֵינְךְ מוֹצֵא כְמוֹתוֹ, וּכְשֶׁיִּהְיוּ בַּגָּלוּת כָּל זְמַן הַחֻרְבָּן הַזֶּה, יִזְדַּקְּנוּ, וְלֹא יוּכְלוּ לִרְאוֹת פְּנֵי שְׁכִינָה עַד שֶׁתָּבֹא בָהֶם רוּחַ אַחֶרֶת.</p>\n<p>מִקֹּדֶם לָכֵן נִטְמְאוּ בְּאֶרֶץ הָעַמִּים וְלֹא הָיוּ בְּדַרְכֵי הַתּוֹרָה כְּמוֹ שֶׁהָיוּ צְרִיכִים לָלֶכֶת, וְיָשְׁבוּ זְמַן רַב בֵּין נָכְרִים דּוֹר אַחֲרֵי דוֹר וְלָמְדוּ מִדַּרְכֵיהֶם. כְּשֶׁיָּשׁוּבוּ פְּנֵי הַשְּׁכִינָה לְאַרְצָם, בַּתְּחִלָּה לֹא יוּכְלוּ לִרְאוֹת פְּנֵי שְׁכִינָה עַד שֶׁיִּתֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחוֹ לָהֶם.</p>\n<p>רַבִּי חִיָּיא פָּתַח, (יחזקאל לו) וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם. וְאַחַר כָּךְ, וְעָשִׂיתִי אֵת אֲשֶׁר בְּחֻקַּי תֵּלֵכוּ וּמִשְׁפָּטַי תִּשְׁמְרוּ וַעֲשִׂיתֶם. מֵאַחַר שֶׁיִּתֵּן רוּחוֹת בָּכֶם וְגַם קְדֻשָּׁה, בִּדְרָכַי תֵּלֵכוּ וְתִתְהַלְּכוּ.</p>\n<p>לֹא יוּכַל לִרְאוֹת. רַבִּי אַבָּא פָּתַח וְאָמַר, (משלי יז) בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים וּרְצוֹנוֹ כְּעָב מַלְקוֹשׁ. כְּשֶׁיְּקַבְּלוּ פְּנֵי שְׁכִינָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְיִתְעַסְּקוּ בְּאוֹתָן מֶרְכָּבוֹת שֶׁמֵּהֶן חַיּוֹת הָעוֹלָם.</p>\n<p>בֹּא רְאֵה, לֹא תִמְצָא בַּפְּסוּקִים הַלָּלוּ כֻּלָּם לָשׁוֹן אֶלָּא לָאֲנָשִׁים, (תהלים עא) גַּם לְשׁוֹנִי כָּל הַיּוֹם תֶּהְגֶּה צִדְקָתֶךְ. וְלֹא תִמְצָא בַּפְּסוּקִים הַלָּלוּ בַּקָּדוֹשׁ בָּרוּךְ הוּא, וּמִשּׁוּם כָּךְ יָשׁוּבוּ לְאַרְצָם וְיִתֵּן בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ חָכְמָה, לְשׁוֹנָם תִּהְיֶה תָּמִיד. (עד כאן אינו מן הזהר)</p>"],[9522011438,"<p>וַיְחִי יַעֲקֹב וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ וְגוֹ'. אַשְׁרֵיהֶם יִשְׂרָאֵל יוֹתֵר מִכָּל אֻמּוֹת עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא אותָם צַדִּיקִים לְהוֹרִישׁ לָהֶם יְרֻשַּׁת עוֹלָמִים בָּעוֹלָם הַבָּא, לְהִתְעַנֵּג בְּאותו עוֹלָם, כְּמוֹ שֶׁכָּתוּב (ישעיה נח) אָז תִּתְעַנַּג עַל ה'. מָה הַטַּעַם? בִּגְלַל שֶׁנִּדְבָּקִים בַּגּוּף שֶׁל הַמֶּלֶךְ, שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>\n<p>רַבִּי יִצְחָק פָּתַח וְאָמַר, וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ, פָּסוּק זֶה הוּא סוֹד עֶלְיוֹן בֵּין קוֹצְרֵי הַשָּׂדֶה, שֶׁהֲרֵי בְּסוֹד הָאַגָּדָה שָׁנָה רַבִּי שִׁמְעוֹן שֶׁיְּרֻשַּׁת הַיְרֻשָּׁה הָעֶלְיוֹנָה שֶׁל אוֹתָהּ אֶרֶץ, אֵין מִי שֶׁיּוֹרֵשׁ אוֹתוֹ פְּרָט לְאוֹתוֹ שֶׁנִּקְרָא צַדִּיק. (של הארץ הזאת, ואין מי שיורש אותה פרט לאותו שנקרא צדיק, שהרי הצדיק יורש את הגבירה ודאי) שֶׁהֲרֵי הַגְּבִירָה נִדְבֶּקֶת בּוֹ לְהִתְבַּשֵּׂם, וְהַצַּדִּיק יוֹרֵשׁ וַדַּאי אֶת הַגְּבִירָה הַזּוֹ.</p>\n<p>אַף כָּאן, בַּחֲבִיבוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל אָמַר וְעַמֵּךְ כֻּלָּם צַדִּיקִים. וְלָכֵן לְעוֹלָם יִירְשׁוּ אָרֶץ, רְאוּיִים לִירַשׁ אֶת הַגְּבִירָה. מָה הַטַּעַם נִקְרְאוּ צַדִּיקִים, וּמָה הַטַּעַם יוֹרְשִׁים אֶת הַגְּבִירָה? מִשּׁוּם שֶׁנִּמּוֹלוּ, כְּמוֹ שֶׁשָּׁנִינוּ, כָּל מִי שֶׁנִּמּוֹל וְנִכְנַס (בברית הקדש ונכנס בזו) בִּירֻשָּׁה זוֹ וְשָׁמַר אֶת הַבְּרִית הַזּוֹ, נִכְנָס וְנִדְבָּק בְּגוּף הַמֶּלֶךְ וְנִכְנָס בְּצַדִּיק זֶה, וְלָכֵן נִקְרְאוּ צַדִּיקִים, וְעַל כָּךְ לְעוֹלָם יִירְשׁוּ אָרֶץ. אֵיזוֹ אֶרֶץ? זוֹ אֶרֶץ הַחַיִּים.</p>\n<p>חָזַר וְאָמַר, נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. נֵצֶר מַטָּעַי - עָנָף מֵאוֹתָם עֲנָפִים שֶׁנָּטַע הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁבָּרָא אֶת הָעוֹלָם, שֶׁכָּתוּב (בראשית ב) וַיִּטַּע ה' אֱלֹהִים גַּן בְּעֵדֶן מִקֶּדֶם, וְאֶרֶץ זוֹ הִיא אֶחָד מֵהֶם, וּמִשּׁוּם כָּךְ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר.</p>\n<p>דָּבָר אַחֵר וְעַמֵּךְ כֻּלָּם צַדִּיקִים - זֶה יַעֲקֹב וּבָנָיו שֶׁיָּרְדוּ מִצְרַיְמָה בֵּין עַם קְשֵׁי עֹרֶף, וְנִמְצְאוּ כֻלָּם צַדִּיקִים, וְלָכֵן כָּתוּב לְעוֹלָם יִירְשׁוּ אָרֶץ, שֶׁמִּשָּׁם עָלוּ לָרֶשֶׁת אֶת הָאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>וַיְחִי יַעֲקֹב בְּאֶרֶץ מִצְרַיִם. לָמָּה פָּרָשָׁה זוֹ סְתוּמָה? רַבִּי יַעֲקֹב אָמַר, בְּשָׁעָה שֶׁמֵּת יַעֲקֹב, נִסְתְּמוּ עֵינֵיהֶם שֶׁל יִשְׂרָאֵל. רַבִּי יְהוּדָה אָמַר, שֶׁאָז יָרְדוּ לַגָּלוּת וְהִשְׁתַּעְבְּדוּ בָהֶם.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, מַה כָּתוּב לְמַעְלָה? וַיֵּשֶׁב יִשְׂרָאֵל בְּאֶרֶץ מִצְרַיִם בְּאֶרֶץ גֹּשֶׁן וַיֵּאָחֲזוּ בָהּ וַיִּפְרוּ וַיִּרְבּוּ מְאֹד, וְכָתוּב וַיְחִי יַעֲקֹב, שֶׁלֹּא רָאוּי לְהַפְרִיד בֵּין זֶה לָזֶה. מַה הֵם עוֹמְדִים בְּתַפְנוּקִים שֶׁל מְלָכִים וּמְקַבְּלִים לְעַצְמָם עֹנֶג וְכִסּוּפִים, אַף יַעֲקֹב גַּם עוֹמֵד בְּתַפְנוּקֵי מְלָכִים בְּעֹנֶג וְכִסּוּף לִעַצְמוֹ, לֹא נִפְרָד זֶה מִזֶּה.</p>\n<p>וְכָאןֹ נִקְרָא וַיְחִי, שֶׁהֲרֵי כָּל יָמָיו לֹא נִקְרָא וַיְחִי, מִשּׁוּם שֶׁכָּל יָמָיו הָיוּ בְצַעַר, בְּצַעַר נִמְצְאוּ, כָּתוּב עָלָיו (איוב ג) לֹא שָׁלַוְתִּי וְלֹא שָׁקַטְתִּי וְלֹא נָחְתִּי וַיָּבא רֹגֶז. אַחַר שֶׁיָּרַד לְמִצְרַיִם נִקְרָא וַיְחִי. רָאָה אֶת בְּנוֹ מֶלֶךְ, רָאָה אֶת כָּל בָּנָיו צַדִּיקִים וְכֻלָּם בְּתַפְנוּקֵי וְתַעֲנוּגוֹת הָעוֹלָם, וְהוּא יוֹשֵׁב בֵּינֵיהֶם כְּיַיִן טוֹב שֶׁשּׁוֹקֵט עַל שְׁמָרָיו, וְאָז נִקְרָא וַיְחִי יַעֲקֹב, וְלֹא הִפְרִיד בֵּין וַיִּפְרוּ וַיִּרְבּוּ מְאֹד לְבֵין וַיְחִי יַעֲקֹב, וְכָךְ רָאוּי.</p>\n<p>שְׁבַע עֶשְׂרֵה שָׁנָה. מָה הַטַּעַם שְׁבַע עֶשְׂרֵה שָׁנָה? אֶלָּא אָמַר רַבִּי שִׁמְעוֹן, כָּל יְמֵי יַעֲקֹב הָיוּ בְצַעַר. בְּצַעַר עָבַר אוֹתָם בַּהַתְחָלָה. כֵּיוָן שֶׁרָאָה אֶת יוֹסֵף וְהָיָה עוֹמֵד לְפָנָיו, כְּשֶׁיַּעֲקֹב מִסְתַּכֵּל בְּיוֹסֵף, הָיָה נִשְׁלָם בְּנַפְשׁוֹ כְּאִלּוּ רָאָה אֶת אִמּוֹ שֶׁל יוֹסֵף, שֶׁיָּפְיוֹ שֶׁל יוֹסֵף דּוֹמֶה לְיָפְיָהּ שֶׁל רָחֵל, וְהָיָה מְדַמֶּה בְעַצְמוֹ כְּמוֹ שֶׁלֹּא עָבַר עָלָיו צַעַר בְּיָמָיו.</p>\n<p>וּכְשֶׁיּוֹסֵף נִפְרַד מִמֶּנּוּ, אָז הִתְקַיֵּם בּוֹ, לֹא שָׁלַוְתִּי וְלֹא שָׁקַטְתִּי וְלֹא נָחְתִּי וַיָּבֹא רֹגֶז, שֶׁזֶּה הָיָה קָשֶׁה לְיַעֲקֹב מִכָּל מַה שֶּׁעָבַר. וּבִזְמַן שֶׁיּוֹסֵף נִפְרַד מִמֶּנּוּ מַה כָּתוּב? (בראשית לז) יוֹסֵף בֶּן שְׁבַע עֶשְׂרֵה שָׁנָה הָיָה רֹעֶה וְגוֹ'. וְכָל יְמֵי יַעֲקֹב לֹא הָיָה לוֹ צַעַר כָּזֶה, וְהָיָה בּוֹכֶה כָּל יוֹם עַל אוֹתָן שְׁבַע עֶשְׂרֵה שָׁנָה שֶׁל יוֹסֵף.</p>\n<p>מַה הֵשִׁיבוּ לוֹ? (שם מו) וְיוֹסֵף יָשִׁית יָדוֹ עַל עֵינֶיךְ. הֲרֵי לְךְ שְׁבַע עֶשְׂרֵה שָׁנִים אֲחֵרוֹת בְּעִנּוּגִים וְתַפְנוּקִים וַהֲנָאוֹת וְכִסּוּפִים. זֶהוּ שֶׁכָּתוּב וַיְחִי יַעֲקֹב בְּאֶרֶץ מִצְרַיִם שְׁבַע עֶשְׂרֵה שָׁנָה וְגוֹ'. שָׁנִינוּ, שֶׁכָּל אוֹתָן שָׁנִים שְׁכִינַת כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצְאָה עִמּוֹ, וְלָכֵן אֵלּוּ נִקְרְאוּ חַיִּים.</p>\n<p>בֹּא רְאֵה, כָּתוּב וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם. נִרְאֶה הָיָה שֶׁבַּתְּחִלָּה מֵתָה הָיְתָה אוֹתָהּ הָרוּחַ שֶׁלּוֹ וְלֹא הָיָה מִתְכַּוֵּן לְקַבֵּל רוּחַ אַחֶרֶת, שֶׁהֲרֵי רוּחַ שֶׁלְּמַעְלָה לֹא שׁוֹרָה בְּרֵיקָנוּת. אָמַר רַבִּי יוֹסֵי, שְׁכִינָה לֹא שׁוֹרָה אֶלָּא בְּמָקוֹם שָׁלֵם, וְלֹא בְּמָקוֹם חָסֵר, וְלֹא בְּמָקוֹם פָּגוּם, וְלֹא בְּמָקוֹם עָצוּב, אֶלָּא בְּמָקוֹם שֶׁהִתְכַּוֵּן, בִּמְקוֹם שִׂמְחָה, וְלָכֵן בְּכָל אוֹתָן שָׁנִים שֶׁיּוֹסֵף נִפְרַד מֵאָבִיו וְיַעֲקֹב הָיָה עָצוּב, לֹא שָׁרְתָה בּוֹ שְׁכִינָה.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי אֶלְעָזָר אָמַר רַבִּי אַבָּא, כָּתוּב (תהלים ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה בֹּאוּ לְפָנָיו בִּרְנָנָה. לְהוֹצִיא, שֶׁאֵין עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא מִתּוֹךְ חֶדְוָה. שֶׁאָמַר רַבִּי אֶלְעָזָר, אֵין שְׁכִינָה שׁוֹרָה מִתּוֹךְ עַצְבוּת, שֶׁכָּתוּב (מלכים ב ג) וְעַתָּה קְחוּ לִי מְנַגֵּן וְהָיָה כְּנַגֵּן הַמְנַגֵּן. מְנַגֵּן מְנַגֵּן שָׁלֹשׁ פְּעָמִים לְשֵׁם מָה? כְּדֵי לְעוֹרֵר רוּחַ מִשְּׁלֵמוּת הַכֹּל, שֶׁהוּא רוּחַ שָׁלֵם.</p>\n<p>אָמַר רַבִּי אַבָּא, שָׁם שָׁנִינוּ, הַכֹּל נִמְצָא מֵאַרְבָּעָה צְדָדִים, וְכָל הַשָּׁרָשִׁים שֶׁל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים בָּהֶם אֲחוּזִים. וְשָׁנִינוּ, זֶה נִכְנָס וְזֶה יוֹצֵא, זֶה סָתוּם וְזֶה מְפֹרָשׁ, אָחוּז אֶחָד בַּחֲבֵרוֹ, וְהֵם אֲבוֹת הַכֹּל.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, (דברים י) רַק בַּאֲבֹתֶיךְ חָשַׁק ה'. כָּתוּב בַּאֲבֹתֶיךְ, מַמָּשׁ שְׁלֹשָׁה, וּמַשְׁמָע שֶׁכָּתוּב רַק - רַק מַמָּשׁ, וּמֵאֵלֶּה נִפְרָדִים וְנֶאֱחָזִים כָּל שְׁאָר הָאֲחֵרִים וְעוֹלִים הַשֵּׁם לְהִתְעַטֵּר.</p>"],[9522011439,"<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, מִן הַיּוֹם שֶׁהִתְעַלָּה רַבִּי שִׁמְעוֹן מֵהַמְּעָרָה, הַדְּבָרִים הַלָּלוּ לֹא נִתְכַּסּוּ מִן הַחֲבֵרִים וּבְסוֹדוֹת עֶלְיוֹנִים הָיוּ מִסְתַּכְּלִים וּמִתְגַּלִּים מִבֵּינֵיהֶם, כְּאִלּוּ שֶׁנִּתְּנוּ בְּאוֹתָהּ שָׁעָה בְּהַר סִינַי, אַחַר שֶׁמֵּת כָּתוּב (בראשית ה) וַיִּסָּכְרוּ מַעְיְנוֹת תְּהוֹם וַאֲרֻבּוֹת הַשָּׁמַיִם, וְהָיוּ הַחֲבֵרִים מְרַחֲשִׁים דְּבָרִים, וְלֹא מִתְקַיְּמִים בָּהֶם.</p>\n<p>שֶׁיּוֹם אֶחָד הָיָה יוֹשֵׁב רַבִּי יְהוּדָה עַל פִּתְחָהּ שֶׁל טְבֶרְיָה וְרָאָה שְׁנֵי גְמַלִּים שֶׁמַּעֲלִים בִּגְדֵי צֶמֶר מֵעַל הַכְּתֵפַיִם. נָפַל הַמַּשָּׂא שֶׁל בִּגְדֵי הַצֶּמֶר, וּבָאוּ צִפֳּרִים, וְעַד שֶׁלֹּא הִגִּיעוּ עֲלֵיהֶם, הִתְבַּקְּעוּ.</p>\n<p>אַחַר כָּךְ בָּאוּ כַּמָּה צִפֳּרִים, וְהָיוּ הוֹלְכִים אַחֲרֵיהֶם, וְשָׁהוּ (וזרקו) אוֹתָם בְּסֶלַע, וְלֹא הִתְבַּקְּעוּ, וְהָיוּ צוֹוְחִים לָהֶם וְלֹא הָיוּ נִפְרָדִים. שָׁמְעוּ קוֹל אֶחָד עֲטֶרֶת הָעֲטָרוֹת שׁוֹרֶה בַּחֲשֵׁכָה וְהַבְּעָלִים בַּחוּץ.</p>\n<p>עַד שֶׁהָיָה יוֹשֵׁב, עָבַר אִישׁ אֶחָד, הִשְׁגִּיחַ בָּהֶם וְאָמַר, לֹא קִיֵּם זֶה מַה שֶּׁכָּתוּב (בראשית טו) וַיֵּרֶד הָעַיִט עַל הַפְּגָרִים וַיַּשֵּׁב אֹתָם אַבְרָם. אָמַר רַבִּי יְהוּדָה, וַהֲרֵי עָשִׂינוּ וְלֹא הִתְפָּרְדוּ. הֶחֱזִיר רֹאשׁוֹ אוֹתוֹ הָאִישׁ וְאָמַר, עֲדַיִן לֹא מָרַט זֶה רֹאשׁוֹ שֶׁל אֲדוֹנָיו וַעֲדַיִן לֹא הִקְרִיחַ אֶת הַגְּבִירָה. רָץ אַחֲרָיו שְׁלֹשָׁה מִילִין וְלֹא אָמַר לוֹ. חָלְשָׁה דַעְתּוֹ שֶׁל רַבִּי יְהוּדָה.</p>\n<p>יוֹם אֶחָד נִרְדַּם תַּחַת עֵץ וְרָאָה בַּחֲלוֹמוֹ אַרְבַּע כְּנָפָיִם מְתֻקָּנוֹת וְעוֹלֶה עֲלֵיהֶן רַבִּי שִׁמְעוֹן וְסֵפֶר תּוֹרָה עִמּוֹ, וְלֹא הִשְׁאִיר כָּל סִפְרֵי הַסּוֹדוֹת הָעֶלְיוֹנִים וְאַגָּדָה שֶׁלֹּא הֶעֱלָה אוֹתָם עִמּוֹ, וְהֶעֱלָה אוֹתָם (והעלו אותו) לָרָקִיעַ, וְרָאָה שֶׁהוּא מִתְכַּסֶּה מֵהָעֵינַיִם וְלֹא הִתְגַּלָּה.</p>\n<p>כְּשֶׁהִתְעוֹרֵר, אָמַר, וַדַּאי מִשֶּׁמֵּת רַבִּי שִׁמְעוֹן, הַחָכְמָה הִסְתַּלְּקָה מִן הָאָרֶץ. אוֹי לְדוֹר שֶׁהָאֶבֶן הַטּוֹבָה הַזּוֹ, שֶׁהָיוּ נִרְאִים (מתאחדים) מִמֶּנָּה וְסוֹמְכִים עָלֶיהָ עֶלְיוֹנִים וְתַחְתּוֹנִים, נֶאֶבְדָה מֵהֶם.</p>\n<p>בָּא אֶל רַבִּי אַבָּא, סִפֵּר לוֹ. הֵרִים רַבִּי אַבָּא אֶת יָדָיו עַל רֹאשׁוֹ וּבָכָה וְאָמַר, רַבִּי שִׁמְעוֹן רֵחַיִם שֶׁטּוֹחֲנוֹת מִמֶּנּוּ מָן טוֹב כָּל יוֹם וְלוֹקְטִים אוֹתוֹ, כַּכָּתוּב (במדבר יא) הַמַּמְעִיט אָסַף עֲשָׂרָה חֳמָרִים, וְעַכְשָׁו הָרֵחַיִם וְהַמָּן הִסְתַּלְּקוּ וְלֹא נִשְׁאָר מִמֶּנּוּ בָּעוֹלָם, פְּרָט לְמַה שֶּׁכָּתוּב (שמות טז) קַח צִנְצֶנֶת אַחַת וְתֶן שָׁמָּה מְלֹא הָעֹמֶר מָן וְהַנַּח אוֹתוֹ לִפְנֵי ה' לְמִשְׁמֶרֶת. וְאִלּוּ בְּהִתְגַּלּוּת לֹא כָתוּב אֶלָּא לְמִשְׁמֶרֶת, לְהַצְנָעָה. עַכְשָׁו מִי יָכוֹל לְגַלּוֹת סוֹדוֹת וּמִי יֵדַע אוֹתָם.</p>\n<p>לָחַשׁ לוֹ לְרַבִּי יְהוּדָה בְּלַחַשׁ, (אמר לו רבי אבא) וַדַּאי אוֹתוֹ אִישׁ שֶׁרָאִיתָ הָיָה אֵלִיָּהוּ, וְלֹא רָצָה לְגַלּוֹת סוֹדוֹת כְּדֵי שֶׁתֵּדַע אֶת שִׁבְחוֹ שֶׁל רַבִּי שִׁמְעוֹן שֶׁהָיָה בְּיָמָיו וְיִבְכּוּ הַדּוֹר עָלָיו. אָמַר לוֹ, מַסְפִּיק לִבְכּוֹת בְּכִיָּה עָלָיו.</p>\n<p>רַבִּי יְהוּדָה הָיָה בּוֹכֶה כָּל יוֹם עָלָיו, שֶׁהֲרֵי נִפְגַּשׁ עִמּוֹ בָּאִדְרָא הַקְּדוֹשָׁה שֶׁל רַבִּי שִׁמְעוֹן וּשְׁאָר הַחֲבֵרִים. אָמַר לוֹ, אוֹי שֶׁלֹּא הִסְתַּלַּקְתִּי אוֹתוֹ יוֹם עִם אוֹתָם שְׁלֹשָׁה שֶׁהִסְתַּלְּקוּ, וְלֹא לִרְאוֹת דּוֹר זֶה, שֶׁהֲרֵי מִתְהַפֵּךְ.</p>\n<p>אָמַר לוֹ, רַבִּי, אֱמֹר לִי, כָּתוּב (שם כח) וְהֵם יִקְחוּ אֶת הַזָּהָב וְאֶת הַתְּכֵלֶת וְאֶת הָאַרְגָּמָן וְאֶת תּוֹלַעַת הַשָּׁנִי וְאֶת הַשֵּׁשׁ, וְאִלּוּ כֶּסֶף לֹא כָתוּב, וַהֲרֵי כָּתוּב זָהָב וָכֶסֶף? אָמַר לוֹ, וַהֲרֵי גַּם נְחֹשֶׁת, שֶׁכֶּסֶף וּנְחֹשֶׁת הָיוּ בַּחֶשְׁבּוֹן, וְכָאן לֹא. אֶלָּא אִם לֹא שֶׁגִּלָּה הַמְּנוֹרָה הַקְּדוֹשָׁה בִּמְקוֹמוֹ - לֹא הִצְטָרַכְתִּי לְגַלּוֹת.</p>"],[9522011440,"<p>פָּתַח וְאָמַר, (חגי ב) לִי הַכֶּסֶף וְלִי הַזָּהָב נְאֻם ה'. הַיְנוּ שֶׁכָּתוּב (תהלים קטו) הַשָּׁמַיִם שָׁמַיִם לַה'.</p>\n<p>בְּכַמָּה מְקוֹמוֹת הִסְתַּכַּלְתִּי בִּכְלֵי הַקֹּדֶשׁ הַלָּלוּ, שֶׁכָּתוּב (ויקרא טז) בִּגְדֵי קֹדֶשׁ הֵם, וְכָתוּב (שמות כח) וְעָשׂוּ בִּגְדֵי קֹדֶשׁ. אֵיזוֹ קְדֻשָּׁה כָּאן? אֶלָּא כָּךְ שָׁנִינוּ, קְדֻשָּׁה הֵם בְּכָל מָקוֹם, וְכָתוּב בִּגְדֵי קֹדֶשׁ הֵם. וְעָשִׂיתָ בִּגְדֵי קֹדֶשׁ, כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>שֶׁלָּמַדְנוּ, כֹּהֵן גָּדוֹל לְמַעְלָה, כֹּהֵן גָּדוֹל לְמַטָּה. לְבוּשֵׁי כָבוֹד לְמַעְלָה, וּלְבוּשֵׁי כָבוֹד לְמַטָּה. וּמַה שֶּׁלֹּא אָמַר כֶּסֶף וּנְחֹשֶׁת, לְמָקוֹם אַחֵר הֵם הִתְעַלּוּ, שֶׁכָּתוּב (שם כז) כָּל עַמּוּדֵי הֶחָצֵר סָבִיב מְחֻשָּׁקִים כֶּסֶף וְגוֹ', וְכָתוּב וְאַדְנֵיהֶם נְחֹשֶׁת, שֶׁהֵם כֵּלִים לְשִׁמּוּשׁ שֶׁהַמִּשְׁכָּן יִשְׁתַּמֵּשׁ בָּהֶם.</p>\n<p>אֲבָל כָּאן בִּלְבוּשֵׁי כָבוֹד הָאֵלּוּ לֹא צָרִיךְ לְהִשְׁתַּמֵּשׁ בָּהֶם אָדָם אַחֵר, פְּרָט לַכֹּהֵן הַגָּדוֹל שֶׁשֶּׁמֶן מִשְׁחַת קֹדֶשׁ עַל רֹאשׁוֹ, שֶׁכָּתוּב (שם כח) וְעָשִׂיתָ בִּגְדֵי קֹדֶשׁ לְאַהֲרֹן אָחִיךְ לְכָבוֹד וּלְתִפְאָרֶת, שֶׁבְּאוֹתָם לְבוּשִׁים הוּא דוֹמֶה לַגָּוֶן שֶׁלְּמַעְלָה.</p>"],[9522011441,"<p>לָמַדְנוּ, וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת. אָמַר רַבִּי יְהוּדָה, אוֹי לָעוֹלָם, שֶׁהֲרֵי בְּנֵי אָדָם לֹא רוֹאִים וְלֹא שׁוֹמְעִים וְלֹא יוֹדְעִים, שֶׁהֲרֵי כָּל יוֹם וָיוֹם קוֹל הַכָּרוֹז נִשְׁמָע בְּמָאתַיִם חֲמִשִּׁים עוֹלָמוֹת.</p>\n<p>שָׁנִינוּ, עוֹלָם אֶחָד נוֹדַע לְמַעְלָה, וּכְשֶׁהַכָּרוֹז יוֹצֵא, אוֹתוֹ הָעוֹלָם מִזְדַּעְזֵעַ וּמִתְחַלְחֵל יוֹצְאוֹת שְׁתֵּי צִפֳּרִים שֶׁעוֹלוֹת מֵאוֹתוֹ הָעוֹלָם, שֶׁמְּדוֹרָם תַּחַת הָעֵץ שֶׁבּוֹ מַרְאֵה הַחַיִּים וְהַמָּוֶת.</p>\n<p>יוֹצֵאת צִפּוֹר אַחַת לְצַד דָּרוֹם, וְצִפּוֹר אַחַת לְצַד צָפוֹן, וְצִפּוֹר אַחַת כְּשֶׁמֵּאִיר הַיּוֹם, וְאַחַת כְּשֶׁנֶּחְשַׁךְ הַיּוֹם, וְכָל אַחַת וְאַחַת קוֹרֵאת וּמַכְרִיזָה מַה שֶּׁשּׁוֹמְעִים מֵאוֹתוֹ כָּרוֹז.</p>\n<p>אַחַר כָּךְ רוֹצוֹת לְהִתְעַלּוֹת לִמְקוֹמָן, וְנִשְׁמָטוֹת רַגְלֵיהֶן בְּנֶקֶב תְּהוֹם רַבָּה, וְנִלְכָּדוֹת בְּתוֹכָהּ עַד שֶׁנֶּחֱלָק הַלַּיְלָה. וּכְשֶׁנֶּחֱלַק הַלַּיְלָה, הַכָּרוֹז קוֹרֵא: (קהלת ט) וְכַצִּפֳּרִים הָאֲחֻזוֹת בַּפָּח כָּהֵם יוּקָשִׁים בְּנֵי הָאָדָם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בְּשָׁעָה שֶׁנִּלְכָּדוֹת רַגְלֵי בְּנֵי הָאָדָם וְיָמָיו מִתְקָרְבִים, אוֹתוֹ יוֹם נִקְרָא יוֹם ה' לְהָשִׁיב רוּחוֹ אֵלָיו. שָׁנִינוּ, בְּאוֹתָהּ שָׁעָה פּוֹקֵד אוֹתוֹ הַכֶּתֶר הַקָּדוֹשׁ עַל רוּחוֹ, וּמִיהוּ? שֶׁכָּתוּב (תהלים צ) יְמֵי שְׁנוֹתֵינוּ בָהֶם שִׁבְעִים שָׁנָה. וְהִיא כֶּתֶר שֶׁל שְׁבִיעִי שֶׁל הַכֹּל.</p>\n<p>וְאִם מִצַּד הַגְּבוּרָה הוּא בָּא - כָּתוּב וְאִם בִּגְבוּרוֹת שְׁמֹנִים שָׁנָה, שֶׁכֶּתֶר הַגְּבוּרָה הוּא הֲרֵי שְׁמִינִי. מִכָּאן וָהָלְאָה אֵין מָקוֹם לְהִמָּשֵׁךְ, כְּמוֹ שֶׁנֶּאֱמַר וְרָהְבָּם עָמָל וָאָוֶן. בְּמָקוֹם שֶׁלֹּא הָיָה יְסוֹד, הַבִּנְיָן לֹא עוֹמֵד.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אַשְׁרֵיהֶם הַצַּדִּיקִים, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהָשִׁיב אֵלָיו אֶת רוּחוֹ אֵלָיו וְלִשְׁאֹב אוֹתָהּ רוּחַ לְתוֹכוֹ. שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָשִׁיב אֵלָיו אֶת רוּחוֹ, אִם רוּחַ זוֹ הִיא שֶׁל צַדִּיק, מַה כָּתוּב? (קהלת יב) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ.</p>\n<p>וְאִם לֹא נִמְצָא צַדִּיק, אוֹי לְאוֹתָהּ רוּחַ שֶׁצְּרִיכָה לִרְחֹץ בְּאֵשׁ שֶׁדּוֹלֶקֶת וּלְהִתַּקֵּן כְּדֵי לְהִשָּׁאֵב לְגוּף הַמֶּלֶךְ. וְאִם לֹא נִתְקֶנֶת, אוֹי לְאוֹתָהּ רוּחַ שֶׁמִּתְגַּלְגֶּלֶת כְּאֶבֶן בְּכַף הַקֶּלַע, שֶׁכָּתוּב (שמואל א כה) וְאֶת נֶפֶשׁ אֹיְבֶיךְ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע. שָׁנִינוּ, אִם אוֹתָהּ רוּחַ זוֹכָה, כַּמָּה טוֹבוֹת גְּנוּזִים לָהּ בְּאוֹתוֹ עוֹלָם שֶׁכָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כְּשֶׁמִּתְקָרְבִים יְמֵי אוֹתוֹ הָאִישׁ, שְׁלֹשִׁים יוֹם מַכְרִיזִים עָלָיו בָּעוֹלָם, וַאֲפִלּוּ צִפֳּרֵי הַשָּׁמַיִם מַכְרִיזִים עָלָיו. וְאִם צַדִּיק הוּא, שְׁלֹשִׁים יוֹם מַכְרִיזִים עָלָיו בֵּין הַצַּדִּיקִים בְּגַן עֵדֶן.</p>\n<p>שָׁנִינוּ, כָּל אוֹתָם שְׁלֹשִׁים יָמִים נִשְׁמָתוֹ יוֹצֵאת מִמֶּנּוּ בְּכָל לַיְלָה, וְעוֹלָה וְרוֹאָה אֶת מְקוֹמָהּ בְּאוֹתוֹ הָעוֹלָם, וְאוֹתוֹ אָדָם לֹא יוֹדֵעַ וְלֹא מַשְׁגִּיחַ וְלֹא שׁוֹלֵט בְּנִשְׁמָתוֹ כָּל אוֹתָם שְׁלֹשִׁים יוֹם כְּמוֹ שֶׁהָיָה בַּתְּחִלָּה, שֶׁכָּתוּב (קהלת ח) אֵין אָדָם שַׁלִּיט בָּרוּחַ לִכְלֹא אֶת הָרוּחַ וְגוֹ'. אָמַר רַבִּי יְהוּדָה, מִכְּשֶׁמַּתְחִילִים אוֹתָם שְׁלֹשִׁים יוֹם, צֶלֶם הָאָדָם נֶחְשָׁךְ, וְהַדְּמוּת שֶׁנִּרְאֵית בָּאָרֶץ נִמְנַעַת.</p>"],[9522011442,"<p>רַבִּי יִצְחָק הָיָה יוֹשֵׁב יוֹם אֶחָד עַל פִּתְחוֹ שֶׁל רַבִּי יְהוּדָה וְהָיָה עָצוּב. יָצָא רַבִּי יְהוּדָה וּמָצָא אוֹתוֹ בַּשַּׁעַר שֶׁלּוֹ שֶׁהָיָה יוֹשֵׁב וְעָצוּב. אָמַר לוֹ, מַה יּוֹם זֶה מִשְּׁאָר יָמִים?</p>\n<p>אָמַר לוֹ, בָּאתִי אֵלֶיךְ לְבַקֵּשׁ מִמְּךְ שְׁלֹשָׁה דְבָרִים. אֶחָד - שֶׁכַּאֲשֶׁר תֹּאמַר דִּבְרֵי תוֹרָה וְתַזְכִּיר מֵאוֹתָם דְּבָרִים שֶׁאֲנִי אָמַרְתִּי, שֶׁתֹּאמַר אוֹתָם בִּשְׁמִי, כְּדֵי לְהַזְכִּיר אֶת שְׁמִי. וְאֶחָד - שֶׁתְּזַכֶּה אֶת יוֹסֵף בְּנִי בַּתּוֹרָה. וְאֶחָד - שֶׁתֵּלֵךְ לְקִבְרִי כָּל שִׁבְעַת הַיָּמִים וּתְבַקֵּשׁ בַּקָּשָׁתְךְ עָלַי.</p>\n<p>אָמַר לוֹ, מִנַּיִן לְךְ? אָמַר לוֹ, הֲרֵי נִשְׁמָתִי מִסְתַּלֶּקֶת מִמֶּנִּי בְּכָל לַיְלָה, וְלֹא מְאִירָה לִי בַּחֲלוֹם כְּמוֹ שֶׁהָיְתָה בַּתְּחִלָּה. וְעוֹד, שֶׁכַּאֲשֶׁר אֲנִי מִתְפַּלֵּל וּמַגִּיעַ לְשׁוֹמֵעַ תְּפִלָּה, אֲנִי מַשְׁגִּיחַ בְּצַלְמִי שֶׁבַּכֹּתֶל וְלֹא רוֹאֶה אוֹתוֹ, וְאָמַרְתִּי, הוֹאִיל וְהַצֶּלֶם הָעֳבַר וְלֹא נִרְאֶה, שֶׁהֲרֵי הַכָּרוֹז יוֹצֵא וּמַכְרִיז, שֶׁכָּתוּב (תהלים לט) אַךְ בְּצֶלֶם יִתְהַלֵּךְ אִישׁ - כָּל זְמַן שֶׁצֶּלֶם הָאָדָם לֹא יַעֲבֹר מִמֶּנּוּ, יִתְהַלֵּךְ אִישׁ וְרוּחוֹ עוֹמֶדֶת בְּתוֹכוֹ. כְּשֶׁהָעֳבַר צֶלֶם הָאָדָם וְלֹא נִרְאֶה, אָז הוּא מָעֳבָר מֵהָעוֹלָם הַזֶּה.</p>\n<p>אָמַר לוֹ, וּמִכָּאן, שֶׁכָּתוּב (איוב ח) כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ. אָמַר לוֹ, כָּל הַדְּבָרִים הַלָּלוּ שֶׁאַתָּה רוֹצֶה שֶׁאֲנִי אֶעֱשֶׂה, אֲבָל אֲבַקֵּשׁ מִמְּךְ, שֶׁבְּאוֹתוֹ עוֹלָם תְּבָרֵר אֶת מְקוֹמִי אֶצְלְךְ כְּמוֹ שֶׁהָיִיתִי בָּעוֹלָם הַזֶּה. בָּכָה רַבִּי יִצְחָק וְאָמַר, בְּבַקָּשָׁה מִמְּךְ שֶׁלֹּא תִפָּרֵד מִמֶּנִּי כָּל הַיָּמִים הַלָּלוּ.</p>\n<p>הָלְכוּ לְרַבִּי שִׁמְעוֹן, מְצָאוּהוּ שֶׁהָיָה יוֹשֵׁב וְעוֹסֵק בַּתּוֹרָה. זָקַף עֵינָיו רַבִּי שִׁמְעוֹן וְרָאָה אֶת רַבִּי יִצְחָק, וְרָאָה אֶת מַלְאַךְ הַמָּוֶת שֶׁרָץ לְפָנָיו וְרוֹקֵד לְפָנָיו. קָם רַבִּי שִׁמְעוֹן, וְאָחַז בְּיַד רַבִּי יִצְחָק. אָמַר, גּוֹזְרַנִי שֶׁמִּי שֶׁרָגִיל לְהִכָּנֵס - יִכָּנֵס, וּמִי שֶׁלֹּא רָגִיל לְהִכָּנֵס - לֹא יִכָּנֵס. נִכְנְסוּ רַבִּי יִצְחָק וְרַבִּי יְהוּדָה, קָשַׁר אֶת מַלְאַךְ הַמָּוֶת בַּחוּץ.</p>\n<p>הִתְבּוֹנֵן רַבִּי שִׁמְעוֹן, וְרָאָה שֶׁעַד עַכְשָׁו טֶרֶם הִגִּיעַ זְמַן, שֶׁהֲרֵי עַד שְׁמֹנֶה שָׁעוֹת שֶׁל הַיּוֹם הָיָה זְמַן. הוֹשִׁיבוֹ לִפְנֵי רַבִּי שִׁמְעוֹן וְהָיָה מְלַמְּדוֹ בַּתּוֹרָה. אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אֶלְעָזָר בְּנוֹ, שֵׁב עַל הַפֶּתַח, וּמַה (ומי) שֶּׁתִּרְאֶה אַל תְּדַבֵּר עִמּוֹ. אִם יִרְצֶה לְהִכָּנֵס לְכָאן, תַּשְׁבִּיעַ אוֹתוֹ שְׁבוּעָה שֶׁלֹּא יִכָּנֵס.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי יִצְחָק, רָאִיתָ אֶת דְּמוּת אָבִיךְ הַיּוֹם אוֹ לֹא? שֶׁהֲרֵי שָׁנִינוּ, בְּשָׁעָה שֶׁאָדָם מִסְתַּלֵּק מִן הָעוֹלָם, אָבִיו וּקְרוֹבָיו נִמְצָאִים שָׁם, וְרוֹאֶה אוֹתָם וְנוֹדָע לָהֶם, וְכָל אוֹתָם שֶׁיִּהְיֶה מְדוֹרוֹ עִמָּם שֶׁבְּאוֹתוֹ עוֹלָם בְּדַרְגָּה אַחַת, כֻּלָּם מִתְכַּנְּסִים וְנִמְצָאִים עִמּוֹ, וְהוֹלְכִים עִם נִשְׁמָתוֹ עַד הַמָּקוֹם שֶׁתִּשְׁרֶה בִמְקוֹמָהּ. אָמַר, עַד עַכְשָׁו לֹא רָאִיתִי.</p>\n<p>בֵּין כָּךְ קָם רַבִּי שִׁמְעוֹן וְאָמַר, רִבּוֹן הָעוֹלָם, נוֹדָע רַבִּי יִצְחָק אֶצְלֵנוּ, וְהוּא מֵאוֹתָן שֶׁבַע עֵינַיִם שֶׁל כָּאן. הֲרֵי אָחַזְתִּי אוֹתוֹ וְתֵן לִי. יָצָא קוֹל וְאָמַר: כִּסֵּא אֲדוֹנֵנוּ קָרְבָה בְּכַנְפֵי רַבִּי שִׁמְעוֹן, הֲרֵי הוּא שֶׁלְּךְ וְעִמְּךְ יָבֹא בִּזְמַן שֶׁתִּכָּנֵס לִשְׁרוֹת בְּכִסְאֲךְ. אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי.</p>\n<p>בֵּין כָּךְ רָאָה רַבִּי אֶלְעָזָר שֶׁהָיָה מִסְתַּלֵּק מַלְאַךְ הַמָּוֶת, וְאָמַר, אֵין גְּזַר דִּין בְּמָקוֹם שֶׁמָּצוּי רַבִּי שִׁמְעוֹן בַּר יוֹחַאי. אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אֶלְעָזָר בְּנוֹ, תִּכָּנֵס לְכָאן וֶאֱחֹז בְּרַבִּי יִצְחָק, שֶׁהֲרֵי רָאִיתִי בוֹ שֶׁהוּא פּוֹחֵד. נִכְנַס רַבִּי אֶלְעָזָר וְאָחַז בּוֹ, וְרַבִּי שִׁמְעוֹן הֶחֱזִיר פָּנָיו וְלָמַד תּוֹרָה.</p>\n<p>נִרְדַּם רַבִּי יִצְחָק וְרָאָה אֶת אָבִיו. אָמַר לוֹ, בְּנִי, אַשְׁרֵי חֶלְקְךְ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהֲרֵי בֵּין הֶעָלִים שֶׁל עֵץ הַחַיִּים שֶׁבְּגַן עֵדֶן נָתוּן (אתה יושב) עֵץ גָּדוֹל וְחָזָק בִּשְׁנֵי עוֹלָמוֹת, וְהוּא רַבִּי שִׁמְעוֹן בַּר יוֹחַאי, שֶׁהֲרֵי הוּא אוֹחֵז אוֹתְךְ בַּעֲנָפָיו. אַשְׁרֵי חֶלְקְךְ בְּנִי.</p>\n<p>אָמַר לוֹ, אַבָּא, וּמָה אֲנִי שָׁם? אָמַר לוֹ, שְׁלֹשָׁה יָמִים הָיוּ שֶׁכִּסּוּ אֶת חֲדַר מִשְׁכָּבְךְ, וְתִקְּנוּ לְךְ חַלּוֹנוֹת פְּתוּחִים לְהָאִיר לְךְ מֵאַרְבַּעַת צִדְדֵי העוֹלָם, וַאֲנִי רָאִיתִי מְקוֹמְךְ וְשָׂמַחְתִּי, שֶׁאָמַרְתִּי אַשְׁרֵי חֶלְקְךְ בְּנִי, מִחוּץ לָזֶה שֶׁעַד עַכְשָׁו לֹא זָכָה בִּנְךְ בַּתּוֹרָה.</p>\n<p>וַהֲרֵי עַכְשָׁו הָיוּ עֲתִידִים לָבא אֵלֶיךְ שְׁנֵים עָשָׂר צַדִּיקִים מֵהַחֲבֵרִים, וְעַד שֶׁהָיוּ יוֹצְאִים הִתְעוֹרֵר קוֹל בְּכָל הָעוֹלָמוֹת: מִי הֵם הַחֲבֵרִים (השבילים) שֶׁעוֹמְדִים כָּאן? הִתְעַטְּרוּ בִּשְׁבִיל רַבִּי שִׁמְעוֹן, בַּקָּשָׁה בִּקֵּשׁ וְנִתְּנָה לוֹ.</p>\n<p>וְלֹא זֶה לְבַדּוֹ, שֶׁהֲרֵי שִׁבְעִים מְקוֹמוֹת מִתְעַטְּרִים כָּאן בִּשְׁבִילוֹ, וּבְכָל מָקוֹם וּמָקוֹם פְּתוּחִים פְּתָחִים לְשִׁבְעִים עוֹלָמוֹת, וְכָל עוֹלָם וְעוֹלָם נִפְתָּח לְשִׁבְעִים רָצִים, וְכָל רָץ וְרָץ נִפְתָּח לְשִׁבְעִים כְּתָרִים עֶלְיוֹנִים, וּמִשָּׁם נִפְתְּחוּ דְרָכִים לְעַתִּיק, נִסְתַּר הַכֹּל, לִרְאוֹת בְּאוֹתָהּ נְעִימוּת עֶלְיוֹנָה שֶׁמְּאִירָה וּמְהַנָּה לַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (תהלים פז) לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ. מַה זֶּה וּלְבַקֵּר בְּהֵיכָלוֹ? הַיְנוּ שֶׁכָּתוּב (במדבר יב) בְּכָל בֵּיתִי נֶאֱמָן הוּא.</p>"],[9522011443,"<p>אָמַר לוֹ, אַבָּא, כַּמָּה זְמַן נָתְנוּ לִי בָּעוֹלָם הַזֶּה? אָמַר לוֹ, אֵין רְשׁוּת וְלֹא מוֹדִיעִים לְאָדָם, אֲבָל בַּהִלּוּלָא הַגְּדוֹלָה שֶׁל רַבִּי שִׁמְעוֹן תִּהְיֶה עוֹרֵךְ שֻׁלְחָנוֹ, כְּמוֹ שֶׁנֶּאֱמַר צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה בָּעֲטָרָה שֶׁעִטְּרָה לוֹ אִמּוֹ בְּיוֹם חֲתֻנָּתוֹ וּבְיוֹם שִׂמְחַת לִבּוֹ.</p>\n<p>בֵּין כָּךְ הִתְעוֹרֵר רַבִּי יִצְחָק, וְהָיָה צוֹחֵק וּפָּנָיו מְאִירִים. רָאָה רַבִּי שִׁמְעוֹן, וְהִסְתַּכֵּל בְּפָנָיו. אָמַר לוֹ, דָּבָר חָדָשׁ שָׁמַעְתָּ? אָמַר לוֹ, וַדַּאי. אָמַר לוֹ. הִשְׁתַּטַּח לִפְנֵי רַבִּי שִׁמְעוֹן.</p>\n<p>לָמַדְנוּ, מֵאוֹתוֹ יוֹם הָיָה רַבִּי יִצְחָק אוֹחֵז אֶת בְּנוֹ בְּיָדוֹ וּמְלַמֵּד אוֹתוֹ תּוֹרָה, וְלֹא הָיָה עוֹזֵב אוֹתוֹ. כְּשֶׁהָיָה נִכְנַס לִפְנֵי רַבִּי שִׁמְעוֹן, הוֹשִׁיב אֶת בְּנוֹ בַּחוּץ, וְיָשַׁב לִפְנֵי רַבִּי שִׁמְעוֹן, וְהָיָה קוֹרֵא לְפָנָיו, (ישעיה לח) ה' עָשְׁקָה לִי עָרְבֵנִי.</p>\n<p>לָמַדְנוּ, בְּאוֹתוֹ יוֹם תַּקִּיף וּמַפְחִיד שֶׁל הָאָדָם, כְּשֶׁמַּגִּיעַ זְמַנּוֹ לְהִסְתַּלֵּק מֵהָעוֹלָם, אַרְבַּעַת צִדְדֵי הָעוֹלָם עוֹמְדִים בַּדִּין הַקָּשֶׁה, וּמִתְעוֹרְרִי דִּינִים מֵאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְאַרְבָּעָה קְשָׁרִים נִיצִים, וּקְטָטָה נִמְצֵאת בֵּינֵיהֶם, וְרוֹצִים לְהַפְרִיד כָּל אֶחָד לְצִדּוֹ.</p>\n<p>הַכָּרוֹז יוֹצֵא וּמַכְרִיז בְּאוֹתוֹ הָעוֹלָם, וְנִשְׁמָע בְּמָאתַיִם שִׁבְעִים עוֹלָמוֹת. אִם צַדִּיק הוּא - כָּל הָעוֹלָמוֹת שְׂמֵחִים כְּנֶגְדּוֹ, וְאִם לֹא - אוֹי לְאוֹתוֹ הָאִישׁ וּלְחֶלְקוֹ.</p>\n<p>לָמַדְנוּ, בְּאוֹתוֹ הַזְּמַן שֶׁהַכָּרוֹז מַכְרִיז, אָז יוֹצֵאת שַׁלְהֶבֶת מִצַּד צָפוֹן, וְהוֹלֶכֶת וּבוֹעֶרֶת בִּנְהַר דִּינוּר, וְנִפְרֶדֶת לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְשׂוֹרֶפֶת אֶת נִשְׁמוֹת הָרְשָׁעִים.</p>\n<p>וְיוֹצֵאת אוֹתָהּ שַׁלְהֶבֶת וְעוֹלָה וְיוֹרֶדֶת בָּעוֹלָם, וְאוֹתָהּ שַׁלְהֶבֶת מַגִּיעָה לְכַנְפֵי הַתַּרְנְגוֹל הַשָּׁחֹר, וּמַכֶּה בִּכְנָפָיו וְקוֹרֵא בַפֶּתַח בֵּין הַשְּׁעָרִים.</p>\n<p>פַּעַם רִאשׁוֹנָה קוֹרֵא וְאוֹמֵר, (מלאכי ג) הִנֵּה הַיּוֹם בָּא בֹּעֵר כַּתַּנּוּר וְגוֹ'. פַּעַם שְׁנִיָּה קוֹרֵא וְאוֹמֵר, (עמוס ד) כִּי הִנֵּה יוֹצֵר הָרִים וּבֹרֵא רוּחַ וּמַגִּיד לְאָדָם מַה שֵּׂחוֹ. וְאוֹתָהּ שָׁעָה יוֹשֵׁב בֶּן אָדָם בְּמַעֲשָׂיו שֶׁמְּעִידִים לְפָנָיו, וְהוּא מוֹדֶה עֲלֵיהֶם. פַּעַם שְׁלִישִׁית, כְּשֶׁרוֹצִים לְהוֹצִיא מִמֶּנּוּ אֶת נִשְׁמָתוֹ, קוֹרֵא הַתַּרְנְגוֹל וְאוֹמֵר, (ירמיה י) מִי לֹא יִרָאֲךְ מֶלֶךְ הַגּוֹיִם כִּי לְךְ יָאָתָה וְגוֹ'.</p>\n<p>אָמַר רַבִּי יוֹסֵי, תַּרְנְגוֹל שָׁחֹר לָמָּה יוֹצֵא? אָמַר לוֹ רַבִּי יְהוּדָה, כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ, הַכֹּל רָמוּז בַּחָכְמָה, רַק שֶׁבְּנֵי אָדָם לֹא יוֹדְעִים. זֶהוּ שֶׁכָּתוּב (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ מָלְאָה הָאָרֶץ קִנְיָנֶךְ. וּמִשּׁוּם שֶׁנַּעֲשׂוּ בְחָכְמָה, כֻּלָּם רְמוּזִים בַּחָכְמָה.</p>\n<p>וְהַתַּרְנְגוֹל הַשָּׁחֹר, שָׁנִינוּ, אֵין דִּין שׁוֹרֶה אֶלָּא בְּמָקוֹם שֶׁהוּא מִינוֹ, וְשָׁחֹר בָּא מִצַּד הַדִּין. וְלָכֵן בַּחֲצוֹת הַלַּיְלָה מַמָּשׁ, כְּשֶׁמִּתְעוֹרֶרֶת רוּחַ שֶׁל צַד צָפוֹן, שַׁלְהֶבֶת אַחַת יוֹצֵאת וּמַכָּה תַּחַת כַּנְפֵי הַתַּרְנְגוֹל וְהוּא קוֹרֵא. וְכָל שֶׁכֵּן בְּתַרְנְגוֹל שָׁחֹר, שֶׁמִּתְכַּוֵּן יוֹתֵר מֵאַחֵר.</p>\n<p>אַף כָּאן, בְּשָׁעָה שֶׁדִּין הָאָדָם יִתְעוֹרֵר, מַתְחִיל וְקוֹרֵא לוֹ, וְאֵין מִי שֶׁיּוֹדֵעַ בָּזֶה, פְּרָט לְאוֹתוֹ אִישׁ שֶׁשּׁוֹכֵב. שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁהָאִישׁ שׁוֹכֵב וְהַדִּין שָׁרוּי עָלָיו לְהוֹצִיא מֵהָעוֹלָם הַזֶּה, מִתּוֹסֶפֶת בּוֹ רוּחַ עֶלְיוֹנָה מַה שֶּׁלֹּא הָיָה בְּיָמָיו, וְכֵיוָן שֶׁשּׁוֹרָה עָלָיו וְנִדְבֶּקֶת בּוֹ, רוֹאֶה מַה שֶּׁלֹּא זָכָה בְּיָמָיו, מִשּׁוּם שֶׁהִתּוֹסְפָה בּוֹ אוֹתָהּ הָרוּחַ. וּכְשֶׁמִּתּוֹסֶפֶת בּוֹ וְרוֹאֶה, אָז יוֹצֵא מֵהָעוֹלָם הַזֶּה. זֶהוּ שֶׁכָּתוּב (שם) תֹּסֵף רוּחָם יִגְוָעוּן וְאֶל עֲפָרָם יְשׁוּבוּן. אָז כָּתוּב (שמות לג) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי. בְּחַיֵּיהֶם לֹא זוֹכִים, בְּמִיתָתָם זוֹכִים.</p>\n<p>לָמַדְנוּ, בְּשָׁעָה שֶׁאָדָם מֵת, נִתְּנָה לוֹ רְשׁוּת לִרְאוֹת, וְרוֹאֶה אֶצְלוֹ קְרוֹבָיו וַחֲבֵרָיו מֵאוֹתוֹ הָעוֹלָם, וְנוֹדָע לָהֶם, וְכֻלָּם חֲקוּקִים בִּדְמֻיּוֹתֵיהֶם כְּמוֹ שֶׁהָיוּ בָּעוֹלָם הַזֶּה. אִם צַדִּיק אוֹתוֹ הָאִישׁ, כֻּלָּם שְׂמֵחִים לְפָנָיו וּמַקְדִּימִים לוֹ שָׁלוֹם.</p>\n<p>וְאִם אֵינוֹ צַדִּיק, לֹא נוֹדָעִים אֵלָיו. פְּרָט לְאוֹתָם הָרְשָׁעִים שֶׁטּוֹרְדִים אוֹתָם בְּכָל יוֹם בַּגֵּיהִנֹּם, וְכֻלָּם עֲצוּבִים וּפוֹתְחִים בְּוַי וּמְסַיְּמִים בְּוַי, וּמֵרִים עֵינָיו וְרוֹאֶה אוֹתָם כְּמוֹ גֵץ שֶׁעוֹלֶה מֵהָאֵשׁ. אַף כָּךְ הוּא פּוֹתֵחַ וַי.</p>\n<p>לָמַדְנוּ, בְּשָׁעָה שֶׁיּוֹצֵאת נִשְׁמַת הָאָדָם, הוֹלְכִים כָּל קְרוֹבָיו וַחֲבֵרָיו שֶׁבְּאוֹתוֹ עוֹלָם עִם נִשְׁמתוֹ, וּמַרְאִים לוֹ מְקוֹם הָעִדּוּן וּמְקוֹם הָעֹנֶשׁ. אִם הוּא צַדִּיק, רוֹאֶה אֶת מְקוֹמוֹ, וְעוֹלֶה וְיוֹשֵׁב וּמִתְעַדֵּן בְּעִדּוּן עֶלְיוֹן שֶׁל אוֹתוֹ עוֹלָם. וְאִם אֵינוֹ צַדִּיק, נִשְׁאֶרֶת אוֹתָהּ נְשָׁמָה בָּעוֹלָם הַזֶּה עַד שֶׁנִּטְמָן הַגּוּף בַּקַּרְקַע. כֵּיוָן שֶׁנִּטְמָן, כַּמָּה שׁוֹמְרֵי הַחֻקִּים אוֹחֲזִים בּוֹ עַד שֶׁמַּגִּיעַ לְדוּמָ\"ה, וּמַכְנִיסִים אוֹתוֹ בַּמָּדוֹר שֶׁלּוֹ שֶׁל הַגֵּיהִנֹּם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּל שִׁבְעַת הַיָּמִים הַנְּשָׁמָה הוֹלֶכֶת מֵהַבַּיִת לְקִבְרוֹ וּמִקִּבְרוֹ לַבַּיִת, וּמִתְאַבֶּלֶת עָלָיו עַל הַגּוּף, שֶׁכָּתוּב (איוב יד) אַךְ בְּשָׂרוֹ עָלָיו יִכְאָב וְנַפְשׁוֹ עָלָיו תֶּאֱבָל. הוֹלֶכֶת וְיוֹשֶׁבֶת בְּבֵיתוֹ, וְרוֹאָה אֶת כֻּלָּם עֲצוּבִים וַאֲבֵלִים.</p>\n<p>לָמַדְנוּ, אַחַר שִׁבְעָה יָמִים הַגּוּף נִהְיָה כְּמוֹ שֶׁהָיָה, וְנִשְׁמָתוֹ עוֹלָה לִמְקוֹמָהּ. נִכְנֶסֶת לִמְעָרַת הַמַּכְפֵּלָה, רוֹאָה מַה שֶּׁרוֹאָה, וְנִכְנֶסֶת לְמָקוֹם שֶׁנִּכְנֶסֶת, עַד שֶׁמַּגִּיעָה לְגַן עֵדֶן, וּפוֹגֶשֶׁת אֶת הַכְּרוּבִים וּשְׁנִינוּת הַחֶרֶב שֶׁבְּגַן עֵדֶן שֶׁלְּמַטָּה. אִם צַדִּיק הוּא שֶׁתִּכָּנֵס, נִכְנֶסֶת.</p>\n<p>שָׁנִינוּ, אַרְבָּעָה עַמּוּדִים זְמִינִים, וּדְמוּת אַחַת שֶׁל הַגּוּף בִּידֵיהֶם, מִתְלַבֶּשֶׁת בּוֹ בְּחֶדְוָה וְיוֹשֶׁבֶת בְּאוֹתוֹ מָדוֹר שֶׁל גַּן עֵדֶן שֶׁלְּמַטָּה עַד זְמַן שֶׁנִּגְזָר עָלֶיהָ, אַחַר כָּךְ הַכָּרוֹז קוֹרֵא.</p>\n<p>וְעַמּוּד שֶׁל שְׁלֹשָׁה גְוָנִים מִזְדַּמֵּן, וְאוֹתוֹ הָעַמּוּד נִקְרָא מְכוֹן הַר צִיּוֹן, שֶׁכָּתוּב (ישעיה ד) וּבָרָא ה' עַל כָּל מְכוֹן הַר צִיּוֹן וְעַל מִקְרָאֶהָ עָנָן יוֹמָם וְעָשָׁן וְגוֹ'. עוֹלָה בְּאוֹתוֹ הָעַמּוּד לְפֶתַח שֶׁל צֶדֶק שֶׁצִּיּוֹן וִירוּשָׁלַיִם בּוֹ.</p>\n<p>אִם זָכָה לַעֲלוֹת יוֹתֵר - טוֹב חֶלְקוֹ וְגוֹרָלוֹ לְהִדָּבֵק בְּתוֹךְ הַגּוּף שֶׁל הַמֶּלֶךְ, וְאִם לֹא זוֹכֶה לַעֲלוֹת יוֹתֵר - כָּתוּב (שם) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁ לם קָדוֹשׁ יֵאָמֶר לוֹ. וְאִם זָכָה לַעֲלוֹת יוֹתֵר - צַדִּיק הוּא, שֶׁזּוֹכֶה לַכָּבוֹד שֶׁל הַמֶּלֶךְ וּלְהִתְעַדֵּן בְּעִדּוּן עֶלְיוֹן שֶׁלְּמַעְלָה מִמָּקוֹם שֶׁנִּקְרָא שָׁמַיִם, שֶׁכָּתוּב (שם נח) אָז תִּתְעַנַּג עַל ה'. עַל ה' דַּוְקָא. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכֶה לַחֶסֶד הַזֶּה, שֶׁכָּתוּב (תהלים קח) כִּי גָדל מֵעַל שָׁמַיִם חַסְדֶּךְ.</p>\n<p>וְכִי עַל הַשָּׁמַיִם הוּא, וַהֲרֵי כָּתוּב (שם נז) כִּי גָדֹל עַד שָׁמַיִם חַסְדֶּךְ? אָמַר רַבִּי יוֹסֵי, יֵשׁ חֶסֶד וְיֵשׁ חֶסֶד, חֶסֶד עֶלְיוֹן וְחֶסֶד תַּחְתּוֹן. חֶסֶד עֶלְיוֹן הוּא מֵעַל הַשָּׁמַיִם, וְחֶסֶד תַּחְתּוֹן הוּא שֶׁכָּתוּב (ישעיה נה) חַסְדֵי דָוִד הַנֶּאֱמָנִים, וּבְאֵלֶּה כָּתוּב עַד שָׁמַיִם.</p>"],[9522011444,"<p>לָמַדְנוּ, אָמַר רַבִּי יִצְחָק, כָּתוּב (תהלים קיג) אֵם הַבָּנִים שְׂמֵחָה הַלְלוּיָהּ. הָאֵם הַיְדוּעָה. הַבָּנִים מִי הֵם? אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי שָׁנִינוּ שֶׁיֵּשׁ שְׁנֵי בָנִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא, אֶחָד זָכָר וְאֶחָד נְקֵבָה. הַזָּכָר נָתַן אוֹתוֹ לְיַעֲקֹב, שֶׁכָּתוּב (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, וְכָתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. בַּת נָתַן לְאַבְרָהָם, שֶׁכָּתוּב (בראשית כד) וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. בַּת הָיְתָה לוֹ לְאַבְרָהָם, וּבַכֹּל שְׁמָהּ.</p>\n<p>וְהָאֵם רוֹבֶצֶת עֲלֵיהֶם, שֶׁמֵּינִיקָה אוֹתָם, וְעַל זֶה כָּתוּב לֹא תִקַּח הָאֵם עַל הַבָּנִים. וְשָׁנִינוּ, אַל יַרְבֶּה הָאָדָם חֲטָאָיו לְמַטָּה, כְּדֵי שֶׁתִּסְתַּלֵּק הָאֵם מֵעַל הַבָּנִים, וְכָתוּב (ויקרא יח) אִמְּךְ הִוא לֹא תְגַלֶּה עֶרְוָתָהּ. אוֹי לְמִי שֶׁמְּגַלֶּה עֶרְוָתָהּ.</p>\n<p>וּכְשֶׁשָּׁבִים בְּנֵי הָעוֹלָם וּמַרְבִּים בִּזְכֻיּוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהָאֵם שָׁבָה וּמְכַסָּה עַל הַבָּנִים, אָז זֶה נִקְרָא תְשׁוּבָה. מַה זֶּה תְּשׁוּבָה? זוֹ תְשׁוּבָה שֶׁל הָאֵם שֶׁשָּׁבָה בְּקִיּוּמָהּ, וְאָז כָּתוּב אֵם הַבָּנִים שְׂמֵחָה. אֵם הַבָּנִים וַדַּאי. וְלָכֵן לֹא יִפָּטֵר הָאָדָם מִפְּרִיָּה וּרְבִיָּה עַד שֶׁמּוֹלִיד בֵּן וּבַת.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יִצְחָק, כָּתוּב (תהלים כז) לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ. תְּשׁוּקַת הַצַּדִּיקִים לִרְאוֹת אֶת זֶה, וְאַתָּה אָמַרְתָּ עַל ה'? אָמַר רַבִּי שִׁמְעוֹן, הַכֹּל אֶחָד, מַשְׁמָע שֶׁכָּתוּב נֹעַם ה', שֶׁבָּא מֵהָעַתִּיק הַקָּדוֹשׁ לַשָּׁמַיִם הַזֶּה, וּתְשׁוּקַת הַצַּדִּיקִים כָּךְ הִיא וַדַּאי. וְכָתוּב עַל הַשָּׁמַיִם, אָז תִּתְעַנַּג עַל ה'. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכֶה. וַדַּאי מְעַטִּים הֵם.</p>"],[9522011445,"<p>שָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב (שיר א) בְּנֵי אִמִּי נִחֲרוּ בִי שָׂמֻנִי נֹטֵרָה אֶת הַכְּרָמִים. בְּנֵי אִמִּי, כְּמוֹ שֶׁכָּתוּב (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ. שֶׁכְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲרִיב בֵּיתוֹ שֶׁלְּמַטָּה וּלְהַגְלוֹת אֶת יִשְׂרָאֵל לְבֵין הָעַמִּים, הֶעֱבִיר הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְּפָנָיו אֶת הָאָרֶץ הַזּוֹ, וְהִתְרַחֲקָה מִמֶּנּוּ, כַּכָּתוּב (שמות ב) וַתֵּתַצַּב אֲחֹתוֹ מֵרָחֹק. וּכְשֶׁאֶרֶץ זוֹ הִתְרַחֲקָה מִשָּׁמַיִם שֶׁלְּמַעְלָה, הָאָרֶץ הַזּוֹ שֶׁלְּמַטָּה נֶחְרְבָה, וְיִשְׂרָאֵל הִתְפַּזְּרוּ בֵּין הָעַמִּים. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל: מִי גָרַם לִי אֶת זֶה וּמִי עָשָׂה לִי אֶת זֶה? בְּנֵי אִמִּי שֶׁנִּחֲרוּ בִי וְהִתְרַחֲקוּ מִמֶּנִּי, בְּנֵי אִמִּי וַדַּאי.</p>\n<p>רַבִּי יוֹסֵי הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְהָיָה עִמּוֹ רַבִּי חִיָּיא בַּר רַב. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי יוֹסֵי לְרַבִּי חִיָּיא, רָאִיתָ מַה שֶּׁרָאִיתִי? אָמַר לוֹ, רָאִיתִי גֶבֶר אֶחָד בַּנָּהָר, וְצִפּוֹר אַחַת עַל רֹאשׁוֹ, וְעָלֶה בְּפִי הַצִּפּוֹר, וְאוֹכֶלֶת וְרוֹמֶסֶת בְּרַגְלֶיהָ, וְאוֹתוֹ גֶבֶר מֵרִים קוֹלוֹת וְצוֹוֵחַ, וְלֹא יָדַעְתִּי מָה אָמַר.</p>\n<p>אָמַר, נִקְרַב אֵלָיו וְנִשְׁמַע. אָמַר, אֲנִי פּוֹחֵד לְהִתְקָרֵב. אָמַר לוֹ, וְכִי בֶּן אָדָם הוּא בְּמָקוֹם זֶה? אֶלָּא רֶמֶז שֶׁל חָכְמָה שֶׁרָמַז לָנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא. קָרְבוּ אֵלָיו. שָׁמְעוּ שֶׁהָיָה אוֹמֵר: כֶּתֶר, כֶּתֶר, שְׁנֵי בָנִים שְׁרוּיִים בַּחוּץ (זרוקים לבחוץ). לֹא נָח וְלֹא מְנוּחָה, עַד שֶׁהַצִּפּוֹר בַּפַּח תִּפֹּל.</p>\n<p>בָּכָה רַבִּי יוֹסֵי וְאָמַר, זֶהוּ שֶׁשָּׁנִינוּ בְּנֵי אִמִּי נִחֲרוּ בִי. מָה הַטַּעַם? מִשּׁוּם שֶׁכַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי.</p>\n<p>אָמַר, וַדַּאי הַגָּלוּת נִמְשָׁךְ, וְעַל זֶה (ש) צִפֳּרֵי הַשָּׁמַיִם לֹא זָזוֹת עַד שֶׁשִּׁלְטוֹן הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת יַעֲבֹר מֵהָעוֹלָם, וּמָתַי? עַד שֶׁיַּגִּיעַ הַיּוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְעוֹרֵר דִּינָיו בָּעוֹלָם, שֶׁכָּתוּב (זכריה יד) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה' לֹא יוֹם וְלֹא לָיְלָה.</p>\n<p>עַד שֶׁהָיוּ הוֹלְכִים, שָׁמְעוּ קוֹל אֶחָד שֶׁהָיָה אוֹמֵר: שַׁלְהֶבֶת הַדִּין הִגִּיעָה בְּדִינָיו. יָצְאָה שַׁלְהֶבֶת אַחַת וְשָׂרְפָה אֶת אוֹתָהּ הַצִּפּוֹר. אָמַר, וַדַּאי כְּמוֹ שֶׁכָּתוּב (דניאל ז) וְנִתְּנָה לִשְׂרֵפַת הָאֵשׁ.</p>"],[9522011446,"<p>אָמַר רַבִּי יוֹסֵי, לֹא הִגְלָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל אֶלָּא בִּזְמַן שֶׁלֹּא נִמְצְאָה בֵינֵיהֶם אֱמוּנָה, כְּשֶׁנִּמְנְעָה בֵינֵיהֶם הָאֱמוּנָה, כִּבְיָכוֹל, כָּךְ נִמְצָא בַּכֹּל, שֶׁכָּתוּב (ישעיה כח) וְכֻפַּר בְּרִיתְכֶם אֶת מָוֶת.</p>\n<p>אָמַר רַבִּי חִיָּיא, מַהוּ שֶׁכָּתוּב בִּלַּע הַמָּוֶת לָנֶצַח? אָמַר לוֹ, כְּשֶׁיְּעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יְמִינוֹ, יִמָּנַע מָוֶת מֵהָעוֹלָם, וְלֹא תִתְעוֹרֵר יָמִין זוֹ אֶלָּא כְּשֶׁיִּתְעוֹרְרוּ יִשְׂרָאֵל בִּימִינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמַה זֶּה? תּוֹרָה שֶׁכָּתוּב בָּהּ (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. בְּאוֹתוֹ זְמַן (תהלים קיח) יְמִי ה' עֹשָׂה חָיִל וְגוֹ', לֹא אָמוּת כִּי אֶחְיֶה וַאֲסַפֵּר מַעֲשֵׂי יָהּ.</p>"],[9522011447,"<p>לָמַדְנוּ, אוֹתוֹ הַצַּדִּיק שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בּוֹ, וְהַכָּרוֹז קוֹרֵא עָלָיו שְׁלֹשִׁים יָמִים בֵּין צַדִּיקֵי גַּן הָעֵדֶן, כָּל הַצַּדִּיקִים שְׂמֵחִים, כָּל הַצַּדִּיקִים בָּאִים וּמְעַטְּרִים מְקוֹמוֹ שֶׁל אוֹתוֹ הַצַּדִּיק עַד שֶׁיָּבֹא לְמַדֵּר אֶת דִּיּוּרוֹ בֵּינֵיהֶם.</p>\n<p>וְאִם רָשָׁע הוּא, הַכָּרוֹז קוֹרֵא עָלָיו בַּגֵּיהִנֹּם שְׁלֹשִׁים יוֹם (עליו), וְכָל הָרְשָׁעִים כֻּלָּם עֲצוּבִים.</p>\n<p>כֻּלָּם פּוֹתְחִים: וַי, שֶׁהֲרֵי דִּין חָדָשׁ מִתְעוֹרֵר כָּעֵת בִּגְלָלוֹ שֶׁל פְּלוֹנִי. כַּמָּה שׁוֹמְרֵי הַחֹק מִזְדַּמְּנִים כְּנֶגְדּוֹ וּמַקְדִּימִים לוֹ: וַי, אוֹי לָרָשָׁע אוֹי לִשְׁכֵנוֹ. וְכֻלָּם פּוֹתְחִים וְאוֹמְרִים: אוֹי לְרָשָׁע רָע כִּי גְמוּל יָדָיו יֵעָשֶׂה לּוֹ. מַה זֶּה (טעם) גְּמוּל יָדָיו? אָמַר רַבִּי יִצְחָק, לִכְלֹל (להוציא) מִי שֶׁזּוֹנֶה בְיָדוֹ לְהוֹצִיא וּלְהַשְׁחִית זַרְעוֹ לָרִיק.</p>\n<p>שֶׁהֲרֵי שָׁנִינוּ, כָּל מִי שֶׁמּוֹצִיא זַרְעוֹ לָרִיק נִקְרָא רָע, וְלֹא רוֹאֶה פְּנֵי שְׁכִינָה, שֶׁכָּתוּב (תהלים ה) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע, וְכָתוּב (בראשית לב) וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע. אַף כָּאן, אוֹי לְרָשָׁע רָע - אוֹי לְאוֹתוֹ רָשָׁע שֶׁהוּא רָע, שֶׁעָשָׂה עַצְמוֹ רָע, כִּי גְמוּל יָדָיו יֵעָשֶׂה לּוֹ - לִכְלֹל מִי שֶׁזּוֹנֶה בְיָדוֹ לְהוֹצִיא וּלְהַשְׁחִית זַרְעוֹ לָרִיק, וְלָזֶה טוֹרְדִים אוֹתוֹ בְּאוֹתוֹ הָעוֹלָם יוֹתֵר מִכֻּלָּם.</p>\n<p>בֹּא תִרְאה, שֶׁהֲרֵי כָּתוּב אוֹי לְרָשָׁע (רע). כֵּיוָן שֶׁכָּתוּב אוֹי לְרָשָׁע, לָמָּה רָע? אֶלָּא כְּמוֹ שֶׁאָמַרְנוּ, שֶׁעָשָׂה עַצְמוֹ רָע, וְכָתוּב לֹא יְגֻרְךְ רָע, וְכֻלָּם עוֹלִים וְזֶה לֹא עוֹלֶה. וְאִם תֹּאמַר, שְׁאָר רְשָׁעִים שֶׁהָרְגוּ בְּנֵי אָדָם? בֹּא רְאֵה, כֻּלָּם עוֹלִים וְהוּא לֹא עוֹלֶה. מָה הַטַּעַם? הֵם הָרְגוּ בְּנֵי אָדָם אֲחֵרִים, וְזֶה הָרַג בָּנָיו מַמָּשׁ, שָׁפַךְ דָּמִים רַבִּים. בֹּא רְאֵה, בִּשְׁאָר רִשְׁעֵי הָעוֹלָם לֹא כָתוּב וַיֵּרַע בְעֵינֵי ה', וְכָאן כָּתוּב וַיֵּרַע בְּעֵינֵי ה' אֲשֶׁר עָשָׂה. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב וְשִׁחֵת אַרְצָה.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יְהוּדָה, אֵין לְךְ חֵטְא בָּעוֹלָם שֶׁאֵין לוֹ תְּשׁוּבָה פְּרָט לָזֶה, וְאֵין לְךְ רָשָׁע שֶׁלֹּא רוֹאֶה פְּנֵי שְׁכִינָה פְּרָט לָזֶה, שֶׁכָּתוּב לֹא יְגֻרְךְ רָע, כְּלַל. אָמַר רַבִּי יִצְחָק, אַשְׁרֵי הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ. מַה זֶּה לְעוֹלָם יִירְשׁוּ אָרֶץ? אָמַר רַבִּי יְהוּדָה, כְּמוֹ שֶׁכָּתוּב (תהלים קטז) אֶתְהַלֵּךְ לִפְנֵי ה' בְּאַרְצוֹת הַחַיִּים.</p>"],[9522011448,"<p>וַיְחִי יַעֲקֹב, בְּתוֹכָם. לָכֵן צָרִיךְ לְאָדָם שֶׁלֹּא לְעָרֵב צֶלֶם שֶׁלּוֹ בְּצֶלֶם שֶׁל עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, מִשּׁוּם שֶׁזֶּה קָדוֹשׁ וְזֶה טָמֵא.</p>\n<p>בֹּא רְאֵה מַה בֵּין יִשְׂרָאֵל לָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, שֶׁיִּשְׂרָאֵל כְּשֶׁנִּמְצָא אָדָם מֵת, הוּא מְטַמֵּא אֶת כָּל הַגּוּף, וְהַבַּיִת טָמֵא. וְגוּף שֶׁל עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת לֹא מְטַמֵּא מִישֶׁהוּ אַחֵר, וְגוּפוֹ (וביתו) לֹא טָמֵא כְּשֶׁהוּא מֵת. מָה הַטַּעַם?</p>\n<p>יִשְׂרָאֵל בְּשָׁעָה שֶׁהוּא מֵת, כָּל הַקְּדֻשּׁוֹת שֶׁל רִבּוֹנוֹ עוֹבְרוֹת מִמֶּנּוּ, וְעוֹבֵר מִמֶּנּוּ הַצֶּלֶם הַקָּדוֹשׁ הַזֶּה, וְעוֹבֶרֶת מִמֶּנּוּ רוּחַ הַקְּדֻשָּׁה הַזּוֹ, נִשְׁאָר הַגּוּף טָמֵא.</p>\n<p>אֲבָל עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת עוֹבֵד עֲבוֹדָה זָרָה לֹא כָּךְ, שֶׁבְּחַיָּיו טָמֵא בְּכָל הַצְּדִים, צַלְמוֹ טָמֵא וְרוּחוֹ טְמֵאָה, וּמִשּׁוּם שֶׁכָּל הַטֻּמְאוֹת הַלָּלוּ שְׁרוּיוֹת בְּתוֹכוֹ, אָסוּר לִקְרַב אֵלָיו. כֵּיוָן שֶׁמֵּת, יוֹצְאוֹת כָּל הַטֻּמְאוֹת הַלָּלוּ, וְנִשִׁאָר גּוּף בְּלִי טֻמְאָה לְטַמֵּא.</p>\n<p>וְאַףֹ עַל גַּב שֶׁגּוּפָם טָמֵא, בֵּין בְּחַיֵּיהֶם וּבֵין בְּמִיתָתָם, אֲבָל בְּחַיֵּיהֶם שֶׁכָּל אוֹתָן הַטֻּמְאוֹת שֶׁנִּמְצָאוֹת אֶצְלָהֶם, יֵשׁ לָהֶם כֹּחַ לְטַמֵּא אֲחֵרִים. וּבְמִיתָתָם, כַּאֲשֶׁר יוֹצְאוֹת כָּל אוֹתָן הַטֻּמְאוֹת מֵהֶם, לֹא יְכוֹלִים לְטַמֵּא, וְשֶׁל יִשְׂרָאֵל יָכוֹל לְטַמֵּא אֲחֵרִים, כִּי כָּל הַקְּדֻשּׁוֹת יוֹצְאוֹת מִמֶּנּוּ, וְשׁוֹרֶה עָלָיו צַד הָאַחֵר.</p>\n<p>בֹּא רְאֵה, הַצֶּלֶם הַקָּדוֹשׁ הַזֶּה, כְּשֶׁהוֹלֵךְ אָדָם וּמִתְגַּדֵּל וְנַעֲשֵׂית מֵהַפַּרְצוּף הַזֶּה הַדְּמוּת שֶׁלּוֹ, נַעֲשֶׂה צֶלֶם אַחֵר, וּמִתְחַבְּרִים כְּאֶחָד, וְזֶה נוֹטֵל אֶת זֶה. בְּשָׁעָה שֶׁנִּמְצָאִים שְׁנֵי צְלָמִים שָׁמוּר הוּא הָאָדָם, וְגוּפוֹ בְּקִיּוּם, וְרוּחַ שְׁרוּיָה בְתוֹכוֹ.</p>\n<p>בְּשָׁעָה שֶׁקְּרֵבִים יָמָיו, הֵם עוֹבְרִים מִמֶּנּוּ, וְזֶה עוֹלֶה לָזֶה, וְנִשְׁאָר אָדָם בְּלִי שְׁמִירָה, אָז (שיר ב) עַד שֶׁיָּפוּחַ הַיּוֹם וְנָסוּ הַצְּלָלִים, שְׁנַיִם.</p>\n<p>בֹּא רְאֵה, כְּשֶׁמִּתְעוֹרֵר דִּין בָּעוֹלָם, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב עַל כִּסֵּא דִין לָדוּן אֶת הָעוֹלָם, צָרִיךְ אָדָם לְעוֹרֵר (בדין) תְּשׁוּבָה שֶׁיָּשׁוּב מֵהָרֶשַׁע (מחטאיו), שֶׁהֲרֵי אוֹתוֹ יוֹם נִכְתָּבִים פְּתָקִים, וְכֻלָּם נִמְצָאִים בְּתִיק כְּתוּבִים. אִם זָכָה אָדָם שֶׁיָּשׁוּב לִפְנֵי רִבּוֹנוֹ, קוֹרְעִים אֶת הַפְּתָקִים שֶׁעָלָיו.</p>\n<p>אַחַר כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מַזְמִין לִפְנֵי הָאָדָם אֶת יוֹם הַכִּפּוּרִים, יוֹם הַתְּשׁוּבָה. אִם שָׁב מֵחֲטָאָיו - טוֹב. אִם לֹא - מְצַוֶּה הַמֶּלֶךְ לַחְתֹּם פְּתָקִים. אוֹי כִּי הַתְּשׁוּבָה רוֹצָה לְהִסְתַּלֵּק מִמֶּנּוּ.</p>\n<p>אִם זָכָה בִּתְשׁוּבָה וְלֹא שְׁלֵמָה כָּרָאוּי - תּוֹלִים לוֹ עַד אוֹתוֹ יוֹם אַחֲרוֹן שֶׁל עֲצֶרֶת, שֶׁהוּא שְׁמִינִי לֶחָג. אִם עָשָׂה תְשׁוּבָה שְׁלֵמָה לִפְנֵי רִבּוֹנוֹ - נִקְרָעִים. וְאִם לֹא זוֹכֶה - אוֹתָם פְּתָקִים יוֹצְאִים מִבֵּית הַמֶּלֶךְ וְנִמְסָרִים בִּידֵי מַלְאַךְ הַדִּין, וְהַדִּין נַעֲשֶׂה, וּפְתָקִים יוֹתֵר לֹא חוֹזְרִים עוֹד לְבֵית הַמֶּלֶךְ.</p>\n<p>אָז מָעֳבָרִים הַצְּלָמִים מִמֶּנּוּ וְלֹא נִמְצָאִים עִמּוֹ. כֵּיוָן שֶׁעָבְרוּ מִמֶּנּוּ, הֲרֵי וַדַּאי שֶׁעֹנֶשׁ הַמֶּלֶךְ יַעֲבֹר עָלָיו וְיִטְעַם מִכּוֹס הַמָּוֶת. וּבְאוֹתוֹ לַיְלָה שֶׁל חַג הָאַחֲרוֹן, הַמַּלְאָכִים הַמַּעֲנִישִׁים מְזֻמָּנִים, וְנוֹטְלִים אֶת הַפְּתָקִים. וְאַחַר שֶׁנָּטְלוּ אוֹתָם, מָעֳבָרִים הַצְּלָמִים, וְלֹא נִמְצָאִים (ואם נמצאים פגומים, יעבר עליו מחלות וכו') בָּהֶם יָדַיִם. וְאִם נִמְצָאִים בָּהֶם יָדַיִם - דִּין גָּרוּעַ, אוֹ יַעֲבֹר עָלָיו דִּין שֶׁל מַחֲלוֹת רָעוֹת בַּפְּגָם שֶׁלָּהֶם, וַהֲרֵי בֵּאַרְנוּ אֶת זֶה.</p>\n<p>וּבְסִפְרִי הַקַּדְמוֹנִים אוֹמְרִים יוֹתֵר, כְּשֶׁהָרֹאשׁ נִגְרָע וְיִמָּצֵא הַגּוּף - בְּנוֹ אוֹ אִשְׁתּוֹ יִמָּצְאוּ, וְהוּא יִסְתַּלֵּק. וְזֶה מְדֻבָּר כְּשֶׁלֹּא חָזַר כָּל אוֹתוֹ זְמַן בִּתְשׁוּבָה. אֲבָל אִם חָזַר, טַעַם הַמָּוֶת יִטְעַם וְיִתְרַפֵּא.</p>\n<p>וְאִם הַגּוּף לֹא נִרְאֶה וְיִמָּצֵא הָרֹאשׁ - הֵם מִסְתַּלְּקִים וְהוּא מִתְקַיֵּם, וְזֶה מְדֻבָּר כְּשֶׁבְּנוֹ הַקָּטָן בִּרְשׁוּתוֹ.</p>\n<p>וְאִם יָדָיו פְּגוּמִים, מַעֲשֵׂה יָדָיו פְּגוּמִים, רַגְלָיו - מַחֲלוֹת רוֹדְפוֹת אוֹתוֹ. בּוֹרֵחַ הַצֶּלֶם וְחוֹזֵר, בּוֹרֵחַ וְחוֹזֵר, עָלָיו כָּתוּב (דברים כח) בַּבֹּקֶר תֹּאמַר מִי יִתֵּן עֶרֶב. וְזֶה כְּשֶׁהַלְּבָנָה מְאִירָה וְהַלַּיְלָה מְתֻקָּן בְּאוֹר.</p>\n<p>אֲבָל צַדִּיקִים חֲסִידִים, כָּל יוֹם וָיוֹם מִסְתַּכְּלִים בְּלִבָּם כְּאִלּוּ אוֹתוֹ יוֹם מִסְתַּלְּקִים מֵהָעוֹלָם, וְעוֹשִׂים תְּשׁוּבָה שְׁלֵמָה לִפְנֵי רִבּוֹנָם, וְלֹא יִצְטָרְכוּ לְדָבָר אַחֵר. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522011449,"<p>בֹּא רְאֵה, כֹּל הַנִּקְרָא בִשְׁמִי - כַּמָּה עֶלְיוֹנִים מַעֲשֵׂי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁהֲרֵי בְּאוֹתָם מַעֲשִׂים (בריות) שֶׁהוּא עוֹשֶׂה לְמַטָּה, קוֹשֵׁר אוֹתָם בִּדְבָרִים עֶלְיוֹנִים שֶׁלְּמַעְלָה, וּכְשֶׁנּוֹטְלִים אוֹתָם לְמַטָּה וְעוֹשִׂים בָּהֶם מַעֲשֶׂה, מִתְעוֹרֵר אוֹתוֹ מַעֲשֶׂה שֶׁלְּמַעְלָה שֶׁקָּשׁוּר בּוֹ, כְּגוֹן אֵזוֹב וְעֵץ אֶרֶז, וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים.</p>\n<p>וְיִשִׁ מֵהֶם שֶׁאֲחוּזִים בַּשֵּׁם הַקָּדוֹשׁ, כְּמוֹ לוּלָב, וְאֶתְרוֹג, הֲדַס, וַעֲרָבָה, שֶׁכֻּלָּם אֲחוּזִים בַּשֵּׁם הַקָּדוֹשׁ לְמַעְלָה. וְעַל כָּךְ שָׁנִינוּ, לֶאֱחֹז אוֹתָם וְלַעֲשׂוֹת בָּהֶם מַעֲשֶׂה כְּדֵי לְעוֹרֵר חֶדְוָה אוֹתוֹ שֶׁאוֹחֵז בּוֹ. וְעַל זֶה שָׁנִינוּ, בִּדְבָרִים וּמַעֲשֶׂה צָרִיךְ לְהַרְאוֹת דָּבָר כְּדֵי לְעוֹרֵר דָּבָר אַחֵר.</p>\n<p>זֶהוּ שֶׁכָּתוּב כֹּל הַנִּקְרָא בִשְׁמִי וְלִכְבוֹדִי (בראתיו) - לְעוֹרֵר כְּבוֹדִי. בְּרָאתִיו - לְיַחֵד לִי. יְצַרְתִּיו - לַעֲשׂוֹת בּוֹ מַעֲשֶׂה (כח). אַף עֲשִׂיתִיו - לְעוֹרֵר בּוֹ כֹּחַ שֶׁלְּמַעְלָה.</p>\n<p>דָּבָר אַחֵר כֹּל הַנִּקְרָא בִשְׁמִי - הַיְנוּ שֶׁכָּתוּב (ויקרא כג) פְּרִי עֵץ הָדָר. וְלִכְבוֹדִי בְּרָאתִיו - הַיְנוּ כַּפֹּת תְּמָרִים. יְצַרְתִּיו - הַיְנוּ וַעֲנַף עֵץ עָבת. אַף עֲשִׂיתִיו - הַיְנוּ וְעַרְבֵי נָחַל.</p>\n<p>וְתִקּוּן שֶׁל זֶה שֶׁאָמַר הַכָּתוּב וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן, דַּוְקָא שֶׁהוּא חֲמִישִׁי עַל עָשׂוֹר.</p>\n<p>אֲבָל בַּיּוֹם הָרִאשׁוֹן, אוֹתוֹ יוֹם רִאשׁוֹן מִי הוּא? אֶלָּא יוֹם שֶׁיָּצָא רִאשׁוֹן לִנְסֹעַ (לכל) בְּמַעְיָנָיו שֶׁל מַיִם נוֹבְעִים, וְאָנוּ רוֹצִים לְהַמְשִׁיכוֹ לָעוֹלָם.</p>\n<p>מָשָׁל לְמֶלֶךְ שֶׁקָּשַׁר בְּנֵי אָדָם בְּמַאֲסָר. בָּאָה אִמּוֹ הַגְּבִירָה וְהוֹצִיאָה אוֹתָם לַחֵרוּת, וְהַמֶּלֶךְ מַשְׁגִּיחַ עַל כְּבוֹדָהּ וְנָתַן אוֹתָם בְּיָדֶיהָ. מָצְאָה אוֹתָם רְעֵבִים וּצְמֵאִים. אָמְרָה, הֲרֵי הוֹצֵאתִי אוֹתָם לַחֵרוּת, תָּבִיא לָהֶם אֹכֶל וּמַשְׁקֶה.</p>\n<p>כָּךָ יוֹם הַכִּפּוּרִים הַזֶּה מוֹצִיא אֶת כֻּלָּם לַחֵרוּת, וְאָנוּ רְעֵבִים לְמָזוֹן וּצְמֵאִים לִשְׁתִיָּה. הִיא מְעַטֶּרֶת אֶת הַמֶּלֶךְ בְּעַטְרוֹתָיו. בַּיּוֹם הַזֶּה יָדַעְנוּ שֶׁמַּיִם נוֹבְעִים שׁוֹרִים עִמָּהּ, שׁוֹאֲלִים לִשְׁתּוֹת לְמִי שֶׁהוֹצִיא אוֹתָם לַחֵרוּת, וְעַל כָּךְ קוֹרְאִים לוֹ בְּיוֹם רִאשׁוֹן.</p>\n<p>זְהִ בְּסֵפֶר הָאַגָּדָה, וְהוּא יָפֶה. אֲבָל בַּיּוֹם הַזֶּה, לְאַבְרָהָם שֶׁהוּא רֵאשִׁית הַכֹּל, אִם בְּעַנְנֵי כָבוֹד הוּא הָרֵאשִׁית אוֹ בְּמַיִם הוּא הָרֵאשִׁית, שֶׁאַבְרָהָם הִתְחִיל לַחְפֹּר בּוֹרוֹת מַיִם.</p>\n<p>פְּרִי עֵץ הָדָר - זוֹ בְּאֵר שֶׁל יִצְחָק, שֶׁיִּצְחָק הִדֵּר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְקָרָא לוֹ עֵץ הָדָר. פִּרְיוֹ שֶׁל עֵץ הֶהָדָר הַזֶּה יָדוּעַ. כַּפֹּת תְּמָרִים - שֶׁכָּתוּב (תהלים צב) צַדִּיק כַּתָּמָר יִפְרָח, וְלֹא נִמְצָא בֵּינֵיהֶם פֵּרוּד. וְלָכֵן לֹא כָתוּב וְכַפֹּת, אֶלָּא כַּפֹּת, מִשּׁוּם שֶׁלֹּא עוֹלֶה זֶה בְּלִי זֶה. וּבָזֶה מִתְמַלֵּאת הַבְּאֵר הַ את, מִבְּאֵר מַיִם עֶלְיוֹנִים שֶׁנּוֹבְעִים. הַהוּא מִתְמַלֵּא בַּתְּחִלָּה, וּמִמֶּנּוּ מִתְמַלֵּאת הַבְּאֵר עַד שֶׁנּוֹבַעַת לַכֹּל.</p>\n<p>וַעָנַף עֵץ עָבֹת - זֶה עָנָף שֶׁל אִילָן הַגָּדוֹל שֶׁהִתְחַזֵּק וְנִשְׁרַשׁ בְּשָׁרְשׁוֹ, נַעֲשָׂה אִילָן עֶלְיוֹן עַל הַכֹּל, שֶׁאָחוּז בְּכָל הַצְּדָדִים שֶׁלּוֹ, עָנָף שֶׁהוּא עֵץ עָבֹת, עֵץ שֶׁאוֹחֵז אֶת הֶעָבוֹת, שֶׁהֲרֵי מִזֶּה נוֹטֵל יְסוֹד הָעוֹלָם וּמִתְמַלֵּא כְּדֵי לְהָרִיק בַּבְּאֵר, זֶהוּ עוֹלַם אֶרֶץ הַהַשְׁקָאָה.</p>\n<p>וְעַרְבֵי נָחַל - שְׁנַיִם הֵם, שְׁנֵי נַחֲלֵי מַיִם מִתְכַּנְּסִים לְתוֹכָם לְהָרִיק לַצַּדִּיק. דָּבָר אַחֵר וְעַרְבֵי נָחַל - אֵלֶּה הֵם גְּבוּרוֹת שֶׁאֲחוּזוֹת בְּיִצְחָק, שֶׁבָּאִים מִצַּד אוֹתוֹ נַחַל עֶלְיוֹן וְלֹא מִצַּד הָאָב. לָכֵן הַכֹּל נָאֶה, וְלֹא מְבֻשָּׂם לַפֵּרוֹת, וְלֹא עוֹשֶׂה פֵּרוֹת.</p>\n<p>וְעַרְבֵי נָחַל - שְׁנֵי עַמּוּדִים שֶׁהַגּוּף עוֹמֵד עֲלֵיהֶם. אֲבָל וְעַרְבֵי נָחַל וַדַּאי, כְּמוֹ שֶׁנִּתְבָּאֵר, וְאֵלֶּה הֵם כֻּלָּם לְרוֹקֵן מַיִם לַבְּאֵר.</p>\n<p>דָּבָר אַחֵר, וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן פְּרִי עֵץ הָדָר - זֶה אַבְרָהָם. כַּפֹּת תְּמָרִים - זֶה יִצְחָק. וַעֲנַף עֵץ עָבֹת - זֶה יַעֲקֹב. וְעַרְבֵי נָחַל - אֵלֶּה הֵן שְׁתֵּי הַדְּרָגוֹת שֶׁאָמַ רְנוּ.</p>\n<p>וּמִי שֶׁשּׁוֹנֶה זֶה, מִשּׁוּם שֶׁעֵץ עָבֹת זֶה יַעֲקֹב, שֶׁאוֹחֵז אֶת כָּל הַחֲלָקִים, וַדַּאי זֶה יַעֲקֹב. אֲבָל הֲרֵי בֵּאַרְנוּ, פְּרִי עֵץ הָדָר - זוֹ בְּאֵר יִצְחָק, זוֹ גְּבוּרָה תַחְתּוֹנָה. כַּפֹּת תְּמָרִים - כַּפֹּת חָסֵר, קֶשֶׁר שֶׁנִּקְשָׁר בַּבְּאֵר, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ג) כְּפוּתִים בְּסַרְבְּלֵיהֶם, מִשּׁוּם שֶׁאֵלֶּה לֹא עוֹלִים זֶה בְּלִי זֶה. וַעֲנַף עֵץ עָבת, עָנָף הוּא עֶלְיוֹן שֶׁנַּעֲשֶׂה עֵץ עָבוֹת וְאוֹחֵז לְכָל צַד, כְּמוֹ שֶׁנֶּאֱמַר. עַרְבֵי נָחַל - זֶה יִצְחָק, בְּכָל הַצְּדָדִים שֶׁאֲחוּזִים בְּצַד הַנַּחַל וְלֹא בְּצַד הָאָב. שֶׁשָּׁנִינוּ, אַף עַל גַּב שֶׁבַּנַּחַל הַזֶּה לֹא נִמְצָא דִין, מִתְעוֹרְרִים מִמֶּנּוּ דִּינִים.</p>\n<p>וְרַב הַמְנוּנָא הַזָּקֵן פֵּרַשׁ, וְעַרְבֵי נָחַל - אֵלּוּ שְׁנֵי הָעַמּוּדִים שֶׁאָמַרְנוּ שֶׁיּוֹצְאִים מֵהֶם מַיִם, וְיָפֶה. אֲבָל בּא רְאֵה, הֲרֵי רָאִינוּ שֶׁשְּׁתֵּי דְרָגוֹת אֵלֶּה שֶׁעוֹמְדוֹת עַל דַּרְגָּה שֶׁל צַדִּיק, פְּרִי וְכִנּוּס גָּדוֹל (הברכות) יוֹצְאִים מֵהֶם, וְעַרְבֵי נַחַל לֹא יוֹצְאִים מֵהֶם לֹא פְרִי וְלֹא טַעַם וְלֹא רֵיחַ, וַהֲרֵי בֵּאַרְנוּ, וְהַכֹּל יָפֶה.</p>\n<p>וְעַל כֵּן אֶתְרוֹג בִּשְׂמֹאל, כְּנֶגֶד הַלֵּב. לוּלָב בְּיָמִין. כַּפֹּת בַּכֹּל, וְקָשׁוּר בַּכֹּל, שֶׁהֲרֵי צַדִּיק כַּפּוֹת הוּא בְּכָל הַצְּדָדִים וְקָשׁוּר בַּכֹּל, וְזֶהוּ קֶשֶׁר הָאֱמוּנָה.</p>\n<p>וְיָפֶה אָמַר בְּסֵפֶר הָאַגָּדָה שֶׁכָּל אֵלֶּה הֵם אוֹרְחִים שֶׁמַּזְמִינִים הָעָם הַקָּדוֹשׁ בַּיּוֹם הַזֶּה, שֶׁצְּרִיכִים לִמְצֹא אוֹתָם, כֵּיוָן שֶׁהִזְמִין אוֹתָם, וּבָהֶם מְבַקֵּשׁ אָדָם בַּקָּשָׁתוֹ לַמֶּלֶךְ. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁיּוֹדְעִים דַּרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְיוֹדְעִים דַּרְכֵי הַתּוֹרָה לָלֶכֶת בְּדֶרֶךְ אֱמֶת, לִזְכּוֹת בָּהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בַּיּוֹם הַזֶּה יוֹצְאִים יִשְׂרָאֵל בְּסִימָנִים רְשׁוּמִים מִתּוֹךְ הַמֶּלֶךְ, מִשּׁוּם שֶׁהֵם נִצְּחוּ בַדִּין, וּמָהֵם הַסִּימָנִים? סִימָנֵי הָאֱמוּנָה, חוֹתַם הַמֶּלֶךְ הָעֶלְיוֹן. לִשְׁנֵי בְּנֵי אָדָם שֶׁנִּכְנְסוּ לִבְנֵי הַמֶּלֶךְ לְדִין, וּבָעוֹלָם לֹא יוֹדְעִים מִי מֵהֶם נִצַּח. יָצָא לִגְיוֹן אֶחָד מִבֵּית הַמֶּלֶךְ, וְשָׁאֲלוּ אוֹתוֹ מִי נִצַּח? אָמַר לָהֶם, מִי שֶׁיֵּצֵא וּבְיָדוֹ סִימָנֵי הַמֶּלֶךְ, הוּא שֶׁנִּצַּח.</p>\n<p>כָּךָ כָּל הָעוֹלָם נִכְנָסִים לְדִין לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן, וְהוּא דָּן אוֹתָם מִיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים, עַד חֲמֵשׁ עֶשְׂרֵה יוֹם לַחֹדֶשׁ, וּבֵין כָּךְ נִמְצְאוּ יִשְׂרָאֵל כֻּלָּם צַדִּיקִים בִּתְשׁוּבָה, טוֹרְחִים בַּסֻּכָּה וְלוּלָב וְאֶתְרוֹג, וְלֹא יוֹדְעִים מִי נִצַּח בַּדִּין. הַמַּלְאָכִים הָעֶלְיוֹנִים שׁוֹאֲלִים, מִי נִצַּח בַּדִּין? אוֹמֵר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵלֶּה שֶׁמּוֹצִיאִים בִּידֵיהֶם אֶת הַסִּימָנִים שֶׁלִּי, הֵם נִצְּחוּ בַדִּין.</p>\n<p>בַּיּוֹם הַזֶּה יוֹצְאִים יִשְׂרָאֵל בְּרֹשֶׁם הַמֶּלֶךְ, בְּתִשְׁבְּחוֹת הַהַלֵּל, נִכְנָסִים לַסֻּכָּה, אֶתְרוֹג בִּשְׂמֹאל, לוּלָב בְּיָמִין. כֻּלָּם רוֹאִים שֶׁיִּשְׂרָאֵל רְשׁוּמִים בְּרִשּׁוּמֵי הַמֶּלֶךְ הַקָּדוֹשׁ, פּוֹתְחִים וְאוֹמְרִים, (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו.</p>\n<p>עֵד כָּאן חֶדְוַת הַכֹּל, חֶדְוַת הָאוֹרְחִים, וַאֲפִלּוּ אֻמּוֹת הָעוֹלָם שְׂמֵחִים בַּחֶדְוָה וּמִתְבָּרְכִים מִמֶּנָּה, וְלָכֵן מַקְרִיבִים בְּכָל יוֹם עֲלֵיהֶם לְהַטִּיל עֲלֵיהֶם שָׁלוֹם, וְיִתְבָּרְכוּ מֵאִתָּנוּ. מִכָּאן וָהָלְאָה יוֹם אֶחָד שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן שֶׁשָּׂמֵחַ בָּהֶם בְּיִשְׂרָאֵל, שֶׁכָּתוּב (במדבר כט) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. שֶׁהֲרֵי יוֹם זֶה מִן הַמֶּלֶךְ בִּלְבַדּוֹ חֶדְוָתוֹ לְיִשְׂרָאֵל. מָשָׁל לְמֶלֶךְ שֶׁהִזְמִין אוֹרְחִים וְכוּ'.</p>"],[9522011450,"<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, אֲנִי חֲבַצֶּלֶת הַשָּׁרוֹן שׁוֹשַׁנַּת הָעֲמָקִים. כַּמָּה חֲבִיבָה כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׁבֵּחַ אוֹתָהּ, וְהִיא מְשַׁבַּחַת אוֹתוֹ תָּמִיד. וְכַמָּה מְשַׁבְּחִים וּמְזַמְּרִים מַזְמִינָה תָּמִיד לַקָּדוֹשׁ-בָּרוּךְ-הוּא. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁאֲחוּזִים בּוֹ בְּגוֹרַל הַחֵלֶק הַקָּדוֹשׁ, כַּכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ וְגוֹ'.</p>\n<p>אֲנִי חֲבַצֶּלֶת הַשָּׁרוֹן - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁעוֹמֶדֶת בַּיּפִי שֶׁל נוֹי בְּגַן עֵדֶן. הַשָּׁרוֹן - שֶׁהִיא שָׁרָה וּמְשַׁבַּחַת אֶת הַמֶּלֶךְ הָעֶלְיוֹן.</p>\n<p>דָּבָר אַחֵר, אֲנִי חֲבַצֶּלֶת הַשָּׁרוֹן - שֶׁרוֹצָה לִהְיוֹת מֻשְׁקָה מֵהַשְׁקָיַת הַנַּחַל הֶעָמֹק, מְקוֹר הַנְּחָלִים, כַּנֶּאֱמַר וְהָיָה הַשָּׁרָב לַאֲגַם. (נ\"א (ישעיה לג) והיה השדון כעדבה) שׁוֹשַׁנַּת הָעֲמָקִים - שֶׁעוֹמֶדֶת בְּעֹמֶק הַכֹּל. מִי הֵם הָעֲמָקִים? כְּמוֹ שֶׁנֶּאֱמַר (תהלים קל) מִמַּעֲמַקִּים קְרָאתִיךְ ה'. חֲבַצֶּלֶת הַשָּׁרוֹן. חֲבַצֶּלֶת - מֵאוֹתוֹ מָקוֹם שֶׁל הַשְׁקָאַת הַנְּחָלִים שֶׁיּוֹצְאִים וְלֹא פוֹסְקִים לְעוֹלָמִים. שׁוֹשַׁנַּת הָעֲמָקִים - שׁוֹשַׁנָּה מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא עֹמֶק הַכֹּל, נִסְתָּר מִכָּל הַצְּדָדִים.</p>\n<p>בֹּא רְאֵה, בַּתְּחִלָּה יְרֻקָּה כַּחֲבַצֶּלֶת, שֶׁהֶעָלִים שֶׁלָּהּ יְרֻקִּים, אַחַר כָּךְ שׁוֹשַׁנָּה אֲדֻמָּה בִּגְוָנִים לְבָנִים. שׁוֹשַׁנָּה בְּשִׁשָּׁה עָלִים. שׁוֹשַׁנַּת - שֶׁמִּשְׁתַּנֵּית מִגָּוֶן לְגָוֶן וּמְשַׁנָּה אֶת גְּוָנֶיהָ.</p>\n<p>שׁוֹשַׁנַּת - בַּתְּחִלָּה חֲבַצֶּלֶת. בִּזְמַן שֶׁרוֹצָה לְהִזְדַּוֵּג בַּמֶּלֶךְ נִקְרֵאת חֲבַצֶּלֶת, אַחַר שֶׁנִּדְבְּקָה עִם הַמֶּלֶךְ בְּאוֹתָן נְשִׁיקוֹת הִיא נִקְרֵאת שׁוֹשַׁנַּת, מִשּׁוּם שֶׁכָּתוּב (שיר ה) שִׂפְתוֹתָיו שׁוֹשַׁנִּים. שׁוֹשַׁנַּת הָעֲמָקִים - שֶׁהִיא מְשַׁנָּה אֶת גְּוָנֶיהָ לִפְעָמִים לְטוֹב וְלִפְעָמִים לְרַע, לִפְעָמִים לְרַחֲמִים וְלִפְעָמִים לְדִין.</p>\n<p>וַתֵּרֶא הָאִשָּׁה כִּי טוֹב הָעֵץ לְמַאֲכָל וְכִי תַאֲוָה הוּא לָעֵינַיִם (בראשית ב). בֹּא רְאֵה, שֶׁהֲרֵי בְּנֵי אָדָם לֹא מִסְתַּכְּלִים וְלֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם וְכִבֵּד אוֹתוֹ בְּכָבוֹד עֶלְיוֹן, רָצָה מִמֶּנּוּ לְהִדָּבֵק בּוֹ כְּדֵי שֶׁיִּמָּצֵא יְחִידִי, וּבַלֵּב יְחִידִי, וּבְמָקוֹם שֶׁל דְּבֵקוּת יְחִידָה שֶׁלֹּא מִשְׁתַּנֶּה וְלֹא מִתְהַפֵּךְ לְעוֹלָמִים בְּאוֹתוֹ קֶשֶׁר יָחִיד שֶׁהַכֹּל נִקְשָׁר בּוֹ. זֶהוּ שֶׁכָּתוּב וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן.</p>\n<p>אַחַר כָּךְ סָטוּ מִדֶּרֶךְ הָאֱמוּנָה וְעָזְבוּ אֶת הָעֵץ הַיְחִידִי, הָעֶלְיוֹן מִכָּל הָאִילָנוֹת, וּבָאוּ לְהִדָּבֵק בְּמָקוֹם שֶׁמִּשְׁתַּנֶּה וּמִתְהַפֵּךְ מִגָּוֶן לְגָוֶן וּמִטּוֹב לְרַע וּמֵרַע לְטוֹב, וְיָרְדוּ מִלְמַעְלָה מַטָּה, וְנִדְבְּקוּ לְמַטָּה בְּשִׁנּוּיִים רַבִּים, וְעָזְבוּ אֶת הָאִילָן הַיְחִידִי הָעֶלְיוֹן מִכָּל הָאִילָנוֹת. זֶהוּ שֶׁכָּתוּב (קהלת ז) אֲשֶׁר עָשָׂה הָאֱלֹהִים אֶת הָאָדָם יָשָׁר וְגוֹ'.</p>\n<p>וַדַּאי שֶׁאָז הִתְהַפֵּךְ לִבָּם בְּאוֹתוֹ הַצַּד מַמָּשׁ, לִפְעָמִים לְטוֹב לִפְעָמִים לְרַע, לִפְעָמִים לְרַחֲמִים לִפְעָמִים לְדִין. בַּדָּבָר הַזֶּה נִדְבְּקוּ בוֹ וַדַּאי, בִּקְשׁוּ חִשְּׁבוֹנוֹת רַבִּים וְנִדְבְּקוּ בָהֶם.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אָדָם, עָזַבְתָּ חַיִּים וְנִדְבַּקְתָּ בַּמָּוֶת. חַיִּים - שֶׁכָּתוּב וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן, שֶׁנִּקְרָא חַיִּים, שֶׁמִּי שֶׁאוֹחֵז בּוֹ לֹא טוֹעֵם מָוֶת לְעוֹלָמִים. נִדְבַּקְתָּ בְּעֵץ אַחֵר - הֲרֵי וַדַּאי הַמָּוֶת כְּנֶגְדְּךְ. זֶהוּ שֶׁכָּתוּב (משלי ה) רַגְלֶיהָ יֹרְדוֹת מָוֶת, וְכָתוּב (קהלת ז) וּמֹצֵא אֲנִי מַר מִמָּוֶת אֶת הָאִשָּׁה. וַדַּאי שֶׁנִּדְבַּק בִּמְקוֹם הַמָּוֶת וְעָזַב מְקוֹם הַחַיִּים. מִשּׁוּם כָּךְ נִגְזַר עָלָיו וְעַל כָּל הָעוֹלָם מָוֶת.</p>\n<p>אִם הוּא חָטָא, מֶה חָטְאוּ כָּל הָעוֹלָם? אִם תֹּאמַר שֶׁכָּל הָעוֹלָם אָכְלוּ מֵהָעֵץ הַזֶּה וְזֶה קָרָא לְכֻלָּם - לֹא כָּךְ! אֶלָּא בְּשָׁעָה שֶׁאָדָם עָמַד עַל רַגְלָיו, רָאוּ אוֹתוֹ כָּל הַבְּרִיּוֹת וּפָחֲדוּ מִלְּפָנָיו, וְהָיוּ נוֹסְעִים אַחֲרָיו כַּעֲבָדִים אַחַר הַמֶּלֶךְ, וְהוּא אָמַר לָהֶם: אֲנִי וְאַתֶּם (תהלים צה) בּאוּ נִשְׁתַּחֲוֶה וְנִכְרָעָה וְגוֹ'. וְכֻלָּם הָלְכוּ אַחֲרָיו. כֵּיוָן שֶׁרָאוּ שֶׁאָדָם מִשְׁתַּחֲוֶה לְמָקוֹם זֶה וְנִדְבָּק בּוֹ, כֻּלָּם נִמְשְׁכוּ אַחֲרָיו, וְגָרַם מָוֶת לְכָל הָעוֹלָם.</p>\n<p>וְאָז הִשְׁתַּנָּה הָאָדָם לְכַמָּה גְוָנִים, לִפְעָמִים דִּין לִפְעָמִים רַחֲמִים, לִפְעָמִים מָוֶת לִפְעָמִים חַיִּים, וְלֹא עוֹמֵד בְּקִיּוּם תָּמִיד בְּאֶחָד מֵהֶם, מִשּׁוּם שֶׁאוֹתוֹ מָקוֹם גָּרַם לוֹ, וְלָכֵן נִקְרָא חֶרֶב הַמִּתְהַפֶּכֶת, הַמִּתְהַפֶּכֶת מִצַּד זֶה לְצַד זֶה, מִטּוֹב לְרַע, מֵרַחֲמִים לְדִין, מִשָּׁלוֹם לִקְרָב, מִתְהַפֶּכֶת הִיא בַּכֹּל, טוֹב וָרַע, שֶׁכָּתוּב (בראשית ב) וִעֵץ הַדַּעַת טוֹב וָרָע.</p>\n<p>וְהַמֶּלֶךָֹ הָעֶלְיוֹן, לְרַחֵם עַל מַעֲשָׂיו, הוֹכִיחַ אוֹתוֹ וְאָמַר לוֹ, וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ וְגוֹ'. וְהוּא לֹא קִבֵּל מִמֶּנּוּ וְנִמְשַׁךְ אַחַר אִשְׁתּוֹ, וְגֹרַשׁ לְעוֹלָמִים, שֶׁהֲרֵי אִשָּׁה עוֹלָה לְמָקוֹם (למקום זה) וְלֹא יוֹתֵר, וְהָאִשָּׁה גָרְמָה מָוֶת לַכֹּל.</p>\n<p>בֹּא רְאֵה, לָעוֹלָם הַבָּא כָּתוּב (ישעיה סה) כִּי כִּימֵי הָעֵץ יְמֵי עַמִּי. כִּימֵי הָעֵץ - אוֹתוֹ שֶׁנּוֹדַע בְּאוֹתוֹ הַזְּמַן. כָּתוּב (שם כה) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ וְגוֹ'.</p>"],[9522011451,"<p>וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת. שָׁנִינוּ, אָמַר רַבִּי חִיָּיא, כָּתוּב וַיְחִי יַעֲקֹב בְּאֶרֶץ מִצְרַיִם שְׁבַע עֶשְׂרֵה שָׁנָה. שָׁם בְּקִיּוּמוֹ יַעֲקֹב, וְכָאן בְּמִיתָתוֹ יִשְׂרָאֵל, שֶׁכָּתוּב וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת. אָמַר רַבִּי יוֹסֵי, כָּךְ הוּא וַדַּאי, שֶׁהֲרֵי לֹא כָתוּב וַיִּקְרַב יוֹם יִשְׂרָאֵל לָמוּת, אֶלָּא יְמֵי, וְכִי בְּכַמָּה יָמִים מֵת בֶּן אָדָם? וַהֲרֵי בְּשָׁעָה אַחַת, בְּרֶגַע אֶחָד מֵת וְיוֹצֵא מִן הָעוֹלָם.</p>\n<p>אֶלָּא כָּךְ לָמַדְנוּ, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהָשִׁיב אֵלָיו אֶת רוּחוֹ, כָּל אוֹתָם יָמִים שֶׁעוֹמֵד בֶּן אָדָם בָּעוֹלָם הַזֶּה נִפְקָדִים לְפָנָיו וְנִכְנָסִים בְּחֶשְׁבּוֹן, וּכְשֶׁנִּקְרָבִים לְפָנָיו לְהִכָּנֵס בְּחֶשְׁבּוֹן, מֵת הָאָדָם, וּמֵשִׁיב הַקָּדוֹשׁ בָּרוּךְ הוּא אֵלָיו אֶת רוּחוֹ. אוֹתוֹ הַהֶבֶל שֶׁהוֹצִיא וְנָפַח בּוֹ, מֵשִׁיב אוֹתוֹ אֵלָיו.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁיָּמָיו הִתְקָרְבוּ אֶל הַמֶּלֶךְ בְּלִי בוּשָׁה, וְלֹא נִדְחָה יוֹם אֶחָד מֵהֶם הַחוּצָה שֶׁיִּמָּצֵא שֶׁבְּאוֹתוֹ יוֹם שֶׁנַּעֲשָׂה בּוֹ חֵטְא, לָכֵן כָּתוּב בְּצַדִּיקִים קְרִיבָה. (ואיך יקרבו) מִשּׁוּם שֶׁקְּרֵבִים יָמָיו לִפְנֵי הַמֶּלֶךְ בְּלִי בוּשָׁה.</p>\n<p>אוֹי לָרְשָׁעִים, שֶׁלֹּא כָתוּב בָּהֶם קְרִיבָה, וְאֵיךְ יִקְרְבוּ הַיָּמִים לִפְנֵי הַמֶּלֶךְ, שֶׁהֲרֵי כָּל יָמָיו נִמְצְאוּ בַּחֲטָאֵי הָעוֹלָם, וְלָכֵן לֹא יִקְרְבוּ לִפְנֵי הַמֶּלֶךְ וְלֹא יִמָּנוּ לְפָנָיו וְלֹא יִזָּכְרוּ לְמַעְלָה, אֶלָּא הֵם מִתְכַּלִּים מִתּוֹכָם. עֲלֵיהֶם כָּתוּב (משלי ד) דֶּרֶךְ רְשָׁעִים כָּאֲפֵלָה לֹא יָדְעוּ בַּמֶּה יִכָּשֵׁלוּ.</p>\n<p>וְכָאן וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת וַדַּאי, בְּלִי בוּשָׁה, בִּשְׁלֵמוּת, בְּחֶדְוָה שְׁלֵמָה, וּמִשּׁוּם כָּךְ יְמֵי יִשְׂרָאֵל, שֶׁהָיָה יִשְׂרָאֵל יוֹתֵר שָׁלֵם מִיַּעֲקֹב. וְאִם תֹּאמַר, הֲרֵי כָּתוּב (בראשית כה) וְיַעֲקֹב אִישׁ תָּם, שָׁלֵם? שָׁלֵם הָיָה, אֲבָל לֹא שָׁלֵם בְּדַרְגָּה עֶלְיוֹנָה כְּמוֹ יִשְׂרָאֵל.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, בְּשָׁעָה שֶׁיְּמֵי הָאָדָם נִפְקָדִים לִפְנֵי הַמֶּלֶךְ, יֵשׁ צַדִּיק שֶׁנִּפְקָדִים יָמָיו, וְהֵם רְחוֹקִּים מִלִּפְנֵי הַמֶּלֶךְ, וְיֵשׁ צַדִּיק שֶׁכַּאֲשֶׁר נִפְקָדִים יָמָיו, הֵם קְרוֹבִים וּסְמוּכִים לַמֶּלֶךְ וְלֹא מְרֻחָקִים, נִכְנָסִים בְּלִי בוּשָׁה וּקְרֵבִים לַמֶּלֶךְ. אַשְׁרֵי חֶלְקָם. זֶהוּ שֶׁכָּתוּב וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת.</p>"],[9522011452,"<p>וַיִּקְרָא לִבְנוֹ לְיוֹסֵף. אָמַר רַבִּי יִצְחָק, וְכִי שְׁאָר הַשְּׁבָטִים לֹא בָנָיו הֵם? אֶלָּא, אָמַר רַבִּי אַבָּא, יוֹסֵף הָיָה בְנוֹ יוֹתֵר מִכֻּלָּם, שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁאֵשֶׁת פּוֹטִיפַר דָּחֲקָה אֶת יוֹסֵף, מַה כָּתוּב? וַיָּבֹא הַבַּיְתָה לַעֲשׂוֹת מְלַאכְתּוֹ וְאֵין אִישׁ מֵאַנְשֵׁי הַבַּיִת. פָּסוּק זֶה הָיָה צָרִיךְ לִכְתֹּב וְאֵין אִישׁ בַּבַּיִת, מַה זֶּה מֵאַנְשֵׁי הַבַּיִת? אֶלָּא לְהַכְלִיל אֶת דְּמוּתוֹ שֶׁל יַעֲקֹב שֶׁהָיְתָה שָׁם וְנִמְצְאָה שָׁם, וּמִשּׁוּם כָּךְ מֵאַנְשֵׁי הַבַּיִת, אֲבָל אִישׁ אַחֵר הָיָה שָׁם. כֵּיוָן שֶׁהֵרִים יוֹסֵף עֵינָיו וְרָאָה אֶת דְּמוּת אָבִיו, יָשַׁב בְּקִיּוּמוֹ וְנִרְתַּע לְאָחוֹר.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וַיְמָאֵן וַיֹּאמֶר אֶל אֵשֶׁת אֲדנָיו. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתָּה אָמַרְתָּ וַיְמָאֵן וַיּאמֶר, חַיֶּיךְ וַיְמָאֵן וַיֹּאמֶר אַחֵר יָבא לְבָרֵךְ אֶת בָּנֶיךְ וְיִתְבָּרְכוּ בוֹ, זֶהוּ שֶׁכָּתוּב וַיְמָאֵן אָבִיו וַיֹּאמֶר יָדַעְתִּי בְנִי יָדַעְתִּי.</p>\n<p>כֵּיוָן שֶׁאָמַר יָדַעְתִּי בְנִי, לָמָּה אָמַר יָדַעְתִּי אַחֵר? אֶלָּא אָמַר יָדַעְתִּי בְנִי, בִּזְמַן שֶׁעָמַדְתָּ בְּגוּפְךְ שֶׁאַתָּה בָּרוּר, כְּשֶׁרָאִיתָ אֶת דְּמוּתִי וְשַׁבְתָּ בְּקִיּוּמְךְ, וּמִשּׁוּם כָּךְ כָּתוּב יָדַעְתִּי בְנִי יָדַעְתִּי, עַל מַה שֶּׁאָמַרְתָּ שֶׁזֶּהוּ הַבְּכוֹר, גַּם הוּא יִהְיֶה לְּעָם וְגַם הוּא יִגְדָּל, וְכָאן מִשּׁוּם כָּךְ כָּתוּב וַיִּקְרָא לִבְנוֹ לְיוֹסֵף, לִבְנוֹ לְיוֹסֵף מַמָּשׁ.</p>\n<p>דָּבָר אַחֵר וַיִּקְרָא לִבְנוֹ לְיוֹסֵף - שֶׁבִּדְמוּת אַחַת הָיוּ נִרְאִים. שֶׁכָּל מִי שֶׁרָאָה אֶת יוֹסֵף, הָיָה מֵעִיד שֶׁבְּנוֹ שֶׁל יַעֲקֹב הָיָה. רַבִּי יוֹסֵי אָמַר, הַכֹּל כָּךְ הוּא, וְעוֹד, שֶׁיּוֹסֵף זָן אוֹתוֹ וְאֶת בָּנָיו בְּזִקְנוּתוֹ, וְלָכֵן בְּנוֹ מַמָּשׁ יוֹתֵר מִכֻּלָּם. וַיִּקְרָא לִבְנוֹ לְיוֹסֵף, לָמָּה לְיוֹסֵף וְלֹא לְאַחֵר? מִשּׁוּם שֶׁהָיְתָה רְשׁוּת בְּיָדוֹ לְהַעֲלוֹתוֹ מִשָּׁם.</p>\n<p>רַבִּי יוֹסֵי אָמַר, כֵּיוָן שֶׁיַּעֲקֹב הָיָה יוֹדֵעַ שֶׁבָּנָיו יִשְׁתַּעְבְּדוּ בַגָּלוּת שָׁם בְּמִצְרַיִם, לָמָּה לֹא נִקְבַּר שָׁם כְּדֵי שֶׁזְּכוּתוֹ תָּגֵן עַל בָּנָיו? לָמָּה רָצָה לַעֲלוֹת מִשָּׁם, וַהֲרֵי כָּתוּב (תהלים קג) כְּרַחֵם אָב עַל בָּנִים, אֵיפֹה הָרַחֲמָנוּת?</p>\n<p>אֶלָּא, כָּךְ שָׁנִינוּ, בְּשָׁעָה שֶׁהָיָה יוֹרֵד יַעֲקֹב לְמִצְרַיִם, הָיָה פוֹחֵד, וְהָיָה אוֹמֵר: חַס וְחָלִילָה יִכְלוּ בָנַי בֵּין הָעַמִּים, וְאוּלַי הַקָּדוֹשׁ בָּרוּךְ הוּא יְסַלֵּק שְׁכִינָתוֹ מִמֶּנִּי כְּבַתְּחִלָּה. מַה כָּתוּב? וַיֵּרָא אֱלֹהִים אֶל יַעֲקֹב וְגוֹ', (ויאמר אלהים לישראל) אַל תִּירָא מֵרְדָה מִצְרַיְמָה כִּי לְגוֹי גָּדוֹל אֲשִׂימְךְ שָׁם. וּמַה שֶּׁאָמַרְתָּ אוּלַי אֲסַלֵּק שְׁכִינָתִי מִבֵּינְךְ - אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה.</p>\n<p>אָמַר עוֹד, פּוֹחֵד אֲנִי שֶׁמָּא אֶקָּבֵר שָׁם וְלֹא אֶזְכֶּה עִם אֲבוֹתַי. אָמַר לוֹ, וְאָנֹכִי אֲעַלְךְ גַּם עָלֹה. אֲעַלְךְ - מִמִּצְרַיִם. גַּם עָלֹה - לְהִקָּבֵר בְּקֶבֶר אֲבוֹתֶיךְ.</p>\n<p>מִשּׁוּם כָּךְ רָצָה לְהַעֲלוֹת עַצְמוֹ מִמִּצְרַיִם: אֶחָד - כְּדֵי שֶׁלֹּא יַעֲשׂוּ מִמֶּנּוּ יִרְאָה, שֶׁהֲרֵי רָאָה שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִפָּרַע מִיִּרְאָתָם. וְאֶחָד - שֶׁרָאָה שֶׁשְּׁכִינָה תָּשִׂים מְדוֹרָהּ בֵּין בָּנָיו בַּגָּלוּת. וְאֶחָד - כְּדֵי שֶׁיִּהְיֶה גוּפוֹ דָר בֵּין גּוּפוֹת אֲבוֹתָיו לְהִכָּלֵל בֵּינֵיהֶם, וְלֹא יִמָּנֶה עִם רִשְׁעֵי מִצְרַיִם.</p>\n<p>וְשָׁנִינוּ, הַגּוּף שֶׁל יַעֲקֹב נִמְשַׁךְ מִיָּפְיוֹ שֶׁל אָדָם הָרִאשׁוֹן, וְהָיְתָה דְמוּתוֹ שֶׁל יַעֲקֹב דְמוּת עֶלְיוֹנָה וּקְדוֹשָׁה, דְּמוּת שֶׁל הַכִּסֵּא הַקָּדוֹשׁ, וְלֹא רָצָה לְהִקָּבֵר בֵּין רְשָׁעִים. וְסוֹד הַדָּבָר, שֶׁבָּאָבוֹת אֵין כְּלָל פֵּרוּד, וְעַל זֶה כָּתוּב וְשָׁכַבְתִּי עִם אֲבֹתַי.</p>\n<p>וַיִּקְרָא לִבְנוֹ לְיוֹסֵף. בְּנוֹ - בִּדְמוּת אַחַת שֶׁל הַפָּנִים, מִשּׁוּם שֶׁבִּרְצוֹן הָרוּחַ וְהַלֵּב הוֹלִיד אוֹתוֹ יוֹתֵר מִכֻּלָּם בֹּא רְאֵה מַה כָּתוּב, (בראשית ל) הַמְעַט קַחְתֵּךְ אֶת אִישִׁי, שֶׁכָּל רְצוֹנוֹ שֶׁל יַעֲקֹב הָיָה בְרָחֵל, וּמִשּׁוּם כָּךְ וַיִּקְרָא לִבְנוֹ לְיוֹסֵף.</p>\n<p>שָׁנִינוּ, רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (דברים כט) הַנִּסְתָּרֹת לַה' אֱלֹהֵינוּ וְגוֹ'. הַנִּסְתָּרֹת לַה' אֱלֹהֵינוּ, בֹּא רְאֵה כַּמָּה יֵשׁ לָאָדָם לְהִזָּהֵר מֵחֲטָאָיו וּלְהִסְתַּכֵּל שֶׁלֹּא יַעֲבֹר עַל מִצְוַת רִבּוֹנוֹ, שֶׁשָּׁנִינוּ, כָּל מַה שֶּׁאָדָם עוֹשֶׂה בָּעוֹלָם הַזֶּה, אוֹתָם מַעֲשִׂים כְּתוּבִים בַּסֵּפֶר וְנִכְנָסִים בְּחֶשְׁבּוֹן לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְהַכֹּל גָּלוּי לְפָנָיו. זֶהוּ שֶׁכָּתוּב (ירמיה כג) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם ה'!? אִם כָּךְ, אֵיךְ לֹא יִשָּׁמֵר אָדָם מִלַּחֲטֹא לִפְנֵי רִבּוֹנוֹ. וְשָׁנִינוּ, אֲפִלּוּ אוֹתוֹ (מי) מַה שֶּׁחָשַׁב אָדָם וְעָלָה בִרְצוֹנוֹ, הַכֹּל נִמְצָא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא נֶאֱבָד מִמֶּנּוּ.</p>\n<p>בֹּא רְאֵה, בְּאוֹתוֹ לַיְלָה שֶׁנִּכְנְסָה לֵאָה אֶל יַעֲקֹב וְנָתְנָה לוֹ אוֹתָם סִימָנִים שֶׁנָּתַן יַעֲקֹב לְרָחֵל, עָלָה בִרְצוֹנוֹ שֶׁהִיא רָחֵל וְשִׁמֵּשׁ בָּהּ תַּשְׁמִישׁ, וְאוֹתָהּ טִפָּה רִאשׁוֹנָה שֶׁל יַעֲקֹב הָיְתָה, שֶׁכָּתוּב (בראשית מט) כֹּחִי וְרֵאשִׁית אוֹנִי, וְסָבַר שֶׁהִיא רָחֵל. הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא מְגַלֵּה עֲמֻקּוֹת וְנִסְתָּרוֹת וְיוֹדֵעַ מַה שֶּׁבַּחֲשֵׁכָה, הֶעֱלָה אוֹתוֹ רָצוֹן לִמְקוֹמוֹ, וּבְכוֹרַת רְאוּבֵן עָלְתָה לְיוֹסֵף. מָה הַטַּעַם? מִשּׁוּם שֶׁהֲרֵי שֶׁל רָחֵל הָיְתָה אוֹתָהּ טִפָּה רִאשׁוֹנָה שֶׁיָּצְאָה מִיַּעֲקֹב, מִשּׁוּם שֶׁהָיְתָה שֶׁלָּהּ, אוֹתָהּ בְּכוֹרָה מַמָּשׁ שֶׁל רְאוּבֵן יָרַשׁ יוֹסֵף, וְרָחֵל יָרְשָׁה אֶת שֶׁלָּהּ.</p>\n<p>וּמִשּׁוּם כָּךְ, סוֹד הַדָּבָר, לֹא הִתְעַלָּה רְאוּבֵן בַּשֵּׁם כִּשְׁאָר הַשְּׁבָטִים, אֶלָּא רְאוּבֵן, כְּלוֹמַר רְאוּ בֵן. רְאוּ בֵן סְתָם. וְהַבֵּן הַזֶּה לֹא נוֹדַע שְׁמוֹ. וְעַל כֵּן לֹא קָרְאָה לֵאָה בְּנִי בַּשֵּׁם הַזֶּה, וְלֹא נִקְרָא רְאוּ בְנִי, שֶׁהֲרֵי לֵאָה יָדְעָה אֶת הַמַּעֲשֶׂה.</p>\n<p>וְשָׁנִינוּ, גָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאֵין רְצוֹן יַעֲקֹב הָיָה לַחֲטֹא לְפָנָיו בָּזֶה וְלֹא הִסְתַּכֵּל בְּרָצוֹן בְּאִשָּׁה אַחֶרֶת בְּאוֹתָהּ שָׁעָה כִּשְׁאָר רִשְׁעֵי הָעוֹלָם, וְעַל כָּךְ כָּתוּב (שם לה) וַיִּהְיוּ בְּנֵי יַעֲקֹב שְׁנֵים עָשָׂר, שֶׁהֲרֵי בְּנֵיהֶם שֶׁל שְׁאָר הָרְשָׁעִים בָּעוֹלָם שֶׁעוֹשִׂים אוֹתוֹ מַעֲשֶׂה, נִקְרָאִים בְּשֵׁם אַחֵר, וַהֲרֵי דָּבָר זֶה יָדוּעַ בֵּין הַחֲבֵרִים, וּמִשּׁוּם כָּךְ וַיִּקְרָא לִבְנוֹ לְיוֹסֵף, בְּנוֹ מַמָּשׁ, מֵהָרֵאשִׁית וְעַד הַסִּיּוּם (בנו) הָיָה בְנוֹ.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, בַּמָּה הִשְׁבִּיעַ יַעֲקֹב אֶת יוֹסֵף, שֶׁכָּתוּב שִׂים נָא יָדְךְ תַּחַת יְרֵכִי? אֶלָּא בְּאוֹתוֹ אוֹת הַבְּרִית שֶׁהָיָה רָשׁוּם בִּבְשָׂרוֹ, שֶׁזּוֹ חֲשִׁיבוּת הָאָבוֹת יוֹתֵר מֵהַכֹּל, וּבְרִית זוֹ הִיא סוֹד שֶׁל יוֹסֵף.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּאַבְרָהָם וּבְיַעֲקֹב כָּתוּב שִׂים נָא יָדְךְ תַּחַת יְרֵכִי. תַּחַת יְרֵכִי, כְּלוֹמַר בְּאוֹתוֹ מָקוֹם שֶׁרָמוּז בַּשֵּׁם הַקָּדוֹשׁ וּמוֹצִיא זֶרַע קֹדֶשׁ נֶאֱמָן לָעוֹלָם. בְּיִצְחָק לֹא כָתוּב, כִּי יָצָא מִמֶּנּוּ עֵשָׂו.</p>\n<p>עוֹד, מָה הַטַּעַם שִׂים נָא יָדְךְ תַּחַת יְרֵכִי, אַל נָא תִקְבְּרֵנִי בְּמִצְרָיִם? אֶלָּא אָמַר לוֹ יַעֲקֹב לְיוֹסֵף, בָּרֹשֶׁם הַקָּדוֹשׁ הַזֶּה הִשָּׁבַע לִי, שֶׁהוֹצִיא זֶרַע קָדוֹשׁ נֶאֱמָן לָעוֹלָם, וְנִשְׁמָר וְלֹא נִטְמָא לְעוֹלָמִים, שֶׁלֹּא יִקָּבֵר בֵּין אוֹתָם הַטְּמֵאִים שֶׁלֹּא שָׁמְרוּ אוֹתוֹ לְעוֹלָמִים, שֶׁכָּתוּב בָּהֶם (יחזקאל כג) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרם וְזִרְמַת סוּסִים זִרְמָתָם.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי יוֹסֵף, שֶׁשָּׁמַר אוֹתוֹ מֵעַל הַכֹּל, לָמָּה נִקְבַּר בֵּינֵיהֶם? אֶלָּא שָׁנִינוּ, כָּתוּב (שם א) הָיֹה הָיָה דְבַר ה' אֶל יְחֶזְקֵאל בֶּן בּוּזִי הַכֹּהֵן בְּאֶרֶץ כַּשְׂדִּים עַל נְהַר כְּבָר. וַהֲרֵי שָׁנִינוּ שֶׁשְּׁכִינָה לֹא שׁוֹרָה, רַק בְּאֶרֶץ יִשְׂרָאֵל, אָז לָמָּה כָּאן שְׁכִינָה? אֶלָּא כָּתוּב עַל נְהַר כְּבָר, וְכָתוּב וַתְּהִי עָלָיו שָׁם יַד ה'. אַף כָּאן, אֲרוֹנוֹ שֶׁל יוֹסֵף נִשְׁלַךְ בְּתוֹךְ הַמַּיִם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אִם יוֹסֵף יַעֲלֶה מִכָּאן, הַגָּלוּת לֹא תִתְקַיֵּם, אֶלָּא תִּהְיֶה קְבוּרָתוֹ בְּמָקוֹם שֶׁלֹּא נִטְמָא, וְיִסְבְּלוּ בְּנֵי יִשְׂרָאֵל אֶת הַגָּלוּת.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, רָאָה יַעֲקֹב שֶׁהֲרֵי בַּכֹּל נִתְקַן לַכִּסֵּא הַקָּדוֹשׁ בָּאָבוֹת (כאבות). אָמַר, אִם כָּךְ, יִקָּבֵר, אֵיךְ הַגּוּף הַזֶּה יִתְאַחֵד בָּאָבוֹת. וַאֲפִלּוּ הַמְּעָרָה שֶׁנִּקְבַּר שָׁם נִקְרֵאת מַכְפֵּלָה, מִשּׁוּם שֶׁכָּל דָּבָר שֶׁל מַכְפֵּלָה הוּא שְׁנַיִם וְאֶחָד, אַף הַמְּעָרָה שְׁנַיִם וְאֶחָד.</p>\n<p>וּבֹא וּרְאֵה, הָאָבוֹת זָכוּ לְהִקָּבֵר שָׁם הֵם וְזִוּוּגֵיהֶם. יַעֲקֹב - הוּא וְלֵאָה. מָה הַטַּעַם רָחֵל לֹא, וַהֲרֵי כָּתוּב וְרָחֵל עֲקָרָה, שֶׁהִיא עִקַּר הַבַּיִת? אֶלָּא לֵאָה זָכְתָה בּוֹ לְהוֹצִיא שִׁשָּׁה שְׁבָטִים מִגֶּזַע קָדוֹשׁ בָּעוֹלָם יוֹתֵר, וּמִשּׁוּם כָּךְ הִיא נִתְּנָה עִמּוֹ לְזִוּוּג בַּמְּעָרָה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּל יָמֶיהָ הָיְתָה לֵאָה עוֹמֶדֶת בְּפָרָשַׁת דְּרָכִים, וּבָכְתָה בִּשְׁבִיל יַעֲקֹב, כְּשֶׁשָּׁמְעָה שֶׁהוּא צַדִּיק, וּתְפִלָּה הִיא הִקְדִּימָה לוֹ, וְהַיְנוּ שֶׁכָּתוּב (בראשית כט) וְעֵינֵי לֵאָה רַכּוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁמַּקְדִּימָה וְיוֹשֶׁבֶת בְּפָרָשַׁת דְּרָכִים לִשְׁאֹל.</p>\n<p>רָחֵל לֹא יָצְאָה לַדְּרָכִים לְעוֹלָם, מִשּׁוּם כָּךְ זָכְתָה לֵאָה לְהִקָּבֵר עִמּוֹ, וְרָחֵל קְבוּרָתָהּ עוֹמֶדֶת בְּפָרָשַׁת דְּרָכִים וְנִקְבְּרָה שָׁם. זֶהוּ שֶׁכָּתוּב וַאֲנִי בְּבאִי מִפַּדַּן אֲרָם מֵתָה עָלַי רָחֵל. מַה זֶּה עָלַי? עָלַי וַדַּאי, כְּלוֹמַר בִּגְלָלִי. בְּאֶרֶץ כְּנַעַן בַּדֶּרֶךְ - בִּגְלָלִי מֵתָה בַּדֶּרֶךְ, שֶׁלֹּא יָצְאָה בִּשְׁבִילִי לְעוֹלָמִים כְּמוֹ אֲחוֹתָהּ.</p>\n<p>מִשּׁוּם כָּךְ, לֵאָה שֶׁיָּצְאָה וּבָכְתָה בְּפָרָשַׁת דְּרָכִים בִּשְׁבִיל יַעֲקֹב, זָכְתָה לְהִקָּבֵר עִמּוֹ. רָחֵל שֶׁלֹּא רָצְתָה לָצֵאת וְלִשְׁאֹל בִּשְׁבִילוֹ, מִשּׁוּם כָּךְ קְבוּרָתָהּ בְּפָרָשַׁת דְּרָכִים, וְסוֹד הַדָּבָר הֲרֵי בֵּאַרְנוּ וְנִתְבָּאֵר, זֶה בְּגָלוּי וְזֶה בְּנִסְתָּר.</p>\n<p>וּבֹא וּרְאֵה, שֶׁשָּׁנִינוּ, דְּמָעוֹת רַבּוֹת שָׁפְכָה אוֹתָהּ לֵאָה הַצַּדֶּקֶת כְּדֵי לִהְיוֹת חֶלְקוֹ שֶׁל יַעֲקֹב וְלֹא שֶׁל אוֹתוֹ עֵשָׂו הָרָשָׁע. וְהַיְנוּ מַה שֶּׁשָּׁנִינוּ, כָּל אָדָם שֶׁשּׁוֹפֵךְ דְּמָעוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, אַף עַל גַּב שֶׁנִּגְזַר עָלָיו עֹנֶשׁ - הוּא יִקָּרַע, וְלֹא יוּכַל אוֹתוֹ עֹנֶשׁ לִשְׁלֹט בּוֹ. מִנַּיִן לָנוּ. מִלֵּאָה, שֶׁהֲרֵי נִגְזַר עַל לֵאָה לִהְיוֹת חֶלְקוֹ שֶׁל עֵשָׂו, הִיא בְּבַקָּשָׁתָהּ הִקְדִּימָה לְיַעֲקֹב וְלֹא נִתְּנָה לְעֵשָׂו.</p>\n<p>אָמַר רַבִּי חִיָּיא, וְשָׁכַבְתִּי עִם אֲבתַי. רַבִּי יִצְחָק פָּתַח וְאָמַר, (קהלת א) מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ שֶׁיַּעֲמֹל תַּחַת הַשָּׁמֶשׁ. בְּכַמָּה מְקוֹמוֹת נִתְבָּאֵר שֶׁהִסְתַּכַּלְנוּ בְּדִבְרֵי שְׁלֹמֹה וְנִרְאָה שֶׁדְּבָרָיו סְתוּמִים, אֲבָל כָּל דִּבְרֵי שְׁלֹמֹה, כֻּלָּם נִקְרְאוּ בְחָכְמָה.</p>"],[9522011453,"<p>שֶׁשָּׁנִינוּ, כָּתוּב וַתֵּרֶב חָכְמַת שְׁלֹמֹה. בִּימֵי שְׁלֹמֹה הַמֶּלֶךְ עָמְדָה הַלְּבָנָה בִּשְׁלֵמוּת, וְהַיְינוּ שֶׁכָּתוּב (מלכים א ה) וַתֵּרֶב חָכְמַת שְׁלֹמֹה מֵחָכְמַת כָּל בְּנֵי קֶדֶם. שָׁם שָׁנִינוּ, מִי הֵם בְּנֵי קֶדֶם? הֲרֵי פֵּרְשׁוּהָ, אֲבָל חָכְמַת בְּנֵי קֶדֶם הִיא חָכְמָה שֶׁיָּרְשׁוּ מֵאַבְרָהָם.</p>\n<p>שֶׁשָּׁנִינוּ, כָּתוּב (בראשית כה) וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק. מַה זֶּה אֶת כָּל אֲשֶׁר לוֹ? זוֹ חָכְמָה עֶלְיוֹנָה שֶׁהָיָה יוֹדֵעַ בַּשֵּׁם הַקָּדוֹשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמַשְׁמָע אֶת, אֶת כָּל אֲשֶׁר לוֹ - שֶׁהָיָה שֶׁלּוֹ. כְּמוֹ שֶׁשָּׁנִינוּ, בְּאוֹתָהּ בַּת שֶׁהָיְתָה לְאַבְרָהָם, וּבַכֹּל שְׁמָהּ.</p>\n<p>וְלִבְנֵי הַפִּילַגְשִׁים אֲשֶׁר לְאַבְרָהָם נָתַן אַבְרָהָם מַתָּנֹת וְגוֹ'. שֶׁנָּתַן לָהֶם דְּבָרִים יְדוּעִים בַּכְּתָרִים הַתַּחְתּוֹנִים. וּבְאֵיזֶה מָקוֹם הִשְׁרָה אוֹתָם? אֶל אֶרֶץ קֶדֶם, וּמִשָּׁם יָרְשׁוּ בְּנֵי קֶדֶם חָכְמָה, וְהַיְנוּ שֶׁכָּתוּב מֵחָכְמַת כָּל בְּנֵי קֶדֶם.</p>\n<p>שָׁנִינוּ, יוֹם אֶחָד הָיָה בָּא רַבִּי שִׁמְעוֹן מִקַּפּוֹטְקִיָּא לְלוֹד, וְהָיָה עִמּוֹ רַבִּי אַבָּא וְרַבִּי יְהוּדָה. רַבִּי אַבָּא הָיָה עָיֵף וְרָץ אַחֲרֵי רַבִּי שִׁמְעוֹן, שֶׁהָיָה רוֹכֵב. אָמַר רַבִּי אַבָּא, וַדַּאי (הושע יא) אַחֲרֵי ה' יֵלֵכוּ כְּאַרְיֵה יִשְׁאָג.</p>\n<p>יָרַד רַבִּי שִׁמְעוֹן, אָמַר לוֹ, וַדַּאי כָּתוּב (דברים ט) וָאֵשֵׁב בָּהָר אַרְבָּעִים יוֹם וְאַרְבָּעִים לַיְלָה. וַדַּאי שֶׁחָכְמָה לֹא מִתְיַשֶּׁבֶת אֶלָּא כְּשֶׁאָדָם יוֹשֵׁב וְלֹא הוֹלֵךְ, אֶלָּא עוֹמֵד בְּקִיּוּמוֹ. וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים עַל מַה כָּתוּב וָאֵשֵׁב. עַכְשָׁו בִּמְנוּחָה הַדָּבָר תָּלוּי. יָשְׁבוּ.</p>\n<p>אָמַר רַבִּי אַבָּא, כָּתוּב וַתֵּרֶב חָכְמַת שְׁלמֹה מֵחָכְמַת כָּל בְּנֵי קֶדֶם וּמִכָּל חָכְמַת מִצְרַים. מַה הִיא חָכְמַת שְׁלֹמֹה, וּמַה הִיא חָכְמַת מִצְרַיִם, וּמַה הִיא חָכְמַת כָּל בְּנֵי קֶדֶם? אָמַר לוֹ, בּא רְאֵה, בְּכַמָּה מְקוֹמוֹת פֵּרְשׁוּהָ בְּאוֹתוֹ שֵׁם. שֶׁהַלְּבָנָה כְּשֶׁמִּתְבָּרֶכֶת מֵהַכֹּל כָּתוּב וַתֵּרֶב, בִּימֵי שְׁלֹמֹה, שֶׁהִתְרַבְּתָה וְהִתְבָּרְכָה וְעָמְדָה בִּשְׁלֵמוּת.</p>\n<p>וְשָׁנִינוּ, אֶלֶף הָרִים מִתְגַּדְּלִים לְפָנֶיהָ, וְכֻלָּם הָיוּ לְפָנֶיהָ שְׁאִיבָה אַחַת, וְאֶלֶף נְהָרוֹת גְּדוֹלִים לָהּ, וְגוֹמַעַת אֶת כֻּלָּם בִּגְמִיעָה אַחַת.</p>\n<p>צִפָּרְנֶיהָ אוֹחֲזוֹת בְּאֶלֶף וְשִׁבְעִים עֲבָרִים. יָדֶיהָ אֲחוּזוֹת לְעֶשְׂרִים וְאַרְבָּעָה (וחמשה) אֶלֶף עֲבָרִים, אֵין יוֹצֵא מִמֶּנָּה לְצַד זֶה, וְאֵין יוֹצֵא מִמֶּנָּה לְצַד אַחֵר. כַּמָּה וְכַמָּה אַלְפֵי מָגִנִּים אֲחוּזִים בְּשַׂעֲרוֹתֶיהָ.</p>\n<p>עָלֶם אֶחָד שֶׁאָרְכּוֹ מֵרֹאשׁ הָעוֹלָם וְעַד סוֹף הָעוֹלָם יוֹצֵא בֵּין רַגְלֶיהָ, מִתְלַבֵּשׁ בְּשִׁשִּׁים מַכּוֹת אֵשׁ, בִּגְוָנִים אֵלּוּ הִתְמַנָּה עַל הַתַּחְתּוֹנִים (מתחת) מֵאַרְבָּעָה צְדָדֶיהָ. זֶהוּ נַעַר שֶׁאוֹחֵז שֵׁשׁ מֵאוֹת וּשְׁלֹשׁ עֶשְׂרֵה מַפְתְּחוֹת עֶלְיוֹנִים מִצַּד הָאֵם, וְכָל הַמַּפְתְּחוֹת הָעֶלְיוֹנִים בְּלַהַט הַחֶרֶב שֶׁחוֹגֵר בְּמָתְנָיו תְּלוּיִים.</p>\n<p>לְאוֹתוֹ נַעַר קוֹרְאִים חֲנוֹךְ בֶּן יֶרֶד, בְּאוֹתָן בָּרַיְתוֹת, שֶׁכָּתוּב (משלי כב) חֲנֹךְ לַנַּעַר עַל פִּי דַרְכּוֹ. וְאִם תֹּאמַר, מִשְׁנָה הִיא וְלֹא בָּרַיְתָא - בְּמִשְׁנָתֵנוּ בֵּאַרְנוּ אֶת הַדְּבָרִים, וַהֲרֵי נִתְבָּאֵר, וְהַכֹּל דָּבָר אֶחָד הִסְתַּכְּלוּ (נתקנו). תַּחְתָּיו תּוֹפְסוֹת חַיּוֹת הַשָּׂדֶה, שֶׁשָּׁנִינוּ (שבא ראה), כְּמוֹ שֶׁיִּשְׂרָאֵל הַקָּדוֹשׁ הָעֶלְיוֹן נִקְרָא בֵּן לְאִמּוֹ, שֶׁכָּתוּב (שם ד) כִּי בֵּן הָיִיתִי לְאָבִי רַךְ וְיָחִיד לִפְנֵי אִמִּי, וְכָתוּב (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, כָּךְ גַּם לְמַטָּה זֶה נִקְרָא נַעַר לְאִמּוֹ, שֶׁכָּתוּב (הושע יא) כִּי נַעַר יִשְׂרָאֵל וָאֹהֲבֵהוּ. וּבְכַמָּה גְוָנִים נִקְרָא בֶּן יֶרֶד, וַהֲרֵי בֵּאַרְנוּ. אֲבָל בֹּא רְאֵה, בֶּן יֶרֶד מַמָּשׁ, שֶׁשָּׁנִינוּ, עֶשֶׂר יְרִידוֹת יָרְדָה שְׁכִינָה אָרֶץ, וְאֶת כֻּלָּם בֵּאֲרוּ הַחֲבֵרִים וְנִתְבָּאֵר. וְתַחַת זֶה כַּמָּה חַיּוֹת עוֹמְדוֹת, שֶׁנִּקְרָאוֹת חַיּוֹת הַשָּׂדֶה מַמָּשׁ.</p>\n<p>תַּחַת אוֹתָן הַחַיּוֹת נֶאֱחָזוֹת שַׂעֲרוֹת הַלְּבָנָה שֶׁנִּקְרָאוֹת כּוֹכְבֵי שַׁרְבִיט, שֶׁל שַׁרְבִיט מַמָּשׁ, בַּעֲלֵי דִין, בַּעֲלֵי מִשְׁקָל, בַּעֲלֵי הַדִּין הַקָּשֶׁה, בַּעֲלֵי חֻצְפָּה, וְכֻלָּם נִקְרָאִים בַּעֲלֵי (שערות) אַרְגָּמָן. יָדֶיהָ וְרַגְלֶיהָ אֲחוּזוֹת בָּזֶה כְּמוֹ אַרְיֵה (קדוש) חָזָק שֶׁאוֹחֵז בְּטִרְפּוֹ, וְעַל זֶה כָּתוּב (מיכה ה) וְטָרַף וְאֵין מַצִּיל.</p>\n<p>צִפָּרְנֶיהָ - כָּל אוֹתָם שֶׁמַּזְכִּירִים אֶת חֲטָאֵי בְּנֵי הָאָדָם וְכוֹתְבִים וְרוֹשְׁמִים אֶת חֲטָאֵיהֶם בְּתֹקֶף הַדִּין הַקָּשֶׁה, וְלָכֵן כָּתוּב (ירמיה טז) חַטַּאת יְהוּדָה כְּתוּבָה בְּעֵט בַּרְזֶל בְּצִפֹּרֶן שָׁמִיר. מַה זֶּה שָׁמִיר? אוֹתוֹ שֶׁרוֹשֵׁם וְנוֹקֵב בָּאֶבֶן וְחוֹתֵךְ אוֹתָהּ לְכָל צַד.</p>\n<p>זֻהֲמַת הַצִּפָּרְנַיִם - כָּל אֵלּוּ שֶׁלֹּא נִדְבָּקִים בְּגוּף הַמֶּלֶךְ וְיוֹנְקִים מִצַּד הַטֻּמְאָה כְּשֶׁמַּתְחִילָה הַלְּבָנָה לְהִפָּגֵם.</p>\n<p>וּמִשּׁוּם שֶׁשְּׁלֹמֹה הַמֶּלֶךְ יָרַשׁ אֶת הַלְּבָנָה בִּשְׁלֵמוּתָהּ, צָרִיךְ לִירַשׁ אוֹתָהּ בִּפְגִימָתָהּ, וְלָכֵן הִשְׁתַּדֵּל לָדַעַת אֶת דַּעַת (רצון) הָרוּחוֹת וְהַשֵּׁדִים, כְּדֵי לִירַשׁ אֶת הַלְּבָנָה בְּכָל צְדָדֶיהָ.</p>\n<p>וּבִימֵי שְׁלֹמֹה הַמֶּלֶךְ בַּכֹּל הֵאִירָה הַלְּבָנָה. זֶהוּ שֶׁכָּתוּב (מלכים א ה) וַתֵּרֶב חָכְמַת שְׁלֹמֹה. וַתֵּרֶב דַּוְקָא. מֵחָכְמַת כָּל בְּנֵי קֶדֶם, סוֹד עֶלְיוֹן הוּא, כַּכָּתוּב (בראשית לו) וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם וְגוֹ', וְאֵלֶּה נִקְרָאִים בְּנֵי קֶדֶם, שֶׁכֻּלָּם לֹא הִתְקַיְּמוּ, פְּרָט לָזֶה שֶׁכָּלוּל זָכָר וּנְקֵבָה, שֶׁנִּקְרָא הֲדַר, שֶׁכָּתוּב וַיִּמְלֹךְ תַּחְתָּיו הֲדַר וְגוֹ'.</p>\n<p>וְשָׁנִינוּ, שֶׁאַף עַל גַּב שֶׁהִתְקַיְּמָה (שהאירה הלבנה), לֹא הֵאִירָה בִּשְׁלֵמוּת, עַד שֶׁבָּא שְׁלמֹה שֶׁרָאוּי כְּנֶגְדָּהּ, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁמִּשּׁוּם כָּךְ אִמּוֹ הָיְתָה בַּת שֶׁבַע.</p>\n<p>וּמִכָּל חָכְמַת מִצְרַיִם - זוֹ הַחָכְמָה הַתַּחְתּוֹנָה שֶׁנִּקְרֵאת שִׁפְחָה שֶׁאַחַר הָרֵחַיִם, וְהַכֹּל כָּלְלָה חָכְמָה זוֹ שֶׁל שְׁלֹמֹה - חָכְמַת בְּנֵי קֶדֶם וְחָכְמַת מִצְרַיִם. אָמַר רַבִּי אַבָּא, בָּרוּךְ הָרַחֲמָן שֶׁשָּׁאַלְתִּי דָבָר זֶה לְפָנֶיךְ, שֶׁהֲרֵי בְּכָל הַדְּבָרִים הַלָּלוּ (דבר זה) זָכִיתִי. אָמַר רַבִּי שִׁמְעוֹן, דְּבָרִים אֵלּוּ הֲרֵי בֵּאַרְנוּם, וַהֲרֵי נֶאֶמְרוּ.</p>\n<p>שָׁנִינוּ, (קהלת א) מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ. יָכוֹל אַף עֲמַל הַתּוֹרָה? תַּלְמוּד לוֹמַר, שֶׁיַּעֲמֹל תַּחַת הַשָּׁמֶשׁ (כתוב). שׁוֹנֶה עֲמָלָהּ שֶׁל תּוֹרָה, שֶׁהוּא לְמַעְלָה מִן הַשֶּׁמֶשׁ. רַבִּי חִיָּיא אָמַר, אַף עֲמָלָהּ שֶׁל תּוֹרָה, שֶׁהוּא עָמָל בִּגְלַל בְּנֵי אָדָם אוֹ בִּשְׁבִיל כְּבוֹדוֹ. עַל זֶה כָּתוּב תַּחַת הַשָּׁמֶשׁ, שֶׁזֶּה לֹא עוֹלֶה לְמַעְלָה. שָׁנִינוּ, אָמַר רַבִּי אֶלְעָזָר, אֲפִלּוּ אִם אָדָם עוֹמֵד אֶלֶף שָׁנִים, אוֹתוֹ יוֹם שֶׁמִּסְתַּלֵּק מִן הָעוֹלָם דּוֹמֶה לוֹ כְּאִלּוּ לֹא הִתְקַיֵּם, רַק יוֹם אֶחָד.</p>"],[9522011454,"<p>וְשָׁכַבְתִּי עִם אֲבֹתַי. אַשְׁרֵי חֶלְקָם שֶׁל הָאָבוֹת שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אוֹתָם מֶרְכָּבָה קְדוֹשָׁה לְמַעְלָה וְהִתְרַצָּה בָהֶם לְהִתְעַטֵּר עִמָּהֶם. זֶהוּ שֶׁכָּתוּב (דברים י) רַק בַּאֲבֹתֶיךְ חָשַׁק ה' וְגוֹ'. אָמַר רַבִּי אֶלְעָזָר, יַעֲקֹב הָיָה יוֹדֵעַ שֶׁהָעִטּוּר שֶׁלּוֹ הוּא בַּאֲבוֹתָיו, שֶׁהֲרֵי הָעִטּוּר שֶׁל הָאָבוֹת הוּא עִמּוֹ, וְהוּא עִמָּהֶם. וְעַל זֶה בְּאוֹתִיּוֹת חֲקוּקוֹת שָׁנִינוּ, ש שְׁלֹשָׁה קְשָׁרִים, שְׁנֵי קְשָׁרִים - אֶחָד מִצַּד זֶה וְאֶחָד מִצַּד זֶה, וְאֶחָד שֶׁכּוֹלֵל אוֹתָם. וְזֶהוּ שֶׁשָּׁנִינוּ, (שמות כו) וְהַבְּרִיחַ הַתִּיכֹן בְּתוֹךְ הַקְּרָשִׁים מַבְרִחַ מִן הַקָּצֶה אֶל הַקָּצֶה. וְאוֹתוֹ קֶשֶׁר שֶׁבָּאֶמְצַע אָחוּז לְצַד זֶה וּלְצַד זֶה, וְעַל זֶה כָּתוּב וְשָׁכַבְתִּי עִם אֲבֹתַי, וַדַּאי.</p>\n<p>וְשָׁכַבְתִּי עִם אֲבֹתַי וְגוֹ'. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (ישעיה מב) הַחֵרְשִׁים שְׁמָעוּ וְהַעִוְרִים הַבִּיטוּ לִרְאוֹת. הַחֵרְשִׁים שְׁמָעוּ - אֵלּוּ בְּנֵי אָדָם שֶׁלֹּא מַקְשִׁיבִים לְדִבּוּרֵי הַתּוֹרָה וְלֹא פוֹקְחִים אָזְנֵיהֶם לִשְׁמֹעַ אֶת מִצְווֹת רִבּוֹנָם. וְהַעִוְרִים - שֶׁלֹּא מִסְתַּכְּלִים לָדַעַת עַל מָה הֵם עוֹמְדִים, שֶׁהֲרֵי בְּכָל יוֹם וָיוֹם הַכָּרוֹז יוֹצֵא וְקוֹרֵא, וְאֵין מִי שֶׁיַּשְׁגִּיחַ.</p>\n<p>שֶׁלָּמַדְנוּ, בְּאוֹתָם יָמִים שֶׁנִּבְרָא הָאָדָם, בְּאוֹתוֹ יוֹם שֶׁיּוֹצֵא לָעוֹלָם, כֻּלָּם עוֹמְדִים בְּקִיּוּמָם וְהוֹלְכִים וְטָסִים בָּעוֹלָם, יוֹרְדִים וּמַזְהִירִים אֶת הָאָדָם כָּל יוֹם וָיוֹם לְבַדּוֹ. וּכְשֶׁאוֹתוֹ יוֹם בָּא וּמַזְהִירִים אוֹתוֹ, וּבֶן אָדָם עוֹשֶׂה בְּאוֹתוֹ יוֹם חֵטְא לִפְנֵי רִבּוֹנוֹ - אוֹתוֹ יוֹם עוֹלֶה בְּבוּשָׁה וּמֵעִיד עֵדוּת, וְעוֹמֵד לְבַדּוֹ בַּחוּץ.</p>\n<p>וְשָׁנִינוּ, אַחַר שֶׁעוֹמֵד לְבַדּוֹ, יוֹשֵׁב, עַד שֶׁאָדָם עוֹשֶׂה מִמֶּנּוּ תְשׁוּבָה. זָכָה - שָׁב אוֹתוֹ יוֹם לִמְקוֹמוֹ. לֹא זָכָה - אוֹתוֹ יוֹם יוֹרֵד וּמִשְׁתַּתֵּף עִם אוֹתָהּ רוּחַ שֶׁבַּחוּץ, וְשָׁב לְבֵיתוֹ, וְנִתְקָן בִּדְמוּת אוֹתוֹ אָדָם מַמָּשׁ כְּדֵי לְהָרַע לוֹ, וְדָר עִמּוֹ בַּבַּיִת. וְיֵשׁ שֶׁדִּיּוּרוֹ לְטוֹב, אִם הוּא זוֹכֶה. וְאִם לָאו, הוּא דָּר עִמּוֹ לְרַע.</p>\n<p>בֵּין כָּךְ וּבֵין כָּךְ נִפְקָדִים אוֹתָם יָמִים וַחֲסֵרִים, וְלֹא נִכְנָסִים בְּחֶשְׁבּוֹן שֶׁל אוֹתָם שֶׁנִּשְׁאֲרוּ. אוֹי לְאוֹתוֹ הָאָדָם שֶׁגּוֹרֵעַ יָמָיו לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְלֹא הִשְׁאִיר לְמַעְלָה יָמִים לְהִתְעַטֵּר בָּהֶם בְּאוֹתוֹ הָעוֹלָם וּלְהִתְקָרֵב עִמָּם לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>בֹּא רְאֵה, כְּשֶׁקְּרֵבִים אוֹתָם יָמִים לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, אִם הוּא צַדִּיק, זֶה הָאָדָם שֶׁיּוֹצֵא מִן הָעוֹלָם וְנִכְנָס בְּאוֹתָם יָמִים, וְהֵם לְבוּשֵׁי כָבוֹד שֶׁנִּשְׁמָתוֹ מִתְלַבֶּשֶׁת בָּהֶם, וְהֵם אוֹתָם יָמִים שֶׁצַּדִּיק הָיָה בָהֶם וְלֹא הִרְשִׁיעַ בָּהֶם.</p>\n<p>אוֹי לְאוֹתוֹ שֶׁגּוֹרֵעַ יָמָיו לְמַעְלָה, שֶׁכַּאֲשֶׁר רוֹצִים לְהַלְבִּישׁ אוֹתוֹ בְּיָמָיו, אוֹתָם יָמִים שֶׁפָּגַם בַּחֲטָאָיו חֲסֵרִים מֵאוֹתוֹ לְבוּשׁ, וּמִתְלַבֵּשׁ בְּבֶגֶד חָסֵר. כָּל שֶׁכֵּן אִם הֵם רַבִּים, וְאֵין לָאָדָם בַּמֶּה לְהִתְלַבֵּשׁ בְּאוֹתוֹ הָעוֹלָם, אֲזַי אוֹי לוֹ וְאוֹי לְנַפְשׁוֹ, שֶׁדָּנִים אוֹתוֹ בַּגֵּיהִנֹּם עַל אוֹתָם יָמִים, יָמִים עַל יָמִים, יָמִים עַל כָּל אֶחָד שְׁנַיִם. שֶׁכַּאֲשֶׁר יוֹצֵא מִן הָעוֹלָם הַזֶּה, אֵינוֹ מוֹצֵא יָמִים לְהִתְלַבֵּשׁ בָּהֶם, וְלֹא יִהְיֶה לוֹ לְבוּשׁ בַּמֶּה לְהִתְכַּסּוֹת. אַשְׁרֵי הַצַּדִּיקִים שֶׁכָּל יְמֵיהֶם שְׁמוּרִים הֵם אֵצֶל הַמֶּלֶךְ הַקָּדוֹשׁ, וְנַעֲשִׂים מֵהֶם לְבוּשֵׁי כָבוֹד לְהִתְלַבֵּשׁ בָּהֶם בָּעוֹלָם הַבָּא.</p>\n<p>שָׁנִינוּ בְּסוֹד הַמִּשְׁנָה, מַה שֶּׁכָּתוּב (בראשית ג) וַיֵּדְעוּ כִּי עֵירֻמִּם הֵם - יְדִיעָה מַמָּשׁ יָדְעוּ, שֶׁאוֹתוֹ לְבוּשׁ שֶׁל כָּבוֹד שֶׁנַּעֲשָׂה מֵאוֹתָם יָמִים נִגְרַע מֵהֶם, וְלֹא נִשְׁאַר יוֹם מֵאוֹתָם יָמִים לְהִתְלַבֵּשׁ בּוֹ. זֶהוּ שֶׁכָּתוּב (תהלים קלט) גָּלְמִי רָאוּ עֵינֶיךְ וְעַל סִפְרְךְ כֻּלָּם יִכָּתֵבוּ יָמִים יֻצָּרוּ. יָמִים יֻצָּרוּ וַדַּאי. וְלֹא אֶחָד בָּהֶם, שֶׁהֲרֵי לֹא נִשְׁאַר אֶחָד לְהִתְלַבֵּשׁ בּוֹ, עַד שֶׁהִשְׁתַּדֵּל אָדָם וְעָשָׂה תְשׁוּבָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קִבֵּל אוֹתוֹ וְעָשָׂה לוֹ כְּלִי לְבוּשׁ אֲחֵרִים, וְלֹא מִן הַיָּמִים שֶׁלּוֹ. זֶהוּ שֶׁכָּתוּב (בראשית ג) וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּשֵׁם.</p>\n<p>בֹּא רְאֵה, בְּאַבְרָהָם שֶׁזָּכָה מַה כָּתוּב? (שם כד) בָּא בַּיָּמִים, מִשּׁוּם שֶׁזָּכָה. כַּאֲשֶׁר הִסְתַּלֵּק מִן הָעוֹלָם הַזֶּה, מַמָּשׁ בְּאוֹתָם יָמִים שֶׁלּוֹ, נִכְנַס וְהִתְלַבֵּשׁ בָּהֶם, וְלֹא נִגְרַע מֵאוֹתוֹ לְבוּשׁ כָּבוֹד כְּלוּם, שֶׁכָּתוּב בָּא בַּיָּמִים. בְּאִיּוֹב מַה כָּתוּב? (איוב א) וַיֹּאמֶר עָרֹם יָצָתִי מִבֶּטֶן אִמִּי וְעָרֹם אָשׁוּב שָׁמָּה, שֶׁהֲרֵי לֹא נִשְׁאַר לְבוּשׁ לְהִתְלַבֵּשׁ בּוֹ.</p>\n<p>שָׁנִינוּ, אַשְׁרֵיהֶם הַצַּדִּיקִים, שֶׁיְּמֵיהֶם צַדִּיקִים, וְנִשְׁאֲרוּ לָעוֹלָם הַבָּא (צדיקים), וְכַאֲשֶׁר יוֹצְאִים, כֻּלָּם מִתְחַבְּרִים וְנַעֲשִׂים לְבוּשֵׁי כָבוֹד לְהִתְלַבֵּשׁ בּוֹ, וּבְאוֹתוֹ לְבוּשׁ זוֹכִים לְהִתְעַנֵּג מֵעֹנֶג הָעוֹלָם הַבָּא, וּבְאוֹתוֹ לְבוּשׁ עֲתִידִים לָקוּם לִתְחִיָּה, וְכָל אוֹתָם שֶׁיֵּשׁ לָהֶם לְבוּשׁ יָקוּמוּ. זֶהוּ שֶׁכָּתוּב (איוב לח) וַיִּתְיַצְּבוּ כְּמוֹ לְבוּשׁ. אוֹי לְאוֹתָם רְשָׁעִים שֶׁל הָעוֹלָם שֶׁיְּמֵיהֶם בַּחֲטָאֵיהֶם (עולמות) חֲסֵרִים, וְלֹא נִשְׁאָר מֵהֶם בְּמַה שֶּׁיִּתְכַּסּוּ כְּשֶׁיֵּצְאוּ מִן הָעוֹלָם.</p>\n<p>שָׁנִינוּ, כָּל אוֹתָם צַדִּיקִים שֶׁזָּכוּ לְהִתְלַבֵּשׁ בִּלְבוּשׁ כָּבוֹד בִּימֵיהֶם, מִתְעַטְּרִים בְּאוֹתוֹ עוֹלָם (לבוש) מֵהָעִטּוּרִים שֶׁבָּהֶם מִתְעַטְּרִים הָאָבוֹת, מֵאוֹתוֹ נַחַל שֶׁיּוֹצֵא וְשׁוֹפֵעַ לְגַן עֵדֶן. זֶהוּ שֶׁכָּתוּב וְנָחֲךְ ה' תָּמִיד וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ וְגוֹ'. וְאוֹתָם רִשְׁעֵי הָעוֹלָם שֶׁלֹּא זָכוּ לְהִתְלַבֵּשׁ בַּלְּבוּשׁ שֶׁל יְמֵיהֶם, עֲלֵיהֶם כָּתוּב (ירמיז יז) וְהָיָה כְּעַרְעָר בָּעֲרָבָה וְלֹא יִרְאֶה כִּי יָבֹא טוֹב וְשָׁכַן חֲרֵרִים בַּמִּדְבָּר.</p>\n<p>אָמַר רַבִּי יִצְחָק, אַשְׁרֵי חֶלְקוֹ שֶׁל יַעֲקֹב שֶׁבִּטָּחוֹן יָתֵר הָיָה לוֹ, שֶׁכָּתוּב וְשָׁכַבְתִּי עִם אֲבתַי, שֶׁאֶזְכֶּה בָהֶם וְלֹא בְאַחֵר. שֶׁאֶזְכֶּה בָהֶם לְהִתְלַבֵּשׁ בַּיָּמִים שֶׁלּוֹ וּבַיָּמִים שֶׁלָּהֶם.</p>\n<p>רַבִּי יְהוּדָה אָמַר, כָּתוּב (בראשית כז) וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרֲכֵהוּ. בְּגָדָיו? בִּגְדֵי עֵשָׂו הָיָה צָרִיךְ לִכְתֹּב, שֶׁהֲרֵי לֹא הָיוּ שֶׁלּוֹ, אֶלָּא שֶׁל עֵשָׂו הָיוּ בְגָדִים אֵלּוּ, שֶׁכָּתוּב (שם) וַתִּקַּח רִבְקָה אֶת בִּגְדֵי עֵשָׂו בְּנָהּ הַגָּדֹל הַחֲמֻדת? בִּגְדֵי עֵשָׂו כָּתוּב (כאן), וְכָאן רֵיחַ בְּגָדָיו, שֶׁל יַעֲקֹב מַשְׁמָע.</p>\n<p>אֶלָּא כָּךְ בֵּאַרְנוּ, וַיָּרַח, כְּלוֹמַר שֶׁהִסְתַּכֵּל הָלְאָה, וְהֵרִיחַ אֶת רֵיחַ לְבוּשׁוֹ שֶׁל אוֹתוֹ הָעוֹלָם וְאָז בֵּרְכוֹ, וְעַל זֶה כָּתוּב רְאֵה רֵיחַ בְּנִי כְּרֵיחַ שָׂדֶה, זֶהוּ שְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים. וְאָמַר, הוֹאִיל וְזָכִיתָ בְּאוֹתָם לְבוּשֵׁי כָבוֹד - וְיִתֶּן לְךְ הָאֱלֹהִים מִטַּל הַשָּׁמַיִם. מַה מַּשְׁמִיעַ? מִשּׁוּם שֶׁבְּאוֹתוֹ שְׂדֵה תַפּוּחִים קְדוֹשִׁים נוֹטֵל טַל כָּל יוֹם מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא שָׁמַיִם, שֶׁכָּתוּב מִטַּל הַשָּׁמַיִם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, בֵּרַךְ אוֹתוֹ בַּכֹּל - מִטַּל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ. מָה הַטַּעַם? מִשּׁוּם שֶׁוַּיָּרַח אֶת רֵיחַ בְּגָדָיו, בְּגָדָיו מַמָּשׁ, כְּמוֹ שֶׁבֵּאַרְנוּ. שָׁנִינוּ, אֶלֶף וַחֲמֵשׁ מֵאוֹת רֵיחוֹת עוֹלִים בְּכָל יוֹם מִגַּן עֵדֶן, שֶׁבָּהֶם מִתְבַּשְּׂמִים אוֹתָם לְבוּשֵׁי כָבוֹד שֶׁל אוֹתוֹ עוֹלָם שֶׁמִּתְעַטְּרִים מִיָּמָיו שֶׁל בֶּן אָדָם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כַּמָּה לְבוּשִׁים הֵם? אָמַר רַבִּי אֶלְעָזָר, הֶהָרִים שֶׁל הָעוֹלָם, עַל זֶה נֶחְלְקוּ, אֲבָל שְׁלֹשָׁה הֵם: אֶחָד שֶׁמִּתְלַבְּשִׁים בְּאוֹתוֹ הַלְּבוּשׁ, הָרוּחַ שֶׁבְּגַן עֵדֶן שֶׁבָּאָרֶץ. וְאֶחָד נִכְבָּד מֵהַכֹּל, שֶׁמִּתְלַבֶּשֶׁת בּוֹ הַנְּשָׁמָה בְּתוֹךְ צְרוֹר הַחַיִּים בֵּין אַדֶּרֶת הַמֶּלֶךְ. וְאֶחָד לְבוּשׁ שֶׁל בַּחוּץ, שֶׁעוֹמֵד וְלֹא עוֹמֵד, נִרְאֶה וְלֹא נִרְאֶה, בָּזֶה מִתְלַבֶּשֶׁת הַנֶּפֶשׁ וְהוֹלֶכֶת וּמְשׁוֹטֶטֶת בָּעוֹלָם.</p>\n<p>וּבְכָל רֹאשׁ חֹדֶשׁ (שנה) וְשַׁבָּת הוֹלֶכֶת וְנִקְשֶׁרֶת בָּרוּחַ שֶׁבְּגַן עֵדֶן שֶׁבָּאָרֶץ שֶׁעוֹמֶדֶת בֵּין פַּרְגּוֹד נִכְבָּד, וּמִמֶּנּוּ לוֹמֵד וְיוֹדֵעַ מַה שֶּׁיּוֹדֵעַ, וּמְשׁוֹטֵט וּמוֹדִיעַ אוֹתוֹ בָּעוֹלָם.</p>\n<p>לָמַדְנוּ, בִּשְׁנֵי קְשָׁרִים נִקְשֶׁרֶת הַנֶּפֶשׁ בְּכָל רֹאשׁ חֹדֶשׁ וְשַׁבָּת, בַּקֶּשֶׁר שֶׁל הָרוּחַ שֶׁבֵּין רֵיחוֹת הַבְּשָׂמִים שֶׁבְּגַן עֵדֶן שֶׁבָּאָרֶץ, וּמִשָּׁם הוֹלֵךְ וּמְשׁוֹטֵט, וְנִקְשָׁר עִם הָרוּחַ בַּנְּשָׁמָה שֶׁצְּרוּרָה בִּצְרוֹר הַחַיִּים, וְנִרְוֵית וְנִזּוֹנֵית מֵאוֹתוֹ זִיו הַנִּכְבָּד שֶׁל צַד זֶה וְשֶׁל צַד זֶה. זֶהוּ שֶׁכָּתוּב וְנָחֲךְ ה' תָּמִיד, תָּמִיד דַּוְקָא.</p>\n<p>וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. מַה זֶּה בְּצַחְצָחוֹת? אֶלָּא צַחוּת אַחַת, כְּשֶׁנִּקְשֶׁרֶת עִם הָרוּחַ שֶׁבַּגַּן שֶׁלְּמַטָּה, צַחוּת שֶׁלִּפְנִים מִן הַצַּחוּת, כְּשֶׁנִּקְשָׁרִים בַּנְּשָׁמָה שֶׁלְּמַעְלָה בִּצְרוֹר הַחַיִּים. וְהַיְנוּ בְּצַח - אֶחָד, צָחוֹת - שְׁנַיִם, שֶׁהֵם לְמַעְלָה לְמַעְלָה, בִּכְבוֹד הַנְּשָׁמָה וַדַּאי. כְּלוֹמַר, צַחְצָחוֹת, מִי יוֹרֵשׁ אֶת אֶת זֶה? נַפְשֶׁךְ, נַפְשֶׁךְ מַמָּשׁ. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כְּשֶׁאֲנִי בֵּין אוֹתָם הַחֲבֵרִים מִבָּבֶל, מִתְכַּנְּסִים אֵלַי, וְלוֹמְדִים דְּבָרִים בַּנִּגְלֶה, וְהֵם מַכְנִיסִים אוֹתָם בְּחוֹתַם בַּרְזֶל חָזָק, סָתוּם מִכָּל הַצְּדָדִים. כַּמָּה פְעָמִים לִמַּדְתִּי אוֹתָם דַּרְכֵי גִּנַּת הַמֶּלֶךְ, דַּרְכֵי הַמֶּלֶךְ. (כמה פעמים אמרתי להם דרכי התורה של המלך הקדוש ודרכים עליונים,)</p>\n<p>כַּמָּה פְעָמִים לִמַּדְתִּי אוֹתָם כָּל אוֹתָן דַּרְגוֹת הַצַּדִּיקִים שֶׁבְּאוֹתוֹ עוֹלָם, וְכֻלָּם פּוֹחֲדִים לוֹמַר דְּבָרִים הַלָּלוּ, אֶלָּא לוֹמְדִים בְּגִמְגּוּם, מִשּׁוּם כָּךְ נִקְרָאִים כִּבְדֵי לָשׁוֹן, כְּמוֹ אוֹתוֹ כְּבַד לָשׁוֹן שֶׁמְּגַמְגֵּם בְּפִיו.</p>\n<p>אֲבָל לִזְכוּת אֲנִי דָן אוֹתָם, הוֹאִיל וּפוֹחֲדִים, שֶׁהֲרֵי אֲוִיר הַקָּדוֹשׁ וְרוּחַ הַקֹּדֶשׁ עָבְרָה מֵהֶם, וְיוֹנְקִים אֲוִיר וְרוּחַ שֶׁל רָשׁוּת אַחֶרֶת. וְלֹא עוֹד, אֶלָּא שֶׁנִּרְאֵית עֲלֵיהֶם קֶשֶׁת, וְאֵינָם כְּדָאִים לִרְאוֹת סֵבֶר פָּנָיו (של אליהו), כָּל שֶׁכֵּן סֵבֶר פָּנִים אֲחֵרוֹת.</p>\n<p>אֲבָל זֶה מוֹעִיל לָהֶם שֶׁאֲנִי מָצוּי בָּעוֹלָם וַאֲנִי סִימָן (תומך) בָּעוֹלָם, שֶׁהֲרֵי בְּחַיַּי לֹא יָשַׁב הָעוֹלָם בְּצַעַר, וְלֹא נִדּוֹן בַּדִּין שֶׁלְּמַעְלָה, אַחֲרַי לֹא יָקוּם דּוֹר כְּמוֹ הַדּוֹר הַזֶּה. וְעָתִיד הָעוֹלָם שֶׁלֹּא יִמָּצֵא מִי שֶׁיָּגֵן עֲלֵיהֶם, וְכָל הַפָּנִים הַחֲצוּפוֹת יִמָּצְאוּ בֵּין לְמַעְלָה בֵּין לְמַטָּה. לְמַעְלָה - בַּחֲטָאֵי הַתַּחְתּוֹנִים וְהַחֻצְפָּה שֶׁלָּהֶם.</p>\n<p>וַעָתִידִים בְּנֵי הָעוֹלָם לִצְווֹחַ, וְאֵין מִי שֶׁיַּשְׁגִּיחַ עֲלֵיהֶם. יַחֲזִירוּ רֹאשׁ לְכָל הָרוּחוֹת שֶׁל הָעוֹלָם, וְלֹא יָשׁוּבוּ עִם רְפוּאָה. אֲבָל רְפוּאָה אַחַת מָצָאתִי לָהֶם בָּעוֹלָם וְלֹא יוֹתֵר, בְּאוֹתוֹ מָקוֹם שֶׁיִּמָּצְאוּ אוֹתָם שֶׁעוֹסְקִים בַּתּוֹרָה, וְנִמְצָא בֵינֵיהֶם סֵפֶר תּוֹרָה שֶׁאֵין בּוֹ שֶׁקֶר, כְּשֶׁמּוֹצִיאִים אוֹתוֹ, בִּגְלָלוֹ מִתְעוֹרְרִים עֶלְיוֹנִים וְתַחְתּוֹנִים. וְכָל שֶׁכֵּן אִם נִכְתַּב בּוֹ הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי, וַהֲרֵי כְּבָר לָמַדְנוּ אֶת הַדָּבָר.</p>\n<p>אוֹי לְדוֹר שֶׁהִתְגַּלָּה בֵינֵיהֶם סֵפֶר תּוֹרָה, וְלֹא מִתְעוֹרְרִים עָלָיו לְמַעְלָה וּלְמַטָּה. מִי מִתְעוֹרֵר עָלָיו בְּשָׁעָה שֶׁהָעוֹלָם בְּצַעַר יָתֵר, וְהָעוֹלָם צָרִיךְ לְמָטָר, וְצָרִיךְ לְהַגְלוֹת סֵפֶר תּוֹרָה יוֹתֵר בְּצַעַר הָעוֹלָם.</p>\n<p>שֶׁכַּאֲשֶׁר הָעוֹלָם בְּצַעַר וּמְבַקְשִׁים בְּנֵי אָדָם רַחֲמִים עַל הַקְּבָרִים, כָּל הַמֵּתִים מִתְעוֹרְרִים עָלָיו, שֶׁהֲרֵי הַנֶּפֶשׁ מַקְדִּימָה וּמוֹדִיעָה לָרוּחַ, שֶׁהֲרֵי סֵפֶר תּוֹרָה נִמְצָא בַגָּלוּת, שֶׁהֻגְלָה בְצַעַר הָעוֹלָם, וְהַחַיִּים בָּאִים וּמְבַקְשִׁים רַחֲמִים.</p>\n<p>וְאָז הָרוּחַ מוֹדִיעָה לַנְּשָׁמָה, וְהַנְּשָׁמָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעוֹרֵר וְחָס עַל הָעוֹלָם, וְזֶה עַל גָּלוּת סֵפֶר תּוֹרָה מִמְּקוֹמוֹ, וְהַחַיִּים בָּאִים לְבַקֵּשׁ רַחֲמִים עַל קִבְרֵי הַמֵּתִים. אוֹי לַדּוֹר אִם צָרִיךְ סֵפֶר תּוֹרָה לְהַגְלוֹתוֹ מִמָּקוֹם לְמָקוֹם, וַאֲפִלּוּ מִבֵּית כְּנֶסֶת לְבֵית כְּנֶסֶת, שֶׁהֲרֵי לֹא נִמְצָא בֵינֵיהֶם עַל מַה יַּשְׁגִּיחוּ עֲלֵיהֶם.</p>\n<p>וְאֶת זֶה לֹא יוֹדְעִים כָּל בְּנֵי הָעוֹלָם, שֶׁהֲרֵי שְׁכִינָה, כְּשֶׁגָּלְתָה גָלוּת אַחֲרוֹנָה, עַד שֶׁלֹּא עָלְתָה לְמַעְלָה מַה כָּתוּב? (ירמיה ט) מִי יִתְּנֵנִי בַמִּדְבָּר מְלוֹן אֹרְחִים. אַחַר כָּךְ בִּזְמַן שֶׁדּחַק רַב נִמְצָא בָעוֹלָם, הִיא נִמְצֵאת שָׁם, וּבַגָּלוּת שֶׁל סֵפֶר תּוֹרָה שָׁם הִיא, וְהַכֹּל מִתְעוֹרְרִים עָלֶיהָ, עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אִם הַבַּבְלִים הַטִּפְּשִׁים הַלָּלוּ יֵדְעוּ דְבָרִים שֶׁל סוֹדוֹת הַחָכְמָה עַל מָה עוֹמֵד הָעוֹלָם, וְתוֹמְכָיו עַל מַה מִּתְרַגְּשִׁים כְּשֶׁהוּא נִמְצָא בְצַעַר, אָז יֵדְעוּ שִׁבְחוֹ שֶׁל רַב (המנונא) יֵיבָא הַזָּקֵן כַּאֲשֶׁר הָיָה מָצוּי בֵינֵיהֶם וְלֹא הָיוּ יוֹדְעִים אֶת שִׁבְחוֹ. וַהֲרֵי מָצָאנוּ דְבָרִים שֶׁלּוֹ קְשׁוּרִים לְדִבְרֵי שְׁלֹמֹה הַמֶּלֶךְ בְּסוֹד עֶלְיוֹן שֶׁל הַחָכְמָה, וְהֵם לֹא הָיוּ יוֹדְעִים אֶת שִׁבְחוֹ.</p>\n<p>וְעַכְשָׁו הוֹלְכִים אַחַר דִּבְרֵי חָכְמָה, וְאֵין מִי שֶׁעוֹמֵד עָלֶיהָ וְאֵין מִי שֶׁקּוֹרֵא, וְעִם כָּל זֶה יֵשׁ בֵּינֵיהֶם פִּקְחִים בְּעִבּוּר שָׁנָה וּקְבִיעַת הֶחֳדָשִׁים, אַף עַל גַּב שֶׁלֹּא נִתַּן לָהֶם וְלֹא נִמְסַר בִּידֵיהֶם.</p>\n<p>שָׁנִינוּ, שְׁנֵים עָשָׂר חֹדֶשׁ הַנֶּפֶשׁ הַזּוֹ מִתְקַשֶּׁרֶת בַּגּוּף בַּקֶּבֶר, וְנִדּוֹנִים בְּדִין אֶחָד, פְּרָט לְאוֹתָהּ נֶפֶשׁ שֶׁל הַצַּדִּיקִים, כְּמוֹ שֶׁבֵּאֲרוּהָ, וְנִמְצֵאת בַּקֶּבֶר וְיוֹדַעַת בַּצַּעַר שֶׁלּוֹ, וּבְצַעַר הַחַיִּים יוֹדַעַת (לא יודעת), וְלֹא מִשְׁתַּדֶּלֶת עֲלֵיהֶם.</p>\n<p>וְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ מִתְלַבֶּשֶׁת בִּלְבוּשׁ אֶחָד, וְהוֹלֶכֶת וּמְשׁוֹטֶטֶת בָּעוֹלָם, וְיוֹדַעַת מִן הָרוּחַ מַה שֶּׁהִיא יוֹדַעַת, וּמִשְׁתַּדֶּלֶת עַל הַצַּעַר שֶׁל הָעוֹלָם, וּלְבַקֵּשׁ רַחֲמִים, וְלָדַעַת אֶת צַעֲרָם שֶׁל הַחַיִּים.</p>\n<p>וּמִי מִתְעוֹרֵר לְכָל זֶה? בִּזְמַן שֶׁיֵּשׁ צַדִּיק שֶׁמּוֹדִיעַ לוֹ כָּרָאוּי, וְאוֹתוֹ צַדִּיק נוֹדָע בֵּינֵיהֶם. שֶׁשָּׁנִינוּ, צַדִּיק אֶחָד נִשְׁאָר בָּעוֹלָם, בֵּין הַחַיִּים וּבֵין הַמֵּתִים הוּא נוֹדָע, שֶׁהֲרֵי כָּל יוֹם מַכְרִיזִים עָלָיו בֵּינֵיהֶם, וּכְשֶׁיֵּשׁ יוֹתֵר צַעַר בָּעוֹלָם וְהוּא לֹא יָכוֹל לְהָגֵן עַל הַדּוֹר, הוּא מוֹדִיעַ לָהֶם אֶת צַעַר הָעוֹלָם.</p>\n<p>וּכְשֶׁלֹּא נִמְצָא צַדִּיק בָּעוֹלָם שֶׁמַּכְרִיזִים עָלָיו בֵּינֵיהֶם, וְלֹא נִמְצָא (ביניהם) מִי שֶׁיְּעוֹרֵר אוֹתָם בַּצַּעַר שֶׁל הָעוֹלָם אֶלָּא סֵפֶר תּוֹרָה, אָז מִתְעוֹרְרִים עָלָיו עֶלְיוֹנִים וְתַחְתּוֹנִים, וּצְרִיכִים כֻּלָּם לְהִמָּצֵא בְּאוֹתוֹ זְמַן בִּתְשׁוּבָה. וְאִם לֹא נִמְצָאִים, מִתְעוֹרְרִים עֲלֵיהֶם בַּעֲלֵי הַדִּין, וַאֲפִלּוּ רוּחַ שֶׁל גַּן עֵדֶן מִתְעוֹרְרִים עֲלֵיהֶם מִשּׁוּם סֵפֶר תּוֹרָה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>שָׁנִינוּ, וְשָׁכַבְתִּי עִם אֲבֹתַי - בְּגוּף, בְּנֶפֶשׁ, בְּרוּחַ, בִּנְשָׁמָה, בְּמֶרְכָּבָה אַחַת, בְּדַרְגָּה עֶלְיוֹנָה. אָמַר רַבִּי יְהוּדָה, כַּמָּה אֲטוּמִים מֵהַכֹּל בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים וְלֹא שׁוֹמְעִים וְלֹא מִסְתַּכְּלִים בְּדִבְרֵי הָעוֹלָם, וְאֵיךְ הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא עֲלֵיהֶם בְּרַחֲמִים בְּכָל זְמַן וְעִדָּן, וְאֵין מִי שֶׁיַּשְׁגִּיחַ.</p>\n<p>שָׁלש פְּעָמִים בְּיוֹם נִכְנֶסֶת רוּחַ אַחַת לִמְעָרַת הַמַּכְפֵּלָה, וְנוֹשֶׁבֶת בְּקִבְרֵי הָאָבוֹת, וּמִתְרַפְּאִים כָּל הָעֲצָמוֹת וְעוֹמְדִים בְּקִיּוּמָם, וְאוֹתָהּ רוּחַ מַשְׁפִּיעָה טַל מִלְמַעְלָה מֵרֹאשׁ הַמֶּלֶךְ, מָקוֹם שֶׁנִּמְצָאִים הָאָבוֹת הָעֶלְיוֹנִים. וּכְשֶׁמַּגִּיעַ (וכשמתעורר) אוֹתוֹ הַטַּל מֵהֶם, מִתְעוֹרְרִים הָאָבוֹת שֶׁלְּמַטָּה.</p>\n<p>וְלָמַדְנוּ שֶׁיּוֹרֵד אוֹתוֹ הַטַּל בִּדְרָגוֹת יְדוּעוֹת, דַּרְגָּה אַחַר דַּרְגָּה, וּמַגִּיעַ לְגַן הָעֵדֶן שֶׁלְּמַטָּה, וּמֵאוֹתוֹ הַטַּל רוֹחֲצִים בִּבְשָׂמִים שֶׁל גַּן עֵדֶן, וּמִתְעוֹרֶרֶת רוּחַ אַחַת שֶׁכְּלוּלָה בִּשְׁתֵּי אֲחֵרוֹת, וְעוֹלָה וּמְשׁוֹטֶטֶת בֵּין הַבְּשָׂמִים, וְנִכְנֶסֶת בְּפֶתַח הַמְּעָרָה, וְאָז מִתְעוֹרְרִים הָאָבוֹת, הֵם וְזִוּוּגֵיהֶם, וּמְבַקְשִׁים רַחֲמִים עַל בְּנֵיהֶם.</p>\n<p>וְכַאֲשֶׁר נִמְצָא צַעַר בָּעוֹלָם, מִשּׁוּם שֶׁהֵם יְשֵׁנִים עַל חֲטָאֵי הָעוֹלָם, וְאוֹתוֹ טַל לֹא שׁוֹפֵעַ וְלֹא נִמְצָא, עַד שֶׁמִּתְעוֹרֵר סֵפֶר תּוֹרָה כָּרָאוּי בָּעוֹלָם, וְהַנֶּפֶשׁ מוֹדִיעָה לָרוּחַ, וְהָרוּחַ לַנְּשָׁמָה, וְהַנְּשָׁמָה לַקָּדוֹשׁ- בָּרוּךְ-הוּא. אָז יוֹשֵׁב הַמֶּלֶךְ עַל כִּסֵּא רַחֲמִים, וְשׁוֹפֵעַ מֵהָעַתִּיק הַקָּדוֹשׁ הָעֶלְיוֹן שֶׁפַע שֶׁל טַל הַבְּדוֹלַח, וּמַגִּיעַ לְרֹאשׁ הַמֶּלֶךְ, וּמִתְבָּרְכִים הָאָבוֹת. וְשׁוֹפֵעַ אוֹתוֹ טַל לְאוֹתָם יְשֵׁנִים, וְאָז כֻּלָּם מִתְחַבְּרִים (מתברכים). וְחָס הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הָעוֹלָם. וְלָמַדְנוּ, לֹא חָס הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הָעוֹלָם עַד שֶׁמּוֹדִיעַ לָאָבוֹת, וּבִשְׁבִילָם הָעוֹלָם מִתְבָּרֵךְ. אָמַר רַבִּי יוֹסֵי, וַדַּאי כָּךְ זֶה, וַהֲרֵי מָצָאנוּ דְבָרִים בְּסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, אוֹתוֹ עֶלְיוֹן, שֶׁקּוֹרְאִים לוֹ עֵצָה שֶׁל חָכְמָה שֶׁל הַכֹּל.</p>\n<p>וְרַב הַמְנוּנָא, כָּךְ גִּלָּה וְאָמַר, שֶׁהֲרֵי הֶרְאוּ לוֹ שֶׁרָחֵל עָשְׂתָה יוֹתֵר, שֶׁעוֹמֶדֶת בְּפָרָשַׁת דְּרָכִים בְּכָל זְמַן שֶׁהָעוֹלָם צָרִיךְ, מִכֻּלָּם, וְסוֹד הַדָּבָר - אָרוֹן וְכַפֹּרֶת בְּחֶלְקוֹ שֶׁל בִּנְיָמִין, שֶׁנּוֹלַד בַּדֶּרֶךְ, וּשְׁכִינָה עַל הַכֹּל.</p>"],[9522011455,"<p>וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה. מַה זֶּה רֹאשׁ הַמִּטָּה? זוֹ הַשְּׁכִינָה. אָמַר רַבִּי שִׁמְעוֹן, חַס וְחָלִילָה, אֶלָּא אֵלָיו כָּרַע וְהִשְׁתַּחֲוָה. אֶלָּא בּא רְאֵה, מִטָּה זוֹ שְׁכִינָה, שֶׁכָּתוּב (שיר ג) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה. רֹאשׁ הַמִּטָּה מַה זֶּה? זֶה יְסוֹד הָעוֹלָם, שֶׁהוּא רֹאשׁ הַמִּטָּה הַקְּדוֹשָׁה. עַל רֹאשׁ - זֶה יִשְׂרָאֵל שֶׁעוֹמֵד עַל רֹאשׁ הַמִּטָּה, מִשּׁוּם כָּךְ יִשְׂרָאֵל לְשֶׁלּוֹ הוּא הִשְׁתַּחֲוָה.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי בְּאוֹתוֹ זְמַן הוּא לֹא הָיָה חוֹלֶה, שֶׁהֲרֵי אַחַר כָּךְ כָּתוּב וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וַיֹּאמֶר לְיוֹסֵף הִנֵּה אָבִיךְ חוֹלֶה, וּבְשָׁעָה שֶׁהִשְׁתַּחֲוָה לֹא הָיָה חוֹלֶה, וְעַל שֶׁיָּדַע שֶׁהֲרֵי בְּאוֹתוֹ הַזְּמַן עָלָה לְדַרְגָּה עֶלְיוֹנָה קְדוֹשָׁה כִּסֵּא שָׁלֵם, מִשּׁוּם כָּךְ הִשְׁתַּחֲוָה לְאוֹתָהּ מֶרְכָּבָה, כִּסֵּא עֶלְיוֹן, שְׁלֵמוּת הָאִילָן הַגָּדוֹל וְהֶחָזָק שֶׁנִּקְרָא עַל שְׁמוֹ, וְעַל זֶה וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה. וַדַּאי עַל רֹאשׁ הַמִּטָּה, שֶׁהֲרֵי עָלָה לִמְקוֹמוֹ וְהִתְעַטֵּר בְּעַטְרוֹת הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>וַיֹּאמֶר הִשָּׁבְעָה לִי וַיִּשָּׁבַע לוֹ וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה. רַבִּי חִיָּיא פָּתַח וְאָמַר, (קהלת ז) כָּל זֹה נִסִּיתִי בַחָכְמָה אָמַרְתִּי אֶחְכָּמָה וְהִיא רְחוֹקָה מִמֶּנִּי. הֲרֵי שָׁנִינוּ, שְׁלֹמֹה הַמֶּלֶךְ יָרַשׁ אֶת הַלְּבָנָה מִכָּל צְדָדֶיהָ, וּבְיָמָיו עָמְדָה בִּשְׁלֵמוּת אוֹתָהּ הַלְּבָנָה שֶׁהִתְבָּרְכָה מֵהַכֹּל, וּכְשֶׁרָצָה לַעֲמֹד עַל הַנְהָגוֹת הַתּוֹרָה אָמַר, אָמַרְתִּי אֶחְכָּמָה וְגוֹ'.</p>\n<p>אָמַר רַבִּי יְהוּדָה, יַעֲקֹב אָמַר וְשָׁכַבְתִּי עִם אֲבתַי וּנְשָׂאתַנִי מִמִּצְרַיִם וּקְבַרְתַּנִי בִּקְבֻרָתָם. שָׁם שָׁנִינוּ, מִי שֶׁיָּצְאָה נִשְׁמָתוֹ בְּרָשׁוּת אַחֶרֶת, וְגוּפוֹ נִקְבָּר בָּאָרֶץ הַקְּדוֹשָׁה, כָּתוּב עָלָיו (ירמיה כ) וַתָּבאוּ וַתְּטַמְּאוּ אֶת אַרְצִי וְנַחֲלָתִי שַׂמְתֶּם לְתוֹעֵבָה. וְיַעֲקֹב אָמַר וּקְבַרְתַּנִי בִּקְבֻרָתָם, וְנִשְׁמָתוֹ יָצְאָה בְּרָשׁוּת אַחֶרֶת?!</p>\n<p>אָמַר רַבִּי יְהוּדָה, שׁוֹנֶה יַעֲקֹב, שֶׁהַשְּׁכִינָה הָיְתָה אֲחוּזָה בּוֹ וּדְבוּקָה בּוֹ. זֶהוּ שֶׁכָּתוּב (בראשית מז) אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה - לָדוּר עִמְּךְ בַּגָּלוּת, וְאָנֹכִי אַעַלְךְ גַּם עָלֹה - לְזַוֵּג בִּי אֶת נִשְׁמָתְךְ וְלִקְבֹּר אֶת גּוּפְךְ בְּקִבְרֵי אֲבוֹתֶיךְ. מַה זֶּה אוֹמֵר? (אף על גב ש) (שהרי לא) יָצְאָה נִשְׁמָתוֹ בְּרָשׁוּת אַחֶרֶת. (ועל זה ואנכי אעלך גם עלה כתוב,)</p>\n<p>וְיוֹסֵף יָשִׁית יָדוֹ עַל עֵינֶיךְ. יוֹסֵף וַדַּאי, שֶׁהֲרֵי הוּא בְּכוֹר שֶׁל הִרְהוּר הַלֵּב, בְּכוֹר שֶׁל טִפָּה רִאשׁוֹנָה הָיָה, כְּמוֹ שֶׁנִּתְבָּאֵר, וּמִשּׁוּם שֶׁיָּדַע הַקָּדוֹשׁ בָּרוּךְ הוּא סֵתֶר זֶה, הִתְבַּשֵּׂר לוֹ בְּיוֹסֵף, שֶׁהֲרֵי כָּל אַהֲבָתוֹ בּוֹ הָיְתָה תְלוּיָה.</p>\n<p>יָשִׁית יָדוֹ עַל עֵינֶיךְ, מַה זֶּה אוֹמֵר? אָמַר רַבִּי יֵיסָא, בִּשְׁבִיל כְּבוֹד יַעֲקֹב, וּלְבַשֵּׂר לוֹ שֶׁהֲרֵי יוֹסֵף קַיָּם וְיִמָּצֵא אֶצְלוֹ בְּמִיתָתוֹ. רַבִּי חִזְקִיָּה אָמַר, לָמַדְתִּי דָבָר, וַאֲנִי פוֹחֵד לְגַלּוֹתוֹ, וּבְמַעֲשֵׂי הָעוֹלָם נִמְצֵאת חָכְמָה. בָּא רַבִּי אַבָּא, (ונשקו) וְהִכָּה בּוֹ. אָמַר לוֹ, אֱמֹר דְּבָרֶיךְ וַחֲגֹר כְּלֵי זֵינֶיךְ. בִּימֵי רַבִּי שִׁמְעוֹן דְּבָרִים מִתְגַּלִּים.</p>\n<p>אָמַר, לָמַדְתִּי מִפִּרְקֵי רַבִּי יֵיסָא הַזָּקֵן בְּהַנְהָגוֹת הָעוֹלָם, בֶּן אָדָם שֶׁזּוֹכֶה לְבֵן בָּעוֹלָם הַזֶּה, צָרִיךְ לָשִׂים עָפָר עַל עֵינָיו כְּשֶׁנִּקְבָּר, וְזֶהוּ כְּבוֹדוֹ, לְהַרְאוֹת שֶׁהָעוֹלָם נִסְתָּר מִמֶּנּוּ, וְהוּא יוֹרֵשׁ אוֹתוֹ בָּעוֹלָם תַּחְתָּיו.</p>\n<p>מִשּׁוּם שֶׁעֵינֵי הָאָדָם, מַרְאֵה הָעוֹלָם נִרְאֶה בָהֶם, וְכָל הַגְּוָנִים כָּךְ הֵם שֶׁסְּבִיבוֹ: הַלָּבָן שֶׁבּוֹ הוּא הַיָּם הַגָּדוֹל אוֹקְיָנוֹס, שֶׁמַּקִּיף אֶת כָּל הָעוֹלָם בְּכָל הַצְּדָדִים. גָּוֶן אַחֵר הוּא הַיַּבָּשָׁה (שמקפת) שֶׁמּוֹצִיאָה מַיִם, וְהַיַּבָּשָׁה עוֹמֶדֶת בֵּין הַמַּיִם, כָּךְ הוּא הַגָּוֶן בֵּין הַמַּיִם.</p>\n<p>גָּוֶן אַחֵר שְׁלִישִׁי הוּא בָּאֶמְצַע שֶׁלּוֹ, זוֹ יְרוּשָׁלַיִם, שֶׁהִיא אֶמְצַע הָעוֹלָם. גָּוֶן רְבִיעִי הוּא מַרְאֶה שֶׁל כָּל הָעַיִן, וְנִקְרָא בַּת עַיִן, שֶׁבְּאוֹתוֹ בַּת עַיִן נִרְאֶה הַפַּרְצוּף, וְהַמַּרְאֶה הַנִּכְבָּד מִכֹּל זוֹ צִיּוֹן, שֶׁהִיא נְקֻדָּה אֶמְצַע שֶׁל הַכֹּל, שֶׁמַּרְאֵה כָּל הָעוֹלָם נִרְאֶה שָׁם, וְשָׁם שׁוֹרָה הַשְּׁכִינָה שֶׁהִיא הַיֹּפִי שֶׁל הַכֹּל וּמַרְאֶה שֶׁל הַכֹּל, וְהָעַיִן הַזּוֹ הִיא יְרֻשַּׁת הָעוֹלָם. וְלָכֵן זֶה עוֹזֵב אוֹתָהּ וְזֶה נוֹטֵל אוֹתָהּ וְיוֹרֵשׁ אוֹתָהּ.</p>\n<p>אָמַר לוֹ, יָפֶה אָמַרְתָּ, אֲבָל דָּבָר נִסְתָּר יוֹתֵר הוּא, וּבְנֵי הָעוֹלָם לֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים, שֶׁהֲרֵי בְּשָׁעָה שֶׁבֶּן אָדָם יוֹצֵא מֵהָעוֹלָם, נַפְשׁוֹ נִסְתֶּרֶת עִמּוֹ, וְעַד שֶׁלֹּא יוֹצֵאת, עֵינֵי הָאָדָם רוֹאוֹת מַה שֶּׁרוֹאוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ (שמות לג) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי - בְּחַיֵּיהֶם לֹא רוֹאִים, אֲבָל בְּמִיתָתָם רוֹאִים.</p>\n<p>וְעֵינָיו פְּקוּחוֹת מֵאוֹתוֹ מַרְאֶה שֶׁרָאָה, וְאוֹתָם שֶׁעוֹמְדִים עָלָיו צְרִיכִים לָשִׂים יָד עַל עֵינָיו וְלִסְגֹּר אוֹתָם, מִשּׁוּם מַה שֶּׁלָּמַדְנוּ בְּסוֹד נִימוּסֵי הָעוֹלָם, שֶׁבְּשָׁעָה שֶׁעֵינָיו נִשְׁאָרוֹת פְּקוּחוֹת מֵאוֹתוֹ מַרְאֶה נִכְבָּד שֶׁרָאָה - אִם זָכָה לְבֵן, הַבֵּן מַקְדִּים לָשִׂים יָדוֹ עַל עֵינָיו וְלִסְגֹּר אוֹתָם, כְּמוֹ שֶׁכָּתוּב וְיוֹסֵף יָשִׁית יָדוֹ עַל עֵינֶיךְ. מִשּׁוּם שֶׁהֲרֵי מַרְאֶה אַחֵר לֹא קָדוֹשׁ מִזְדַּמֵּן כְּנֶגְדּוֹ, וְהָעַיִן שֶׁרָאֲתָה כָּעֵת מַרְאֶה קָדוֹשׁ עֶלְיוֹן, לֹא תִסְתַּכֵּל בְּמַרְאֶה אַחֵר.</p>\n<p>וְעוֹד, שֶׁאוֹתָהּ נֶפֶשׁ סְמוּכָה כְּנֶגְדּוֹ בַּבַּיִת, וְאִם הָעַיִן נִשְׁאֶרֶת פְּקוּחָה וְאוֹתוֹ מַרְאֶה אַחֵר יִשְׁרֶה עַל עֵינָיו - בְּכָל מַה שֶּׁמִּסְתַּכֵּל מִתְקַלְקֵל, וְאֵין זֶה כְּבוֹד הָעַיִן, וְכָל שֶׁכֵּן מִקְּרוֹבָיו, וְכָל שֶׁכֵּן מִן הַמֵּת, שֶׁאֵין כְּבוֹדוֹ לְהִסְתַּכֵּל בְּמַה שֶּׁלֹּא צָרִיךְ וּלְהַשְׁרוֹת עַל עֵינָיו דָּבָר אַחֵר. לְאַחַר כָּךְ מִתְכַּסֶּה בְּעָפָר, וַהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים עַל דִּין הַקֶּבֶר מַהוּ, וְכָבוֹד הוּא שֶׁיִּסְתֹּם הָעַיִן מֵהַכֹּל עַל יְדֵי בְנוֹ שֶׁהִשְׁאִיר בָּעוֹלָם.</p>\n<p>בֹּא רְאֵה, כָּל שִׁבְעַת הַיָּמִים, הַנֶּפֶשׁ הוֹלֶכֶת מֵהַבַּיִת לַקֶּבֶר, וּמֵהַקֶּבֶר לַבַּיִת, וּמִתְאַבֶּלֶת עָלָיו, וְשָׁלֹשׁ פְּעָמִים בַּיּוֹם נִדּוֹנִים כְּאֶחָד הַנֶּפֶשׁ וְהַגּוּף, וְאֵין מִי שֶׁיּוֹדֵעַ בָּעוֹלָם וְיַשְׁגִּיחַ לְעוֹרֵר אֶת הַלֵּב.</p>\n<p>אַחַר כָּךְ הַגּוּף נִטְרָד, וְהַנֶּפֶשׁ הוֹלֶכֶת וּמִתְרַחֶצֶת בַּגֵּיהִנֹּם, וְיוֹצֵאת וּמְשׁוֹטֶטֶת בָּעוֹלָם וּמְבַקֶּרֶת אֶת קִבְרוֹ, עַד שֶׁמִּתְלַבֶּשֶׁת בְּמַה שֶּׁמִּתְלַבֶּשֶׁת.</p>\n<p>אַחַר שְׁנֵים עָשָׂר חֹדֶשׁ כֻּלָּם נָחִים. הַגּוּף נִשְׁאָר (נח) בֶּעָפָר. הַנֶּפֶשׁ נִצְרֶרֶת וּמְאִירָה בָּרוּחַ, בַּמַּלְבּוּשׁ שֶׁמִּתְלַבֶּשֶׁת. הָרוּחַ מִתְעַנֶּגֶת בְּגַן עֵדֶן, וְהַנְּשָׁמָה עוֹלָה לִצְרוֹר שֶׁל עֹנֶג כָּל הָעִנּוּגִים, וְהַכֹּל נִקְשָׁר זֶה בָּזֶה לִזְמַנִּים יְדוּעִים.</p>\n<p>בֹּא רְאֵה, אוֹי לָהֶם לִבְנֵי אָדָם שֶׁלֹּא מִסְתַּכְּלִים וְלֹא יוֹדְעִים וְלֹא מוּדָעִים עַל מָה עוֹמְדִים, וְנִשְׁכָּח מֵהֶם לַעֲשׂוֹת מִצְווֹת הַתּוֹרָה. שֶׁיֵּשׁ מִצְווֹת תּוֹרָה שֶׁעוֹשׂוֹת לְבוּשׁ נִכְבָּד לְמַעְלָה, וְיֵשׁ מִצְווֹת תּוֹרָה שֶׁעוֹשׂוֹת לְבוּשׁ נִכְבָּד לְמַטָּה, וְיֵשׁ מִצְווֹת תּוֹרָה שֶׁעוֹשׂוֹת לְבוּשׁ נִכְבָּד לָעוֹלָם הַזֶּה, וְהַכֹּל צָרִיךְ לוֹ לָאָדָם, וּמִיָּמָיו מַמָּשׁ כֻּלָּם נִתְקָנִים, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>רַבִּי יְהוּדָה הַזָּקֵן הִתְרַגֵּשׁ בְּדַעְתּוֹ יוֹם אֶחָד, וְהֶרְאוּ לוֹ בַּחֲלוֹמוֹ דְּמוּת אַחַת מֵאוֹר שֶׁלּוֹ, חֲזָקָה, שֶׁזּוֹהֶרֶת לְאַרְבָּעָה צְדָדִים. אָמַר לָהֶם, מַה זֶּה? אָמְרוּ לוֹ, לְבוּשׁ שֶׁלְּךְ לַמָּדוֹר הַזֶּה, וּמֵאוֹתוֹ הַיּוֹם הָיָה שָׂמֵחַ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּל יוֹם וָיוֹם רוּחוֹת הַצַּדִּיקִים יוֹשְׁבִים בִּלְבוּשֵׁיהֶם שׁוּרוֹת שׁוּרוֹת בְּגַן עֵדֶן וּמְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָבוֹד עֶלְיוֹן. זֶהוּ שֶׁכָּתוּב (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ. אָמַר רַבִּי אַבָּא, בַּתְּחִלָּה מַה כָּתוּב? וַיִּשְׁתַּחוּ יִשְׂרָאֵל וְגוֹ', כְּמוֹ שֶׁבֵּאַרְנוּ. מִי הַמִּטָּה? זוֹ כְּנֶסֶת יִשְׂרָאֵל. רֹאשׁ הַמִּטָּה - זֶה צַדִּיק. עַל רֹאשׁ הַמִּטָּה - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁהַשָּׁלוֹם שֶׁל הַכֹּל שֶׁלּוֹ, שֶׁכָּתוּב (שיר ג) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, שֶׁיַּעֲקֹב לְשֶׁלּוֹ הִשְׁתַּחֲוָה, לְאוֹתוֹ שֶׁעוֹמֵד עַל רֹאשׁ הַמִּטָּה, יִשְׂרָאֵל שְׁמוֹ, מִשּׁוּם כֵּן וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה.</p>\n<p>אַחַר כָּךְ, כֵּיוָן שֶׁיַּעֲקֹב יָדַע, שֶׁהֲרֵי בְּדַרְגָּה עֶלְיוֹנָה הִשְׁתַּלֵּם, וְדַרְגָּתוֹ הִיא לְמַעְלָה עִם הָאָבוֹת, וְהוּא לְבַדּוֹ תִּקּוּן שָׁלֵם, הִתְחַזֵּק לִבּוֹ וְשָׂמַח, וְהִתְחַזֵּק בְּרָצוֹן עֶלְיוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹ, מַה כָּתוּב בּוֹ? וַיִּתְחַזֵּק יִשְׂרָאֵל וַיֵּשֶׁב עַל הַמִּטָּה, עַל הַמִּטָּה מַמָּשׁ, שֶׁהֲרֵי בְּדַרְגָּה עֶלְיוֹנָה יוֹתֵר הִשְׁתַּלֵּם. אַשְׁרֵי חֶלְקוֹ.</p>"],[9522011456,"<p>שָׁנִינוּ, אָמַר רַבִּי יְהוּדָה, בְּמִשְׁנָתֵנוּ בֵּאַרְנוּ, הֲרֵי שֶׁשָּׁנִינוּ בְּאַרְבָּעָה פְרָקִים בְּשָׁנָה הָעוֹלָם נִדּוֹן: בְּפֶסַח עַל הַתְּבוּאָה, בַּעֲצֶרֶת עַל פֵּרוֹת הָאִילָן, בְּרֹאשׁ הַשָּׁנָה כָּל בָּאֵי הָעוֹלָם עוֹבְרִים לְפָנָיו כִּבְנֵי מָרוֹן, וּבֶחָג נִדּוֹנִים עַל הַמַּיִם. הֲרֵי בֵּאַרְנוּ דְבָרִים, וְסוֹד הַמִּשְׁנָה בֵּאַרְנוּ, בְּפֶסַח עַל הַתְּבוּאָה וְכוּ', כְּנֶגֶד הַמֶּרְכָּבָה הָעֶלְיוֹנָה, סוֹד הָאָבוֹת, וְדָוִד הַמֶּלֶךְ. בְּפֶסַח עַל הַתְּבוּאָה, שֶׁכָּךְ זֶה מַמָּשׁ, וַהֲרֵי בֵּאַרְנוּ דָבָר זֶה, עַל מַה בָּאָה מַצָּה בְּפֶסַח, וַהֲרֵי דִּין הוּא, דִּין הַמַּלְכוּת דִּין, וְזוֹ הָרֵאשִׁית שֶׁהִתְחִילוּ יִשְׂרָאֵל לְהִכָּנֵס בַּחֵלֶק הַקָּדוֹשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְבַעֵר מֵהֶם חָמֵץ, שֶׁהִיא טָעֻיּוֹת אֲחֵרוֹת שֶׁמְּמֻנִּים עַל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁנִּקְרָאִים אֱלֹהִים אֲחֵרִים, אֱלֹהֵי נֵכָר, וְנִקְרָאִים חָמֵץ, יֵצֶר הָרָע, וּלְהִכָּנֵס בַּמַּצָּה, חֵלֶק הַקָּדוֹשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. לָמָּה תְּבוּאָה? (כמו שנאמר תבואתה בה\"א, רמז לה\"א ראשונה של השם הקדוש) לָכֵן בְּפֶסַח נִדּוֹנִים עַל הַתְּבוּאָה, וּבֵאַרְנוּ שֶׁהָעוֹלָם נִדּוֹן עַל דִּין שֶׁל הֵ\"א.</p>\n<p>בַּעָצֶרֶת עַל פֵּרוֹת הָאִילָן. פֵּרוֹת הָאִילָן!? פֵּרוֹת הָאִילָנוֹת צָרִיךְ לִהְיוֹת! מַה זֶּה פֵּרוֹת הָאִילָן? אֶלָּא זֶהוּ הָאִילָן הַגָּדוֹל וְהֶחָזָק לְמַעְלָה. פֵּרוֹת הָאִילָן, כְּמוֹ שֶׁכָּתוּב (הושע יד) אֲנִי כִּבְרוֹשׁ רַעֲנָן מִמֶּנִּי פֶּרְיְךְ נִמְצָא.</p>\n<p>בְּרֹאשׁ הַשָּׁנָה עוֹבְרִין לְפָנָיו כִּבְנֵי מָרוֹן. שָׁנִינוּ, רֹאשׁ הַשָּׁנָה זֶהוּ רֹאשׁ הַשָּׁנָה שֶׁל הַמֶּלֶךְ. וּמִי הוּא רֹאשׁ הַשָּׁנָה? זֶה יִצְחָק שֶׁנִּקְרָא רֹאשׁ, שֶׁהוּא רֹאשׁ אֶחָד שֶׁל הַמֶּלֶךְ (למעלה), מָקוֹם שֶׁנִּקְרָא שָׁנָה, לָכֵן כָּל בָּאֵי עוֹלָם עוֹבְרִים לְפָנָיו כִּבְנֵי מָרוֹן, וְעַל זֶה שָׁנִינוּ בְּרֹאשׁ הַשָּׁנָה, שֶׁהֲרֵי בְּרֹאשׁ הַשָּׁנָה שׁוֹרֶה יִצְחָק.</p>\n<p>וּבֶחָג נִדּוֹנִים עַל הַמַּיִם, זוֹהִי רֵאשִׁית (של ראש) שֶׁל יְמִין הַמֶּלֶךְ, וְעַל זֶה שִׂמְחַת הַמַּיִם נִמְצֵאת בַּכֹּל בְּשָׁעָה שֶׁמְּנַסְּכִים מַיִם וְשׁוֹאֲבִים אוֹתָם, מִשּׁוּם שֶׁמַּיִם זֶה יָדוּעַ, וְעַל זֶה בְּאַרְבָּעָה פְרָקִים אֵלּוּ הַכֹּל נִמְצָאִים.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כְּשֶׁיִּסְתַּכְּלוּ בַּדְּבָרִים, הַכֹּל נִמְצָא בַּפְּרָקִים הַלָּלוּ, אַבְרָהָם, יִצְחָק וְיַעֲקֹב, דָּוִד הַמֶּלֶךְ, וּבְאֵלֶּה הָעוֹלָם נִדּוֹן, וּבְאַרְבָּעָה פְרָקִים בְּנֵי אָדָם נִדּוֹנִים בַּיָּמִים שֶׁנִּמְצָאִים בָּעוֹלָם, וּבְכָל יוֹם וָיוֹם הַסְּפָרִים נִפְתָּחִים וְהַמַּעֲשִׂים נִכְתָּבִים, וְאֵין מִי שֶׁיָּשִׂים לֵב, וְאֵין מִי שֶׁיַּרְכִּין אָזְנַיִם. וְהַתּוֹרָה מְעִידָה בּוֹ בְּכָל יוֹם, וְקוֹל קוֹרֵא בְחַיִל, (משלי ט) מִי פֶתִי יָסֻר הֵנָּה חֲסַר לֵב אָמְרָה לּוֹ, וְאֵין מִי שֶׁיַּקְשִׁיב לְקוֹלוֹ.</p>\n<p>לָמַדְנוּ, בְּשָׁעָה שֶׁבֶּן אָדָם קָם בַּבֹּקֶר, עֵדִים עוֹמְדִים כְּנֶגְדּוֹ וּמְעִידִים בּוֹ, וְהוּא אֵינוֹ מַשְׁגִּיחַ. הַנְּשָׁמָה מְעִידָה עָלָיו בְּכָל זְמַן וּבְכָל שָׁעָה. אִם הִקְשִׁיב - יָפֶה, וְאִם לֹא - הֲרֵי הַסְּפָרִים פְּתוּחִים וְהַמַּעֲשִׂים נִכְתָּבִים. אָמַר רַבִּי חִיָּיא, אַשְׁרֵי הַצַּדִּיקִים שֶׁאֵינָם פּוֹחֲדִים מִן הַדִּין לֹא בָּעוֹלָם הַזֶּה וְלֹא בָּעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב (שם כח) וְצַדִּיקִים כִּכְפִיר יִבְטָח. וְכָתוּב (תהלים לז) צַדִּיקִים יִירְשׁוּ אָרֶץ.</p>"],[9522011457,"<p>רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (בראשית טו) ויהי השמש לבא ותרדמה נפלה על אברם וגו'. פסוק זה בארוהו, אבל זה יום הדין הקשה שמוציאים את האדם מהעולם הזה. ששנינו, (אותו יום) הזמן שמגיע שהאדם יוצא מהעולם הזה, אותו (יום) זמן יום הדין הגדול, שנחשך השמש מן הלבנה, כמו שכתוב (קהלת יב) עד אשר לא תחשך השמש, זו הנשמה הקדושה שנמנעת מבן האדם שלשים יום עד שלא יצא מן העולם, ורואה שהצלם שנמנע ממנו ולא נראה.</p>\n<p>מָה הַטַּעַם נִמְנָע מִמֶּנּוּ? מִשּׁוּם שֶׁהַנְּשָׁמָה הַקְּדוֹשָׁה עוֹלָה וּמָעֳבֶרֶת מִמֶּנּוּ וְלֹא נִרְאֵית. שֶׁלֹּא תֹאמַר, שֶׁכְּשֶׁמֵּת אָדָם וְנֶחֱלָשׁ, נְשָׁמָה זוֹ מָעֳבֶרֶת מִמֶּנּוּ, אֶלָּא כְּשֶׁהוּא בְּחַיָּיו בְּכֹחוֹ, מָעֳבֶרֶת מִמֶּנּוּ (ונחלשת) נְשָׁמָה זוֹ וְלֹא מְאִירָה לָרוּחַ, וְהָרוּחַ לֹא מְאִירָה לַנֶּפֶשׁ, וְאָז מָעֳבָר מִמֶּנּוּ הַצֶּלֶם וְלֹא מֵאִיר לוֹ. (אלא) מֵאוֹתוֹ הַיּוֹם כֻּלָּם מַכְרִיזִים עָלָיו, וַאֲפִלּוּ צִפֳּרֵי הַשָּׁמַיִם. מָה הַטַּעַם? מִשּׁוּם שֶׁנְּשָׁמָה זוֹ עָלְתָה מִמֶּנּוּ, וְהָרוּחַ לֹא מְאִירָה לַנֶּפֶשׁ, וְאָז הַנֶּפֶשׁ נֶחֱלֶשֶׁת, וְהַמַּאֲכָל וְכָל תַּאֲווֹת הַגּוּף עוֹלִים מִמֶּנּוּ וּמָעֳבָרִים.</p>\n<p>וְאָמַר רַבִּי יְהוּדָה, וַאֲפִלּוּ כָּל פַּעַם שֶׁנּוֹפֵל אִישׁ בְּבֵית חָלְיוֹ וְלֹא יָכוֹל לְהִתְפַּלֵּל, הַנְּשָׁמָה מָעֳבֶרֶת וְעוֹלָה מִמֶּנּוּ, וְאָז הָרוּחַ לֹא מְאִירָה לַנֶּפֶשׁ, עַד שֶׁדָּנִים דִּינוֹ שֶׁל הָאָדָם. וְאִם דָּנִים אֶת הָאִישׁ לְטוֹב, אָז הַנְּשָׁמָה חוֹזֶרֶת לִמְקוֹמָהּ וּמְאִירָה לַכֹּל. הֲרֵי בִּזְמַן שֶׁעוֹמֵד הַדָּבָר בְּדִין, וּבִזְמַן שֶׁלֹּא עוֹמֵד הַדָּבָר בְּדִין, שְׁלֹשִׁים יוֹם מַקְדִּימָה הַנְּשָׁמָה לַכֹּל, וְהַצֶּלֶם מָעֳבָר מִמֶּנּוּ.</p>\n<p>שָׁנִינוּ, בִּזְמַן שֶׁדָּנִים אֶת הָאָדָם לְמַעְלָה, מַעֲלִים אֶת נִשְׁמָתוֹ לְבֵית דִּין וְדָנִים אוֹתָהּ עַל פִּי דְבָרֶיהָ, וְהִיא מְעִידָה בַּכֹּל וּמְעִידָה בְּכָל רַעְיוֹנוֹת הָאָדָם, וּבַמַּעֲשִׂים לֹא מְעִידָה, שֶׁהֲרֵי כֻּלָּם כְּתוּבִים בַּסְּפָרִים, וְכֻלָּם דָּנִים אֶת הָאָדָם. בְּאוֹתָהּ שָׁעָה שֶׁדָּנִים אֶת הָאָדָם לְמַעְלָה, אָז דּחַק הַגּוּף נִמְצָא יוֹתֵר מִשְּׁאָר הַזְּמַנִּים.</p>\n<p>אִם דָּנִים אוֹתוֹ לְטוֹבָה, אָז מַרְפִּים מִמֶּנּוּ, וְזֵעָה נִבְקַעַת עַל הַגּוּף, וְהַנְּשָׁמָה חוֹזֶרֶת אַחַר כָּךְ וּמְאִירָה לַכֹּל, וְלֹא עוֹלֶה אָדָם מִבֵּית חָלְיוֹ לְעוֹלָמִים עַד שֶׁדָּנִים דִּינוֹ לְמַעְלָה. וְאִם תֹּאמַר, הֲרֵי כַּמָּה חַיָּבֵי עוֹלָם, כַּמָּה רִשְׁעֵי עוֹלָם עוֹמְדִים בְּקִיּוּמָם? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ בְּדִין הָאָדָם, אַף עַל גַּב שֶׁכָּעֵת לֹא זוֹכֶה, וְהוּא רוֹאֶה שֶׁאַחַר כָּךְ יִזְכֶּה - דָּן אוֹתוֹ לְטוֹבָה. אוֹ לִפְעָמִים שֶׁמּוֹלִיד בֵּן שֶׁיִּהְיֶה צַדִּיק בָּעוֹלָם, וְעַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא דָּן אוֹתוֹ לְטוֹבָה.</p>\n<p>וְכָל מַעֲשָׂיו וְדִינָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְטוֹבָה, וּמַשְׁגִּיחַ בְּהַכֹּל, כְּמוֹ שֶׁכָּתוּב (יחזקאל לג) חי אני נאם ה' וגו' אם אחפץ במות הרשע כי אם בשוב רשע מדרכו. ובגלל זה כל אותם רשעי העולם שעומדים במקומם, הקדוש ברוך הוא דן אותם לטובה.</p>\n<p>וְלִפְעָמִים אוֹתָם הֶחֳלָאִים נִשְׁלַם זְמַנָּם מִלִּשְׁרוֹת שָׁם, כְּמוֹ שֶׁנֶּאֱמַר (דברים מב) וָחֳלָאִים רָעִים וְנֶאֱמָנִים, שֶׁעָשׂוּ אֱמוּנָה, שֶׁכְּשֶׁשּׁוֹרִים עַל הָאָדָם מִסְתַּלְּקִים מִמֶּנּוּ לְאַחַר שֶׁהִשְׁלִימוּ זְמַנָּם, בֵּין לְצַדִּיקִים, בֵּין לִרְשָׁעִים, וְהַכֹּל נַעֲשֶׂה בְדִין, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>וַיַּרְא יִשְׂרָאֵל אֶת בְּנֵי יוֹסֵף וַיֹּאמֶר מִי אֵלֶּה. אָמַר רַבִּי יִצְחָק, פָּסוּק זֶה קָשֶׁה, שֶׁכָּתוּב וַיַּרְא יִשְׂרָאֵל, וְכָתוּב וְעֵינֵי יִשְׂרָאֵל כָּבְדוּ מִ קֶן לֹא יוּכַל לִרְאוֹת. אִם לֹא יוּכַל לִרְאוֹת, אָז מַה זֶּה וַיַּרְא יִשְׂרָאֵל? אֶלָּא שֶׁרָאָה בְּרוּחַ הַקֹּדֶשׁ אוֹתָם בְּנֵי יוֹסֵף, שֶׁהֵם יָרָבְעָם וַחֲבֵרָיו, שֶׁיָּרָבְעָם עָשָׂה שְׁנֵי עֶגְלֵי זָהָב וְאָמַר (מלכים א יב) אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל. וְלָכֵן מִי אֵלֶּה, מִי הוּא שֶׁעָתִיד לוֹמַר אֵלֶּה אֱלֹהֶיךְ לַעֲבוֹדָה זָרָה, וְלָכֵן וַיַּרְא יִשְׂרָאֵל אֶת בְּנֵי יוֹסֵף.</p>\n<p>מִכָּאן שֶׁצַּדִּיקִים רוֹאִים מַעֲשֶׂה לְמֵרָחוֹק, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְעַטֵּר אוֹתָם בַּעֲטַרְתּוֹ. מָה הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה לְמֵרָחוֹק, כְּמוֹ שֶׁכָּתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה כָּל הַמַּעֲשִׂים עַד שֶׁלֹּא עוֹשִׂים אוֹתָם, וְכֻלָּם עוֹבְרִים לְפָנָיו.</p>\n<p>כְּמוֹ זֶה כָּל דּוֹרוֹת הָעוֹלָם מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם, כֻּלָּם הִתְיַצְּבוּ וְעָמְדוּ לְפָנָיו עַד שֶׁלֹּא יָבאוּ לָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ישעיה מא) קֹרֵא הַדֹּרוֹת מֵרֹאשׁ, עַד שֶׁלֹּא נִבְרָא הָעוֹלָם. מִשּׁוּם שֶׁכָּל הַנְּשָׁמוֹת שֶׁיּוֹרְדוֹת לָעוֹלָם, עַד שֶׁלֹּא יָרְדוּ, כֻּלָּם עוֹמְדִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בַּדְּמוּת שֶׁעוֹמְדִים בָּעוֹלָם הַזֶּה, וְנִקְרָאִים בְּשֵׁמוֹת, שֶׁכָּתוּב (שם מ) לְכֻלָּם בְּשֵׁם יִקְרָא.</p>\n<p>גַּם כָּךְ הַצַּדִּיקִים, הַקָּדוֹשׁ בָּרוּךְ הוּא מַרְאֶה לָהֶם כָּל דּוֹרוֹת הָעוֹלָם עַד שֶׁלֹּא יָבאוּ וְיִמָּצְאוּ בָעוֹלָם. מִנַּיִן לָנוּ? מֵאָדָם (זה אדם) שֶׁהָיָה רִאשׁוֹן, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לוֹ כָּל אוֹתָם דּוֹרוֹת עַד שֶׁלֹּא יָבֹאוּ, כַּכָּתוּב (בראשית ה) זֶה סֵפֶר תּוֹלְדת (אדם), שֶׁשָּׁנִינוּ, הֶרְאָה לוֹ כָּל אוֹתָם דּוֹרוֹת שֶׁעֲתִידִים לָבֹא לָעוֹלָם. וְכֵן לְמֹשֶׁה, שֶׁכָּתוּב (דברים לד) וַיַּרְאֵהוּ ה' אֶת כָּל הָאָרֶץ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לוֹ כָּל דּוֹרוֹת הָעוֹלָם וְכל אוֹתָם מַנְהִיגֵי הָעוֹלָם וְכָל שְׁאָר הַנְּבִיאִים עַד שֶׁלֹּא יָבֹאוּ לָעוֹלָם.</p>\n<p>גַּם כָּאן, וַיַּרְא יִשְׂרָאֵל אֶת בְּנֵי יוֹסֵף, רָאָה לְמֵרָחוֹק וְהִזְדַּעְזַע, וְאָמַר מִי אֵלֶּה? וּפָסוּק זֶה מַשְׁלִים לִשְׁנֵי צְדָדִים, לְצַד זֶה וּלְצַד זֶה. וְלָכֵן הֵשִׁיב יוֹסֵף וְאָמַר, בָּנַי הֵם אֲשֶׁר נָתַן לִי אֱלֹהִים בָּזֶה. וּמִנַּיִן לָנוּ שֶׁהֶרְאָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּרוּחַ הַקֹּדֶשׁ? שֶׁכָּתוּב וְהִנֵּה הֶרְאָה אֹתִי אֱלֹהִים גַּם אֶת זַרְעֶךְ. גַּם - לְרַבּוֹת אוֹתָם שֶׁיָּצְאוּ מִמֶּנּוּ, כְּפִי שֶׁאָמַרְנוּ.</p>"],[9522011458,"<p>וַיְבָרֶךָ אֶת יוֹסֵף וַיֹּאמַר הָאֱלֹהִים אֲשֶׁר וְגוֹ'. בַּפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן בּוֹ, וַיְבָרֶךְ אֶת יוֹסֵף, שֶׁלֹּא מָצָאנוּ כָּאן בְּרָכָה שֶׁבֵּרַךְ אֶת יוֹסֵף, אֶלָּא אֶת בָּנָיו. אִם לְבָנָיו, אָז צָרִיךְ לִהְיוֹת כָּתוּב וַיְבָרֲכֵם, אָז מַה זֶּה וַיְבָרֶךְ אֶת יוֹסֵף, וְלֹא מָצָאנוּ כָּאן שֶׁיּוֹסֵף הִתְבָּרֵךְ?</p>\n<p>אָמַר רַבִּי יוֹסֵי, דַּוְקָא אֶת, כָּתוּב אֶת יוֹסֵף, הַבְּרָכָה שֶׁל בָּנָיו הָיְתָה, וְכַאֲשֶׁר מִתְבָּרְכִים בָּנָיו, הוּא מִתְבָּרֵךְ. שֶׁבְּרָכָה שֶׁל בָּנָיו שֶׁל אָדָם בִּרְכָתוֹ הִיא.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, וַיְבָרֶךְ אֶת יוֹסֵף, דַּוְקָא אֶת, שֶׁבֵּרַךְ אֶת אוֹת הַבְּרִית, סוֹד (הברית משום שכיון שאמר בני הם אשר נתן לי אלהים בזה, אז ברך לאותו מקום סוד) הַבְּרִית שֶׁיּוֹסֵף שָׁמַר, וְלָכֵן נִקְרָא צַדִּיק. אֶת שֶׁל יוֹסֵף, סוֹד הַבְּרִית שֶׁעוֹמֶדֶת עִם יוֹסֵף.</p>\n<p>הָאֱלֹהִים אֲשֶׁר הִתְהַלְּכוּ אֲבתַי לְפָנָיו. הָאֱלֹהִים - זֶה סוֹד הַבְּרִית הַקְּדוֹשָׁה, בְּרִית קֹדֶשׁ. אֲבֹתַי לְפָנָיו - דַּוְקָא לְפָנָיו, שֶׁאוֹתָם רִאשׁוֹנִים עֶלְיוֹנִים מִלִּפְנֵי סוֹד שֶׁלָּנוּ, אַבְרָהָם וְיִצְחָק, שֶׁהֲרֵי מֵהֶם נִזּוֹן וְיוֹנֵק אוֹתוֹ (מאותו) מָקוֹם.</p>\n<p>הָאֱלֹהִים הָרֹעֶה אֹתִי, מָה הַטַּעַם פַּעַם אַחֶרֶת הָאֱלֹהִים? אֶלָּא סוֹד עֶלְיוֹן הוּא, וְכָאן בֵּרַךְ אֶת אוֹתוֹ מָקוֹם בְּסוֹד שֶׁל אֱלֹהִים חַיִּים, מְקוֹר הַחַיִּים שֶׁמִּמֶּנּוּ יוֹצְאוֹת בְּרָכוֹת, וְלָכֵן הִזְכִּיר עַצְמוֹ בַּמָּקוֹם הַזֶּה וְאָמַר הָאֱלֹהִים הָרֹעֶה אֹתִי, מִשּׁוּם שֶׁכָּל הַבְּרָכוֹת שֶׁשּׁוֹפְעוֹת מִמְּקוֹר הַחַיִּים יַעֲקֹב לָקַח אוֹתָן, וְכֵיוָן שֶׁהוּא לָקַח אוֹתָן, מָקוֹם זֶה לָקַח בְּרָכוֹת, וְהַכֹּל תָּלוּי (בזכר) בַּדִּבּוּר, וְעַל זֶה וַיְבָרֶךְ אֶת יוֹסֵף כָּתוּב.</p>\n<p>לָכֵן בְּכָל מָקוֹם שֶׁצָּרִיךְ לְבָרֵךְ בְּרָכוֹת, צָרִיךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְבָּרֵךְ בַּהַתְחָלָה, וְאַחַר כָּךְ מִתְבָּרְכִים הָאֲחֵרִים. וְאִם הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מִתְבָּרֵךְ בַּהַתְחָלָה, אוֹתָן בְּרָכוֹת לֹא מִתְקַיְּמוֹת.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי יַעֲקֹב, שֶׁבֵּרַךְ אוֹתוֹ אָבִיו וְלֹא בֵרַךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בַּהַתְחָלָה - בּא רְאֵה, בְּשָׁעָה שֶׁבֵּרַךְ יִצְחָק אֶת יַעֲקֹב, לֹא בֵרְכוֹ עַד שֶׁבֵּרַךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בַּהַתְחָלָה. כֵּיוָן שֶׁבֵּרַךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בַּהַתְחָלָה, הוּא בֵּרַךְ אֶת יַעֲקֹב. מִנַּיִן לָנוּ? שֶׁכָּתוּב (בראשית כז) וַיֹּאמֶר רְאֵה רֵיחַ בְּנִי כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה'. כָּאן עוֹמֶדֶת בְּרָכָה לַקָּדוֹשׁ-בָּרוּךְ- הוּא, שֶׁכָּתוּב אֲשֶׁר בֵּרַכוֹ ה'. הִתְבָּרֵךְ בְּקִיּוּם הַבְּרָכוֹת, וְאַחַר כָּךְ אַחֲרָיו וְיִתֶּן לְךְ וְגוֹ'. כֵּיוָן שֶׁאוֹתוֹ שָׂדֶה הִתְקַיֵּם בַּעֲמִידַת הַבְּרָכוֹת, (בברכותיו, מיד ברכו ויתן לך האלהים, שאותו שדה סוד) שֶׁיָּצְאוּ מִמֶּנּוּ בְּרָכוֹת, אַחַר שֶׁהוּא הִתְקַיֵּם בְּבִרְכוֹתָיו. כְמוֹ זֶה בֵּרַךְ יַעֲקֹב בַּתְּחִלָּה אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאַחַר כָּךְ בֵּרַךְ אֶת בָּנָיו. בּא רְאֵה, בַּבֹּקֶר צָרִיךְ אָדָם לְהַקְדִּים בְּרָכוֹת לַקָּדוֹשׁ- בָּרוּךְ-הוּא, וְאַחַר כָּךְ לִשְׁאָר בְּנֵי הָעוֹלָם, וַהֲרֵי הֵקַמְנוּ בַּבֹּקֶר יֹאכַל עַד וְגוֹ'.</p>\n<p>וּבֹא רְאֵה, כְּשֶׁרָצָה יַעֲקֹב לְבָרֵךְ אֶת אוֹתָם בְּנֵי יוֹסֵף, רָאָה בְּרוּחַ הַקֹּדֶשׁ שֶׁעָתִיד לָצֵאת מֵאֶפְרַיִם יָרָבְעָם בֶּן נְבָט. פָּתַח וְאָמַר מִי אֵלֶּה? מַשְׁמָע (מה שונה) שֶׁאָמַר בַּעֲבוֹדָה זוֹ שֶׁל צַד עֲבוֹדָה זָרָה אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל? אֶלָּא סוֹד הוּא, כָּל אוֹתָם הַצְּדָדִים שֶׁל אוֹתוֹ הַנָּחָשׁ הָרָע, וּמִצַּד אוֹתָהּ רוּחַ טֻמְאָה אוֹתוֹ הַנָּחָשׁ, וְיֵשׁ מִי שֶׁרוֹכֵב עָלָיו, וּכְשֶׁמִּזְדַּוְּגִים נִקְרָאִים אֵלֶּה, וְהֵם מִזְדַּמְּנִים בָּעוֹלָם בְּכָל אוֹתָם צְדָדִים שֶׁלָּהֶם.</p>\n<p>וְרוּחַ הַקֹּדֶשׁ נִקְרֵאת זֹאת, שֶׁהוּא סוֹד הַבְּרִית, רֹשֶׁם הַקָּדוֹשׁ שֶׁנִּמְצָא תָמִיד בָּאָדָם. וְכֵן זֶה אֵלִי וְאַנְוֵהוּ - זֶה ה'. (הוא ה') אֲבָל אֵלֶּה נִקְרָאִים אֵלֶּה, וְעַל זֶה כָּתוּב (שמות לח) אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל.</p>\n<p>וְלָכֵן כָּתוּב (ישעיה מט) גַּם אֵלֶּה תִּשְׁכַּחְנָה, וְאָנֹכִי - סוֹד שֶׁל זאת - לֹא אֶשְׁכָּחֵךְ, וְכָתוּב (איכה א) עַל אֵלֶּה אֲנִי בוֹכִיָּה, שֶׁאוֹתוֹ הַחֵטְא גָּרַם לָהֶם לִבְכּוֹת כַּמָּה בְכִיּוֹת. דָּבָר אַחֵר עַל אֵלֶּה אֲנִי - מָה הַטַּעַם? מִשּׁוּם שֶׁנִּתְּנָה רְשׁוּת לְמָקוֹם זֶה לִשְׁלֹט עַל יִשְׂרָאֵל וּלְהַחֲרִיב אֶת בֵּית הַמִּקְדָּשׁ, וּמִשּׁוּם שֶׁנִּתְּנָה לָהֶם רְשׁוּת לִשְׁלֹט, (כתוב על אלה אני בוכיה, סוד הדבר זה צד הטמאה שנתנה להם רשות לשלט) אֲנִי בוֹכִיָּה, זוֹ רוּחַ הַקֹּדֶשׁ שֶׁנִּקְרֵאת אֲנִי.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב (דברים כח) אֵלֶּה דִּבְרֵי הַבְּרִית - כָּךְ זֶה בְּוַדַּאי, שֶׁכָּל אֵלֶּה לֹא מִתְקַיְּמִים אֶלָּא מִתּוֹךְ אֵלֶּה שֶׁשָּׁם כָּל הַקְּלָלוֹת שְׁרוּיוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁהוּא אָרוּר, וְלָכֵן הִקְדִּים וְאָמַר אֵלֶּה, שֶׁעוֹמֵד לְמִי שֶׁעוֹבֵר עַל דִּבְרֵי הַבְּרִית.</p>\n<p>אֵלֶּה הַמִּצְות אֲשֶׁר צִוָּה ה' (ויקרא כו), מִשּׁוּם שֶׁכָּל מִצְוָה שֶׁל הַתּוֹרָה לְטַהֵר אֶת הָאָדָם, וְלֹא יִסְטֶה מִדֶּרֶךְ זוֹ, וְיִשָּׁמֵר מִשָּׁם וְיִפָּרֵד מֵהֶם. וְאִם תֹּאמַר, (בראשית ו) אֵלֶּה תּוֹלְדת נֹחַ - כָּךְ הוּא וַדַּאי, שֶׁהֲרֵי יָצָא חָם, שֶׁהוּא אֲבִי כְנַעַן, וְכָתוּב (שם ט) אָרוּר כְּנָעַן, וְהוּא סוֹד זֶה שֶׁל אֵלֶּה.</p>\n<p>וְלָכֵן (וכל אלה התוך פסלת הזהב, ועל זה כתוב מי אלה, ישראל כאשר עשו את העגל) כָּתוּב וַיֹּאמְרוּ אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל, וְכָל אֵלֶּה הִתּוּךְ פְּסֹלֶת הַזָּהָב. אַהֲרֹן הִקְרִיב זָהָב שֶׁהוּא צַד שֶׁלּוֹ שֶׁכָּלוּל הוּא בְּחֹזֶק הָאֵשׁ, וְהַכֹּל אֶחָד, וְצַד זֶה זָהָב וְאֵשׁ. (להגביר) רוּחַ טֻמְאָה שֶׁנִּמְצֵאת תָּמִיד בַּמִּדְבָּר, מָצְאָה מָקוֹם בְּאוֹתוֹ זְמַן לְהַחֲזִיק בּוֹ.</p>\n<p>וּמַה שֶּׁהָיוּ יִשְׂרָאֵל טְהוֹרִים מֵאוֹתָהּ זֻהֲמָה רִאשׁוֹנָה שֶׁהִטִּיל בָּעוֹלָם, שֶׁגָּרַם מָוֶת לָעוֹלָם, כְּשֶׁעָמְדוּ עַל הַר סִינַי, אַחַר כָּךְ חָזְרוּ, וְגָרַם לָהֶם כְּמוֹ מִקֹּדֶם לְטַמֵּא אוֹתָם וּלְהִתְחַזֵּק עֲלֵיהֶם, וְגָרַם לָהֶם מָוֶת וּלְכָל הָעוֹלָם לְדוֹרוֹתֵיהֶם אַחֲרֵיהֶם. זֶהוּ שֶׁכָּתוּב (תהלים פג) אֲנִי אָמַרְתִּי אֱלֹהִים אַתֶּם וְגוֹ', אָכֵן כְּאָדָם וְגוֹ'.</p>\n<p>וְעַל זֶה, כְּשֶׁרָאָה יַעֲקֹב אֶת יָרָבְעָם בֶּן נְבָט שֶׁעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת וְאָמַר אֵלֶּה אֱלֹהֶיךְ, הִזְדַּעְזַע וְאָמַר מִי אֵלֶּה. כְּשֶׁרָצָה אַחַר כָּךְ לְבָרְכָם, בֵּרַךְ אֶת (השכינה בתחלה) וְאַחַר כָּךְ בֵּרַךְ (את) בָּנָיו. כֵּיוָן שֶׁבֵּרַךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתְּחִלָּה, אַחַר כָּךְ מֵאוֹתוֹ מָקוֹם שֶׁבֵּרַךְ בַּתְּחִלָּה בֵּרַךְ אוֹתָם. זֶהוּ שֶׁכָּתוּב הַמַּלְאָךְ הַגֹּאֵל אֹתִי מִכָּל רַע וְגוֹ'.</p>"],[9522011459,"<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (ישעיה לח) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וַיִּתְפַּלֵּל אֶל ה'. הֲרֵי פֵּרְשׁוּהָ שֶׁלֹּא יִתְפַּלֵּל אָדָם רַק סָמוּךְ לַכֹּתֶל, וְלֹא יִהְיֶה דָבָר חוֹצֵץ בֵּינוֹ לְבֵין הַכֹּתֶל, שֶׁכָּתוּב וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר. מַה שּׁוֹנֶה בְּכֻלָּם שֶׁהִתְפַּלְלוּ תְפִלָּה, שֶׁלֹּא כָתוּב בָּהֶם וַיַּסֵּב פָּנָיו אֶל הַקִּיר? שֶׁהֲרֵי דַּי לוֹ לוֹמַר וַיִּתְפַּלֵּל אֶל ה', שֶׁהֲרֵי מִי שֶׁמִּתְפַּלֵּל תְּפִלָּה, הוּא מְכַוֵּן דַּעְתּוֹ כָּרָאוּי, שֶׁהֲרֵי כָּתוּב בְּמֹשֶׁה (במדבר כב) וַיִּתְפַּלֵּל מֹשֶׁה אֶל ה', וַיִּצְעַק מֹשֶׁה אֶל ה', וְלֹא כָתוּב וַיַּסֵּב פָּנָיו. כָּאן בְּחִזְקִיָּהוּ מָה הַטַּעַם וַיַּסֵּב חִזְקִיָּה פָּנָיו אֶל הַקִּיר וְאַחַר כָּךְ וַיִּתְפַּלֵּל?</p>\n<p>אֶלָּא סוֹד הַדָּבָר הוּא, שֶׁשָּׁנִינוּ, חִזְקִיָּה בְּאוֹתוֹ זְמַן לֹא הָיָה נָשׂוּי, וְלֹא הָיְתָה לוֹ אִשָּׁה וְלֹא הוֹלִיד בָּנִים, מַה כָּתוּב? וַיָּבא אֵלָיו וְגוֹ' כִּי מֵת אַתָּה וְלֹא תִחְיֶה. וְשָׁנִינוּ, כִּי מֵת אַתָּה - בָּעוֹלָם הַזֶּה, וְלֹא תִחְיֶה - בָּעוֹלָם הַבָּא. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא הוֹלִיד בָּנִים.</p>\n<p>שֶׁכָּל מִי שֶׁלֹּא מִשְׁתַּדֵּל לְהוֹלִיד בָּנִים בָּעוֹלָם הַזֶּה, לֹא מִתְקַיֵּם בָּעוֹלָם הַבָּא, וְלֹא יִהְיֶה לוֹ חֵלֶק בְּאוֹתוֹ הָעוֹלָם, וּמִתְגָּרֶשֶׁת נִשְׁמָתוֹ בָּעוֹלָם (הבא), וְלֹא מוֹצֵאת מְנוּחָה בְּמָקוֹם בָּעוֹלָם, וְזֶהוּ הָעֹנֶשׁ שֶׁכָּתוּב בַּתּוֹרָה (ויקרא כ) עֲרִירִים יָמוּתוּ, וּמְתַרְגְּמִים בְּלֹא וָלָד, מִשּׁוּם שֶׁמִּי שֶׁהוּא בְּלִי וָלָד, כְּשֶׁהוֹלֵךְ לְאוֹתוֹ הָעוֹלָם מֵת הוּא שָׁם, מֵת בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וְלָכֵן כָּתוּב כִּי מֵת אַתָּה וְלֹא תִחְיֶה.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁשְּׁכִינָה לֹא שׁוֹרָה עָלָיו כְּלָל, אָז כָּתוּב וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר. לָמַדְנוּ שֶׁשָּׂם רַעְיוֹנוֹתָיו וְכִוֵּן אֶת פָּנָיו לָשֵׂאת אִשָּׁה, כְּדֵי שֶׁתִּשְׁרֶה עָלָיו הַשְּׁכִינָה, סוֹד שֶׁל הַקִּיר.</p>\n<p>וְלָכֵן כָּתוּב אַחַר כָּךְ וַיִּתְפַּלֵּל אֶל ה'. מִכָּאן לָמַדְנוּ, שֶׁמִּי שֶׁיֵּשׁ בּוֹ חֵטְא וְצָרִיךְ לְבַקֵּשׁ רַחֲמִים עָלָיו, יְכַוֵּן פָּנָיו וְרַעְיוֹנוֹתָיו לְתַקֵּן עַצְמוֹ מֵאוֹתוֹ חֵטְא, וְאַחַר כָּךְ יְבַקֵּשׁ לְהִתְפַּלֵּל, כְּמוֹ שֶׁנֶּאֱמַר (איכה ג) נַחְפְּשָׂה דְרָכֵינוּ וְנַחְקֹרָה - בַּתְּחִלָּה, וְאַחַר כָּךְ - וְנָשׁוּבָה. גַּם כָּאן, כֵּיוָן שֶׁיָּדַע חִזְקִיָּה חֶטְאוֹ, מַה כָּתוּב? וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר. שָׂם פָּנָיו לְתַקֵּן אֶל הַשְּׁכִינָה, שֶׁהֲרֵי אֶל הַמָּקוֹם הַזֶּה חָטָא.</p>\n<p>מִשּׁוּם שֶׁהַשְּׁכִינָה, כָּל נְקֵבוֹת הָעוֹלָם עוֹמְדוֹת בְּצִדָּהּ. מִי שֶׁיֵּשׁ לוֹ נְקֵבָה, שׁוֹרָה הִיא עָלָיו. וּמִי שֶׁאֵין לוֹ, לֹא שׁוֹרָה עָלָיו. וְעַל זֶה תִּקֵּן עַצְמוֹ אֵלֶיהָ לְתַקֵּן, וְקִבֵּל עָלָיו לְהִנָּשֵׂא, וְאַחַר כָּךְ וַיִּתְפַּלֵּל אֶל ה'.</p>\n<p>קִיר - זֶהוּ אֲדוֹן כָּל הָאָרֶץ, וְזוֹ הַשְּׁכִינָה, כְּמוֹ שֶׁנֶּאֱמַר (יהושע ג) הִנֵּה אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ. קִיר - כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כב) מְקַרְקַר קִר וְשׁוֹעַ, קִרְקוּר וּנְהִימַת הַקִּיר שֶׁהוּא אָדוֹן, כְּשֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) רָחֵל מְבַכָּה עַל בָּנֶיהָ, וַהֲרֵי בֵּאַרְנוּ. וְלָכֵן וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר.</p>\n<p>בֹּא רְאֵה, בַּתְּפִלָּה מַה כָּתוּב? אָנָּה ה' זְכָר נָא אֵת אֲשֶׁר הִתְהַלַּכְתִּי לְפָנֶיךְ. רָמַז כָּאן שֶׁשָּׁמַר בְּרִית הַקֹּדֶשׁ וְלֹא טִמֵּא אוֹתוֹ, וְשָׁמַר אוֹתוֹ כָּרָאוּי. כָּתוּב כָּאן הִתְהַלַּכְתִּי לְפָנֶיךְ, וְכָתוּב שָׁם (בראשית יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים וְאֶתְּנָה בְרִיתִי בֵּינִי וּבֵינֶיךְ, שֶׁשָּׁמַר בְּרִית הַקֹּדֶשׁ כָּרָאוּי, בֶּאֱמֶת וּבְלֵב שָׁלֵם, שֶׁהִתְכַּוֵּן בְּכָל אוֹתָם סוֹדוֹת הָאֱמוּנָה שֶׁכְּלוּלִים בֶּאֱמֶת.</p>\n<p>וְהַטוֹב בְּעֵינֶיךְ עָשִׂיתִי, שֶׁסָּמַךְ גְּאֻלָּה לִתְפִלָּה, וַהֲרֵי בֵּאַרְנוּ. וְהִנֵּה פֵּרְשׁוּהָ הַחֲבֵרִים, שֶׁהִתְכַּוֵּן לְיַחֵד יִחוּד כָּרָאוּי, וְלָכֵן וַיֵּבְךָּ חִזְקִיָּהוּ בְּכִי גָדוֹל, שֶׁאֵין שַׁעַר שֶׁעוֹמֵד לִפְנֵי דְמָעוֹת. גְּאֻלָּה - זֶה הַמַּלְאָךְ הַגֹּאֵל, שֶׁזֶּהוּ נִמְצָא בְּכָל גְּאֻלָּה שֶׁבָּעוֹלָם, וַהֲרֵי בֵּאַרְנוּ.</p>"],[9522011460,"<p>הַמַּלְאָךָ הַגֹּאֵל אֹתִי מִכָּל רָע. רַבִּי אֶלְעָזָר אָמַר, כֵּיוָן שֶׁבֵּרַךְ יַעֲקֹב וְהִתְכַּוֵּן מִלְּמַטָּה לְמַעְלָה, אָז הִמְשִׁיךְ מִלְמַעְלָה לְמַטָּה, שֶׁכָּתוּב הָאֱלֹהִים הָרֹעֶה אֹתִי. כֵּיוָן שֶׁהוּא לָקַח, נָתַן בְּרָכוֹת לְמָקוֹם זֶה. כֵּיוָן שֶׁהִגִּיעַ אֶת הַבְּרָכוֹת לַמָּקוֹם הַזֶּה, אָז פָּתַח וְאָמַר הַמַּלְאָךְ הַגֹּאֵל וְכוּ'.</p>\n<p>פָּתַח וְאָמַר, (מלכים א ח) כִּי הַכְּרוּבִים פֹּרְשִׂים כְּנָפַיִם אֶל מְקוֹם הָאָרוֹן וְגוֹ'. בּא רְאֵה, הַכְּרוּבִים בְּאוֹת וּבְנֵס הָיוּ עוֹמְדִים, שָׁלֹשׁ פְּעָמִים בְּיוֹם הָיוּ פוֹרְשִׂים כַּנְפֵיהֶם וְסוֹכְכִים עַל הָאָרוֹן לְמַטָּה, שֶׁכָּתוּב (שמות כה, כ) פֹּרְשֵׂי כְנָפַיִם. פְּרוּשֵׂי כְנָפַיִם לֹא כָתוּב, אֶלָּא פֹּרְשֵׂי.</p>\n<p>וּבֹא וּרְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה. כְּרוּבִים דְּמוּתָם כְּמַרְאֵה תִינוֹקוֹת, וְעוֹמְדִים תַּחַת מָקוֹם זֶה מִיָּמִין וּמִשְּׂמֹאל, וְאֵלֶּה מִתְבָּרְכִים בַּתְּחִלָּה מֵאוֹתָן בְּרָכוֹת שֶׁשּׁוֹפְעוֹת מִלְמַעְלָה, וּמִכָּאן שׁוֹפְעוֹת הַבְּרָכוֹת לְמַטָּה.</p>\n<p>וְלָכֵן כָּתוּב הַמַּלְאָךְ הַגֹּאֵל אֹתִי מִכָּל רָע. אֹתִי - שֶׁנָּטַל בְּרָכוֹת מִגְּוָנִים שֶׁלְּמַעְלָה. וְכֵיוָן שֶׁהוּא נָטַל, יְבָרֵךְ אֶת הַנְּעָרִים, זֶהוּ סוֹד הַכְּרוּבִים, שֶׁמֵּהֶם שׁוֹפְעוֹת בְּרָכוֹת מֵהָעֶלְיוֹנִים לַתַּחְתּוֹנִים (ותחתונים).</p>\n<p>הַמַּלְאָךָ הַגֹּאֵל אֹתִי מִכָּל רָע יְבָרֵךְ אֶת הַנְּעָרִים וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (משלי יט) בַּיִת וָהוֹן נַחֲלַת אָבוֹת. וְכִי נַחֲלַת אָבוֹת הֵם, וַהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן הַכֹּל לִבְנֵי אָדָם? אֶלָּא, כֵּיוָן שֶׁמּוֹרִישׁ בַּיִת וּמָמוֹן לְבֶן הָאָדָם, לִפְעָמִים יוֹרִישׁ הַכֹּל לִבְנוֹ, וְיִהְיֶה יְרֻשַּׁת הָאָבוֹת, אֲבָל וּמֵה' אִשָּׁה מַשְׂכָּלֶת, מִשּׁוּם שֶׁהָאִשָּׁה, כְּשֶׁיּוֹרֵשׁ אוֹתָהּ הַבֶּן אָדָם, הוּא יוֹרֵשׁ אוֹתָהּ מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי לֹא יוֹרִישׁ אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְבֶן הָאָדָם אֶלָּא כְּשֶׁמַּכְרִיזִים עָלָיו בָּרָקִיעַ.</p>\n<p>שֶׁהַקָּדוֹשׁ בָּרוּךָ הוּא מְזַוֵּג זִוּוּגִים עַד שֶׁלֹּא בָאוּ לָעוֹלָם. וּכְשֶׁזָּכוּ בְּנֵי אָדָם לְפִי מַעֲשֵׂיהֶם, כָּךְ נוֹתְנִים לָהֶם אִשָּׁה, וְהַכֹּל גָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּלְפִי מַעֲשִׂים שֶׁל צַדִּיקִים כָּךְ מְזַוֵּג זִוּוּגִים.</p>\n<p>וְלִפְעָמִים שֶׁעוֹלִים בְּמֹאזְנַיִם, וּמַסְטֶה אוֹתוֹ הָאִישׁ דַּרְכּוֹ, עוֹלֶה זִוּוּגוֹ לְאַחֵר עַד שֶׁיַּכְשִׁיר מַעֲשָׂיו, וּכְשֶׁיַּכְשִׁיר מַעֲשָׂיו אוֹ שֶׁמַּגִּיעַ זְמַנּוֹ, נִדְחֶה אִישׁ מִפְּנֵי אִישׁ, וּבָא זֶה וְלוֹקֵחַ אֶת שֶׁלּוֹ. וְזֶה קָשֶׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהַכֹּל, לִדְחוֹת אִישׁ מִפְּנֵי אִישׁ אַחֵר, וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא נוֹתֵן אִשָּׁה לְבֶן הָאָדָם, וּמִמֶּנּוּ בָּאִים הַזִּוּוּגִים. וְלָכֵן וּמֵה' אִשָּׁה מַשְׂכָּלֶת.</p>\n<p>לָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן הַכֹּל לְבֶן הָאָדָם. וְאִם תֹּאמַר, אִשָּׁה מַשְׂכֶּלֶת וְלֹא אַחֶרֶת - בּא רְאֵה, אַף עַל גַּב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַזְמִין טוֹב לָאָדָם לָתֵת לוֹ, וְהוּא מַסְטֶה דַרְכּוֹ מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא לְצַד אַחֵר - מֵאוֹתוֹ צַד אַחֵר שֶׁנִּדְבַּק בּוֹ יָבֹא לוֹ מַה שֶּׁיָּבֹא, בְּכָל (כל) הַקִּטְרוּגִים וְכָל הָרָעוֹת, וְלֹא בָאִים אֵלָיו מִן הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא מֵאוֹתוֹ צַד רָע שֶׁנִּדְבַּק בּוֹ בְּאוֹתָם מַעֲשִׂים שֶׁעָשָׂה.</p>\n<p>וְעַל זֶה, אִשָּׁה שֶׁאֵינָהּ מַשְׂכֶּלֶת, קָרָא עַל זֶה שְׁלֹמֹה, (קהלת ז) וּמֹצֵא אֲנִי מַר מִמָּוֶת אֶת הָאִשָּׁה, מִשּׁוּם שֶׁחֲטָאֵי הָאָדָם הוּא מוֹשֵׁךְ עָלָיו בְּאוֹתָם מַעֲשִׂים שֶׁעָשָׂה. וְלָכֵן, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בָּאָדָם מִשּׁוּם מַעֲשָׂיו הַכְּשֵׁרִים, הוּא מַזְמִין לוֹ אִשָּׁה שֶׁהִיא מַשְׂכֶּלֶת, וּפוֹדֵהוּ בִּפְדוּת מִתּוֹךְ הַצַּד הָאַחֵר.</p>\n<p>וְעַל זֶה אָמַר יַעֲקֹב הַמַּלְאָךְ הַגֹּאֵל אֹתִי מִכָּל רָע. מַה זֶה מִכָּל רָע? שֶׁלֹּא הִזְדַּמְּנָה לִי אִשָּׁה שֶׁהִיא מִתּוֹךְ הַצַּד הָאַחֵר, וְלֹא קָרָה פְסוּל בְּזַרְעִי (במטתי), שֶׁכֻּלָּם צַדִּיקִים וּשְׁלֵמִים בִּשְׁלֵמוּת, מִשּׁוּם שֶׁנִּפְדָּה מִכָּל רָע, וְיַעֲקֹב לֹא נִדְבַּק בְּאוֹתוֹ צַד הָאַחֵר כְּלָל.</p>\n<p>וְעַל זֶה הַמַּלְאָךְ הַגֹּאֵל אֹתִי מִכָּל רָע יְבָרֵךְ אֶת הַנְּעָרִים. מָה הַטַּעַם נִרְאוּ לִבְרָכָה? מִשּׁוּם שֶׁשָּׁמַר יוֹסֵף אֶת אוֹת הַבְּרִית הַקְּדוֹשָׁה, וְעַל זֶה אָמַר יוֹסֵף, בָּנַי הֵם אֲשֶׁר נָתַן לִי אֱלֹהִים בָּזֶה. הֶרְאָה לוֹ סוֹד הַבְּרִית שֶׁשָּׁמַר אוֹתוֹ, וּמִשּׁוּם שֶׁשָּׁמַר אוֹתוֹ, רְאוּיִים לְהִתְבָּרֵךְ וְרָאוּי הוּא לִבְרָכוֹת רַבּוֹת. מִשּׁוּם כָּךְ לְכֻלָּם נָתַן בְּרָכָה אַחַת, וּלְיוֹסֵף בְּרָכוֹת רַבּוֹת, מַשְׁמָע שֶׁכָּתוּב בִּרְכֹת אָבִיךְ גָּבְרוּ עַל בִּרְכֹת הוֹרַי וְגוֹ', בִּרְכֹת שָׁדַיִם וָרָחַם, תִּהְיֶיןָ לְרֹאשׁ יוֹסֵף.</p>\n<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים קכג) אֵלֶיךְ נָשָׂאתִי אֶת עֵינַי הַיֹּשְׁבִי בַּשָּׁמָיִם. פָּסוּק זֶה בֵּאֲרוּהוּ, אֲבָל בּא רְאֵה, תְּפִלָּה שֶׁל בֶּן אָדָם שֶׁמִּתְכַּוֵּן בָּהּ, הוּא לְמַעְלָה לָעֹמֶק הָעֶלְיוֹן שֶׁמִּשָּׁם שׁוֹפְעוֹת כָּל הַבְּרָכוֹת וְכָל הַחֵרוּת, וּמִשָּׁם יוֹצְאִים לְקַיֵּם אֶת הַכֹּל.</p>\n<p>וְעַל זֶה יָתֵר יוֹ\"ד, מִשּׁוּם שֶׁיּוֹ\"ד לֹא פוֹסֵק מִמָּקוֹם הַזֶּה לְעוֹלָמִים, וְלָכֵן כָּתוּב הַיֹּשְׁבִי בַּשָּׁמָיִם, אָחוּז לְמַעְלָה בְּסוֹד הַחָכְמָה הָעֶלְיוֹנָה, וְאָחוּז לְמַטָּה שֶׁיּוֹשֵׁב עַל כִּסֵּא הָאָבוֹת, יוֹשֵׁב עַל הַכִּסֵּא שֶׁנִּקְרָא שָׁמַיִם, וְלָכֵן כָּתוּב הַיֹּשְׁבִי בַּשָּׁמָיִם.</p>\n<p>וּמִכָּאן, כְּשֶׁבְּרָכוֹת שׁוֹפְעוֹת מִלְמַעְלָה מֵהָעֹמֶק הַזֶּה, אֶת כֻּלָּן נוֹטֵל הַמָּקוֹם הַזֶּה שֶׁנִּקְרָא שָׁמַיִם, וּמִזֶּה שׁוֹפְעִים לְמַטָּה, עַד שֶׁמַּגִּיעִים לְצַדִּיק עַמּוּד הָעוֹלָם, וּמִכָּאן מִתְבָּרְכִים כָּל אוֹתָם הַחֲיָלוֹת וְכָל אוֹתָם הַמַּחֲנוֹת לְמִינֵיהֶם, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>בֹּא רְאֵה, בְּשִׁבְעִים וּשְׁנַיִם מְאוֹרוֹת עוֹלָה עֲטֶרֶת כָּל הַמַּחֲנוֹת, עִגּוּל הָעוֹלָם, בְּשִׁבְעִים מְקוֹמוֹת, עִגּוּל אֶחָד לְכֻלָּם. בְּתוֹךְ אוֹתוֹ עִגּוּל נְקֻדָּה אַחַת שֶׁעוֹמֶדֶת בָּאֶמְצַע. מִנְּקֻדָּה זוֹ נִזּוֹן כָּל אוֹתוֹ עִגּוּל, בֵּית קֹדֶשׁ הַקְּדָשִׁים, הוּא מָקוֹם לְאוֹתָהּ רוּחַ כָּל הָרוּחוֹת, (כמו סוד של כל הסודות) נִסְתָּר בְּתוֹכוֹ. סֵתֶר זֶה הוּא בְּתוֹךְ חֵילוֹתֶיהָ, טָמִיר הוּא לִפְנַי וְלִפְנִים. כְּשֶׁעוֹלָה זוֹ, עוֹלִים כֻּלָּם אַחֲרֶיהָ. זֶהוּ שֶׁכָּתוּב (שיר א) מָשְׁכֵנִי אַחֲרֶיךְ נָרוּצָה.</p>"],[9522011461,"<p>רַבִּי חִזְקִיָּה וְרַבִּי יוֹסֵי וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי, כָּל אֶחָד וְאֶחָד מֵאִתָּנוּ יֹאמַר דִּבְרֵי תוֹרָה. פָּתַח רַבִּי יְהוּדָה וְאָמַר, (תהלים עט) אַל תִּזְכָּר לָנוּ עֲונֹת רִאשּנִים מַהֵר יְקַדְּמוּנוּ וְגוֹ'. בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּאַהֲבַת יִשְׂרָאֵל אוֹהֵב אוֹתָם, שֶׁהֵם גּוֹרָלוֹ וִירֻשָּׁתוֹ, לֹא מִסְתַּכֵּל אַחֵר בְּדִינָם, פְּרָט לוֹ לְבַדּוֹ. וְכֵיוָן שֶׁהוּא מִסְתַּכֵּל בְּדִינָם, מִתְמַלֵּא עֲלֵיהֶם רַחֲמִים, מִשּׁוּם שֶׁהוּא כְּאָב שֶׁמְּרַחֵם עַל הַבָּנִים, כְּמוֹ שֶׁנֶּאֱמַר (שם קג) כְּרַחֵם אָב עַל בָּנִים רִחַם ה' וְגוֹ'. וְכֵיוָן שֶׁנִּמְצָאִים לָהֶם חֲטָאִים, מַעֲבִיר אוֹתָם רִאשׁוֹן רִאשׁוֹן, עַד שֶׁמַּעֲבִיר כֻּלָּם מִלְּפָנָיו. וְכֵיוָן שֶׁהֶעֱבִיר כֻּלָּם מִלְּפָנָיו, לֹא נִשְׁאָרִים עֲלֵיהֶם חֲטָאִים לָתֵת שִׁלְטוֹן לַצַּד הָאַחֵר שֶׁל דִּין עֲלֵיהֶם.</p>\n<p>בָּא לַחֲטֹא לְפָנָיו כְּבַתְּחִלָּה - אוֹתָם חֲטָאִים רִאשׁוֹנִים שֶׁהֶעֱבִיר מִלְּפָנָיו, חָשַׁב עֲלֵיהֶם, וְלָכֵן כָּתוּב אַל תִּזְכָּר לָנוּ עֲונֹת רִאשֹׁנִים מַהֵר יְקַדְּמוּנוּ רַחֲמֶיךְ וְגוֹ'. שֶׁאִם רַחֲמֶיךְ לֹא יַקְדִּימוּ עַל יִשְׂרָאֵל, לֹא יוּכְלוּ לַעֲמֹד בָּעוֹלָם. מִשּׁוּם שֶׁכַּמָּה הֵם בַּעֲלֵי הַדִּין הַקָּשֶׁה, בַּעֲלֵי מָגִנִּים, וְכַמָּה מַלְשִׁינִים שֶׁעוֹמְדִים עֲלֵיהֶם שֶׁלְּיִשְׂרָאֵל לְמַעְלָה, וְאִלְמָלֵא שֶׁהִקְדִּים הַקָּדוֹשׁ בָּרוּךְ הוּא רַחֲמִים עַל יִשְׂרָאֵל, עַד שֶׁלֹּא יַשְׁגִּיחַ בְּדִינָם, לֹא יוּכְלוּ לַעֲמֹד בָּעוֹלָם. וְעַל זֶה מַהֵר יְקַדְּמוּנוּ רַחֲמֶיךְ כִּי דַלּוֹנוּ מְאֹד, דַּלּוּת שֶׁל מַעֲשִׂים טוֹבִים, דַּלּוּת שֶׁל מַעֲשִׂים כְּשֵׁרִים (לפני הקדוש ברוך הוא).</p>\n<p>בֹּא תִרְאֶה, אִלְמָלֵא יְסַגְּלוּ יִשְׂרָאֵל מַעֲשִׂים כְּשֵׁרִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא הָיוּ עוֹמְדים עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת בָּעוֹלָם, אֲבָל יִשְׂרָאֵל הֵם גּוֹרְמִים לִשְׁאָר עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת לִזְקֹף רָאשֵׁיהֶם בָּעוֹלָם. שֶׁאִלְמָלֵא יִשְׂרָאֵל לֹא הָיוּ חוֹטְאִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שְׁאָר עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת נִכְפִּים לִפְנֵיהֶם.</p>\n<p>וּבֹא רְאֵה, אִלְמָלֵא שֶׁהִמְשִׁיכוּ יִשְׂרָאֵל בְּמַעֲשִׂים רָעִים לְצַד אַחֵר בָּאָרֶץ הַקְּדוֹשָׁה, הֲרֵי נִתְבָּאֵר, שֶׁלֹּא יִשְׁלְטוּ עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת בָּאָרֶץ הַקְּדוֹשָׁה, וְלֹא הֻגְלוּ מֵעַל הָאָרֶץ, וְעַל זֶה כָּתוּב כִּי דַלּוֹנוּ מְאֹד, שֶׁאֵין לָנוּ מַעֲשִׂים כְּשֵׁרִים כָּרָאוּי, וְלָכֵן כִּי דַלּוֹנוּ מְאֹד מַהֵר יְקַדְּמוּנוּ רַחֲמֶיךְ.</p>"],[9522011462,"<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, (שם ב) עִבְדוּ אֶת ה' בְּיִרְאָה וְגִילוּ בִּרְעָדָה, וְכָתוּב (שם ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה בֹּאוּ לְפָנָיו בִּרְנָנָה. בֹּא רְאֵה, כָּל אָדם שֶׁבָּא לַעֲבֹד לַקָּדוֹשׁ-בָּרוּךְ-הוּא, בַּבֹּקֶר וּבָעֶרֶב צָרִיךְ לַעֲבֹד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בַּבֹּקֶר, כְּשֶׁעוֹלֶה הָאוֹר, וְהִתְעוֹרְרוּת צַד הַיָּמִין מִתְעוֹרֶרֶת בָּעוֹלָם, אָז צָרִיךְ אָדָם לְהִתְקַשֵּׁר בִּימִין הַקָּדוֹשׁ בָּרוּךְ הוּא וְלַעֲבֹד לְפָנָיו בַּעֲבוֹדַת הַתְּפִלָּה, מִשּׁוּם שֶׁתְּפִלָּה מַחֲזֶקֶת תֹּקֶף לְמַעְלָה, וּמַמְשִׁיכָה בְּרָכוֹת מֵהָעֹמֶק הָעֶלְיוֹן לְכָל הָעוֹלָמוֹת, וּמִשָּׁם מַמְשִׁיךְ בְּרָכוֹת לְמַטָּה לַתַּחְתּוֹנִים, וְנִמְצְאוּ עֶלְיוֹנִים וְתַחְתּוֹנִים מִתְבָּרְכִים בְּאוֹתָהּ עֲבוֹדַת הַתְּפִלָּה.</p>\n<p>עָבוֹדַת הַתְּפִלָּה, שֶׁצָּרִיךְ אָדָם לַעֲבֹד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּשִׂמְחָה וּבִרְנָנָה לְהַכְלִיל אֶת כְּנֶסֶת יִשְׂרָאֵל בֵּינֵיהֶם, וְאַחַר כָּךְ לְיַחֵד הַיִּחוּד כָּרָאוּי, שֶׁכָּתוּב דְּעוּ כִּי ה' הוּא אֱלֹהִים. זֶהוּ סוֹד הַיִּחוּד בְּסוֹד הָעֲבוֹדָה.</p>\n<p>וְעִם כָּל זֶה צָרִיךְ אָדָם לַעֲבֹד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּחֶדְוָה וּלְהַרְאוֹת חֶדְוָה בַּעֲבוֹדָתוֹ, וּשְׁנֵי אֵלֶּה - שִׂמְחָה וּרְנָנָה - כְּנֶגֶד שְׁנֵי אֵלֶּה. שְׁתֵּי תְפִלּוֹת, שְׁנֵי קָרְבָּנוֹת לְיוֹם כְּנֶגֶד שְׁנֵי אֵלֶּה, שֶׁהֵם שִׂמְחָה וּרְנָנָה. שִׂמְחָה בַּבֹּקֶר, וּרְנָנָה בַּלַּיְלָה. וְעַל זֶה (במדבר כח) אֶת הַכֶּבֶשׂ אֶחָד תַּעֲשֶׂה בַבֹּקֶר וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם.</p>\n<p>וְעַל זֶה תְּפִלַּת עַרְבִית הִיא רְשׁוּת, מִשּׁוּם שֶׁאוֹתָהּ שָׁעָה מְחַלֶּקֶת טֶרֶף לְכָל חֵילוֹתֶיהָ, וְלֹא שָׁעָה לְהַזְכִּיר (להתברך), אֶלָּא לָתֵת מָזוֹן. בַּיּוֹם הַהוּא מִתְבָּרֶכֶת מִשְּׁנֵי הַצְּדָדִים הַלָּלוּ, בַּבֹּקֶר וּבַלַּיְלָה, מִתּוֹךְ שִׂמְחָה וּרְנָנָה, וּבַלַּיְלָה מְחַלֶּקֶת לַכֹּל כָּרָאוּי. זֶהוּ שֶׁכָּתוּב (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְגוֹ'.</p>"],[9522011463,"<p>פָּתַח רַבִּי חִזְקִיָּה וְאָמַר, (תהלים קמא) תִּכּוֹן תְּפִלָּתִי קְטֹרֶת לְפָנֶיךְ מַשְׂאַת כַּפַּי מִנְחַת עָרֶב. לָמָּה מִנְחַת עָרֶב וְלֹא תְּפִלַּת הַבּקֶר, שֶׁלֹּא כָתוּב תִּכּוֹן תְּפִלָּתִי בַּבֹּקֶר? אֶלָּא כָּךְ נִתְבָּאֵר, תִּכּוֹן תְּפִלָּתִי קְטֹרֶת לְפָנֶיךְ. קְטֹרֶת לֹא בָאָה אֶלָּא רַק עַל חֶדְוָה. זֶהוּ שֶׁכָּתוּב (משלי כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. וְלָכֵן הַכֹּהֵן כְּשֶׁמַּדְלִיק נֵרוֹת, הָיָה מַקְרִיב קְטֹרֶת, כְּמוֹ שֶׁנֶּאֱמַר (שמות ל) בְּהֵיטִיבוֹ אֶת הַנֵּרֹת יַקְטִירֶנָּה וּבְהַעֲלֹת אַהֲרֹן אֶת הַנֵּרֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה. בַּבֹּקֶר עַל חֶדְוָה, שֶׁהַשָּׁעָה גּוֹרֶמֶת בָּעֶרֶב לְשַׂמֵּחַ צַד שְׂמֹאל, וְכָךְ רָאוּי, וּלְעוֹלָם לֹא בָא אֶלָּא עַל חֶדְוָה.</p>\n<p>וּבֹא רְאֵה, קְטֹרֶת מְקַשֶּׁרֶת קְשָׁרִים וְאוֹחֶזֶת לְמַעְלָה וּלְמַטָּה, וְזֶה מַעֲבִיר מָוֶת וְקִטְרוּג וְרֹגֶז, שֶׁלֹּא יוּכְלוּ לִשְׁלֹט בָּעוֹלָם, כְּמוֹ שֶׁכָּתוּב (במדבר יז) וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְתֶן עָלֶיהָ אֵשׁ מֵעַל הַמִּזְבֵּחַ וְשִׂים קְטֹרֶת וְהוֹלֵךְ מְהֵרָה וְגוֹ'. אַחַר זֶה כָּתוּב וַיָּרָץ וְגוֹ', וַיְכַפֵּר עַל הָעָם, וְכָתוּב וַיַּעֲמֹד בֵּין הַמֵּתִים וּבֵין הַחַיִּים וַתֵּעָצַר הַמַּגֵּפָה. מִשּׁוּם שֶׁלֹּא יְכוֹלִים כָּל הַצְּדָדִים הָרָעִים וְכָל הַמְקַטְרְגִים לַעֲמֹד לִפְנֵי הַקְּטֹרֶת, וְעַל זֶה הִיא סוֹד (חדות) הַכֹּל וְקִשּׁוּר הַכֹּל.</p>\n<p>וּבִשְׁעַת הַמִּנְחָה, כְּשֶׁהַדִּין שָׁרוּי בָּעוֹלָם, הִתְכַּוֵּן דָּוִד בְּאוֹתָהּ תְּפִלָּה, שֶׁכָּתוּב תִּכּוֹן תְּפִלָּתִי קְטֹרֶת לְפָנֶיךְ וְגוֹ'. וּתְפִלָּה זוֹ שֶׁעוֹלָה תַּעֲבִיר רֹגֶז דִּין הַקָּשֶׁה שֶׁשּׁוֹלֵט כָּעֵת בַּזְּמַן הַזֶּה בְּאוֹתָהּ קְטֹרֶת, שֶׁדּוֹחָה וּמַעֲבִירָה מִלְּפָנָיו כָּל רֹגֶז (שעולה כעת בשעה זו באותה קטרת שמעבירה כל רגז) וְכָל קִטְרוּג שֶׁבָּעוֹלָם, (הינו מה שכתוב) (מה הטעם? משום שהיא) מִנְחַת עָרֶב, כְּשֶׁהַדִּין תָּלוּי בָּעוֹלָם.</p>\n<p>בֹּא רְאֵה, כְּשֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, בְּשָׁעָה שֶׁנִּשְׂרַף, הָיָה זְמַן מִנְחָה, וְעַל זֶה כָּתוּב (ירמיה ו) אוֹי לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. מַה זֶּה צִלְלֵי עָרֶב? אוֹתָם מְקַטְרְגִים שֶׁל הָעוֹלָם וְרָגְזֵי הַדִּינִים שֶׁמְּזֻמָּנִים בְּאוֹתָהּ הַשָּׁעָה. וְעַל זֶה שָׁנִינוּ שֶׁצָּרִיךְ אָדָם לְכַוֵּן דַּעְתּוֹ בִּתְפִלַּת הַמִּנְחָה. בְּכָל הַתְּפִלּוֹת צָרִיךְ הָאָדָם לְכַוֵּן דַּעְתּוֹ, וּבִתְפִלָּה זוֹ יוֹתֵר מִכֻּלָּן, מִשּׁוּם שֶׁהַדִּין שָׁרוּי בָּעוֹלָם, וְעַל זֶה זְמַן תְּפִלַּת הַמִּנְחָה יִצְחָק תִּקֵּן אוֹתָהּ, וַהֲרֵי פֵּרְשׁוּהָ.</p>"],[9522011464,"<p>עֵד שֶׁהָיוּ הוֹלְכִים, עָלוּ בְּהַר אֶחָד. אָמַר רַבִּי יוֹסֵי, הָהָר הַזֶּה מַפְחִיד, נֵלֵךְ וְלֹא נִתְעַכֵּב כָּאן, מִשּׁוּם שֶׁזֶּהוּ הַר מַפְחִיד. אָמַר רַבִּי יְהוּדָה, אִם הָיָה אֶחָד - הָיִיתִי אוֹמֵר כָּךְ, שֶׁהֲרֵי שָׁנִינוּ שֶׁמִּי שֶׁהוֹלֵךְ יְחִידִי בַּדֶּרֶךְ מִתְחַיֵּב בְּנַפְשׁוֹ, אֲבָל שְׁלֹשָׁה לֹא, וְכָל אֶחָד וְאֶחָד מֵעִמָּנוּ, נִרְאֶה שֶׁלֹּא תָזוּז מֵעִמָּנוּ הַשְּׁכִינָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, הֲרֵי שָׁנִינוּ שֶׁלֹּא יִסְמֹךְ אָדָם עַל נֵס, מִנַּיִן לָנוּ? מִשְּׁמוּאֵל, שֶׁכָּתוּב אֵיךְ אֵלֵךְ וְשָׁמַע שָׁאוּל וַהֲרָגָנִי, וַהֲרֵי שְׁמוּאֵל רָאוּי יוֹתֵר מֵאִתָּנוּ. אָמַר לוֹ, אֲפִלּוּ כָּךְ, הוּא הָיָה אֶחָד, וְהֶזֵּק נִמְצָא לָעַיִן, אֲבָל אָנוּ שְׁלֹשָׁה, וְהֶזֵּק לֹא נִמְצָא לָעַיִן. שֶׁאִם מִשּׁוּם מַזִּיקִים - הֲרֵי שָׁנִינוּ שֶׁלִּשְׁלֹשָׁה לֹא נִרְאִים וְלֹא מַזִּיקִים, וְאִם מִשּׁוּם לִסְטִים - לֹא נִמְצָאִים כָּאן, שֶׁהֲרֵי הָהָר הַזֶּה רָחוֹק מִיִּשּׁוּב, וּבְנֵי אָדָם לֹא נִמְצָאִים כָּאן, בְּרַם פַּחַד הוּא, שֶׁחַיּוֹת הַשָּׂדֶה שֶׁנִּמְצָאוֹת כָּאן.</p>\n<p>פָּתַח וְאָמַר, הַמַּלְאָךְ הַגֹּאֵל אֹתִי מִכָּל רָע. בְּפָסוּק זֶה יֵשׁ לְהִתְבּוֹנֵן בּוֹ, (שהרי כתוב) הַגֹּאֵל!? אֲשֶׁר גָּאַל צָרִיךְ הָיָה לִכְתֹּב! מַה זֶּה הַגֹּאֵל? מִשּׁוּם שֶׁהוּא תָמִיד נִמְצָא אֵצֶל בְּנֵי אָדָם, וְלֹא זָז מֵאָדָם צַדִּיק לְעוֹלָמִים. בֹּא רְאֵה, הַמַּלְאָךְ הַגֹּאֵל אֹתִי - זוֹ הַשְּׁכִינָה שֶׁהוֹלֶכֶת עִם בֶּן הָאָדָם תָּמִיד, וְלֹא זָזָה מִמֶּנּוּ כְּשֶׁבֶּן הָאָדָם שׁוֹמֵר מִצְווֹת הַתּוֹרָה. וְעַל זֶה יִזָּהֵר בֶּן אָדָם שֶׁלֹּא יֵצֵא יְחִידִי בַּדֶּרֶךְ. מַה זֶּה יְחִידִי? שֶׁיִּזָּהֵר בֶּן אָדָם לִשְׁמֹר מִצְווֹת הַתּוֹרָה כְּדֵי שֶׁלֹּא תָזוּז מִמֶּנּוּ שְׁכִינָה, וְיִצְטָרֵךְ לָלֶכֶת יְחִידִי בְּלִי זִוּוּג הַשְּׁכִינָה.</p>\n<p>בֹּא רְאֵה, כְּשֶׁיּוֹצֵא בֶּן אָדָם לַדֶּרֶךְ, יְסַדֵּר תְּפִלָּה לִפְנֵי רִבּוֹנוֹ כְּדֵי לְהַמְשִׁיךְ עָלָיו שְׁכִינָה, וְאַחַר כָּךְ יֵצֵא לַדֶּרֶךְ, וְיִמְצָא זִוּוּג הַשְּׁכִינָה לִגְאֹל אוֹתוֹ בַּדֶּרֶךְ וּלְהַצִּילוֹ בְּכָל מַה שֶּׁיִּצְטָרֵךְ.</p>\n<p>מַה כָּתוּב בְּיַעֲקֹב? (בראשית כח) אִם יִהְיֶה אֱלֹהִים עִמָּדִי, זֶה זִוּוּג הַשְּׁכִינָה. וּשְׁמָרַנִי בַּדֶּרֶךְ הַזֶּה, לִפְדּוֹת אוֹתִי מֵהַכֹּל. וְיַעֲקֹב הָיָה יְחִידִי בְּאוֹתוֹ זְמַן, וּשְׁכִינָה הוֹלֶכֶת לְפָנָיו, כָּל שֶׁכֵּן הַחֲבֵרִים שֶׁיֵּשׁ בֵּינֵיהֶם דִּבְרֵי תוֹרָה עַל אַחַת כַּמָּה וְכַמָּה. (אמר רבי יוסי, ודאי כך הוא, בינתים חשך השמש להעריב,)</p>\n<p>אָמַר רַבִּי יוֹסֵי, מַה נַּעֲשֶׂה? אִם נִתְעַכֵּב כָּאן, הֲרֵי הַיּוֹם נִכְנָס לְהַחֲשִׁיךְ. אִם נֵלֵךְ לְמַעְלָה, הָהָר הוּא גָדוֹל, וּמִפַּחַד חַיּוֹת הַשָּׂדֶה אָנוּ פוֹחֲדִים. אָמַר רַבִּי יְהוּדָה, תְּמֵהַנִי עָלֶיךְ רַבִּי יוֹסֵי. אָמַר לוֹ, הֲרֵי שָׁנִינוּ שֶׁלֹּא יִסְמֹךְ בֶּן אָדָם עַל הַנֵּס, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא יַרְחִישׁ לוֹ נֵס בְּכָל שָׁעָה. אָמַר לוֹ, זֶה מְדֻבָּר בִּיחִידִי, אֲבָל אֲנַחְנוּ שְׁלֹשָׁה, וּבֵינֵינוּ דִּבְרֵי תוֹרָה וְהַשְּׁכִינָה עִמָּנוּ, לֹא נִפְחַד.</p>"],[9522011465,"<p>עַד שֶׁהָיוּ הוֹלְכִים רָאוּ לְמַעְלָה בָּהָר סֶלַע אֶחָד וּמְעָרָה בְּתוֹכוֹ. אָמַר רַבִּי יְהוּדָה, נֵלֵךְ וְנַעֲלֶה לְאוֹתוֹ הַסֶּלַע, שֶׁאָנוּ רוֹאִים מְעָרָה אַחַת שָׁם. עָלוּ לְשָׁם וְרָאוּ אוֹתָהּ הַמְּעָרָה. אָמַר רַבִּי יוֹסֵי, פָּחַדְתִּי אוּלַי אוֹתָהּ מְעָרָה מָקוֹם שֶׁל חַיּוֹת הִיא וְלֹא יִפְגְּעוּ בָנוּ כָּאן.</p>\n<p>אָמַר רַבִּי יְהוּדָה לְרַבִּי חִזְקִיָּה, הֲרֵי רָאִיתִי שֶׁרַבִּי יוֹסֵי פּוֹחֵד. אִם תֹּאמַר מִשּׁוּם שֶׁהוּא חוֹטֵא, שֶׁכָּל מִי שֶׁפּוֹחֵד הוּא חוֹטֵא, שֶׁכָּתוּב (ישעיה לג) פָּחֲדוּ בְצִיּוֹן חַטָּאִים, הֲרֵי אֵינוֹ חוֹטֵא, (והרי) וְכָתוּב (משלי כח) וְצַדִּיקִים כִּכְפִיר יִבְטָח. אָמַר רַבִּי יוֹסֵי, מִשּׁוּם שֶׁהַנֶּזֶק מָצוּי.</p>\n<p>אָמַר לוֹ, אִם הַנֶּזֶק מָצוּי - כָּךְ הוּא, אֲבָל כָּאן לֹא נִמְצָא נֶזֶק, וְאַחַר שֶׁאָנוּ נִכָּנֵס לַמְּעָרָה, לֹא יִכָּנֵס הַנֶּזֶק לְצַעֵר אוֹתָנוּ. נִכְנְסוּ לַמְּעָרָה. אָמַר רַבִּי יְהוּדָה, נְחַלֵּק אֶת הַלַּיְלָה לְשָׁלֹשׁ מִשְׁמָרוֹת, שֶׁהוּא הַלַּיְלָה. כָּל אֶחָד וְאֶחָד מֵעִמָּנוּ יַעֲמֹד עַל עָמְדּוֹ בִּשְׁלֹשֶׁת הַצְּדָדִים הַלָּלוּ שֶׁל הַלַּיְלָה וְלֹא נִישַׁן.</p>\n<p>פָּתַח רַבִּי יְהוּדָה וְאָמַר, (תהלים פט) מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי. הַתִּשְׁבַּחַת הַזּוֹ אַבְרָהָם אָמַר אוֹתָהּ בְּשָׁעָה שֶׁעָסַק בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעָשָׂה חֶסֶד עִם בְּנֵי הָעוֹלָם שֶׁיִּוָּדְעוּ כֻלָּם לַקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט עַל הָעוֹלָם, וְנִקְרָא אֵיתָן מִשּׁוּם שֶׁהִתְחַזֵּק בְּתֹקֶף בַּקָּדוֹשׁ-בָּרוּךְ-הוּא.</p>\n<p>חַסְדֵי ה' לְעוֹלָם אָשִׁירָה, וְכִי מִצַּד הַחֲסָדִים בָּאִים לְזַמֵּר? אֶלָּא כָּאן נִכְלַל צַד הַשְּׂמֹאל בַּיָּמִין, וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא נִסָּה אֶת אַבְרָהָם וּבָחַן אוֹתוֹ. וַהֲרֵי נִתְבָּאֵר שֶׁיִּצְחָק בֶּן שְׁלֹשִׁים וְשֶׁבַע שָׁנִים הָיָה בְּאוֹתוֹ הַזְּמַן, מַה זֶּה נִסָּה אֶת אַבְרָהָם? הָיָה צָרִיךְ לִכְתֹּב נִסָּה אֶת יִצְחָק! אֶלָּא נִסָּה אֶת אַבְרָהָם שֶׁיִּמָּצֵא בַדִּין וּלְהִכָּלֵל בַּדִּין שֶׁיִּמָּצֵא שָׁלֵם כָּרָאוּי, וְעַל זֶה חַסְדֵי ה' עוֹלָם אָשִׁירָה.</p>\n<p>דָּבָר אַחֵר חַסְדֵי ה' עוֹלָם אָשִׁירָה - אוֹתָם חֲסָדִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה עִם הָעוֹלָם. לְדֹר וָדֹר אוֹדִיעַ אֱמוּנָתְךְ בְּפִי - טוֹב וֶאֱמֶת שֶׁעוֹשֶׂה עִם הַכֹּל. לְדר וָדר אוֹדִיעַ אֱמוּנָתְךְ - זוֹ אֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוֹדִיעַ אַבְרָהָם בָּעוֹלָם וְהִזְכִּירוֹ בְּפִי כָּל הַבְּרִיּוֹת, וְעַל זֶה אוֹדִיעַ אֱמוּנָתְךְ בְּפִי.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא הוֹדִיעַ לְאַבְרָהָם סוֹד הָאֱמוּנָה, וּכְשֶׁיָּדַע סוֹד הָאֱמוּנָה, יָדַע שֶׁהוּא עִקַּר וְקִיּוּם הָעוֹלָם, שֶׁבִּגְלָלוֹ נִבְרָא הָעוֹלָם וְהִתְקַיֵּם. זֶהוּ שֶׁכָּתוּב כִּי אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה וְגוֹ'. כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, רָאָה שֶׁלֹּא יָכוֹל לַעֲמֹד, עַד שֶׁהוֹשִׁיט יָמִין עָלָיו וְהִתְקַיֵּם, וְאִם לֹא שֶׁהוֹשִׁיט יָמִין עָלָיו, לֹא הָיָה מִתְקַיֵּם, מִשּׁוּם שֶׁהָעוֹלָם הַזֶּה נִבְרָא בְדִין, וְכָךְ בֵּאַרְנוּ.</p>\n<p>וְנֶאֱמַר בְּרֵאשִׁית, וְסוֹד כְּלָל אֶחָד, שְׁנֵי גְוָנִים כָּאן, בְּרֵאשִׁית. אַף עַל גַּב שֶׁאָמַרְנוּ רֵאשִׁית מִלְּמַטָּה לְמַעְלָה, רֵאשִׁית כָּךְ גַּם מִלְּמַעְלָה לְמַטָּה, וְאָמַרְנוּ ב' רֵאשִׁית, כְּמוֹ שֶׁאָמַרְנוּ בֵּית קֹדֶשׁ הַקְּדָשִׁים, שֶׁהֲרֵי נִתְּנָה (היא בית) לְאוֹתָהּ רֵאשִׁית, וְהַדָּבָר כָּלוּל הוּא כְּאֶחָד.</p>\n<p>וּבַבֵּי\"ת הַזּוֹ נִבְרָא הָעוֹלָם הַזֶּה וְלֹא הִתְקַיֵּם אֶלָּא בְּיָמִין, וַהֲרֵי פֵּרְשׁוּהָ בְּהִבָּרְאָם - כָּתוּב בְּאַבְרָהָם, וּמִשּׁוּם כָּךְ, אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה. וּבִנְיָן הָרִאשׁוֹן שֶׁל הָעוֹלָם (אותו העולם), אוֹתוֹ הָאוֹר שֶׁל הַיּוֹם הָרִאשׁוֹן הָיָה בּוֹ לְקַיֵּם, וְאַחַר כָּךְ בַּיּוֹם הַשֵּׁנִי בִּשְׂמֹאל. וּבְאֵלֶּה תִּקֵּן שָׁמַיִם, וְכָתוּב שָׁמַיִם תָּכִין אֱמוּנָתְךְ בָּהֶם.</p>\n<p>דָּבָר אַחֵר שָׁמַיִם תָּכִין אֱמוּנָתְךְ בָּהֶם - שָׁמַיִם נִתְקְנוּ בְּאוֹתָם חֲסָדִים, וְסוֹד הָאֱמוּנָה הִתְקִינָה בָהֶם, שֶׁאֵין תִּקּוּנֶיהָ אֶלָּא מִתּוֹךְ שָׁמַיִם. כָּרַתִּי בְּרִית לִבְחִירִי - זֶהוּ סוֹד הָאֱמוּנָה.</p>\n<p>דָּבָר אַחֵר, זֶהוּ צַדִּיק שֶׁמִּמֶּנּוּ יוֹצְאוֹת בְּרָכוֹת לְכָל הַתַּחְתּוֹנִים, וְכָל (אותן) הַחַיּוֹת הַקְּדוֹשׁוֹת, כֻּלָּן מִתְבָּרְכוֹת מֵאוֹתוֹ הַשֶּׁפַע שֶׁשּׁוֹפֵעַ לַתַּחְתּוֹנִים, וְלָכֵן כָּתוּב כָּרַתִּי בְּרִית לִבְחִירִי.</p>\n<p>נִשְׁבַּעִִתִּי לְדָוִד עַבְדִּי - זֶה סוֹד הָאֱמוּנָה שֶׁהוּא עוֹמֵד תָּמִיד בַּצַּדִּיק הַזֶּה, קִיּוּם הָעוֹלָם, שֶׁלֹּא יִתְפַּזְּרוּ לְעוֹלָמִים חוּץ מִזְּמַן הַגָּלוּת שֶׁנִּמְנָע שֶׁפַע הַבְּרָכוֹת, וְסוֹד הָאֱמוּנָה לֹא הֻשְׁלַם, וְכָל הַחֶדְווֹת נִמְנְעוּ. וּכְשֶׁנִּכְנָס הַלַּיְלָה, מֵאוֹתוֹ הַזְּמַן הַחֶדְווֹת לֹא נִכְנְסוּ לִפְנֵי הַמֶּלֶךְ.</p>\n<p>וְאַף עַל גַּב שֶׁהַחֶדְווֹת לֹא הִתְעוֹרְרוּ, אֲבָל בַּחוּץ עוֹמְדִים וּמְזַמְּרִים שִׁירָה, וּכְשֶׁנֶּחֱלָק הַלַּיְלָה וְהִתְעוֹרְרוּת עוֹלָה מִלְּמַטָּה לְמַעְלָה, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא מְעוֹרֵר כָּל חֵילוֹת הַשָּׁמַיִם לִבְכִיָּה, וּבוֹעֵט בָּרָקִיעַ, וּמִזִדַּעְזְעִים עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>וְאֵיןֹ מְנוּחָה לְפָנָיו, פְּרָט לַזְּמַן שֶׁמִּתְעוֹרְרִים לְמַטָּה בַּתּוֹרָה, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים (שעמו), כֻּלָּם מַקְשִׁיבִים וּשְׂמֵחִים לְאוֹתוֹ קוֹל, וְאָז מְנוּחָה. (לפניו, ובאה מנוחה לכל נשמות הצדיקים שעמו) (לפניו נמצאת). מִשּׁוּם שֶׁמִּיּוֹם שֶׁנֶּחֱרַב הַמִּקְדָּשׁ לְמַטָּה, נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יִכָּנֵס לְתוֹךְ יְרוּשָׁלַיִם שֶׁל מַעְלָה עַד שֶׁיִּכָּנְסוּ יִשְׂרָאֵל לִירוּשָׁלַיִם שֶׁל מַטָּה, שֶׁכָּתוּב (הושע יא) בְּקִרְבְּךְ קָדוֹשׁ וְלֹא אָבוֹא בְּעִיר, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים.</p>\n<p>וְכָל אוֹתָם מְזַמְּרִים עוֹמְדִים בַּחוּץ וְאוֹמְרִים שִׁירָה בִּשְׁלֹשֶׁת חֶלְקֵי הַלַּיְלָה, וְכֻלָּם מְשַׁבְּחִים בְּתִשְׁבָּחוֹת יְדוּעוֹת, וְכָל חֵילוֹת הַשָּׁמַיִם, כֻּלָּם מִתְעוֹרְרִים בַּלַּיְלָה, וְיִשְׂרָאֵל בַּיּוֹם, וּקְדֻשָּׁה לֹא מְקַדְּשִׁים לְמַעְלָה עַד שֶׁיִּשְׂרָאֵל מְקַדְּשִׁים לְמַטָּה, וְאָז כָּל חֵילוֹת הַשָּׁמַיִם מְקַדְּשִׁים אֶת הַשֵּׁם הַקָּדוֹשׁ כְּאֶחָד. וְעַל זֶה יִשְׂרָאֵל קְדוֹשִׁים מִתְקַדְּשִׁים מֵעֶלְיוֹנִים וְתַחְתּוֹנִים (משום שהקדשה של שמו של הקדוש ברוך הוא לא עולה אלא מלמעלה ומלמטה) כְּאֶחָד. זֶהוּ שֶׁכָּתוּב (ויקרא יט) קדשים תהיו כי קדוש אני ה' אלהיכם.</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (איוב לח) עַל מָה אֲדָנֶיהָ הָטְבָּעוּ. פָּסוּק זֶה אָמַר אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁכְּשֶׁבָּרָא אֶת הָעוֹלָם, לֹא בָרָא אוֹתוֹ אֶלָּא עַל עַמּוּדִים, שֶׁהֵם שִׁבְעַת עַמּוּדֵי הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (משלי ט) חָצְבָה עַמּוּדֶיהָ שִׁבְעָה, וְאוֹתָם עַמּוּדִים לֹא נוֹדָע עַל מָה עוֹמְדִים.</p>\n<p>מִשּׁוּם שֶׁהוּא סוֹד עָמֹק, נִסְתַּר כָּל הַנִּסְתָּרִים, וְהָעוֹלָם לֹא נִבְרָא עַד שֶׁנָּטַל אֶבֶן אַחַת, וְהִיא אֶבֶן שֶׁנִּקְרֵאת אֶבֶן שְׁתִיָּה, וְלָקַח אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא וְזָרַק אוֹתָהּ לְתוֹךְ הַתְּהוֹם, וְנִנְעֲצָה מִלְמַעְלָה לְמַטָּה, וּמִמֶּנָּה נִשְׁתַּל הָעוֹלָם, וְהִיא נְקֻדָּה בְּאֶמְצַע הָעוֹלָם, וּבִנְקֻדָּה זוֹ עוֹמֵד קֹדֶשׁ הַקְּדָשִׁים. זֶהוּ שֶׁכָּתוּב (איוב לח) אוֹ מִי יָרָה אֶבֶן פִּנָּתָהּ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כח) אֶבֶן בּחַן פִּנַּת יִקְרַת, וְכָתוּב (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה.</p>\n<p>בֹּא רְאֵה, אֶבֶן זוֹ נִכְרְתָה מֵאֵשׁ וּמֵרוּחַ וּמִמַּיִם, וְנִגְלְדָה מִכֻּלָּם, וְנֶעֶשְׂתָה אֶבֶן אַחַת, וְעוֹמֶדֶת עַל הַתְּהוֹמוֹת, וְלִפְעָמִים נוֹבְעִים מִמֶּנּוּ מַיִם וּמִתְמַלְּאִים הַתְּהוֹמוֹת, וְאֶבֶן זוֹ עוֹמֶדֶת לְאוֹת בְּאֶמְצַע הָעוֹלָם, וְזוֹהִי אֶבֶן שֶׁהֶעֱמִיד וְהִשְׁתִּיל יַעֲקֹב שְׁתִילַת וְקִיּוּם הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (בראשית לא) וַיִּקַּח יַעֲקֹב אָבֶן וַיְרִימֶהָ מַצֵּבָה.</p>\n<p>וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה וְגוֹ'. וְכִי אֶבֶן זאת שָׂם לוֹ יַעֲקֹב, וַהֲרֵי אֶבֶן הַ את נִבְרְאָה בַּתְּחִלָּה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם? אֶלָּא שֶׁשָּׂם אוֹתָהּ (וכי כעת שם אותה יעקב? והרי עד שלא נברא העולם היתה, אלא שיעקב שם אותה) קִיּוּם שֶׁלְּמַעְלָה וּלְמַטָּה, וְעַל זֶה אֲשֶׁר שַׂמְתִּי מַצֵּבָה כָּתוּב. מַה זֶּה אֲשֶׁר שַׂמְתִּי? שֶׁכָּתוּב יִהְיֶה בֵּית אֱלֹהִים, שֶׁשָּׂם מָדוֹר שֶׁלְּמַעְלָה כָּאן.</p>\n<p>בֹּא רְאֵה, עַל אֶבֶן זוֹ יֵשׁ שִׁבְעָה עֵינַיִם, כְּמוֹ שֶׁנֶּאֱמַר (זכריה ג) עַל אֶבֶן אַחַת שִׁבְעָה עֵינָיִם. עַל מַה נִּקְרֵאת שְׁתִיָּה? אֶחָד - שֶׁמִּמֶּנָּה הֻשְׁתַּל הָעוֹלָם, וְאֶחָד שְׁתִיָּה - שָׁת יָהּ, שֶׁשָּׂם אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְבָּרֵךְ מִמֶּנָּה הָעוֹלָם, בִּשְׁבִיל שֶׁמִּמֶּנָּה מִתְבָּרֵךְ הָעוֹלָם.</p>\n<p>וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁנִּכְנָס הַשֶּׁמֶשׁ, הַכְּרוּבִים הַלָּלוּ שֶׁעוֹמְדִים בַּמָּקוֹם הַזֶּה וְהָיוּ יוֹשְׁבִים בָּאוֹת, הָיוּ מַקִּישִׁים כַּנְפֵיהֶם לְמַעְלָה וּפוֹרְשִׂים אוֹתָם, וְנִשְׁמָע קוֹל נִגּוּן הַכְּנָפַיִם לְמַעְלָה, וְאָז מַתְחִילִים לְנַגֵּן אוֹתָם הַמַּלְאָכִים שֶׁאוֹמְרִים שִׁירָה בְּרֵאשִׁית הַלַּיְלָה, בִּשְׁבִיל שֶׁיַּעֲלֶה כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְּמַטָּה לְמַעְלָה. וְאֵיזוֹ שִׁירָה הָיוּ אוֹמְרִים? אוֹתוֹ נִגּוּן כַּנְפֵי הַכְּרוּבִים, (תהלים קלד) הִנֵּה בָּרְכוּ אֶת ה' כָּל עַבְדֵי ה' וְגוֹ', שְׂאוּ יְדֵיכֶם קֹדֶשׁ וְגוֹ', וְאָז (הם) הִיא שִׁירָה לְאוֹתָם מַלְאָכִים עֶלְיוֹנִים לְזַמֵּר.</p>\n<p>בַּמִּשְׁמֶרֶת הַשְּׁנִיָּה הַכְּרוּבִים הַלָּלוּ מַקִּישִׁים כַּנְפֵיהֶם לְמַעְלָה, וְנִשְׁמָע קוֹל נִגּוּנָם, וְאָז מַתְחִילִים לְנַגֵּן אוֹתָם הַמַּלְאָכִים שֶׁעוֹמְדִים בַּמִּשְׁמֶרֶת הַשְּׁנִיָּה. וְאֵיזוֹ שִׁירָה הָיוּ אוֹמְרִים בַּשָּׁעָה הַזּוֹ? נִגּוּן כַּנְפֵי הַכְּרוּבִים, (תהלים קכה) הַבּטְחִים בַּה' כְּהַר צִיּוֹן לֹא יִמּוֹט וְגוֹ'. וְאָז (אותה) הִיא (שירה) תְּחִלָּה לְאוֹתָם הָעוֹמְדִים בַּמִּשְּׁמֶרֶת הַשְּׁנִיָּה הַזּוֹ לְנַגֵּן.</p>\n<p>בַּמִּשְׁמֶרֶת הַשְּׁלִישִׁית הַכְּרוּבִים הַלָּלוּ מַקִּישִׁים בְּכַנְפֵיהֶם וְאוֹמְרִים שִׁירָה, וּמַה הִיא? (שם קיג) הַלְלוּיָהּ הַלְלוּ עַבְדֵי ה' וְגוֹ', יְהִי שֵׁם ה' מְבֹרָךְ וְגוֹ', מִמִּזְרַח שֶׁמֶשׁ וְגוֹ'. אָז אוֹתָם מַלְאָכִים שֶׁעוֹמְדִים בַּמִּשְׁמֶרֶת הַשְּׁלִישִׁית, כֻּלָּם אוֹמְרִים שִׁירָה.</p>\n<p>וְכָל הַכּוֹכָבִים וּמַזְּלוֹת הָרָקִיעַ פּוֹתְחִים בְּשִׁירָה, כְּמוֹ שֶׁכָּתוּב (איוב לח) ברן יחד כוכבי בקר ויריעו כל בני אלהים, וכתוב (תהלים קמח) הללוהו כל כוכבי אור, שהרי אותם כוכבי האור מנגנים על אור. (שממנים על השירה,)</p>\n<p>כְּשֶׁמַּגִּיעַ הַבֹּקֶר, וְאָז לוֹקְחִים שִׁירָה אַחֲרֵי יִשְׂרָאֵל לְמַטָּה, וְעוֹלֶה כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְּמַטָּה וּמִלְמַעְלָה. יִשְׂרָאֵל לְמַטָּה בַּיּוֹם, וּמַלְאָכִים עֶלְיוֹנִים לְמַעְלָה בַּלַּיְלָה, וְאָז נִשְׁתַּלֵּם הַשֵּׁם הַקָּדוֹשׁ בְּכָל הַצְּדָדִים.</p>\n<p>וְהָאֶבֶן הַזֹּאת שֶׁאָמַר, כָּל הַמַּלְאָכִים הָעֶלְיוֹנִים וְיִשְׂרָאֵל לְמַטָּה, כֻּלָּם מַחֲזִיקִים בָּאֶבֶן הַזֹּאת, וְהִיא עוֹלָה לְמַעְלָה לְהִתְעַטֵּר בְּתוֹךְ הָאָבוֹת בַּיּוֹם, וּבַלַּיְלָה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן.</p>\n<p>אַשְׁרֵיהֶם כָּל הָעוֹמְדִים בְּקִיּוּמָם וְעוֹסְקִים בַּתּוֹרָה בַּלַּיְלָה, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל אוֹתָם הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן שׁוֹמְעִים קוֹלוֹת בְּנֵי הָאָדָם אוֹתָם הָעוֹסְקִים בַּתּוֹרָה, כְּמוֹ שֶׁכָּתוּב (שיר ח) הַיּוֹשֶׁבֶת בַּגַּנִּים וְגוֹ'.</p>\n<p>בֹּא רְאֵה, אֶבֶן זוֹ הִיא אֶבֶן טוֹבָה, וְזֶהוּ סוֹד הַכָּתוּב (שמות כח) וּמִלֵּאתָ בוֹ מִלֻּאַת אֶבֶן אַרְבָּעָה טוּרִים אָבֶן. וְאֵלֶּה הֵם סְדָרִים (של שלמות) שֶׁל הָאֶבֶן הַטּוֹבָה, הַשְּׁלֵמוּת שֶׁל אֶבֶן יְקָרָה, מִשּׁוּם שֶׁיֵּשׁ (שלמות) אֶבֶן אַחֶרֶת, שֶׁכָּתוּב (יחזקאל לו) וַהֲסִרֹתִי אֶת לֵב הָאֶבֶן וְגוֹ', וְכָתוּב (שם) וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם. וְזֶהוּ (ישעיה כח) אֶבֶן בֹּחַן פִּנַּת יִקְרַת, וּבֵאֲרוּהָ.</p>\n<p>וְעַל סוֹד זֶה כָּתוּב (שמות כד) לֻחֹת הָאֶבֶן, שֶׁהֵם לוּחוֹת שֶׁנִּגְזְרוּ מִכָּאן, וְלָכֵן נִקְרְאוּ עַל שְׁמָהּ שֶׁל הָאֶבֶן הַ את, וְזֶהוּ סוֹד הַכָּתוּב (בראשית מט) מִשָּׁם רֹעֶה אֶבֶן יִשְׂרָאֵל, (הרי ודאי אבן ישראל נקראת) כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>פָּתַח רַבִּי חִזְקִיָּה וְאָמַר, (שמות כח) וְהָאֲבָנִים תִּהְיֶיןָ עַל שְׁמוֹת בְּנֵי יִשְׂרָאֵל שְׁתֵּים עֶשְׂרֵה - אֵלּוּ אֲבָנִים יְקָרוֹת עֶלְיוֹנוֹת שֶׁנִּקְרָאוֹת אַבְנֵי הַמָּקוֹם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כח) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם, וַהֲרֵי פֵּרְשׁוּהָ. וְהָאֲבָנִים עַל שְׁמוֹת בְּנֵי יִשְׂרָאֵל, כְּמוֹ שֶׁיֵּשׁ שְׁנֵים עָשָׂר שְׁבָטִים לְמַטָּה, כָּךְ גַּם לְמַעְלָה שְׁנֵים עָשָׂר שְׁבָטִים, וְהֵם שְׁתֵּים עֶשְׂרֵה אֲבָנִים יְקָרוֹת, וְכָתוּב (תהלים קכב) שֶׁשָּׁם עָלוּ שְׁבָטִים וְגוֹ'. עֵדוּת לְיִשְׂרָאֵל - זֶה יִשְׂרָאֵל, סוֹד שֶׁלְּמַעְלָה, וְכֻלָּם לְהוֹדוֹת לְשֵׁם ה', וְעַל זֶה וְהָאֲבָנִים תִּהְיֶין!! עַל שְׁמוֹת בְּנֵי יִשְׂרָאֵל.</p>\n<p>וּכְמוֹ שֶׁיֵּשׁ שְׁתֵּים עֶשְׂרֵה שָׁעוֹת בַּיּוֹם, כָּךְ יֵשׁ שְׁתֵּים עֶשְׂרֵה שָׁעוֹת בַּלַּיְלָה. בַּיּוֹם לְמַעְלָה, וּבַלַּיְלָה לְמַטָּה. הַכֹּל זֶה כְּנֶגֶד זֶה. הַשְּׁתֵּים עֶשְׂרֵה שָׁעוֹת שֶׁל הַלַּיְלָה הַלָּלוּ מִתְחַלְּקוֹת לִשְׁלֹשָׁה חֲלָקִים, וְכַמָּה מְמֻנֵּי מָגִנִּים עוֹמְדִים תַּחְתֵּיהֶם דְּרָגוֹת עַל דְּרָגוֹת, כֻּלָּם מְמֻנִּים בַּלַּיְלָה, וְנוֹטְלִים טֶרֶף בַּהַתְחָלָה.</p>\n<p>וְאָז כְּשֶׁנֶּחֱלָק הַלַּיְלָה, עוֹמְדִים שְׁנֵי (סתרים) סְדָרִים מִצַּד זֶה וּשְׁנֵי סְדָרִים מִצַּד אַחֵר, (וזו) וְרוּחַ עֶלְיוֹנָה יוֹצֵאת (נושבת) בֵּינֵיהֶם, וְאָז כָּל אוֹתָם הָאִילָנוֹת שֶׁבְּגַן עֵדֶן, כֻּלָּם פּוֹתְחִים בְּשִׁירָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס בְּגַן עֵדֶן. זֶהוּ שֶׁכָּתוּב אָז יְרַנְּנוּ עֲצֵי הַיָּעַר מִלִּפְנֵי ה' כִּי בָא לִשְׁפֹּט אֶת הָאָרֶץ, כְּמוֹ שֶׁכָּתוּב (ישעיה יא) וְשָׁפַט בְּצֶדֶק דַּלִּים. מִשּׁוּם שֶׁמִּשְׁפָּט נִכְנָס בֵּינֵיהֶם וּמִתְמַלֵּא מִמֶּנָּה (ממנו) גַּן עֵדֶן.</p>\n<p>וְרוּחַ צָפוֹן מִתְעוֹרֶרֶת בָּעוֹלָם, וְחֶדְוָה נִמְצֵאת, וְנוֹשֶׁבֶת אוֹתָהּ הָרוּחַ בְּאוֹתָם בְּשָׂמִים, וְעוֹלִים רֵיחוֹת לְמַעְלָה, וּמִתְעַטְּרִים (ומתעוררים) הַצַּדִּיקִים בְּעַטְרוֹתֵיהֶם וְנֶהֱנִים מִתּוֹךְ זִיו הָאַסְפַּקְלַרְיָה הַמְּאִירָה.</p>\n<p>אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁזּוֹכִים לְאוֹתוֹ הָאוֹר הָעֶלְיוֹן, וְאוֹתוֹ הָאוֹר שֶׁל הָאַסְפַּקְלַרְיָה הַמְּאִירָה מֵאִיר לְכָל הַצְּדָדִים, וְכָל אֶחָד וְאֶחָד מֵהַצַּדִּיקִים הַלָּלוּ נוֹטֵל אֶת חֶלְקוֹ כָּרָאוּי לוֹ, וְהָיָה נוֹטֵל (וכך מאיר) כָּל אֶחָד וְאֶחָד כְּפִי מַעֲשָׂיו שֶׁעָשָׂה בָּעוֹלָם הַזֶּה. יֵשׁ מֵהֶם שֶׁמִּתְבַּיְּשִׁים מֵאוֹתוֹ אוֹר שֶׁנָּטַל חֲבֵרָם יוֹתֵר וּמֵאִיר, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>חֶלְקוֹ שֶׁל הַלַּיְלָה, מִכָּאן מַתְחִיל הַלַּיְלָה לְהִכָּנֵס. כַּמָּה שׁוֹמְרֵי הַחֹק מִתְעוֹרְרִים וּמְשׁוֹטְטִים בָּעוֹלָם וּפוֹתְחִים הַסְּגוּרִים, וְאַחַר כָּךְ כַּמָּה מִינִים לְמִינֵיהֶם, כְּמוֹ שֶׁבֵּאַרְנוּ. וְאָז, כְּשֶׁנֶּחֱלַק הַלַּיְלָה, צַד צָפוֹן יוֹרֵד (מאיר הארה) מִלְמַעְלָה לְמַטָּה, וְאוֹחֵז בַּלַּיְלָה עַד שְׁנֵי חֲלָקִים שֶׁל הַלַּיְלָה.</p>\n<p>אַחַר כָּךְ מִתְעוֹרֵר צַד דָּרוֹם, עַד שֶׁמַּגִּיעַ הַבֹּקֶר, וּכְשֶׁמַּגִּיעַ הַבֹּקֶר אָז הַדָּרוֹם וְהַצָּפוֹן אוֹחֲזִים בּוֹ, וְאָז בָּאִים יִשְׂרָאֵל לְמַטָּה, מַעֲלִים אוֹתָהּ בִּתְפִלּוֹתֵיהֶם וּבַקָּשׁוֹתֵיהֶם לְמַעְלָה, עַד שֶׁעוֹלָה וְנִגְנֶזֶת בֵּינֵיהֶם, וְנוֹטֶלֶת בְּרָכוֹת מֵהָרֹאשׁ (של המלך) שֶׁל כָּל הָרָאשִׁים.</p>\n<p>וּמִתְבָּרֶכֶת מֵאוֹתוֹ הַטַּל שֶׁנִּמְשָׁךְ מִלְמַעְלָה, וּמֵאוֹתוֹ הַטַּל נֶחֱלָק לְכַמָּה צְדָדִים, וְכַמָּה רְבָבוֹת נִזּוֹנִים מֵאוֹתוֹ הַטַּל, וּמִמֶּנּוּ עֲתִידִים לְהַחֲיוֹת הַמֵּתִים. זֶהוּ שֶׁכָּתוּב (ישעיה כז) הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר כִּי טַל אֹרוֹת טַלֶּךְ, טַל מֵאוֹתָם הָאוֹרוֹת הָעֶלְיוֹנִים שֶׁמְּאִירִים לְמַעְלָה.</p>"],[9522011466,"<p>עַד שֶׁהָיוּ יוֹשְׁבִים, נֶחֱלַק הַלַּיְלָה. אָמַר לוֹ רַבִּי יְהוּדָה לְרַבִּי יוֹסֵי, עַכְשָׁו רוּחַ צָפוֹן מִתְעוֹרֶרֶת וְהַלַּיְלָה נֶחֱלָק, וְכָעֵת הַזְּמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְאַוֶּה לְקוֹל הַצַּדִּיקִים שֶׁבָּעוֹלָם הַזֶּה, אוֹתָם שֶׁעוֹסְקִים בַּתּוֹרָה. כָּעֵת הַקָּדוֹשׁ בָּרוּךְ הוּא מַקְשִׁיב (לקול דבריהם) לָנוּ בַּמָּקוֹם הַזֶּה, לֹא נַפְסִיק בְּדִבְרֵי הַתּוֹרָה.</p>\n<p>פָּתַח וְאָמַר, הַמַּלְאָךְ הַגֹּאֵל אֹתִי מִכָּל רָע. הֲרֵי נִתְבָּאֵר וּפֵרְשׁוּהָ, אֲבָל בּא רְאֵה, כָּתוּב (שמות כג) הִנֵּה אָנֹכִי שּלֵחַ מַלְאָךְ וְגוֹ', זֶהוּ מַלְאָךְ גּוֹאֵל הָעוֹלָם, שְׁמִירָתָם שֶׁל בְּנֵי הָאָדָם, וְזֶהוּ שֶׁמַּזְמִין בְּרָכוֹת לְכָל הָעוֹלָם, מִשּׁוּם שֶׁהוּא נוֹטֵל אוֹתָם בַּהַתְחָלָה, וְאַחַר כָּךְ הוּא מְזַמֵּן אוֹתָם לָעוֹלָם, וְלָכֵן כָּתוּב הִנֵּה אָנֹכִי שּלֵחַ מַלְאָךְ לְפָנֶיךְ. (שם לו) וְשָׁלַחְתִּי לְפָנֶיךְ מַלְאָךְ.</p>\n<p>וְזְהִוּ מַלְאָךְ שֶׁלִּפְעָמִים זָכָר וְלִפְעָמִים נְקֵבָה, וְכָךְ הוּא, שֶׁבַּזְּמַן שֶׁהוּא מַזְמִין בְּרָכוֹת לָעוֹלָם (למעלה), אָז הוּא זָכָר וְנִקְרָא זָכָר. כַּזָּכָר שֶׁמַּזְמִין בְּרָכוֹת (למעלה) לַנְּקֵבָה, כָּךְ הוּא מַזְמִין בְּרָכוֹת לָעוֹלָם. וּבִזְמַן שֶׁעוֹמֵד בְּדִין עַל הָעוֹלָם, אָז נִקְרָא נְקֵבָה, כִּנְקֵבָה הַמְעֻבֶּרֶת, כָּךְ הוּא מִתְמַלֵּא מִן הַדִּין, וְאָז נִקְרָא נְקֵבָה. וְעַל זֶה לִפְעָמִים נִקְרָא זָכָר וְלִפְעָמִים נִקְרָא נְקֵבָה, וְהַכֹּל סוֹד אֶחָד.</p>"],[9522011467,"<p>כְּמוֹ זֶה כָּתוּב (בראשית ג) וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת. יֵשׁ מַלְאָכִים שְׁלוּחִים בָּעוֹלָם שֶׁמִּתְהַפְּכִים לְכַמָּה גְוָנִים, לִפְעָמִים נְקֵבוֹת לִפְעָמִים זְכָרִים, לִפְעָמִים דִּין לִפְעָמִים רַחֲמִים, וְהַכֹּל בְּגָוֶן אֶחָד. כְּמוֹ זֶה הַמַּלְאָךְ הַזֶּה הוּא בִּגְוָנִים רַבִּים, וְכָל הַגְּוָנִים שֶׁבָּעוֹלָם יֶשְׁנָם בַּמָּקוֹם הַזֶּה, וְסוֹד זֶה (יחזקאל א) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶעָנָן בְּיוֹם הַגֶּשֶׁם כֵּן מַרְאֵה הַנֹּגַהּ סָבִיב הוּא מַרְאֵה דְּמוּת כְּבוֹד ה'. וּכְמוֹ שֶׁיֵּשׁ בּוֹ כָּל אֵלּוּ הַגְּוָנִים, כָּךְ גַּם מַנְהִיג אֶת כָּל הָעוֹלָם.</p>\n<p>אֲהוּבִים עֶלְיוֹנִים, בַּעֲלֵי הַתְּבוּנָה, הִתְבּוֹנְנוּ. מוֹשְׁלִים הַיּוֹדְעִים בְּהַכָּאַת הַהַבָּטָה הִתְקָרְבוּ לָדַעַת, מִי מִכֶּם בַּעֲלֵי עֵינַיִם בַּתְּבוּנָה, וְיוֹדֵעַ בְּשָׁעָה שֶׁעוֹלֶה בְרָצוֹן שֶׁל סוֹד הַסּוֹדוֹת לְהוֹצִיא שְׁלֹשָׁה גְוָנִים כְּלוּלִים כְּאֶחָד, וְהֵם לָבָן אָדם וְיָרֹק, שְׁלֹשָׁה גְוָנִים מְשֻׁלָּבִים כְּאֶחָד זֶה בָּזֶה, מִתְיַחֲדִים זֶה עִם זֶה. מַגְרֵפָה תַחְתּוֹנָה נִצְבַּעַת וְיוֹצֵאת מִתּוֹךְ הַגְּוָנִים הַלָּלוּ.</p>\n<p>וְכָל הַגְּוָנִים הָאֵלּוּ נִרְאִים בָּזֶה, מַרְאֶה הוּא לְהִסְתַּכֵּל, כְּעֵין הַבְּדלַח נִרְאֶה בְשָׁעָה. כְּמוֹ שֶׁמַּכֶּה בְתוֹכָהּ, כָּךְ נִרְאֶה בַּחוּץ. שְׁלֹשֶׁת הַגְּוָנִים הַלָּלוּ סוֹבְבִים אֶת זֶה, וְהַגָּוֶן הוֹלֵךְ, עוֹלֶה וְיוֹרֵד. הֵיכְלוֹת הַקֶּשֶׁר קְבוּעִים בְּגָוֶן (בתוכה).</p>\n<p>גְּוָנִים מַקִּיפִים (גונים) כְּלוּלִים כְּאֶחָד, מַעֲלִים אוֹתָהּ לְמַעְלָה בַּיּוֹם וּמוֹרִידִים בַּלַּיְלָה. נֵר שֶׁדּוֹלֵק נִרְאֶה בַּלַּיְלָה. בַּיּוֹם נִסְתָּר הָאוֹר וּמִתְחַבֵּא בְּמָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה עוֹלָמוֹת, שֶׁכֻּלָּם הוֹלְכִים לְתוֹכָהּ (בשבילה) מִלְּמַעְלָה לְמַטָּה בְּתוֹךְ שְׁלֹשׁ מֵאוֹת שִׁשִּׁים וַחֲמִשָּׁה אֵיבָרִים גְּנוּזָה, וּמְכוּסָה לְמַטָּה.</p>\n<p>מִי שֶׁמְּחַפֵּשׂ לִמְצֹא אוֹתָהּ, יִשְׁבֹּר כְּנָפַיִם קְלִפּוֹת נִסְתָּרוֹת וְיִפְתַּח שְׁעָרִים. מִי שֶׁזּוֹכֶה לִרְאוֹת, יִרְאֶה תּוֹךְ יְדִיעָה וּתְבוּנָה כְּמִי שֶׁרוֹאֶה אַחַר הַכֹּתֶל, פְּרָט לְמֹשֶׁה הַנָּבִיא הַנֶּאֱמָן הָעֶלְיוֹן שֶׁהָיָה רוֹאֶה אוֹתָהּ עַיִן בְּעַיִן, לְמַעְלָה בְּמָקוֹם שֶׁלֹּא יָדוּעַ.</p>\n<p>מִי שֶׁלֹּא זוֹכֶה, דּוֹחִים אוֹתוֹ הַחוּצָה. כַּמָּה קְבוּצוֹת בַּעֲלֵי דִין מִזְדַּמְנִים אֵלָיו, מִזְדַּמְּנִים וְיוֹצְאִים עָלָיו, וּמוֹצִיאִים אוֹתוֹ שֶׁלֹּא יִסְתַּכֵּל בְּעֹנֶג הַמֶּלֶךְ. אוֹי לָהֶם לְאוֹתָם הָרְשָׁעִים שֶׁל הָעוֹלָם שֶׁלֹּא זוֹכִים לְהִסְתַּכֵּל, כְּמוֹ שֶׁנֶּאֱמַר וְלֹא יָבֹאוּ לִרְאוֹת כְּבַלַּע אֶת הַקֹּדֶשׁ וְגוֹ'.</p>\n<p>אָמַר רַבִּי יְהוּדָה, הָיִיתִי מִסְתַּכֵּל, וַהֲרֵי מִתּוֹךְ הַזְּהָרִים הַלָּלוּ מִסְתַּכְּלוֹת נִשְׁמוֹת הַצַּדִּיקִים, כְּשֶׁנִּדְבְּקוּ בַּמָּקוֹם הַזֶּה. מִתּוֹךְ הַזְּהָרִים הַלָּלוּ מִסְתַּכְּלוֹת נִשְׁמוֹת הַצַּדִּיקִים. אוֹתָם גְּוָנִים עוֹלִים וְנִכְלָלִים כְּאֶחָד. אַשְׁרֵי מִי שֶׁיּוֹדֵעַ לְהַכְלִיל וּלְיַחֵד אֶת כֻּלָּם כְּאֶחָד, לְתַקֵּן הַכֹּל בְּמָקוֹם שֶׁצָּרִיךְ לְמַעְלָה לְמַעְלָה, וְאָז נִשְׁמָר הָאָדָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. (ע\"כ תוספתא)</p>"],[9522011468,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (תהלים צט) וְעֹז מֶלֶךְ מִשְׁפָּט אָהֵב אַתָּה כּוֹנַנְתָּ מֵישָׁרִים וְגוֹ'. וְעֹז מֶלֶךְ מִשְׁפָּט אָהֵב - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעֹז מֶלֶךְ - תֹּקֶף שֶׁמְּחַזֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינוֹ אֶלָּא בְּמִשְׁפָּט, שֶׁהֲרֵי בְּמִשְׁפָּט עוֹמֶדֶת הָאָרֶץ, כְּמוֹ שֶׁנֶּאֱמַר (משלי כט) מֶלֶךְ בְּמִשְׁפָּט יַעֲמִיד אָרֶץ.</p>\n<p>וּמִשּׁוּם כָּךְ, וְעֹז מֶלֶךְ מִשְׁפָּט אָהֵב, וְלֹא (מתחזקת) נִתְקֶנֶת כְּנֶסֶת יִשְׂרָאֵל אֶלָּא בְּמִשְׁפָּט, מִשּׁוּם שֶׁמִּשָּׁם נִזּוֹנֵית, וְכָל הַבְּרָכוֹת שֶׁנּוֹטֶלֶת, הִיא נוֹטֶלֶת מִשָּׁם, וְלָכֵן וְעֹז מֶלֶךְ מִשְׁפָּט אָהֵב - כָּל הַתְּשׁוּקָה וְכָל הָאַהֲבָה שֶׁלָּהּ כְּנֶגֶד הַמִּשְׁפָּט. אַתָּה כּוֹנַנְתָּ מֵישָׁרִים - סוֹד שֶׁל שְׁנֵי הַכְּרוּבִים לְמַטָּה, שֶׁהֵם תִּקּוּן וְיִשּׁוּב הָעוֹלָם, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522011469,"<p>רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (תהלים קיג) הַלְלוּיָהּ הַלְלוּ עַבְדֵי ה' הַלְלוּ אֶת שֵׁם ה'. בְּפָסוּק זֶה יֵשׁ לְהִתְבּוֹנֵן בּוֹ. כֵּיוָן שֶׁאָמַר הַלְלוּיָהּ, אָז לָמָּה הַלְלוּ עַבְדֵי ה', וְאַחַר כָּךְ הַלְלוּ אֶת שֵׁם ה'? אֶלָּא כָּךְ שָׁנִינוּ, מִי שֶׁמְּשַׁבֵּחַ אֶת (האחד) הָאַחֵר, צָרִיךְ לְשַׁבְּחוֹ לְפִי כְבוֹדוֹ, וּלְפִי כְבוֹדוֹ כָּךְ צָרִיךְ שִׁבְחוֹ. וְשָׁנִינוּ, מִי שֶׁמְּשַׁבֵּחַ אֶת הָאַחֵר בְּשֶׁבַח שֶׁאֵין בּוֹ - הוּא מְגַלֶּה (גלוי ומסבב) אֶת גְּנוּתוֹ, וְרוֹצֶה לְגַלּוֹת אוֹתוֹ. וְעַל זֶה מִי שֶׁעוֹשֶׂה הֶפְסֵד עַל בֶּן אָדָם, צָרִיךְ כְּפִי כְבוֹדוֹ וְלֹא יוֹתֵר, שֶׁמִּתּוֹךְ שִׁבְחוֹ בָּא לִגְנוּתוֹ, וּבְכָל שֶׁבַח צָרִיךְ לְפִי כְבוֹדוֹ.</p>\n<p>בֹּא רְאֵה, הַלְלוּיָהּ, כָּאן יֵשׁ שֶׁבַח עֶלְיוֹן שֶׁל רִבּוֹן הַכֹּל, מָקוֹם שֶׁאֵין הָעַיִן שׁוֹלֶטֶת בּוֹ לָדַעַת וּלְהִתְבּוֹנֵן (מקום), שֶׁהוּא טָמִיר שֶׁל כָּל הַטְּמִירִים, וּמִיהוּ? יָ\"הּ, שֵׁם עֶלְיוֹן עַל הַכֹּל.</p>\n<p>וּמִשּׁוּם כָּךְ הַלְלוּיָהּ, שֶׁבַח וְשֵׁם כְּאֶחָד, כְּלוּלִים כְּאֶחָד, וְכָאן נִסְתָּר הַדָּבָר שֶׁאָמַר הַלְלוּיָהּ וְלֹא אָמַר מִי הַלְלוּיָהּ, לְמִי אָמְרוּ הַלְלוּ? אֶלָּא כְּמוֹ שֶׁיָּ\"הּ נִסְתָּר, כָּךְ שֶׁבַח שֶׁמְּשַׁבְּחִים הֵם נִסְתָּרִים, שֶׁמְּשַׁבְּחִים לֹא יָדַעְנוּ מִי הֵם, וְכָךְ צָרִיךְ הַכֹּל לִהְיוֹת נִסְתָּר בְּסוֹד עֶלְיוֹן. וְאַחַר שֶׁנִּסְתָּר בְּסוֹד עֶלְיוֹן, גִּלָּה וְאָמַר הַלְלוּ עַבְדֵי ה' הַלְלוּ אֶת שֵׁם ה', מִשּׁוּם שֶׁזֶּהוּ מָקוֹם שֶׁלֹּא נִסְתָּר, כְּאוֹתוֹ עֶלְיוֹן הַטָּמִיר שֶׁל כָּל הַטְּמִירִים. זֶהוּ מָקוֹם שֶׁנִּקְרָא שֵׁם, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב ו) אֲשֶׁר נִקְרָא שֵׁם שֵׁם ה'.</p>\n<p>הָרִאשׁוֹן נִסְתָּר שֶׁאֵינוֹ (זה) גָלוּי. (השני) נִסְתָּר וְגָלוּי. וּמִשּׁוּם שֶׁעוֹמֵד בְּהִתְגַּלּוּת אָמַר, אוֹתָם שֶׁמְּשַׁבְּחִים לְאוֹתוֹ מָקוֹם מִי הֵם? וְאָמַר שֶׁהֵם עַבְדֵי ה' הָרְאוּיִים לְשַׁבֵּחַ אֶת הַמָּקוֹם הַזֶּה.</p>\n<p>יְהִי שֵׁם ה' מְבֹרָךְ, מַה שּׁוֹנֶה שֶׁאָמַר יְהִי? אֶלָּא יְהִי - סוֹד הַהַמְשָׁכָה מֵאוֹתוֹ מָקוֹם עֶלְיוֹן, שֶׁהוּא נִסְתָּר, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁהוּא יָ\"הּ, עַד סוֹד הַבְּרִית שֶׁהוּא יוֹ\"ד תַּחְתּוֹנָה, כְּמוֹ שֶׁיּוֹ\"ד הָעֶלְיוֹנָה, הָרֵאשִׁית כַּסּוֹף.</p>\n<p>וּמִשּׁוּם כָּךְ יְהִי, סוֹד הַהַמְשָׁכָה מִטָּמִיר שֶׁל כָּל הַטְּמִירִים עַד הַדַּרְגָּה הַתַּחְתּוֹנָה, וּבַדָּבָר הַזֶּה מִתְקַיֵּם כָּל מַעֲשֵׂה בְרֵאשִׁית, כְּמוֹ שֶׁנֶּאֱמַר יְהִ\"י רָקִיעַ, יְהִ\"י מְאֹרֹת, יְהִ\"י אוֹר. בְּכָל אוֹתָם הַמַּעֲשִׂים שֶׁלְּמַעְלָה כָּתוּב יְהִי.</p>\n<p>בְּכָל אוֹתָם מַעֲשִׂים שֶׁלְּמַטָּה לֹא כָתוּב יְהִי, מִשּׁוּם שֶׁסּוֹד זֶה שֶׁהוּא (המשכה) מִסּוֹד עֶלְיוֹן, נִסְתַּר כָּל הַנִּסְתָּרִים, לֹא מִתְקַיֵּם אֶלָּא בִּדְבָרִים עֶלְיוֹנִים שֶׁלְּמַעְלָה, וְלֹא נֶאֱמַר בְּאוֹתָם דְּבָרִים תַּחְתּוֹנִים שֶׁלְּמַטָּה.</p>\n<p>וּבָזְהִ מִתְבָּרֵךְ הַשֵּׁם הַקָּדוֹשׁ בַּכֹּל, וְעַל זֶה כָּתוּב יְהִי שֵׁם ה' מְבֹרָךְ וְגוֹ', מִמִּזְרַח שֶׁמֶשׁ עַד מְבוֹאוֹ. זֶה מָקוֹם עֶלְיוֹן שֶׁמְּאִירָה מִמֶּנּוּ הַשֶּׁמֶשׁ וּמֵאִיר לַכֹּל, וְזֶהוּ מָקוֹם שֶׁל הָרֹאשׁ הָעֶלְיוֹן הַנִּסְתָּר.</p>\n<p>וְעַד מְבוֹאוֹ - זֶהוּ מְקוֹם הַקֶּשֶׁר שֶׁנִּקְשֶׁרֶת בּוֹ הָאֱמוּנָה כָּרָאוּי, וּמִשָּׁם יוֹצְאוֹת בְּרָכוֹת לַכֹּל, וְהָעוֹלָם מִכָּאן נִזּוֹן, כְּמוֹ שֶׁנִּתְבָּאֵר, וּמִשּׁוּם כָּךְ עוֹמֵד מָקוֹם זֶה לְהִזּוֹן מִלְמַעְלָה וּלְהִתְבָּרֵךְ מִשָּׁם, וְהַכֹּל עוֹמֵד בַּהִתְעוֹרְרוּת הַתַּחְתּוֹנָה שֶׁמְּעוֹרְרִים אוֹתָם עַבְדֵי ה' כְּשֶׁמְּבָרְכִים אֶת הַשֵּׁם הַקָּדוֹשׁ, כְּפִי שֶׁאָמַרְנוּ. וּמִשּׁוּם כָּךְ שֶׁהִיא בְּהִתְגַּלּוּת, כָּתוּב הַלְלוּ עַבְדֵי ה' הַלְלוּ אֶת שֵׁם ה'.</p>\n<p>בֵּינְתַיִם הֵאִיר הַבֹּקֶר וְיָצְאוּ מֵהַמְּעָרָה, וּבְאוֹתוֹ הַלַּיְלָה לֹא יָשְׁנוּ. הָלְכוּ בַּדֶּרֶךְ. כְּשֶׁיָּצְאוּ מֵאוֹתָם הֶהָרִים, יָשְׁבוּ וְהִתְפַּלְלוּ תְפִלָּה. הִגִּיעוּ לִכְפָר אֶחָד וְיָשְׁבוּ שָׁם כָּל אוֹתוֹ הַיּוֹם. בְּאוֹתוֹ הַלַּיְלָה יָשְׁנוּ עַד שֶׁהָיָה חֲצוֹת הַלַּיְלָה, וְקָמוּ לְהִתְעַסֵּק בַּתּוֹרָה.</p>"],[9522011470,"<p>פָּתַח רַבִּי יְהוּדָה וְאָמַר, וַיְבָרֲכֵם בַּיּוֹם הַהוּא לֵאמוֹר בְּךְ יְבָרֵךְ יִשְׂרָאֵל וְגוֹ'. וַיְבָרֲכֵם בַּיּוֹם הַהוּא, מַה זֶּה בַּיּוֹם הַהוּא? שֶׁהֲרֵי מַסְפִּיק שֶׁאָמַר וַיְבָרֲכֵם. וְעוֹד, כָּל לֵאמֹר כָּתוּב חָסֵר, וְכָאן לֵאמוֹר בְּאוֹת וָי\"ו כָּתוּב, (שבכלם כתוב לאמר בלי אות ו', וכאן כתוב לאמור) לָמָּה הַשִּׁנּוּי?</p>\n<p>אֶלָּא סוֹד הוּא, וַיְבָרֲכֵם בַּיּוֹם הַהוּא. מַה זֶּה בַּיּוֹם הַהוּא? סוֹד הַדַּרְגָּה הַמְמֻנָּה עַל הַבְּרָכוֹת לְמַעְלָה. יוֹם הַהוּא - יוֹם מֵאוֹתוֹ מָקוֹם עֶלְיוֹן שֶׁנִּקְרָא הוּא, וְיוֹם הַהוּא הַזֶּה שֶׁאֵין פֵּרוּד בֵּין יוֹם לְבֵין הוּא, וּבְכָל מָקוֹם הַיּוֹם הַהוּא, זֶה (הוא) שְׁתֵּי דְרָגוֹת (עליונות), דַּרְגָּה עֶלְיוֹנָה וְתַחְתּוֹנָה, שֶׁהֵן כְּאַחַת.</p>\n<p>וּמִשּׁוּם כָּךְ, כְּשֶׁרָצָה יַעֲקֹב לְבָרֵךְ אֶת בְּנֵי יוֹסֵף, בֵּרְכָם בַּיִּחוּד שֶׁלְּמַעְלָה וּמַטָּה כֻּלָּם כְּאֶחָד, (לאמור בוא\"ו, שנכלל וא\"ו ביניהם, על זה יחד אותם ביחוד שלמעלה כלם כאחד) כְּדֵי שֶׁתִּתְקַיֵּם בִּרְכָתָם, וְאַחַר כָּךְ כָּלַל הַכֹּל כְּאֶחָד וְאָמַר בְּךְ יְבָרֵךְ יִשְׂרָאֵל (לאמר). מַה זֶּה בְּךְ? וַדַּאי זֶה סוֹד הַיִּחוּד, בַּתְּחִלָּה מִלְּמַטָּה לְמַעְלָה (יום ההוא מלמטה למעלה), וְאַחַר כָּךְ יוֹרֵד לָאֶמְצַע וּלְמַטָּה. לֵאמוֹר - בְּוָא\"ו, הֲרֵי הָאֶמְצַע. וְאַחַר כָּךְ יוֹרֵד לְמַטָּה בְּךְ, וְכָךְ הוּא יָפֶה כָּרָאוּי, מִלְּמַטָּה לְמַעְלָה, וּמִמַּעְלָה לְמַטָּה.</p>\n<p>בְּךָ יְבָרֵךְ יִשְׂרָאֵל, מַה זֶּה יִשְׂרָאֵל? יִשְׂרָאֵל הַזָּקֵן. לֹא כָתוּב יְבֹרַךְ יִשְׂרָאֵל, אֶלָּא יְבָרֵךְ, שֶׁהֲרֵי יִשְׂרָאֵל נוֹטֵל בְּרָכוֹת מִלְמַעְלָה, וְאַחַר כָּךְ הוּא מְבָרֵךְ אֶת הַכֹּל בַּדַּרְגָּה הַתַּחְתּוֹנָה הַזּוֹ דַּוְקָא, שֶׁאָמַר בְּךְ יְבָרֵךְ יִשְׂרָאֵל לֵאמֹר.</p>\n<p>יְשִׂמְךָ אֱלֹהִים כְּאֶפְרַיִם וְכִמְנַשֶּׁה. הִקְדִּים אֶת אֶפְרַיִם בַּתְּחִלָּה, מִשּׁוּם שֶׁאֶפְרַיִם עַל שֵׁם (של יוסף) יִשְׂרָאֵל. מִנַּיִן לָנוּ? מִזֶּה שֶׁכְּשֵׁבֶט אֶפְרַיִם יָצָא, עַד שֶׁלֹּא הֻשְׁלַם זְמַן שִׁעְבּוּד מִצְרַיִם, דָּחֲקוּ אֶת הַשָּׁעָה וְיָצְאוּ מֵהַגָּלוּת, קָמוּ עֲלֵיהֶם שׂוֹנְאֵיהֶם וְהָרְגוּ אוֹתָם, וְכָתוּב בֶּן אָדָם הָעֲצָמוֹת הָאֵלֶּה כָּל בֵּית יִשְׂרָאֵל הֵמָּה, מַשְׁמָע שֶׁכָּתוּב (יחזקאל לז) כָּל בֵּית יִשְׂרָאֵל הֵמָּה, וְלָכֵן הִקְדִּים אֶת אֶפְרַיִם קֹדֶם מְנַשֶּׁה, וְלָכֵן אֶפְרַיִם מַשָּׂאוֹ לְצַד מַעֲרָב, וּמַסָּעוֹ הָיָה.</p>\n<p>בֹּא רְאֵה, הַבְּרָכָה שֶׁבֵּרַךְ אֶת בְּנֵי יוֹסֵף, לָמָּה הִקְדִּים לָהֶם בְּרָכוֹת עַד שֶׁלֹּא יְבָרֵךְ אֶת בָּנָיו? אֶלָּא מִכָּאן שֶׁחֲבִיבוּת בְּנֵי בָנָיו שֶׁל אָדָם חֲבִיבָה עָלָיו יוֹתֵר מִבָּנָיו, וְלָכֵן הִקְדִּים חֲבִיבוּת בְּנֵי בְנוֹ קֹדֶם לִבְנוֹ לְבָרֵךְ אוֹתָם בַּתְּחִלָּה.</p>\n<p>וַיְבָרֲכֵם בַּיּוֹם הַהוּא לֵאמוֹר. רַבִּי יוֹסֵי פָּתַח וְאָמַר, (תהלים קטו) ה' זְכָרָנוּ יְבָרֵךְ יְבָרֵךְ אֶת בֵּית יִשְׂרָאֵל וְגוֹ'. ה' זְכָרָנוּ יְבָרֵךְ - אֵלּוּ הַגְּבָרִים. יְבָרֵךְ אֶת בֵּית יִשְׂרָאֵל - אֵלּוּ הַנָּשִׁים. מִשּׁוּם שֶׁזְּכָרִים צְרִיכִים לְהִתְבָּרֵךְ בַּתְּחִלָּה, וְאַחַר כָּךְ נָשִׁים, וְנָשִׁים לֹא מִתְבָּרְכוֹת אֶלָּא מִבִּרְכַּת הַזְּכָרִים, שֶׁכְּשֶׁזְּכָרִים מִתְבָּרְכִים, אָז מִתְבָּרְכוֹת הַנָּשִׁים. וְאִם תֹּאמַר מִזֶּה שֶׁכָּתוּב (ויקרא טז) וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ, שֶׁצָּרִיךְ לְכַפֵּר עָלָיו בַּתְּחִלָּה וְאַחַר כָּךְ עַל בֵּיתוֹ, מִשּׁוּם שֶׁמִּתְבָּרֵךְ מִמֶּנּוּ.</p>\n<p>בֹּא רְאֵה שֶׁנָּשִׁים לֹא מִתְבָּרְכוֹת אֶלָּא רַק מִגְּבָרִים, שֶׁכְּשֶׁמִּתְבָּרְכִים אֵלּוּ בַּתְּחִלָּה, וּמִבְּרָכָה זוֹ מִתְבָּרְכוֹת. אֶלָּא בַּמֶּה בֵּאַרְנוּ יְבָרֵךְ אֶת בֵּית יִשְׂרָאֵל? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן תּוֹסֶפֶת בְּרָכוֹת לַזָּכָר שֶׁנּוֹשֵׂא, מִשּׁוּם שֶׁמִּתְבָּרֶכֶת מִמֶּנּוּ הָאִשָּׁה, וְכֵן בְּכָל מָקוֹם נוֹתֵן הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹסֶפֶת בְּרָכוֹת לַזָּכָר שֶׁנּוֹשֵׂא, מִשּׁוּם שֶׁמִּתְבָּרֵךְ (ממנו אשתו, וכן בכל מקום נותן הקדוש ברוך הוא תוספת ברכות לזכר שנשא כדי שתתברך ממנו הנקבה) מֵאוֹתָהּ תּוֹסֶפֶת הַבְּרָכוֹת. כֵּיוָן שֶׁנִּשָּׂא הָאָדָם, נוֹתֵן לוֹ שְׁנֵי חֲלָקִים, אֶחָד לוֹ וְאֶחָד לִנְקֵבָתוֹ, וְהוּא נוֹטֵל הַכֹּל - חֶלְקוֹ וְחֵלֶק נְקֵבָתוֹ.</p>\n<p>בֹּא רְאֵה, וַיְבָרֲכֵם בַּיּוֹם הַהוּא (לאמור, ברך אותם ברכות ולכל אלו שיצאו מהם), אַחַר כָּךְ לֵאמוֹר בְּוָא\"ו. כָּאן נִרְמַז בֵּן בְּכוֹר, (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, וְכָתוּב (ירמיה לא) וְאֶפְרַיִם בְּכוֹרִי הוּא, וְעַל זֶה תּוֹסֶפֶת וָא\"ו.</p>"],[9522011471,"<p>רַבִּי חִזְקִיָּה פָּתַח, (תהלים קלט) גָּלְמִי רָאוּ עֵינֶיךְ וְעַל סִפְרְךְ כֻּלָּם יִכָּתֵבוּ וְגוֹ'. פָּסוּק זֶה בֵּאֲרוּהוּ בְּכַמָּה מְקוֹמוֹת. אֲבָל בּא רְאֵה, כָּל אוֹתָן הַנְּשָׁמוֹת שֶׁהָיוּ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, כֻּלָּן עוֹמְדוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁלֹּא יָרְדוּ לָעוֹלָם בְּאוֹתָהּ דְּמוּת מַמָּשׁ שֶׁנִּרְאִים אַחַר כָּךְ בָּעוֹלָם, וְאוֹתוֹ מַרְאֶה שֶׁל גּוּף הָאָדָם שֶׁעוֹמֵד בָּעוֹלָם הַזֶּה, כָּךְ עוֹמֵד לְמַעְלָה.</p>\n<p>וּבְשָׁעָה שֶׁנְּשָׁמָה זוֹ מְזֻמֶּנֶת לָרֶדֶת לָעוֹלָם, אוֹתָהּ נְשָׁמָה בְּאוֹתָהּ דְּמוּת מַמָּשׁ שֶׁעוֹמֶדֶת בָּעוֹלָם הַזֶּה, כָּךְ עוֹמֶדֶת (למעלה) לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמַשְׁבִּיעַ אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁתִּשְׁמֹר מִצְווֹת הַתּוֹרָה וְלֹא לַעֲבֹר עַל הַבְּרִיתוֹת.</p>\n<p>וּמִנַּיִן לָנוּ שֶׁעוֹמֶדֶת לְפָנָיו? שֶׁכָּתוּב (מלכים א יז) חַי ה' אֲשֶׁר עָמַדְתִּי לְפָנָיו. עָמַדְתִּי וַדַּאי, וַהֲרֵי פֵּרְשׁוּהָ. וְלָכֵן גָּלְמִי רָאוּ עֵינֶיךְ, עַד שֶׁלֹּא יִתְרָאֶה (הצלם) בָּעוֹלָם. וְעַל סִפְרְךְ כֻּלָּם יִכָּתֵבוּ, שֶׁהֲרֵי כָּל הַנְּשָׁמוֹת בְּאוֹתָהּ דְּמוּת שֶׁלָּהֶם, כֻּלָּם בַּסֵּפֶר כְּתוּבִים. יָמִים יֵצּרוּ, הֲרֵי פֵּרְשׁוּהָ יֻצָּרוּ וַדַּאי. וְלֹא אֶחָד בָּהֶם, בָּעוֹלָם הַזֶּה לַעֲמֹד בְּקִיּוּם רִבּוֹנָם כָּרָאוּי.</p>"],[9522011472,"<p>בֹּא רְאֵה, יְמֵי בֶּן הָאָדָם כְּשֶׁזּוֹכֶה בָּעוֹלָם הַזֶּה בְּמַעֲשִׂים טוֹבִים, הַיָּמִים שֶׁלּוֹ מִתְרַבִּים לְמַעְלָה מֵאוֹתוֹ מָקוֹם שֶׁהוּא מִדַּת יָמָיו. פָּתַח וְאָמַר, (תהלים לט) הוֹדִיעֵנִי ה' קִצִּי וּמִדַּת יָמַי מַה הִיא וְגוֹ'. פָּסוּק זֶה בֵּאֲרוּהוּ. אֲבָל בֹּא רְאֵה, קִצִּי - זֶה קֵץ הַיָּמִין, שֶׁנִּקְשַׁר בְּדָוִד. וּמִדַּת יָמַי מַה הִיא - זֶהוּ שֶׁמִּתְמַנֶּה (שיש ממנה) מַמָּשׁ עַל יָמָיו.</p>\n<p>אָמַר רַבִּי יְהוּדָה, הֲרֵי שָׁמַעְתִּי מֵרַבִּי שִׁמְעוֹן שֶׁפָּסוּק זֶה נֶאֱמַר עַל אוֹתָם הַיָּמִים שֶׁנִּגְזְרוּ עָלָיו מֵאָדָם הָרִאשׁוֹן, שֶׁהֵם שִׁבְעִים, שֶׁהֲרֵי נֶאֱמַר שֶׁחַיִּים בִּכְלָל לֹא הָיוּ לוֹ, אֶלָּא שֶׁאָדָם נָתַן לוֹ מֵאוֹתָם יָמִים שֶׁלּוֹ שִׁבְעִים שָׁנִים.</p>\n<p>וְסוֹד זֶה, וִילוֹן לֹא מְשַׁמֵּשׁ כְּלוּם, וְהַלְּבָנָה לֹא מְאִירָה כְּלָל מֵעַצְמָהּ, וְשִׁבְעִים שָׁנִים מְאִירוֹת לָהּ בְּכָל צְדָדֶיהָ, וְהֵם חַיֵּי דָוִד סְתָם. וְעַל זֶה רָצָה דָּוִד מֵהַקָּדוֹשׁ בָּרוּךְ הוּא לָדַעַת סוֹד זֶה, וְעַל מָה אֵין חַיִּים לַלְּבָנָה מֵעַצְמָהּ, וְלָדַעַת אֶת הָעִקָּר שֶׁלָּהּ.</p>\n<p>וּמִדַּת יָמַי מַה הִיא - זוֹהִי דַרְגָּה (של העולם) עֶלְיוֹנָה נִסְתֶּרֶת שֶׁעוֹמֶדֶת עַל כָּל אוֹתָם הַיָּמִים שֶׁהֵם חַיִּים שֶׁלָּהּ, מָקוֹם שֶׁמֵּאִיר לַכֹּל. אֵדְעָה מֶה חָדֵל אָנִי - אָמַר דָּוִד, אֵדַע עַל מֶה חָדֵל אֲנִי אוֹר מֵעַצְמִי וְנִמְנָע מִמֶּנִּי כִּשְׁאָר כָּל אוֹתָם הָאוֹרוֹת הָעֶלְיוֹנִים שֶׁיֵּשׁ לָהֶם לְכֻלָּם חַיִּים, וַאֲנִי עַל מָה אֲנִי חָדֵל וְעַל מַה נִּמְנָע מִמֶּנִּי. וְזֶהוּ מַה שֶּׁרָצָה דָוִד לָדַעַת, וְלֹא נִתְּנָה לוֹ רְשׁוּת לָדַעַת.</p>"],[9522011473,"<p>בֹּא רְאֵה, כָּל הַבְּרָכוֹת הָעֶלְיוֹנוֹת, כֻּלָּן נִמְסְרוּ לַדַּרְגָּה הַזּוֹ לְבָרֵךְ אֶת הַכֹּל. וְאַף עַל גַּב שֶׁאֵין לָהּ אוֹר מֵעַצְמָהּ, כָּל הַבְּרָכוֹת וְכָל הַשִּׂמְחָה וְכָל הַטּוּב, כֻּלָּם עוֹמְדִים בָּהּ וּמִמֶּנָּה (עומדים) יוֹצְאִים, וְעַל זֶה נִקְרֵאת כּוֹס שֶׁל בְּרָכָה, וְנִקְרֵאת בְּרָכָה מַמָּשׁ, כְּמוֹ שֶׁכָּתוּב (משלי י) בִּרְכַּת ה' הִיא תַעֲשִׁיר. וְעַל זֶה כָּתוּב (דברים לג) וּמָלֵא בִּרְכַּת ה' יָם וְדָרוֹם יְרָשָׁה.</p>\n<p>וְלָכֵן יֵשׁ לָהּ בְּכֻלָּם שִׁיּוּר, וּמִכֻּלָּם מִתְמַלֵּאת וּמִכֻּלָּם יֵשׁ בָּהּ, וּמִתְבָּרֶכֶת מִכָּל אוֹתָן בְּרָכוֹת עֶלְיוֹנוֹת, וְנִמְסְרוּ לָהּ בְּרָכוֹת לְבָרֵךְ. מִנַּיִן לָנוּ? שֶׁאָמַר רַבִּי יִצְחָק, יַעֲקֹב בֵּרַךְ אֶת בְּנֵי יוֹסֵף מִמָּקוֹם זֶה שֶׁכָּל הַבְּרָכוֹת נִמְסְרוּ בְיָדוֹ לְבָרֵךְ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית יב) וֶהְיֵה בְּרָכָה. מִכָּאן וָהָלְאָה הַבְּרָכוֹת נִמְסְרוּ בְיָדְךְ.</p>\n<p>בֹּא רְאֵה, כְּמוֹ זֶה אָנוּ מְבָרְכִים וּמְשַׁבְּחִים אֶת הַשֵּׁם הַזֶּה, וְעַל זֶה הַלֵּל, שֶׁאוֹתָם יָמִים שֶׁאוֹמְרִים הַלֵּל. שֶׁאָמַר רַבִּי חִיָּיא, בְּהַלֵּל צְרִיכִים שָׁלֹשׁ דְּרָגוֹת: חֲסִידִים, צַדִּיקִים, וְיִשְׂרְאֵלִים. (משום שנתעלה כבוד הקדוש ברוך הוא באלו הדרגות) חֲסִידִים מִצַּד הַיָּמִין, צַדִּיקִים מִצַּד הַשְּׂמֹאל, וְיִשְׂרָאֵל מִכָּל אוֹתָם הַצְּדָדִים, מִשּׁוּם (שהישרים) שֶׁיִּשְׂרָאֵל כְּלוּלִים מִכֻּלָּם, וְעַל זֶה עוֹלָה תִּשְׁבַּחַת הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהַכֹּל, וְכֵן בְּכָל מָקוֹם שֶׁיִּשְׂרָאֵל מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְּמַטָּה, עוֹלֶה כְבוֹדוֹ בַּכֹּל.</p>"],[9522011474,"<p>קוֹל גַּלְגַּל מִתְגַּלְגֵּל מִמַּטָּה לְמַעְלָה, מַרְכְּבוֹתֶיהָ סְגוּרוֹת, הוֹלְכוֹת וּמִתְגַּלְגְּלוֹת. קוֹל נְעִימוּת עוֹלֶה וְיוֹרֵד, הוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם. קוֹל שׁוֹפָר שׁוֹפֵעַ בְּעָמְקֵי הַדְּרָגוֹת מְסוֹבֵב דַּרְגָּה (גלגל) סְבִיבָהּ.</p>\n<p>יוֹשְׁבוֹת שְׁתֵּי מַגְרֵפוֹת מִיָּמִין וּמִשְּׂמֹאל, בִּשְׁנֵי גְוָנִים נִשְׁאָבִים זֶה בָּזֶה, זֶה לָבָן וְזֶה אָדם, וּשְׁנֵיהֶם סוֹבְבִים גַּלְגַּל לְמַעְלָה, סוֹבֵב לְיָמִין - לָבָן עוֹלֶה, וְסוֹבֵב לִשְׂמֹאל - אָדם יוֹרֵד, וְהַגַּלְגַּל סוֹבֵב תָּמִיד וְלֹא שׁוֹכֵךְ.</p>\n<p>שְׁתֵּי צִפֳּרִים עוֹלוֹת, שֶׁמְּצַפְצְפוֹת, אַחַת לְצַד דָּרוֹם וְאַחַת לְצַד צָפוֹן. פּוֹרְחִים בָּאֲוִיר צִפְצוּף, וְקוֹל נְעִימַת הַגַּלְגַּל מִתְחַבְּרִים כְּאֶחָד, וְאָז (תהלים צד) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת. וְכָל הַבְּרָכוֹת שׁוֹפְעוֹת בְּלַחַשׁ בַּנְּעִימוּת הַזּוֹ (מקול), מִתּוֹךְ אַהֲבַת קוֹל הַשּׁוֹפָר.</p>\n<p>כְּנֶגֶד אוֹתָן בְּרָכוֹת יוֹרְדוֹת מִלְמַעְלָה לְמַטָּה, וְנִגְנְזוּ כְּאֶחָד בְּתוֹךְ עֹמֶק הַבְּאֵר, נְבִיעַת הַבְּאֵר שֶׁלֹּא פוֹסֶקֶת בְּלַחַשׁ, עַד שֶׁמִּתְמַלֵּא אוֹתוֹ גַלְגַּל סוֹבֵב.</p>\n<p>אוֹתָן שְׁתֵּי מַגְרֵפוֹת סוֹבְבוֹת, אַחַת הַיְמָנִית, קוֹרֵאת בְּחַיִל וְאוֹמֶרֶת: זהַר שֶׁזּוֹהֲרִים שֶׁעוֹלֶה וְיוֹרֵד, שְׁנֵי אַלְפֵי עוֹלָמוֹ\"ת הָאִירוּ. עוֹלַם הָאֶמְצַע בְּתוֹכָם הָאֵר בְּזֹהַר רִבּוֹנְךְ. כָּל אוֹתָם בַּעֲלֵי הָעֵינַיִם הִסְתַּכְּלוּ וּפִקְחוּ עֵינֵיכֶם, וְתִזְכּוּ לָאוֹר הַזֶּה, לָעִדּוּן הַזֶּה. אֵלּוּ הֵן בְּרָכוֹת שֶׁשּׁוֹפְעוֹת מִלְמַעְלָה, מִי שֶׁזּוֹכֶה, גַּלְגַּל עוֹלֶה סוֹבֵב יָמִינָה, וְשׁוֹפֵעַ וּמוֹשֵׁךְ לְאוֹתוֹ הַזּוֹכֶה, וּמִתְעַדֵּן מִבְּרָכוֹת אֵלּוּ הָעֶלְיוֹנוֹת הַזּוֹהֲרוֹת. אַשְׁרֵיהֶם אוֹתָם שֶׁזּוֹכִים בָּהֶם.</p>\n<p>וּכְשֶׁלֹּא זוֹכֶה, גַּלְגַּל סוֹבֵב, וְאוֹתָהּ מַגְרֵפָה שֶׁל צַד שְׂמֹאל סוֹבֶבֶת וְיוֹרֶדֶת לְמַטָּה, וּמַמְשִׁיכָה דִין עַל זֶה שֶׁלֹּא זוֹכֶה, וְקוֹל יוֹצֵא: אוֹי לְאוֹתָם רְשָׁעִים שֶׁלֹּא זָכוּ. מֵאוֹתוֹ צַד יוֹצֵאת אֵשׁ שֶׁל שַׁלְהֶבֶת שֶׁדּוֹלֶקֶת, שֶׁשּׁוֹרָה עַל רָאשֵׁי הָרְשָׁעִים. אַשְׁרֵיהֶם אוֹתָם כָּל אוֹתָם שֶׁהָלְכוּ בְּדֶרֶךְ אֱמֶת בָּעוֹלָם הַזֶּה לִזְכּוֹת לְאוֹתוֹ אוֹר עֶלְיוֹן, בְּרָכוֹת מְצֻחְצָחוֹת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נח) וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. עד כאן התוספתא</p>"],[9522011475,"<p>וַיִּקְרָא יַעֲקֹב אֶל בָּנָיו וַיֹּאמֶר הֵאָסְפוּ וְגוֹ'. רַבִּי אַבָּא פָּתַח וְאָמַר, (תהלים קב) פָּנָה אֶל תְּפִלַּת הָעַרְעָר וְלֹא בָזָה אֶת תְּפִלָּתָם. פָּסוּק זֶה בֵּאֲרוּהוּ, וְהִתְקַשּׁוּ בוֹ הַחֲבֵרִים. (אלא עוד יש בו צד בציורים רבים) פָּנָה!? הִקְשִׁיב הָיָה צָרִיךְ, אוֹ שָׁמַע. מַה זֶּה פָּנָה?</p>\n<p>אֶלָּא כָּל תְּפִלּוֹת הָעוֹלָם - תְּפִלּוֹת, וּתְפִלַּת הַיָּחִיד לֹא נִכְנֶסֶת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ אֶלָּא בְּכֹחַ חָזָק. שֶׁעַד שֶׁלֹּא נִכְנֶסֶת אוֹתָהּ תְּפִלָּה לְהִתְעַטֵּר בִּמְקוֹמָהּ, מַשְׁגִּיחַ בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִסְתַּכֵּל בָּהּ, וּמִסְתַּכֵּל בַּחֲטָאֵי וּבִזְכוּת אוֹתוֹ הָאָדָם, מַה שֶּׁאֵינוֹ עוֹשֶׂה כֵּן בִּתְפִלַּת הָרַבִּים, שֶׁתְּפִלַּת הָרַבִּים כַּמָּה הֵן תְּפִלּוֹת שֶׁאֵינָן (מבני) מִצַּדִּיקִים, וְכֻלָּן נִכְנָסוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא מַשְׁגִּיחַ בַּחֲטָאֵיהֶם.</p>\n<p>מִשּׁוּם כָּךְ פָּנָה אֶל תְּפִלַּת הָעַרְעָר, מְהַפֵּךְ וּמִסְתַּכֵּל בָּהּ, וּמִסְתַּכֵּל (בזכותו) בַּמָּה רָצוֹן נַעֲשֶׂה, וּמִי אוֹתוֹ הָאִישׁ שֶׁמִּתְפַּלֵּל תְּפִלָּה זוֹ וּמָהֵם מַעֲשָׂיו. מִשּׁוּם כָּךְ צָרִיךְ הָאָדָם לְהִתְפַּלֵּל תְּפִלָּה בְּצִבּוּר. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא בָזָה אֶת תְּפִלָּתָם, אַף עַל גַּב שֶׁלֹּא כֻּלָּם בְּכַוָּנָה וּרְצוֹן הַלֵּב.</p>\n<p>דָּבָר אַחֵר פָּנָה אֶל תְּפִלַּת הָעַרְעָר - זֶה יְחִידִי שֶׁנִּכְלָל בְּרַבִּים. וּמִיהוּ יְחִידִי שֶׁנִּכְלָל בְּרַבִּים? הֱוֵי אוֹמֵר זֶה יַעֲקֹב, שֶׁהוּא כָּלוּל בִּשְׁנֵי צְדָדִים, וְקָרָא לְבָנָיו, וְהִתְפַּלֵּל תְּפִלָּתוֹ עֲלֵיהֶם. אֵיזוֹ תְפִלָּה שֶׁיִּתְקַבְּלוּ בִּשְׁלֵמוּת לְמַעְלָה? תְּפִלָּה שֶׁלֹּא יֻשְׁמְדוּ בַגָּלוּת.</p>\n<p>בְּשָׁעָה זוֹ שֶׁקָּרָא לָהֶם יַעֲקֹב, הִסְתַּלְּקָה מִמֶּנּוּ שְׁכִינָה, וַהֲרֵי פֵּרְשׁוּהָ. וּבא וּרְאֵה, בְּשָׁעָה שֶׁיַּעֲקֹב הָיָה קוֹרֵא לְבָנָיו, הִזְדַּמְּנוּ לְשָׁם אַבְרָהָם וְיִצְחָק, וּשְׁכִינָה עַל גַּבֵּיהֶם. וְהַשְּׁכִינָה הָיְתָה שְׂמֵחָה בְּיַעֲקֹב לְהִתְחַבֵּר בָּאָבוֹת, לְהִתְקַשֵּׁר עִם נַפְשׁוֹתֵיהֶם כְּאֶחָד, לִהְיוֹת מֶרְכָּבָה.</p>\n<p>בְּשָׁעָה שֶׁפָּתַח יַעֲקֹב וְאָמַר, הֵאָסְפוּ וְהַגִּידָה לָכֶם אֵת אֲשֶׁר יִקְרָא אֶתְכֶם בְּאַחֲרִית הַיָּמִים, בְּאַחֲרִית - זוֹ הַשְּׁכִינָה, כִּבְיָכוֹל נָתַן בּוֹ עַצְבוּת, וְהִסְתַּלֵּק. וְאַחַר כָּךְ הֶחֱזִירוּ אוֹתָהּ בָּנָיו בְּיִחוּד הַדְּבָרִים שֶׁלָּהֶם, וּפָתְחוּ וְאָמְרוּ (דברים ו) שְׁמַע יִשְׂרָאֵל וְגוֹ'. בְּאוֹתָהּ שָׁעָה הֶעֱמִידָהּ יַעֲקֹב, וְאָמַר בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, וְהִתְיַשְּׁבָה הַשְּׁכִינָה בִּמְקוֹמָהּ. וַיִּקְרָא יַעֲקֹב, מַה קְּרִיאָה כָּאן? אֶלָּא קְרִיאָה, לְקַיֵּם מְקוֹמָם, לְקַיֵּם אוֹתָם לְמַעְלָה וּמַטָּה.</p>\n<p>בֹּא רְאֵה, בְּכָל מָקוֹם קְרִיאָה בְּגָוֶן זֶה, שֶׁכָּתוּב (במדבר יג) וַיִּקְרָא מֹשֶׁה לְהוֹשֵׁעַ בִּן נוּן יְהוֹשֻׁעַ, לְקַיֵּם מְקוֹמוֹ בְּמָקוֹם שֶׁצָּרִיךְ וּלְקַשֵּׁר אוֹתוֹ. וְכֵן (בראשית כה) וַיִּקְרָא שְׁמוֹ יַעֲקֹב. וְכָתוּב וַיִּקְרָא לוֹ אֵל אֱלֹהֵי יִשְׂרָאֵל. הַקָּדוֹשׁ בָּרוּךְ הוּא הֶעֱמִידוֹ לְמָקוֹם זֶה בְּשֵׁם זֶה. הַקְּרִיאָה בָּאָה לְקִיּוּם.</p>\n<p>אִם תֹּאמַר וְיִקְרְאוּ אֶל אֱלֹהִים, קָרָאתִי מִצָּרָה לִי אֶל ה' - כָּךְ הוּא וַדַּאי, לְקַשֵּׁר וּלְקַיֵּם קִיּוּם הָעֶלְיוֹן, וּמַהוּ? סִדּוּר שֶׁל שֶׁבַח רִבּוֹנוֹ, וְכָל אוֹתָם דְּבָרִים שֶׁצְּרִיכִים לִפְנֵי רִבּוֹנוֹ, קִיּוּם נוֹתֵן לוֹ לְרִבּוֹנוֹ שֶׁמַּרְאֶה שֶׁהַכֹּל תָּלוּי בּוֹ וְלֹא בְּמָקוֹם אַחֵר, הֲרֵי הַכֹּל מַעֲמִיד קִיּוּם. כְּמוֹ זֶה וַיִּקְרָא יַעֲקֹב אֶל בָּנָיו, הֶעֱמִידָם בְּקִיּוּם שָׁלֵם. כְּמוֹ זֶה וַיִּקְרָא אֶל מֹשֶׁה, הִתְקַיֵּם בְּקִיּוּמוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, א' שֶׁל וַיִּקְרָא לָמָּה הִיא קְטַנָּה? אָמַר לוֹ, הִתְקַיֵּם מֹשֶׁה בִּשְׁלֵמוּת, וְלֹא בַּכֹּל, שֶׁהֲרֵי הִסְתַּלֵּק מֵאִשְׁתּוֹ. בְּסִפְרֵי הַקַּדְמוֹנִים אָמְרוּ לְשֶׁבַח, וְאָנוּ כָּךְ שָׁנִינוּ: מַה שֶּׁנִּתְעַלָּה לְמַעְלָה, יִתְקַשֵּׁר לְמַעְלָה וּלְמַטָּה, וְאָז הוּא שָׁלֵם. עוֹד, אָלֶ\"ף קְטַנָּה הָיְתָה מִמָּקוֹם קָטָן, קָטָן שֶׁהוּא גָדוֹל בְּהִתְחַבְּרוּתוֹ לְמַעְלָה. (למעלה ולמטה ואז נשלם,)</p>\n<p>וַיֹּאמֶר, מַה זֶּה וַיֹּאמֶר? הֲרֵי פֵּרְשׁוּהָ, (כמו שנאמר ויאמר בלבו) וְאָמַרְתָּ בִּלְבָבֶךְ - אֲמִירָה בַּחֲשַׁאי. הֵאָסְפוּ!? אִסְפוּ הָיָה צָרִיךְ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים נ) אִסְפוּ לִי חֲסִידָי. אֶלָּא (הקים להם) קַיָּם לָנוּ, הֵאָסְפוּ מִמָּקוֹם שֶׁלְּמַעְלָה הוּא. הֵאָסְפוּ, בְּקִשּׁוּר שָׁלֵם בְּיִחוּד אֶחָד. וְאַגִּידָה לָכֶם, מַה זֶּה וְאַגִּידָה לָכֶם? סוֹד חָכְמָה הוּא.</p>\n<p>רַבִּי יוֹסֵי שָׁאַל אֶת רַבִּי שִׁמְעוֹן. אָמַר לוֹ, וְאַגִּידָה, אוֹ וְיַגֵּד, אוֹ וְיַגִּידוּ, וְכֵן כֻּלָּם, שֶׁשָּׁנִינוּ שֶׁסּוֹד הַחָכְמָה הִיא, לָמָּה בְּדָבָר זֶה (בכלם) הוּא בְּסוֹד הַחָכְמָה? אָמַר לוֹ, מִשּׁוּם שֶׁהוּא דָּבָר שֶׁבָּא בְּגִימֶ\"ל דָּלֶ\"ת בְּלִי פֵרוּד, וְזֶהוּ סוֹד הַחָכְמָה. דָּבָר שֶׁבָּא בִּשְׁלֵמוּת בְּסוֹד הָאוֹתִיּוֹת כָּךְ הוּא כְּשֶׁהֵם בַּחָכְמָה, אֲבָל דָּלֶ\"ת בְּלִי גִימֶ\"ל אֵינוֹ שְׁלֵמוּת, וְכֵן גִּימֶ\"ל בְּלִי דָלֶ\"ת, שֶׁהֲרֵי זֶה בָּזֶה נִקְשְׁרוּ בְּלִי פֵרוּד, וּמִי שֶׁמַּפְרִידָם, גּוֹרֵם לְעַצְמוֹ מָוֶת, וְסוֹד זֶה הוּא חֶטְאוֹ שֶׁל אָדָם.</p>\n<p>מִשּׁוּם כָּךְ הוּא דָּבָר שֶׁל סוֹד חָכְמָה. וְאַף עַל גַּב שֶׁיֵּשׁ יוֹ\"ד לִפְעָמִים בֵּין גִּימֶ\"ל לְדָלֶ\"ת, אֵין פֵּרוּד, וְהַכֹּל קֶשֶׁר אֶחָד. וְעַל זֶה דָּבָר זֶה כָּךְ הוּא וַדַּאי, וְאַגִּידָה לָכֶם - סוֹד הַחָכְמָה, שֶׁרָצָה לְגַלּוֹת אֶת סוֹף כָּל מַעֲשֵׂיהֶם שֶׁל יִשְׂרָאֵל.</p>\n<p>וְאִם תֹּאמַר שֶׁלֹּא גִלָּה מַה שֶּׁרָצָה לְגַלּוֹת, אִם כָּךְ אָז לָמָּה כָּתוּב בַּתּוֹרָה דָּבָר שֶׁל יַעֲקֹב הַשָּׁלֵם, וְאַחַר כָּךְ נִפְגַּם, וְלֹא הִשְׁתַּלֵּם הַדָּבָר? אֶלָּא וַדַּאי שֶׁהִשְׁתַּלֵּם, כָּל מַה שֶּׁצָּרִיךְ לְגַלּוֹת גִּלָּה וְהִסְתִּיר, אָמַר דָּבָר וְגִלָּה בַּחוּץ וְהִסְתִּיר לִפְנִים. וּדְבַר תּוֹרָה לֹא נִפְגָּם לְעוֹלָמִים.</p>\n<p>וְהַסֹל הוּא נִסְתָּר בַּתּוֹרָה, מִשּׁוּם שֶׁהַתּוֹרָה הִיא שְׁלֵמוּת הַכֹּל, שְׁלֵמוּת שֶׁל מַעְלָה וּלְמַטָּה, וְאֵין אוֹת אוֹ דָבָר בַּתּוֹרָה פָּגוּם, וְיַעֲקֹב, כָּל מַה שֶּׁהִצְטָרֵךְ לוֹמַר אָמַר, אֲבָל גִּלָּה וְהִסְתִּיר, וְלֹא פָגַם מִכָּל מַה שֶּׁרָצָה אֲפִלּוּ אוֹת אַחַת.</p>\n<p>רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי הָיוּ יוֹשְׁבִים יוֹם אֶחָד עַל פֶּתַח לוֹד. אָמַר רַבִּי יוֹסֵי לְרַבִּי יְהוּדָה, זֶה שֶׁרָאִינוּ שֶׁיַּעֲקֹב בֵּרַךְ אֶת בָּנָיו, רָאִינוּ מִמַּה שֶּׁכָּתוּב וַיְבָרֶךְ אוֹתָם, אֲבָל אֵיפֹה הַבְּרָכָה שֶׁלָּהֶם? אָמַר לוֹ, כָּל הַבְּרָכוֹת הֵם שֶׁבֵּרַךְ אוֹתָם, כְּמוֹ יְהוּדָה אַתָּה יוֹדוּךְ אַחֶיךְ, דָּן יָדִין עַמּוֹ, מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ, וְכֵן כֻּלָּם.</p>\n<p>אֲבָל מַה שֶּׁרָצָה לְגַלּוֹת לָהֶם לֹא גִלָּה, שֶׁרָצָה לְגַלּוֹת לָהֶם אֶת הַקֵּץ, וַהֲרֵי פֵּרְשׁוּהָ שֶׁיֵּשׁ קֵץ לַיָּמִין וְיֵשׁ קֵץ לַשְּׂמֹאל, וְרָצָה לְגַלּוֹת לָהֶם אֶת הַקֵּץ כְּדֵי לְהִשָּׁמֵר וּלְהִטָּהֵר מֵעָרְלָה. וּמַה שֶּׁגִּלָּה לָהֶם נוֹדַע וְהִתְגַּלָּה עַד שֶׁנִּכְנְסוּ לָאָרֶץ הַקְּדוֹשָׁה, אֲבָל דְּבָרִים אֲחֵרִים אֵינָם בְּגָלוּי, וְהֵם נִסְתָּרִים בַּתּוֹרָה בַּפָּרָשָׁה הַזּוֹ שֶׁל יַעֲקֹב וּבְאוֹתָן הַבְּרָכוֹת.</p>"],[9522011476,"<p>פָּתַח וְאָמַר, רְאוּבֵן בְּכֹרִי אַתָּה כֹּחִי וְרֵאשִׁית אוֹנִי. מָה רָאָה יַעֲקֹב לִפְתֹּחַ בִּרְאוּבֵן? שֶׁיִּפְתַּח בִּיהוּדָה, שֶׁהוּא רִאשׁוֹן לְכָל הַמַּחֲנוֹת, וְהוּא מֶלֶךְ, וְרָאִינוּ שֶׁלֹּא בֵרַךְ אוֹתוֹ וְסִלֵּק בְּרָכוֹת מִמֶּנּוּ, עַד שֶׁבָּא מֹשֶׁה וְהִתְפַּלֵּל תְּפִלָּה עָלָיו, כְּמוֹ שֶׁנֶּאֱמַר (דברים לג) יְחִי רְאוּבֵן וְאַל יָמוֹת.</p>\n<p>אֲבָל וַדַּאי בֵּרְכוֹ, וְעָלְתָה אוֹתָהּ בְּרָכָה לִמְקוֹמָהּ. לְאָדָם שֶׁהָיָה לוֹ בֵּן. כְּשֶׁהִגִּיעַ זְמַנּוֹ לְהִסְתַּלֵּק מִן הָעוֹלָם, בָּא הַמֶּלֶךְ אֵלָיו. אָמַר, הֲרֵי כָּל מָמוֹנִי יִהְיֶה בְּיַד הַמֶּלֶךְ שָׁמוּר לִבְנִי. כְּשֶׁרָאָה הַמֶּלֶךְ שֶׁבְּנוֹ רָאוּי, אָז נָתַן לוֹ. כָּךְ יַעֲקֹב אָמַר.</p>\n<p>רְאוּבֵן בְּכֹרִי אַתָּה, אֲהוּב מֵעַי אַתָּה, אֲבָל הַבְּרָכוֹת שֶׁלְּךְ יַעֲלוּ בִּידֵי הַמֶּלֶךְ הַקָּדוֹשׁ עַד שֶׁיִּרְאֶה אוֹתְךְ, מִשּׁוּם שֶׁהָלַכְתָּ כְּנֶגֶד אַפְּךְ וְגוֹ', כְּתַרְגּוּמוֹ. רְאוּבֵן בְּכֹרִי אַתָּה וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (יחזקאל לז) וַיֹּאמֶר אֵלַי הִנָּבֵא אֶל הָרוּחַ וְגוֹ'. כַּמָּה אֲטוּמִים הֵם בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בִּכְבוֹד הַמֶּלֶךְ, שֶׁהֲרֵי הַתּוֹרָה מַכְרִיזָה עֲלֵיהֶם בְּכָל יוֹם, וְאֵין מִי שֶׁמַּקְשִׁיב בְּאָזְנָיו כְּנֶגְדָּהּ. פָּסוּק זֶה קָשֶׁה, כֵּיוָן שֶׁכָּתוּב הִנָּבֵא אֶל הָרוּחַ, מַדּוּעַ פַּעַם נוֹסֶפֶת הִנָּבֵא בֶּן אָדָם וְאָמַרְתָּ אֶל הָרוּחַ?</p>\n<p>אֶלָּא מִכָּאן לָמַדְנוּ סוֹד הַחָכְמָה, שְׁנַיִם עוֹמְדִים כָּאן - אֶחָד לְעוֹרֵר מִלְּמַטָּה לְמַעְלָה, שֶׁאִם לֹא מִתְעוֹרְרִים לְמַטָּה לֹא מִתְעוֹרְרִים לְמַעְלָה, וּבַהִתְעוֹרְרוּת שֶׁלְּמַטָּה מִתְעוֹרֵר לְמַעְלָה. הִנָּבֵא אֶל הָרוּחַ - מִלְּמַטָּה לְמַעְלָה, הִנָּבֵא בֶּן אָדָם וְאָמַרְתָּ אֶל הָרוּחַ - מִלְמַעְלָה לְמַטָּה.</p>\n<p>שֶׁהֲרֵי אֲפִלּוּ לְמַעְלָה, בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה לוֹקֵחַ אוֹתוֹ עֶלְיוֹן מֵהָעֶלְיוֹן מִמֶּנּוּ. כְּמוֹ פָּסוּק זֶה, כֹּה אָמַר ה' מֵאַרְבַּע רוּחוֹת בּאִי הָרוּחַ. מֵאַרְבַּע רוּחוֹת - זֶה דָּרוֹם וּמִזְרָח וְצָפוֹן וּמַעֲרָב, וְרוּחַ בָּאָה מִמַּעֲרָב בְּהִתְחַבְּרוּת שֶׁל אֵלֶּה הָאֲחֵרִים, כְּמוֹ שֶׁנֶּאֱמַר (במדבר כא) כָּרוּהָ נְדִיבֵי הָעָם וְגוֹ'.</p>\n<p>וּמִכָּאן יוֹצְאוֹת רוּחוֹת וּנְשָׁמוֹת לִבְנֵי הָעוֹלָם לְהִצְטַיֵּר בָּהֶם, וְנוֹשְׁבִים, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. בֹּא רְאֵה, לוֹקֵחַ מִצַּד זֶה וְנוֹתֵן בְּצַד אַחֵר, וְעַל זֶה (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא. לָמָּה אֵינֶנּוּ מָלֵא? מִשּׁוּם שֶׁלּוֹקֵחַ וְנוֹתֵן, מַכְנִיס וּמוֹצִיא.</p>\n<p>רַבִּי אֶלְעָזָר שָׁאַל שְׁאֵלָה אֶת רַבִּי שִׁמְעוֹן. אָמַר, הוֹאִיל וְגָלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁבְּנֵי אָדָם יָמוּתוּ, לָמָּה הוֹרִיד נְשָׁמוֹת לָעוֹלָם, וְלָמָּה הוּא צָרִיךְ אֶת זֶה? אָמַר לוֹ, שְׁאֵלָה זוֹ לִפְנֵי רַבָּנָן שָׁאֲלוּ כַּמָּה וְכַמָּה, וּבֵאֲרוּהָ, אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן נְשָׁמוֹת שֶׁיּוֹרְדוֹת לָעוֹלָם הַזֶּה לְהוֹדִיעַ אֶת כְּבוֹדוֹ, וְלוֹקחַ אוֹתָן אַחַר כָּךְ. אִם כָּךְ לָמָּה יָרְדוּ?</p>\n<p>אֶלָּא סוֹד זֶה כָּךְ הוּא. פָּתַח וְאָמַר, (משלי ה) שְׁתֵה מַיִם מִבּוֹרֶךְ וְנֹזְלִים מִתּוֹךְ בְּאֵרֶךְ. הֲרֵי פֵּרְשׁוּהָ, בּוֹר - מָקוֹם שֶׁלֹּא נוֹבֵעַ מֵעַצְמוֹ. וּמָתַי נוֹבְעִים הַמַּיִם הַלָּלוּ? בְּשָׁעָה שֶׁהִשְׁתַּלְּמָה הַנְּשָׁמָה בָּעוֹלָם הַזֶּה, כְּשֶׁעוֹלָה לְאוֹתוֹ מָקוֹם שֶׁנִּקְשְׁרָה בּוֹ, אָז הוּא שָׁלֵם מִכָּל הַצְּדָדִים, מִמַּטָּה וּמִמַּעְלָה (ומכל הצדדים).</p>\n<p>וּכְשֶׁנְּשָׁמָה עוֹלָה, אָז מִתְעוֹרֶרֶת תְּשׁוּקַת הַנְּקֵבָה לַזָּכָר, וְאָז נוֹבְעִים מַיִם מִלְּמַטָּה לְמַעְלָה, וּבוֹר נַעֲשֶׂה בְּאֵר, מַיִם נוֹבְעִים, וְאָז הִתְחַבְּרוּת וְיִחוּד (ויסוד) וּתְשׁוּקָה וְרָצוֹן נִמְצָאִים, (לזה) שֶׁהֲרֵי בְּנִשְׁמַת הַצַּדִּיק נִתְקָן אוֹתוֹ מָקוֹם, וּמִתְעוֹרֶרֶת חֲבִיבוּת וְרָצוֹן לְמַעְלָה וּמִתְחַבְּרִים כְּאֶחָד.</p>\n<p>רְאוּבֵן בְּכֹרִי אַתָּה. כָּךְ הוּא וַדַּאי, טִפָּה רִאשׁוֹנָה שֶׁל יַעֲקֹב הָיְתָה, וּרְצוֹנוֹ בְּמָקוֹם אַחֵר הָיָה, כְּמוֹ שֶׁנִּתְבָּאֵר. בֹּא רְאֵה, רְאוּבֵן וְכָל שְׁנֵים עָשָׂר הַשְּׁבָטִים, כֻּלָּם אֲחוּזִים בַּשְּׁכִינָה, וּכְשֶׁרָאָה יַעֲקֹב אֶת הַשְּׁכִינָה עָלָיו, קָרָא לִשְׁנֵים עָשָׂר בָּנָיו לְהִתְחַבֵּר עִמָּהּ.</p>\n<p>וּבֹא וּרְאֵה, מִטָּה שְׁלֵמָה לֹא נִמְצְאָה מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם כְּאוֹתָהּ הַשָּׁעָה שֶׁרָצָה יַעֲקֹב לְהִסְתַּלֵּק מִן הָעוֹלָם. אַבְרָהָם מִימִינוֹ, יִצְחָק מִשְּׂמֹאלוֹ (דין), יַעֲקֹב הָיָה שׁוֹכֵב בֵּינֵיהֶם, שְׁכִינָה לְפָנָיו. כֵּיוָן שֶׁרָאָה כָּךְ יַעֲקֹב, קָרָא לְבָנָיו, וְאָחַז אוֹתָם סְבִיב הַשְּׁכִינָה, וְסִדֵּר אוֹתָם בְּסִדּוּר שָׁלֵם.</p>\n<p>מִנַּיִן לָנוּ שֶׁסִּדְּרָם סְבִיב הַשְּׁכִינָה? שֶׁכָּתוּב הֵאָסְפוּ, וְאָז נִמְצְאָה שָׁם שְׁלֵמוּת הַכֹּל, וְכַמָּה מֶרְכָּבוֹת עֶלְיוֹנוֹת סְבִיבָם. פָּתְחוּ וְאָמְרוּ, לְךְ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְגוֹ'. אָז הִתְכַּנֵּס הַשֶּׁמֶשׁ אֶל הַלְּבָנָה, וְהִתְקָרֵב מִזְרָח לַמַּעֲרָב. זֶהוּ שֶׁכָּתוּב וַיֶּאֱסֹף רַגְלָיו אֶל הַמִּטָּה, וּמְאִירָה הַלְּבָנָה, וְנִמְצֵאת בִּשְׁלֵמוּת. וְאָז וַדַּאי שָׁנִינוּ, יַעֲקֹב אָבִינוּ לֹא מֵת. כֵּיוָן שֶׁרָאָה יַעֲקֹב (סדר) צַד שָׁלֵם, מַה שֶּׁלֹּא נִמְצָא כָּךְ לְבֶן אָדָם אַחֵר, שָׂמַח וְשִׁבַּח אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וּפָתַח וּבֵרַךְ אֶת בָּנָיו, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ.</p>"],[9522011477,"<p>רַבִּי יוֹסֵי וְרַבִּי יֵיסָא הָיוּ הוֹלְכִים בַּדֶרֶךְ, אָמַר רַבִּי יֵיסָא, הֲרֵי וַדַּאי שָׁנִינוּ, כָּל בְּנֵי יַעֲקֹב נִתְקְנוּ בְּסֵדֶר שָׁלֵם וְהִתְבָּרְכוּ כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, מַה נֹּאמַר בַּפָּסוּק הַזֶּה, שֶׁכָּתוּב מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ וְגוֹ'? אָמַר לוֹ, לֹא יָדַעְתִּי, כִּי לֹא שָׁמַעְתִּי מֵהַמְּנוֹרָה הַקְּדוֹשָׁה, אֶלָּא אַתָּה וַאֲנִי נֵלֵךְ לַמְּנוֹרָה הַקְּדוֹשָׁה. הָלְכוּ. כְּשֶׁהִגִּיעוּ לְרַבִּי שִׁמְעוֹן, אָמְרוּ דָבָר וְשָׁאֲלוּ שְׁאֵלָה. אָמַר לָהֶם, וַדַּאי סוֹד הַחָכְמָה הוּא.</p>\n<p>פָּתַח וְאָמַר, (שופטים ה) אָשֵׁר יָשַׁב לְחוֹף יַמִּים וְעַל מִפְרָצָיו יִשְׁכּוֹן. לָמָּה יָשַׁב שָׁם? אֶלָּא מִי שֶׁיּוֹשֵׁב עַל שְׂפַת הַיָּם, מִשְׁתַּמֵּשׁ בְּתַפְנוּקֵי הָעוֹלָם. (וכאן אשר זהו פתח עליון של צדיק (של צדק), כשמתברך להוריק ברכות לעולם, וכאן סמך לפסוק הזה מאשר שמנה, לפתח העליון, שמשם מוריקים ברכות לעולם) וּפֶתַח זֶה נוֹדָע תָּמִיד כַּבְּרָכוֹת שֶׁל הָעוֹלָם, וְנִקְרָא אָשֵׁר, וְזֶהוּ עַמּוּד מֵאוֹתָם עַמּוּדִים שֶׁהָעוֹלָם עוֹמֵד עֲלֵיהֶם.</p>\n<p>וְהַמָּקוֹם שֶׁנִּקְרָא לֶחֶם עֹנִי, מֵאוֹתוֹ מָקוֹם נִתְקָן (ההוא). זֶהוּ שֶׁכָּתוּב מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ. מַה שֶּׁהָיָה לֶחֶם עֹנִי, הָפַךְ לִהְיוֹת לֶחֶם (עני) פַּנַּג (שמנה), מִשּׁוּם שֶׁהֵרִיק וְזָרַק בּוֹ בְּרָכוֹת וְתַפְנוּקִים, וְסוֹף הַפָּסוּק מוֹכִיחַ - וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ. מִי הַמֶּלֶךְ? זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁמִּמֶּנָּה נִזּוֹן בְּתַפְנוּקֵי עוֹלָם, וְזֶה נוֹתֵן לַמֶּלֶךְ הַזֶּה כָּל הַבְּרָכוֹת, כָּל שִׂמְחָה וְכָל טוּב הוּא נוֹתֵן, וּמִמֶּנָּה יוֹצְאִים. אָמְרוּ, אִם לֹא בָאנוּ לָעוֹלָם אֶלָּא רַק לָדַעַת אֶת זֶה - טוֹב לָנוּ.</p>"],[9522011478,"<p>רְאוּבֵן הָיָה בְּכוֹר שֶׁל יַעֲקֹב. אָמַר רַבִּי חִיָּיא, לוֹ רָאוּי הַכֹּל, וְהַכֹּל הָעֳבַר מִמֶּנּוּ, וְנִתְּנָה הַמַּלְכוּת לִיהוּדָה, הַבְּכוֹרָה לְיוֹסֵף, וְהַכְּהֻנָּה לְלֵוִי. זֶהוּ שֶׁכָּתוּב פַּחַז כַּמַּיִם אַל תּוֹתַר, לֹא תִשָּׁאֵר בָּהֶם. וּמַה שֶּׁאָמַר כֹּחִי וְרֵאשִׁית אוֹנִי, כָּאן בֵּרְכוֹ וְהִפְקִידוֹ אֵצֶל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>לַאֲהוּב הַמֶּלֶךְ, (שבקש מהמלך לעשות לו טובה) (שהיה לו בן ורצה שהמלך יעשה לו טובה) יוֹם אֶחָד עָבַר בְּנוֹ בַּשּׁוּק. אָמַר לַמֶּלֶךְ, זֶה בְּנִי, וַדַּאי אֲהוּב נַפְשִׁי. שָׁמַע הַמֶּלֶךְ, וְיָדַע שֶׁזֶּה בִּקֵּשׁ עַל בְּנוֹ. כָּךְ יַעֲקֹב אָמַר, רְאוּבֵן בְּכֹרִי אַתָּה כֹּחִי וְגוֹ'. כָּאן צִוָּה אֶת הַמֶּלֶךְ.</p>\n<p>פַּחַז כַּמַּיִם אַל תּוֹתַר. כָּאן אָמַר מַה שֶּׁאֵרַע לוֹ, שֶׁלֹּא נִשְׁאַר (לו) בָּאָרֶץ וְנִזְרַק לְחוּץ לָאָרֶץ. כְּנֶגֶד זֶה מְמֻנֶּה (תחום) אֶחָד מִצַּד הַמִּשְׁכָּן הָעֶלְיוֹן שֶׁמְּמֻנֶּה תַּחַת יַד מִיכָאֵל, וְיֵשׁ אוֹמְרִים תַּחַת יַד גַּבְרִיאֵל. וּמִיכָאֵל הוּא רֹאשׁ בְּכָל מָקוֹם מִצַּד שֶׁל הַחֶסֶ\"ד, וְגַבְרִיאֵל מִצַּד שֶׁל שְׂמֹאל שֶׁל גְּבוּרָ\"ה, וִיהוּדָה עֹד רָד עִם אֵל, צַד הַגְּבוּרָה, נִקְרָא בֵּית דִּין, וְסָמוּךְ לוֹ רְאוּבֵן. וְאַף עַל גַּב שֶׁמַּלְכוּת הָיְתָה שֶׁל יְהוּדָה, רְאוּבֵן סָמוּךְ כְּנֶגְדּוֹ הָיָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, עֲתִידִים אוֹתָם בְּנֵי רְאוּבֵן לְעוֹרֵר שְׁנֵי קְרָבוֹת בְּתוֹךְ הָאָרֶץ. בּא רְאֵה, כָּתוּב כֹּחִי - בְּגָלוּת מִצְרַיִם. וְרֵאשִׁית אוֹנִי - שֶׁהֵם הָיוּ רִאשׁוֹנִים לַאֲחֵיהֶם לַקְּרָב. יֶתֶר שְׂאֵת - לְגָלוּת אַשּׁוּר, שֶׁמִּשָּׁם גָּלוּ בְּנֵי גָד וּבְנֵי רְאוּבֵן רִאשׁוֹנִים מִכֻּלָּם, וְסָבְלוּ כַּמָּה רָעוֹת, וְכַמָּה עִנּוּיִים סָבְלוּ, וְלֹא שָׁבוּ עַד כָּעֵת.</p>\n<p>וְיְתֱר עָז - לַזְּמַן שֶׁמֶּלֶךְ הַמָּשִׁיחַ יִתְעוֹרֵר בָּעוֹלָם, הֵם יֵצְאוּ וְיַעַרְכוּ קְרָבוֹת בָּעוֹלָם וִינַצְּחוּ, וְיִתְחַזְּקוּ עַל הָעַמִּים, וּבְנֵי הָעוֹלָם יִפְחֲדוּ מֵהֶם וְיִרְתְּתוּ לִפְנֵיהֶם וְיַחְשְׁבוּ לְהִתְגַּבֵּר בַּמַּלְכוּת, וְלֹא יִשָּׁאֲרוּ בָהּ. זֶהוּ שֶׁכָּתוּב פַּחַז כַּמַּיִם אַל תּוֹתַר. מָה הַטַּעַם שֶׁלֹּא יִשָּׁאֲרוּ בָהּ וַאֲפִלּוּ בְּצַד אֶחָד שֶׁל הָעוֹלָם? מִשּׁוּם כִּי עָלִיתָ מִשְׁכְּבֵי אָבִיךְ, שֶׁעֲתִידִים לְהִכָּנֵס וְלַעֲרֹךְ קְרָבוֹת בְּתוֹךְ הָאָרֶץ הַקְּדוֹשָׁה, מִשְׁכְּבֵי אָבִיךְ דַּוְקָא, זוֹ יְרוּשָׁלַיִם.</p>\n<p>בֹּא רְאֵה, לְאַרְבַּעַת צִדְדֵי הָעוֹלָם הִתְפַּזְּרוּ בְּנֵי רְאוּבֵן בַּגָּלוּת, כְּנֶגֶד כָּל יִשְׂרָאֵל שֶׁגָּלוּ לַגָּלוּת אַרְבַּע פְּעָמִים בְּאַרְבַּע רוּחוֹת הָעוֹלָם. זֶהוּ שֶׁכָּתוּב כֹּחִי - אֶחָד, וְרֵאשִׁית אוֹנִי - שְׁנַיִם, יֶתֶר שְׂאֵת - שְׁלֹשָׁה, וְיֶתֶר עָז - אַרְבָּעָה. כְּמוֹ כֵן עֲתִידִים הֵם לַעֲרֹךְ קְרָב בְּאַרְבַּע רוּחוֹת הָעוֹלָם וְלִשְׁלֹט בְּקִרְבָּם עַל הַכֹּל, וִינַצְּחוּ עַמִּים רַבִּים וְיִשְׁלְטוּ עֲלֵיהֶם.</p>\n<p>פַּחַז כַּמַּיִם אַל תּוֹתַר כִּי עָלִיתָ עַל מִשְׁכְּבֵי אָבִיךְ. כָּאן נִרְמָז עַל הִרְהוּר רִאשׁוֹן שֶׁהָיָה לְיַעֲקֹב בַּטִּפָּה הָרִאשׁוֹנָה בְּרָחֵל, שֶׁאִלְמָלֵא הִרְהוּר שֶׁל אוֹתָהּ טִפָּה הָיָה בִּמְקוֹמָהּ, נִשְׁאָר הָיָה רְאוּבֵן בַּכֹּל, אֲבָל פַּחַז כַּמַּיִם אַל תּוֹתַר כִּי עָלִיתָ מִשְׁכְּבֵי אָבִיךְ. עָלִיתָ - בְּהִרְהוּר אַחֵר, אָז חִלַּלְתָּ וְגוֹ'.</p>\n<p>דָּבָר אַחֵר פַּחַז כַּמַּיִם אַל תּוֹתַר - שֶׁהֲרֵי כַּאֲשֶׁר יַעַרְכוּ קְרָב בְּנֵי רְאוּבֵן בָּעוֹלָם וִינַצְּחוּ עַמִּים רַבִּים, לֹא יִשָּׁאֲרוּ בַּמַּלְכוּת, מָה הַטַּעַם? כִּי עָלִיתָ מִשְׁכְּבֵי אָבִיךְ, שֶׁעֲתִידִים לַעֲרֹךְ קְרָב בָּאָרֶץ הַקְּדוֹשָׁה דַּוְקָא, שֶׁכָּתוּב כִּי עָלִיתָ מִשְׁכְּבֵי אָבִיךְ, (זו ירושלים, משכבי,)? מִשְׁכָּב הָיָה צָרִיךְ לִכְתֹּב! אֶלָּא אָבִיךְ, זֶה יִשְׂרָאֵל הַזָּקֵן. מִשְׁכְּבֵי אָבִיךְ וְלֹא מִשְׁכָּב, מִשּׁוּם שֶׁהֲרֵי פַּעֲמַיִם נִבְנְתָה יְרוּשָׁלַיִם, וּפַעַם שְׁלִישִׁית לִזְמַנּוֹ שֶׁל מֶלֶךְ הַמָּשִׁיחַ, וְלָכֵן מִשְׁכְּבֵי אָבִיךְ. וְכָאן הִתְגַּלְּתָה בְּרָכָה, וּמַה שֶּׁהָיָה בְּאוֹתוֹ זְמַן, וּמַה שֶּׁהָיָה כְּשֶׁנִּכְנְסוּ יִשְׂרָאֵל לָאָרֶץ, וּמַה שֶּׁיִּהְיֶה בִּזְמַן מֶלֶךְ הַמָּשִׁיחַ בְּמַעֲשֵׂה רְאוּבֵן.</p>"]]});
